INSERT INTO "Cirki".cirki_clubs VALUES ('Хабаровский цирк', 'Хабаровск', 'Asia/Vladivostok', 'ул Краснореченская,д 102', NULL, 'край Хабаровский,г Хабаровск,ул Краснореченская,д 102', '{"type": "Point", "coordinates": [135.11537790298465, 48.438397865873654]}', '<p>20 октября 2001 г. в парке им. Ю. Гагарина распахнул для зрителей свои двери Хабаровский цирк. Это первый и единственный капитальный стационарный комплекс, состоящий из цирка и гостиницы для артистов на территории края. </p><p>Вместимость зала – 1 340 мест, высота купола – 17 м. Проект цирка уникален, он был создан на основании проектов уссурийского, иркутского и ярославского цирков. Жители города по праву считают здание цирка «жемчужиной архитектуры» Хабаровска. </p><p>В 2016 году Хабаровский цирк вошел в состав Краевого государственного автономного учреждения культуры «Краевое научно-образовательное творческое объединение культуры».</p><p>Здание краевого учреждения культуры обеспечено условиями для посещения мероприятий инвалидами и людей с ограниченными возможностями в рамках программы «Доступная среда».<br /></p>', 'https://cirk-khabarovsk.ru', 'press_knotok@mail.ru', '[{"value": "74212307727"}]', '{"url": "https://all.culture.ru/uploads/51f3b6bf2724d46db87aebda8d7f91bb.jpg", "title": "kartinki24_city_0027.jpg"}', NULL, NULL, 'Цирки', 'КГАУК «Краевое научно-образовательное творческое объединение культуры»', 'Хабаровск', 'Asia/Vladivostok', 'ул Фрунзе,д 69А', NULL, 'край Хабаровский,г Хабаровск,ул Фрунзе,д 69А', NULL, 2721070181, 'mincult', 'Хабаровский край', 'Asia/Vladivostok', '[{"network":"vk","name":"Творческий Хабаровск | КНОТОК","networkId":"126669083","updateDate":"2023-03-13T05:25:31Z","createDate":"2023-03-13T05:25:31Z","accountId":46468,"postingGroupId":40888}]', 12697, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18737, '[{"url":"https://www.culture.ru/institutes/42765/khabarovskii-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/habarovsk/cirki/9422pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=3356ec2f-b8e7-4349-88c7-98e228932759&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 18737, NULL, NULL, NULL, '2016-01-28 07:05:12+03', '2026-04-09 09:12:32+03', 50, '0101000020E61000000100002DB1E360402248D86B1D384840');
INSERT INTO "Cirki".cirki_clubs VALUES ('Таганрогский государственный цирк-шапито «Азовье»', 'Таганрог', 'Europe/Moscow', 'ул Чехова,д 100', NULL, 'обл Ростовская,г Таганрог,ул Чехова,д 100', '{"type": "Point", "coordinates": [38.920786678791046, 47.21185234880098]}', '<p><span>Таганрогский государственный цирк был построен в 1963 году и является филиалом Российской государственной цирковой компании</span>. Цирк не имеет каменного здания, а представляет собой стационарное шапито красно-зеленого цвета. Располагается цирк в нескольких шагах от центра города. Функционирует в теплый период года – с апреля по октябрь. </p><p>В течение многих лет на арене цирка-шапито «Азовье» проходили различные программы с участием <span>Михаила Румянцева (Карандаш), Игоря КИО, династии Запашных и других известных цирковых артистов</span>. Цирк-шапито «Азовье» является одним из любимейших центров семейного отдыха Таганрожцев и гостей города.</p>', 'http://circus-taganrog.ru', 'tagcircus@yandex.ru', '[{"value": "79996914207", "comment": "справочная"}, {"value": "78634612433", "comment": "касса"}]', '{"url": "https://all.culture.ru/uploads/235dd119d0d63b1f479fd4a9fefa4a9e.jpg", "title": "цирк шапито.jpg"}', '[{"url": "https://all.culture.ru/uploads/40244a56c8c48a24dab6ba558ea79c95.jpeg", "title": "тихонов11_.jpg"}, {"url": "https://all.culture.ru/uploads/69e5f5ef912ba0e70e6e910f38ad49bb.jpeg", "title": "NKLBHvoRfvY.jpg"}, {"url": "https://all.culture.ru/uploads/edb6538daadd6eea6b3d89ebe31cbba2.jpeg", "title": "d90fc8c3-fa8c-4d39-92ed-992b90c5e360.jpg"}, {"url": "https://all.culture.ru/uploads/3fb9143de8d36309f0cd749d9400e25f.jpeg", "title": "Untitled-1.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016