d":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', '[{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=-165438687&id=456239023&hash=1296d13c9f9535d3&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34855, '[{"url":"http://afisha.sputnik.ru/places/Taganrogskiy-gosudarstvenniy-cirk-shapito-Azove-57e","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2018-05-07 13:32:17+03', '2019-05-24 15:06:19+03', 1, '0101000020E610000000008056DC7543402BD74EFA1D9B4740');
INSERT INTO "Cirki".cirki_clubs VALUES ('Московский государственный цирк на Речном', 'Москва', 'Europe/Moscow', 'ул Флотская,д 5А', NULL, 'г Москва,г Москва,ул Флотская,д 5А', '{"type": "Point", "coordinates": [37.492410000000014, 55.85309699999999]}', '<p><span>«Цирк на Речном» основан в 1994 году. Расположен на территории Парка Дружбы, вблизи станции метро «Речной вокзал». Его зал рассчитан на 1300 посадочных мест. Цирк долгие годы радовал яркими представлениями, фееричными шоу, незабываемыми программами. Но последние пять лет площадка по прямому назначению не использовалась, здесь проходили репетиции, хранились декорации и реквизит.</span></p><p><span>В 2015 года был проведен ремонт. 30 мая цирк открыл свои двери для жителей и гостей столицы программой «Принц цирка» под руководством заслуженного артиста России Анатолия Сокола. </span></p>', 'http://www.circus-msk.ru', NULL, '[{"value": "74957086780", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/566542bd68b34df87c04e01a27b76c9a.jpg", "title": "shapitoraduga-53d8bcd85d1b6_620_416.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"Брянский государственный цирк","networkId":"56911922790443","updateDate":"2016-09-06T08:22:42Z","createDate":"2016-09-06T08:22:42Z","accountId":9126,"postingGroupId":7878},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 24441, '[{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2016-09-20 11:05:57+03', '2016-09-22 16:28:41+03', 2, '0101000020E6100000991C774A07BF424068A8514832ED4B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Летний цирк-шапито Республики Бурятия  ', 'Улан-Удэ', 'Asia/Irkutsk', 'пр-кт 50-летия Октября', 'Парк им. Орешкова', 'Респ Бурятия,г Улан-Удэ,пр-кт 50-летия Октября', '{"type": "Point", "coordinates": [107.61040806770325, 51.84289768050614]}', '<p><span>Цирк-шапито, предназначенный для цирковых представлений. Основную часть помещения составляет круглая площадка (т.н. «арена», она же на профессиональном языке – «манеж»), диаметр которой всегда составляет 13 метров. Неизменность диаметра связана со спецификой цирковых представлений, собирающихся из отдельных номеров или аттракционов различных цирковых трупп. </span></p><p><span>Постоянство параметров манежа позволяет каждому артисту цирка демонстрировать свой номер без дополнительной переделки на любой профессиональной арене мира. Манеж обнесен жестким барьером, отделяющим его от зрительских мест. </span></p><p><span>Вторая непременная составляющая циркового здания – сферический купол, необходимый для воздушных гимнастических номеров. Передвижное цирковое здание называется шапито (от франц. chapiteau – капитель, колпак), и представляет собой систему высоких центральных мачт и боковых стоек, на которые натягивается брезентовый шатер.</span></p>', NULL, 'goscirk2001@yandex.ru', '[{"value": "73012461619", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8038c726f531ee824da945e24eb4c580.jpg", "title": "IMG_4892.jpg"}', NULL, NULL, 'Цирки', 'АУК РБ «Государственный цирк Республики Бурятия»', 'Улан-Удэ', 'Asia/Irkutsk', 'ул 3-я Транспортная,д 33', NULL, 'Респ Бурятия,г Улан-Удэ,ул 3-я Транспортная,д 33', NULL, 326005484, 'mincult', 'Республика Бурятия', 'Asia/Irkutsk', '[{"network":"vk","name":"Цирк Бурятии","networkId":"336246671","isPersonal":true,"updateDate":"2016-06-22T03:03:50Z","createDate":"2016-06-22T03:03:50Z","accountId":7106,"postingGroupId":6634}]', 12466, '[{"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 21364, '[{"url":"https://www.2do2go.ru/places/42989/letniy-cirk-shapito-respubliki-buryatiya","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Letniy-cirk-shapito-Respubliki-Buryatiya-5b2","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2016-05-18 08:00:28+03', '2016-05-18 10:34:01+03', 3, '0101000020E6100000000000ED10E75A40F6D23912E4EB4940');
INSERT INTO "Cirki".cirki_clubs VALUES ('Цирк Чинизелли', 'Санкт-Петербург', 'Europe/Moscow', 'наб Реки Фонтанки,д 3А', NULL, 'г Санкт-Петербург,г Санкт-Петербург,наб Реки Фонтанки,д 3А', '{"type": "Point", "coordinates": [30.3410866856575, 59.93864631987489]}', '<p>Цирк Чинизелли, <span>Цирк на Фонтанке</span><span> или Большой Санкт-Петербургский государственный цирк?</span></p><p><span>Основанный итальянским наездником Гаэтано Чинизелли</span><span> </span><a href="http://new.circus.spb.ru/o-tsirke/istoriya/" style="vertical-align:baseline">в 1877 году</a><span>, цирк жонглирует своими названиями, меняющимися от эпохи к эпохе, но адрес его остается прежним.</span></p><p>Сейчас в здании цирка идут ремонтно-реставрационные работы, и совсем можно будет увидеть его обновленным. Вернут изначальное имя – Цирк Чинизелли, чтобы вновь напомнить о человеке, построившем первый в России каменный цирк.</p><p>В 2015 году Гаэтано Чинизелли исполняется 200 лет со дня рождения. Итальянский дрессировщик лошадей и великий антрепренер, он добился не только громкой славы в Европе и России, но и смог построить каменный цирк на территории Михайловского замка по инновационной для своего времени технологии.</p>', 'http://circus.spb.ru', 'press@circus.spb.ru', '[{"value": "78125705260", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/97b460ea2941efc28b9376db20c245d5.jpg", "title": "Uiq2HS3TEsY.jpg"}', '[{"url": "https://all.culture.ru/uploads/8589a2e66cec90a615be5788ca39969c.jpg", "title": "_U7A3271.jpg"}, {"url": "https://all.culture.ru/uploads/84d5eb84b21ed5a1570a793543c2bea7.jpg", "title": "FC6A8332.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"post