ateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, NULL, NULL, NULL, '{"to": "22:00:00", "from": "18:00:00"}', '{"to": "22:00:00", "from": "14:00:00"}', '{"to": "19:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12879, '[{"url":"https://www.2do2go.ru/places/29809/bolshoi-sankt-peterburgskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Cirk-Chinizelli-552","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-08-06 12:12:43+03', '2016-10-27 18:53:37+03', 4, '0101000020E61000000000007551573E40CC2F079025F84D40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Симферопольский государственный цирк им. Б. Тезикова', 'Симферополь', 'Europe/Moscow', 'ул Горького,д 3', NULL, 'Респ Крым,г Симферополь,ул Горького,д 3', '{"type": "Point", "coordinates": [34.099213000000006, 44.949762]}', '<p style="text-align:left">Симферопольский государственный цирк им. Тезикова – это настоящее чудо. Только здесь можно увидеть удивлённые глаза взрослых и детей. Стоит заметить, что цирк – это не только радость, загадка и сказка, это упорный, тяжёлый труд, результатом которого являются минуты счастья пришедших на выступление зрителей.</p><p style="text-align:left">История Симферопольского цирка началась осенью 1959 года – именно тогда в столице Крыма был построен первый стационарный цирк. До этого в город приезжали временные цирки-шапито. Симферопольский цирк был возведен в самом центре города и работал только летом. Вскоре цирк был частично перестроен и стал функционировать круглый год.</p><p style="text-align:left"></p><p style="text-align:left">На манеже Симферопольского цирка выступали коллективы и артисты из Грузии, Узбекистана, Молдавии, Армении, Белоруссии, Латвии, Казахстана, Литвы, Азербайджана, Китая, Болгарии, Польши, Кении, Румынии, Чехословакии и Венгрии.</p><p></p>', 'http://www.circtezikova.ru', 'info@circtezikova.com', '[{"value": "73652272005", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/3aeb28a014e88fe1d87973b1fd9157dc.jpg", "title": "circus_facade.jpg"}', NULL, NULL, 'Цирки', 'ГАУ РК «Симферопольский государственный цирк им. Б.Тезикова»', 'Симферополь', 'Europe/Moscow', 'ул Горького,д 3', NULL, 'Респ Крым,г Симферополь,ул Горького,д 3', NULL, 9102067949, 'mincult', 'Республика Крым', 'Europe/Moscow', NULL, 7215, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12580, '[{"url":"https://www.2do2go.ru/places/41830/simferopolskiy-gosudarstvennyy-cirk-im-b-tezikova","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Simferopolskiy-gosudarstvenniy-cirk-im-B-Tezikova-93a","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-31 12:50:12+03', '2016-09-01 20:47:33+03', 5, '0101000020E6100000462BF702B30C4140E57D1CCD91794640');
INSERT INTO "Cirki".cirki_clubs VALUES ('Тульский государственный цирк', 'Тула', 'Europe/Moscow', 'ул Советская,д 96', NULL, 'обл Тульская,г Тула,ул Советская,д 96', '{"type": "Point", "coordinates": [37.626187, 54.189656]}', '<p>Торжественное открытие Тульского цирка состоялось 3 сентября 1963 года. Цирковые представления всегда пользовались большим успехом у зрителей. Здесь готовили программы, становившиеся гордостью советского цирка, с успехом гастролировавшие по планете.</p><p>В 1964 году первой такой программой стал «Цирк на льду». В 1965 году была выпущена тематическая программа «Конный цирк». Она вошла в программу «Тула – Париж» и с успехом показывалась в СССР, Франции и далее во всем мире. В 1967 году в Туле состоялась премьера постановки «Цирк <span>на воде».</span></p><p>В Туле выступали и все звезды советского цирка – клоуны Михаил Румянцев (Карандаш), Олег Попов, Юрий Никулин и Михаил Шуйдин. Туляки аплодировали блистательным программам дрессировщиков: Филатова, Запашного, Бугримовой; иллюзионисту Кио и многим другим.</p><p>В декабре 2015 года, <span>после капитального ремонта,</span><span> </span><span>цирк вновь открыл свои двери для публики, став более</span><span> современным</span><span> и удобным. Сейчас тут можно увидеть лучшие программы и звёзд российского цирка. Тульский цирк продолжает удивлять и восхищать своего зрителя.</span></p><p>Во время представления зрители могут бесплатно посетить самый большой в мире музей <span>клоунов,</span><span> </span><span>коллекция которого составляет б</span><span>олее пяти тысяч экспонатов</span><span>. </span><span> </span></p>', 'http://circus-tula.ru', 'info@circus-tula.ru', '[{"value": "78007000493", "comment": ""}, {"value": "74872311298", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/3e7f955b4ac85a844df641cfc59425fc.jpg", "title": "tulcircus1.jpg"}', '[{"url": "https://all.culture.ru/uploads/59f0e8dde2a5d0e6ce66e1a479917552.jpg", "title": "eff1a45e-d79b-49ca-846b-19a1bd1a5aa1.jpg"}, {"url"