INSERT INTO "Cirki".cirki_clubs VALUES ('Кемеровский государственный цирк', 'Кемерово', 'Asia/Krasnoyarsk', 'пр-кт Ленина,д 56', NULL, 'обл Кемеровская,г Кемерово,пр-кт Ленина,д 56', '{"type": "Point", "coordinates": [86.09940599999999, 55.345304]}', '<p>Первые выступления заезжих балаганных цирковых артистов в Кемерово, в то время называемом еще Щегловск, жители города увидели еще до Октябрьской революции. Однако, по историческим документам такие мероприятия-выступления в городе проходили редко, поэтому были горячо ожидаемы жителями и всегда пользовались успехом.</p><p>После 1917 года артисты стали гастролировать гораздо чаще. Этому способствовало, по-видимому, развитие города, увеличение количества жителей – потенциальных зрителей.</p><p>Со временем стало ясно, что в городе пора строить стационарный цирк. Таким образом, первый «зимний» цирк открыл свои двери в 1932 году. Это было яркое и знаменательное событие в развитии циркового искусства в регионе. На выступлениях гастролирующих артистов постоянно присутствовало много зрителей – зал предусматривал 1602 посадочных мест.</p><p>Несмотря на то, что первое стационарное помещение для цирковых представлений было выполнено из дерева, здание простояло достаточно долгое время. Те, когда-то юные зрители, сегодня приводят на программы уже своих правнуков в современный комплекс, что удачно расположился на проспекте Ленина и по праву украсил Кемерово.</p>', 'http://www.circus-kemerovo.ru', 'info@circus-kemerovo.ru', '[{"value": "73842522312", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/fcb599033f93491259010c5ee4d80bf0.jpg", "title": "_VZwYDG5SmQ.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accou