sonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 315, "name": "Шоу-программа", "sysName": "shou-programma"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12051, '[{"url":"https://www.2do2go.ru/places/43427/kemerovskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Kemerovskiy-gosudarstvenniy-cirk-910","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:57:37+03', '2016-09-19 10:40:02+03', 7, '0101000020E6100000ACC1FBAA5C865540C896E5EB32AC4B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Тверской государственный цирк', 'Тверь', 'Europe/Moscow', 'пл Тверская,д 2А', NULL, 'обл Тверская,г Тверь,пл Тверская,д 2А', '{"type": "Point", "coordinates": [35.901053999999995, 56.858312000000005]}', '<p>В 2014 году Тверской цирк отметил свое 90-летие. Все эти годы цирк остается одним из самых любимых заведений местных жителей. Его история была довольно разнообразной, несколько раз цирк горел, однако тверичи с новыми силами восстанавливали и строили новые здания, только бы цирк жил.</p><p>На манеже Тверского цирка работали практически все знаменитые цирковые артисты России и цирковые программы из Китая, Вьетнама, Румынии, Польши, Чехословакии, Монголии, Венгрии.</p><p>На сегодняшний день Тверской цирк поддерживает единую концепцию развития циркового дела в России и продолжает радовать малышей и родителей сложными, гармоничными и красочными, как и десятки лет назад, представлениями. </p>', 'http://www.circus-tver.ru', 'info@circus-tver.ru', '[{"value": "74822321429", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/28a130918aa6b6ce35332b5a9ce56a3c.jpg", "title": "f654x654px_b5f12d51932f1fd6d7b2d7aba33b6207.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государств