INSERT INTO "Cirki".cirki_clubs VALUES ('Тюленарий', 'Чапаевск', 'Europe/Samara', 'ул Таганрогская,д 21', NULL, 'обл Самарская,г Чапаевск,ул Таганрогская,д 21', '{"type": "Point", "coordinates": [49.69826, 52.954988]}', '<p> Тюленарий основан в 2017 году на базе Центра изучения морских млекопитающих, имеет малый камерный зал вместимостью сорок человек, зрители располагаются непосредственно вокруг бассейна, где и проходят научные и развлекательные программы.</p><p> Программы проходят с участием различных морских млекопитающих, таких как морские зайцы (лахтаки), морские котики, ларги (пестрые нерпы). Для содержания животных имеются бассейны с соленой водой и системой фильтрации для поддержания необходимых параметров воды. </p><p>Коллектив театра очень часто можно встретить на гастролях по различным регионам Российской Федерации.</p>', 'https://тюленарий.рф', 'pticevod@mail.ru', '[{"value": "79240102121"}, {"value": "78462001614"}]', '{"url": "https://all.culture.ru/uploads/d7c4028a90b6409825633091d84c0306.jpeg", "title": "mMaYPSn5rpc.jpg"}', '[{"url": "https://all.culture.ru/uploads/7a9126518c274f791dec4b23182c017b.jpeg", "title": "wccLWMY5g1M.jpg"}]', NULL, 'Цирки', 'ООО ЦИММ «Театр морских животных»', 'Чапаевск', 'Europe/Samara', 'ул Таганрогская,21', NULL, 'обл Самарская,г Чапаевск,ул Таганрогская,21', NULL, 6330075968, 'commercial', 'Самарская область', 'Europe/Samara', NULL, 28729, '[{"id": 122, "name": "Искусство", "sysName": "iskusstvo"}]', NULL, NULL, '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 57312, '[{"url":"https://www.culture.ru/institutes/56970/tyulenarii","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2021-10-07 19:05:35+03', '2022-01-11 10:51:26+03', 9, '0101000020E61000006F0D6C9560D948404609FA0B3D7A4A40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Уфимский государственный цирк', 'Уфа', 'Asia/Yekaterinburg', 'пр-кт Октября,д 73', NULL, 'Респ Башкортостан,г Уфа,пр-кт Октября,д 73', '{"type": "Point", "coordinates": [56.017998000000006, 54.767653]}', '<p>Уфимский государственный цирк был построен и допущен к эксплуатации 5 ноября 1968 года. В Уфимском цирке работал один из лучших оркестров в системе «Союзгосцирка» под руководством В. Крупинского, в последующем удостоенного звания заслуженного работника культуры БАССР. Над созданием Башкирского циркового коллектива также работали композиторы Н. Ахметов, Р. Газизов, В. Свешников, И. Королев, С. Миролюбов.</p><p>Уже более 15 лет в Уфе стало доброй традицией приглашать на премьеры цирковых спектаклей совместно с Администрацией города социально незащищенные слои населения – детей детских домов и приютов г. Уфы и РБ, а также детей из патронажных, малообеспеченных и многодетных семей. Также желанные гости в цирке ветераны боевых действий и инвалиды. <span><br /></span></p>', 'http://www.circus-ufa.ru', 'ufacircus@gmail.com', '[{"value": "73472357908", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d10f7df379bff75ad6fd8a3a00ba3439.jpg", "title": "Image07.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":808