: "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 315, "name": "Шоу-программа", "sysName": "shou-programma"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12049, '[{"url":"https://www.2do2go.ru/places/31911/ufimskiy-gosudarstvennyy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Ufimskiy-gosudarstvenniy-cirk-d34","serviceName":"sputnik"},{"url":"https://kudabashkiria.ru/place/ufimskij-gosudarstvennyj-cirk/","serviceName":"Kuda Bashkiria"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:56:48+03', '2016-09-19 10:32:03+03', 10, '0101000020E61000005CB22AC24D024C4091D6187442624B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Самарский государственный цирк', 'Самара', 'Europe/Samara', 'ул Молодогвардейская,д 220', NULL, 'обл Самарская,г Самара,ул Молодогвардейская,д 220', '{"type": "Point", "coordinates": [50.114799999999995, 53.205107000000005]}', '<p>В конце XIX в. цирковые представления в Самаре давались заезжими труппами в собственных шапито. В 1907 г. местными купцами братьями Калиниными был сооружён капитальный Театр-цирк «Олимп».</p><p>С 1919 г. в городе работал цирк братьев Феррони в специально выстроенном ими здании. В 1921 г. этот цирк был национализирован. В 1928 г. в «Олимпе» давал представления цирковой коллектив под руководством Н. Никитина (цирк «Колосс»). В 1928 г. было построено деревянное здание цирка, которое существовало до 1934 г. В 1936 г. представления возобновились в Струковеком парке в новом цирке-шапито.</p><p>10 августа 1969 г. в Самаре открылось новое здание цирка. Капитальное здание рассчитано на 2185 мест. Место для его строительства было выбрано очень удачно – живописная набережная Волги стала отличным дополнением красивого здания Самарского цирка.</p>', 'http://www.circus-samara.ru', 'info@circus-samara.ru', '[{"value": "78462421115", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/79854cad90afcfdcfa65bcf4f0c29d77.jpg", "title": "b6afdcc49191dd9b5bcfe57adc555417_w2048_h2048.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]