INSERT INTO "Cirki".cirki_clubs VALUES ('Иркутский государственный цирк', 'Иркутск', 'Asia/Irkutsk', 'ул Пролетарская,д 13', NULL, 'обл Иркутская,г Иркутск,ул Пролетарская,д 13', '{"type": "Point", "coordinates": [104.28733499999998, 52.287616]}', '<p>Иркутск стал первым городом в Сибири и на Дальнем Востоке, в котором появился каменный цирк. За время его существования было отработанно более 200 цирковых программ, а это значит, что артисты разных стран и городов России дали более 10 тысяч представлений. По приблизительным подсчетам, за все годы существования в цирке побывало 5 миллионов зрителей.</p><p>Иркутяне впервые увидели то, что могло бы называться цирковым представлением в 1795 году – тогда в город со своей труппой приехал некий Миколлето. В его представлениях не было нужного мастерства, а постановки были просты, но горожане, впервые видевшие акробатов и дрессированных животных, нарекли артиста кудесником.</p><p>Первый стационарный цирк зрители увидели в 1868 году, когда в Иркутске обосновался итальянский антрепренер Сулье. Он на собственные деньги отстроил скромное деревянное помещение в районе нынешнего сквера Кирова, где проводил нехитрые представления и устраивал конные ристалища. Строение прожило недолго – в начале XX века цирк сгорел, и горожане остались без любимого праздничного развлечения.</p>', 'http://circus-irkutsk.ru', 'circusirk38@gmail.com', '[{"value": "73952240535", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/0197bf72df67c59450fa5f84f8990a0f.jpg", "title": "118552.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615",