"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 315, "name": "Шоу-программа", "sysName": "shou-programma"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12047, '[{"url":"https://www.2do2go.ru/places/43423/irkutskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Irkutskiy-gosudarstvenniy-cirk-d00","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:56:02+03', '2016-09-19 10:30:57+03', 12, '0101000020E6100000C0FF56B263125A4036E7E099D0244A40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Нижнетагильский государственный цирк', 'Нижний Тагил', 'Asia/Yekaterinburg', 'ул Первомайская,д 8А', NULL, 'обл Свердловская,г Нижний Тагил,ул Первомайская,д 8А', '{"type": "Point", "coordinates": [59.965905, 57.90462099999999]}', '<p>Впервые цирк в Нижнем Тагиле появился летом 1885 г., когда в городе давал представления семейный цирк-шапито М. Труцци. По-видимому, он был монополистом, поскольку другие цирковые труппы начинают упоминаться только в начале XX в., когда в городе работали временные цирки и цирки-шапито антрепренёров: Ф. Изако, М. Боровского, Э. Строкая, В. Комухина.</p><p>Стационарный цирк появился только спустя несколько десятилетий, когда в 1931 г. в Нижнем Тагиле было возведено каркасно-насыпное утеплённое здание цирка. Строительство цирка вёл Б. Муратов, который ещё много лет был его первым директором. Помещение цирка было тёплым, что позволяло давать представления и зимой.</p><p>Насыпной цирк действовал вплоть до 6 апреля 1975 г., после чего было построено новое капитальное здание. Спроектировано оно было архитекторами: И. Шадриным, Л. Сегалом, Д. Леонтьевым, запланировано на две тысячи зрителей. В нём цирк работает вплоть до настоящего времени. </p><p>23 сентября 2017 года после капитального ремонта обновлённый и современный цирк открылся программой «Здравствуйте, друзья!».</p>', 'http://circus-ntagil.ru', 'info@circus-ntagil.ru', '[{"value": "73435411111", "comment": "касса"}, {"value": "73435418888", "comment": "касса"}]', '{"url": "https://all.culture.ru/uploads/d86960b5b507ce9c13bc054c58865df5.JPG", "title": "Image6.JPG"}', '[{"url": "https://all.culture.ru/uploads/dd742f32928483c3f1545a547db1883a.JPG", "title": "Image12.JPG"}, {"url": "https://all.culture.ru/uploads/ffe6f8e8fb97779b91b6cc2aa74ddf51.JPG", "title": "Image17.JPG"}, {"url": "https://all.culture.ru/uploads/d560e9c19380f619d4ad4a30fdf35c91.JPG", "title": "Image16.JPG"}, {"url": "https://all.culture.ru/uploads/8e97da7bcdbc9c314a04e5befcf3f90e.JPG", "title": "Image18.JPG"}, {"url": "https://all.culture.ru/uploads/13c8b002493aefe3761e048c2e11fe00.jpg", "title": "xlg9pJCZpEU.jpg"}, {"url": "https://all.culture.ru/uploads/d1ccf66b66ba605f416b3453fcf717da.jpg", "title": "G6y0fRGBac4.jpg"}, {"url": "https://all.culture.ru/uploads/084468bb5bdbdda242094583fe31737b.jpg", "title": "nHMO2Yvff6A.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"Брянский государственный цирк","networkId":"56911922790443","updateDate":"2016-09-06T08:22:42Z","createDate":"2016-09-06T08:22:42Z","accountId":9126,"postingGroupId":7878},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 167, "name": "Представление", "sysName": "predstavlenie"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12043, '[{"url":"http://afisha.sputnik.ru/places/Nizhnetagilskiy-gosudarstvenniy-cirk-46e","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:53:56+03', '2019-03-04 15:37:05+03', 13, '0101000020E61000007D0569C6A2FB4D402C23F59ECAF34C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Екатеринбургский государственный цирк', 'Екатеринбург', 'Asia/Yekaterinburg', 'ул 8 Марта,д 43', 'имеется бесплатная парковка', 'обл Свердловская,г Екатеринбург,ул 8 Марта,д 43', '{"type": "Point", "coordinates": [60.604769000000005, 56.825886999999994]}', '<p>Екатеринбургский государственный цирк<span> расположен в живописном месте города Екатеринбурга – на берегу реки Исеть, на пересечении улиц Куйбышева – 8 Марта. Открыт 1 февраля 1980 года. По своей конструкции здания считается одним из лучших в Европе и приспособлен для самых сложных постановок, а его интерьер отделан уральским камнем. В цирке 2371 место, два манежа (основной и репетиционный). Более 20 млн. зрителей посетили цирк за время его существования. Цирк носит имя народного артиста СССР, талантливого дрессировщика Валентина Ивановича Филатова. </span><span>С января 1994 года директором цирка назначен народный артист России Анатолий Павлович Марчевский.</span></p><p>На манеже работали мастера международного класса, такие как народный артист СССР, лауреат Государственной премии РФ Мстислав Запашный, народные артисты, лауреаты Государственной премии Николай Павленко, Тамерлан Нугзаров, народная артистка России Тереза Дурова, народные артисты России Владимир Довейко, династия Корниловых и многие другие, чьи имена составили славу школы циркового искусства России.</p>', 'http://circusekb.ru', 'info@circusekb.ru', '[{"value": "73432572783", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/c58b166d0d2dd06b5436f141b184bb3e.JPG", "title": "__.JPG"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":