te":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882},{"network":"fb","name":"Брянский государственный цирк","networkId":"573695142641918","updateDate":"2016-09-06T07:46:38Z","createDate":"2016-09-06T07:46:38Z","accountId":9127,"postingGroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 315, "name": "Шоу-программа", "sysName": "shou-programma"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12041, '[{"url":"https://www.2do2go.ru/places/32212/ekaterinburgskiy-gosudarstvennyy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Ekaterinburgskiy-gosudarstvenniy-cirk-6a2","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:53:09+03', '2016-09-19 14:59:11+03', 14, '0101000020E61000003C511212694D4E4084984BAAB6694C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Челябинский государственный цирк', 'Челябинск', 'Asia/Yekaterinburg', 'ул Кирова,д 25', NULL, 'обл Челябинская,г Челябинск,ул Кирова,д 25', '{"type": "Point", "coordinates": [61.401520999999995, 55.172465]}', '<p>В октябре 1902 года новый цирк-шапито на торговой площади Южного бульвара открыл П. И. Сайковский, который приглашал на работу проезжих артистов. В помещении цирка проводились также сеансы синематографа. Представления успешно проходили в дни ярмарок и праздников, на пасхальной и масленой неделях. <span>В 1915 году цирк заново перестраивают. </span><span>В 1922 году цирк закрывают на ремонт вплоть до 1930 года.</span></p><p>5 сентября 1930 года торжественно открылось новое помещение цирка на улице Труда. Челябинский цирк выходит на широкую дорогу своей творческой деятельностью.</p><p><span>1 января 1980 года в новом здании цирка состоялось первое представление. Его провел литовский коллектив. На манеже Челябинского государственного цирка выступали такие именитые цирковые династии, как Запашные, Дуровы, Филатовы и многие другие.</span></p>', 'http://www.circus-chelyabinsk.ru', 'info@circus-chelyabinsk.ru', '[{"value": "73512647345", "comment": "касса цирка"}]', '{"url": "https://all.culture.ru/uploads/733b665e2876f41d7bba429e527c3aa7.jpg", "title": "cirk.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateD