GroupId":7876}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 167, "name": "Представление", "sysName": "predstavlenie"}, {"id": 202, "name": "Пантомима", "sysName": "pantomima"}, {"id": 226, "name": "Досуг", "sysName": "dosug"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 315, "name": "Шоу-программа", "sysName": "shou-programma"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 349, "name": "Культура", "sysName": "kultura"}, {"id": 355, "name": "Праздник", "sysName": "prazdnik"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12040, '[{"url":"https://www.2do2go.ru/places/32877/chelyabinskiy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Chelyabinskiy-gosudarstvenniy-cirk-6bb","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:52:47+03', '2016-09-19 14:19:25+03', 15, '0101000020E61000001FD4450A65B34E40325A475513964B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Ставропольский государственный цирк', 'Ставрополь', 'Europe/Moscow', 'пл Имени генерала А.Ермолова,д 2', NULL, 'край Ставропольский,г Ставрополь,пл Имени генерала А.Ермолова,д 2', '{"type": "Point", "coordinates": [41.994757, 45.052385]}', '<p>Открытие нынешнего, стационарного здания Ставропольского цирка на 1746 мест состоялось в 1976 году. Здание оборудовано современной театрально-цирковой техникой.</p><p> С того времени здесь выступали многие прославленные артисты страны и мира. Зрители аплодировали Игорю Кио, Марине Маяцкой, группе Валентина Филатова, выступали коллективы Москвы, Молдавии, Ярославля, Вильнюса, Германии. </p><p> В настоящее время Ставропольский государственный цирк принимает не только звезд цирка, но и популярных представителей Российской эстрады, таких именитых звезд как Филипп Киркоров, Владимир Кузьмин, Ирина Аллегрова, София Ротару, Валерий Меладзе, Татьяна Буланова, Максим, группы Boney M, «Синяя птица», «Ранетки», «Король и Шут», «Алиса», «Руки вверх» и многие другие. </p> <p> Когда издали смотришь на здание Ставропольского цирка, он представляется инопланетным пришельцем или межзвездным кораблем будущего. В его облике есть что-то таинственное, как само цирковое искусство. Поэтому, наверное, и спешат сюда люди, чтобы в который раз удивляться и восторгаться увиденным. Так было раньше и так будет всегда, потому что цирк – это радость самой жизни. </p>', 'http://www.circus-stavropol.ru', 'info@circus-stavropol.ru', '[{"value": "78652280655", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/52df389446a02a1ee022a9f38bcb685e.jpg", "title": "4.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45: