INSERT INTO "Cirki".cirki_clubs VALUES ('Магнитогорский государственный цирк', 'Магнитогорск', 'Asia/Yekaterinburg', 'ул Грязнова,д 55', NULL, 'обл Челябинская,г Магнитогорск,ул Грязнова,д 55', '{"type": "Point", "coordinates": [58.98711, 53.399148000000004]}', '<p>Первый (деревянный) цирк Магнитогорска строился одновременно с возведением промышленного комплекса и нового социалистического города (открыт 11 августа 1931 года).</p><p><span>В 1975 году открылся новый цирк фундаментального здания на 2000 мест. Архитекторы – Л. Б. Сегал, Э. С. Акопов, И. А. Шадрин. Среди директоров – К. Червоткин, Д. Левицкий, П. Воронцов. </span><span>В новом здании цирк начал свою работу с того, что в ноябре 1975 года в нем состоялось торжественное заседание городской общественности, посвящённое 57-й годовщине Октябрьской революции.</span></p>', 'http://www.circus-magnitogorsk.ru', 'info@circus-magnitogorsk.ru', '[{"value": "73519454485", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/188dc15bbeecd27567813ec335b0f145.jpg", "title": "77298.jpg"}', '[{"url": "https://all.culture.ru/uploads/1fde1438089a75465bd359d538da7a3e.jpg", "title": "153038.jpg"}, {"url": "https://all.culture.ru/uploads/6e31a77b80ff4a6bef396dbe8837aa9d.jpg", "title": "1421265f704b5bf14d3c149efcba7555.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016