Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12035, '[{"url":"https://www.2do2go.ru/places/43465/magnitogorskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Magnitogorskiy-gosudarstvenniy-cirk-dd1","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:50:17+03', '2018-11-07 16:00:43+03', 17, '0101000020E6100000FCC6D79E597E4D40C5211B4817B34A40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Краснодарский государственный цирк', 'Краснодар', 'Europe/Moscow', 'ул Рашпилевская,д 147', NULL, 'край Краснодарский,г Краснодар,ул Рашпилевская,д 147', '{"type": "Point", "coordinates": [38.97181034088135, 45.03850936120028]}', '<p>В Краснодаре цирк впервые появился в 1880 году в виде балагана с заезжими артистами. В 1908 было построено первое стационарное деревянное здание цирка на тысячу мест на углу улиц Гудимы и Мира. В 1911–1930 годы в Краснодаре функционировал цирк М. Злобина «Цирк – наша Родина». Выступали коллективы под руководством И. Лебедева, А. Лапиадо. В последующие годы цирковые представления давали в городском парке.</p><p>В 1970 году построено новое стационарное здание Краснодарского цирка. На его арене выступали народные артисты СССР и России А. И. Филатов, М. М. и В. М. Запашные, Карандаш (Румянцев), Олег Попов, Юрий Ермолаев, Владимир Шевченко, Евгений Милаев; народные артисты России Сарват Бегбуди, Юрий Мерденов, Анатолий Корнилов, Игорь Кио.</p>', 'http://krasnodar-circus.ru', 'kcirk@mk.krasnodar.ru', '[{"value": "78612558338", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/58dcfb6c02baaa67282960473f040b28.jpeg", "title": "Заставка_цирк-2.jpg"}', NULL, NULL, 'Цирки', 'ГАУК КК «Краснодарский государственный цирк»', 'Краснодар', 'Europe/Moscow', 'ул Рашпилевская,д 147', NULL, 'край Краснодарский,г Краснодар,ул Рашпилевская,д 147', NULL, 2308216662, 'mincult', 'Краснодарский край', 'Europe/Moscow', NULL, 13945, '[{"id": 24, "name": "История", "sysName": "istoriya"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40320, '[{"url":"https://www.culture.ru/institutes/42719/krasnodarskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2019-10-25 12:22:40+03', '2022-07-29 10:21:57+03', 22, '0101000020E610000000000048647C4340F878EFDFED844640');
INSERT INTO "Cirki".cirki_clubs VALUES ('Волгоградский государственный цирк', 'Волгоград', 'Europe/Samara', 'ул Краснознаменская,д 15', NULL, 'обл Волгоградская,г Волгоград,ул Краснознаменская,д 15', '{"type": "Point", "coordinates": [44.505971, 48.706883]}', '<p>Волгоградский государственный цирк открылся в 1967 году.</p><p>Здание Волгоградского цирка представляет собой настоящее архитектурное творение. Зрительный зал вмещает 1840 мест, просторные вестибюли и фойе, удобные обзорные галереи, позволяющие зрителям во время антракта подышать свежим воздухом – все это как нельзя лучше подготавливает к восприятию циркового представления.</p><p>Самым первым директором Волгоградского цирка был заслуженный работник РФ М. М. Псалти, который стоял у самых истоков этого цирка и руководил его проектированием и строительством. Это его усилиями жители Волгограда получили в подарок это уникальное здание. Это был его второй подарок волгоградцам. Первым было открытие цирка-шапито в разбитом Сталинграде во время войны в 1943 году.</p>', 'http://volgocirk.ru', 'volgocirk@mail.ru', '[{"value": "78442334574", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/c5e226b58e37d8749065ba5e0e25772e.jpg", "title": "oS9NeKBekh0.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId"