INSERT INTO "Cirki".cirki_clubs VALUES ('Красноярский государственный цирк', 'Красноярск', 'Asia/Krasnoyarsk', 'пр-кт им газеты Красноярский Рабочий,д 143А', NULL, 'край Красноярский,г Красноярск,пр-кт им газеты Красноярский Рабочий,д 143А', '{"type": "Point", "coordinates": [92.907585, 55.995589]}', '<p>С 1971 года жителей и гостей города Красноярска артисты цирков радуют своими представлениями в зимнем здании. Строительство «Восьмигранной жемчужины» стало важным событием в жизни города, здание с момента постройки превратилось в настоящую достопримечательность.</p><p><span>История цирков в Красноярске начинается с 1896 года и обязана своим появлением, как и город, своим бурным развитием, строительству Сибирской железной дороги.</span></p>', 'http://www.circus-krasnoyarsk.ru', NULL, '[{"value": "73912331455", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/25d61348266e9c4da20065aff6c1c475.jpg", "title": "0_5fcaa1_16d0acf2_orig.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate