INSERT INTO "Cirki".cirki_clubs VALUES ('Оренбургский государственный цирк', 'Оренбург', 'Asia/Yekaterinburg', 'ул Кобозева,д 45', NULL, 'обл Оренбургская,г Оренбург,ул Кобозева,д 45', '{"type": "Point", "coordinates": [55.091925, 51.76585800000001]}', '<p>В 2015 году исполнилось 80 лет Оренбургскому государственному цирку.</p><p>Согласно историческим документам, первые цирковые труппы выступали в Оренбурге еще в начале XIX века. Тогда в городе проводилось много ярмарок, и на торговых площадях вырастали балаганы, в которые «деды-зазывалы» приглашали зрителей посмотреть выступления цирковых акробатов, жонглёров, фокусников и клоунов. Цирковое искусство особо почиталось жителями города: они всегда гостеприимно встречали цирковых антрепренеров и приезжих артистов.</p>', 'http://orencircus.ru', 'orenburg@circus.ru', '[{"value": "73532776081", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/93ba62b59dde41728f71f1d1b86a3b29.jpg", "title": "78510984.jpg"}', '[{"url": "https://all.culture.ru/uploads/5ee7050b2a72486bd8cd64a788c30f46.jpg", "title": "67745ab0d9d0fbacf80d0e9e471747d5_w2048_h2048.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z