INSERT INTO "Cirki".cirki_clubs VALUES ('Кировский государственный цирк', 'Городской округ город Киров', 'Europe/Moscow', 'пр-кт Октябрьский,д 147', NULL, 'обл Кировская,г Киров,пр-кт Октябрьский,д 147', '{"type": "Point", "coordinates": [49.655473, 58.588134000000004]}', '<p><span>Открытие Кировского цирка состоялось 23 декабря 1977 года. За основу был взят типовой проект, разработанный в Москве Центральным институтом зрелищных сооружений (арх. Л. Сегал), подобного типа цирки существуют и в других городах страны. Например, только в 1971 году были сданы в эксплуатацию сразу четыре аналогичных здания: в Твери, Курске, Рязани и Красноярске. </span></p><p><span>Проектная вместимость цирка – 2000 мест, и хотя фактически количество мест при строительстве было сокращено до 1600, это и теперь считается самый большой зрительный зал города.</span></p>', 'http://кировскийцирк.рф', 'kirov@circus.ru', '[{"value": "78332541136", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f16659bc906cab0772619fdfa7996703.jpg", "title": "0_102311_5911e9ee_XL.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId