", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 424, "name": "Клоунада и пантомима", "sysName": "klounada-i-pantomima"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12017, '[{"url":"https://www.2do2go.ru/places/40391/kirovskiy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Kirovskiy-gosudarstvenniy-cirk-3de","serviceName":"sputnik"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:37:32+03', '2017-09-28 10:44:44+03', 21, '0101000020E61000009C340D8AE6D3484035D593F9474B4D40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Цирковая студия «Мечта»', 'Ишим', 'Europe/Moscow', 'ул Чехова,д 13', 'ост. «Авангард» (маршрут №5, 11к, 6)', 'обл Тюменская,р-н Ишимский,г Ишим,ул Чехова,д 13', '{"type": "Point", "coordinates": [69.521464, 56.11436]}', '<p><span>Цирковая студия «Мечта» – это детский коллектив, который создает отдельные цирковые мини-шоу. Все номера отличаются своеобразием и самобытностью, высоким исполнительским мастерством. </span></p><p><span>Обучающиеся получают не только практические навыки эстрадно-циркового искусства, но и изучают историю его развития, теоретические вопросы деятельности современного цирка и хореографии. Цирковая студия предлагает комплексную программу, овладев которой ребята уже смогут остановиться на наиболее привлекательном для себя жанре: акробатике, клоунаде, гимнастике, жонглировании, дрессировке, эквилибристике.</span></p><p> </p><p><span>Коллектив цирковой студии «Мечта» входит в перечень «Книги Почета» Всероссийского реестра организаций, активно участвующих в социально-экономическом развитии субъектов федерации и муниципальных образований, носит звание «Народный коллектив» с 2004 года.</span></p>', 'http://цирк-мечта.рф', 'meshta69@obl72.ru', '[{"value": "73455154592", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/5ba5be1b794a33ff795fea7c23dd2897.jpg", "title": "2015-12-11 20-48-46.jpg"}', NULL, NULL, 'Цирки', 'МАУК Цирковая студия «Мечта»', 'Ишим', 'Europe/Moscow', 'ул Чехова,д 13', NULL, 'обл Тюменская,р-н Ишимский,г Ишим,ул Чехова,д 13', NULL, 7205018812, 'mincult', 'Ишим', 'Europe/Moscow', NULL, 13101, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:30:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 19866, '[{"url":"https://www.culture.ru/institutes/42764/cirkovaya-studiya-mechta","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/ishim/cirki/10186pl","serviceName":"Афиша7"},{"url":"http://afisha.sputnik.ru/places/Cirkovaya-studiya-Mechta-88e","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/ORC19866","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2016-04-11 12:31:02+03', '2022-11-21 15:10:47+03', 23, '0101000020E6100000A5828AAA5F6151403BFC3559A30E4C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Большой Московский государственный цирк на проспекте Вернадского', 'Москва', 'Europe/Moscow', 'пр-кт Вернадского,д 7', NULL, 'г Москва,г Москва,пр-кт Вернадского,д 7', '{"type": "Point", "coordinates": [37.54029, 55.69449]}', '<p>Cовременное техническое оснащение цирка и пять сменных манежей позволяют задействовать инновационные световые, звуковые технологии, создавать великолепные шоу, раз за разом приводя зрителей в изумление и восхищение. Цирковая программа представлена уникальными номерами. Выступления воздушных гимнастов, жонглеров, канатоходцев, акробатов, эквилибристов, уникальные конно-акробатические номера, шоу с дрессированными тиграми, львами, медведями, собаками, обезьянами и кошками. Яркие, смешные и всегда долгожданные выступления клоунов. </p><p>Звездами представлений в цирке на Вернадского в разное время были Карандаш, Олег Попов, Ирина Бугримова, Юрий Никулин и Михаил Шуйдин, Вера и Юрий Дуровы, Эмиль Кио, Вальтер и Мстислав Запашные, Юрий Куклачев, а также Евгений Милаев и Леонид Костюк, являвшиеся руководителями учреждения. Каждое представление, входящее в программу цирка на проспекте Вернадского, – это номера со зрелищными уникальными трюками, поставленные настоящими профессионалами. Интересные режиссерские решения, чудеса дрессуры, высокое мастерство артистов, восхитительные костюмы и декорации – составляющие незабываемого шоу, впечатляющего всех зрителей от мала до велика. Артистам подвластны любые цирковые жанры и сложнейшие номера.</p>', 'http://www.greatcircus.ru', 'press@greatcircus.ru', '[{"value": "74959300300", "comment": ""}, {"value": "74959302360", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/5f1718620331276fc67c1d013d3b0c98.jpeg", "title": "v699pOxmAvU.jpg"}', '[{"url": "https://all.culture.ru/uploads/3b862f4cd29138e5dfaedd374d1fe7b2.jpeg", "title": "_04I5672.jpg"}, {"url": "https://all.culture.ru/uploads/3dde9ed59956ada54010ad4d11af1b25.jpeg", "title": "_04I6521.jpg"}, {"url": "https://all.culture.ru/uploads/0f47fc999b62a062a6e0cb62ee844b53.jpeg", "title": "_04I3473.jpg"}, {"url": "https://all.culture.ru/uploads/3888a1210cd01676b7da0a703ad7248a.jpeg", "title": "_S2I5383.jpg"}, {"url": "https://all.culture.ru/uploads/7ab7ccf3d520961c2d13c870b1d72c9d.jpeg", "title": "_04I9023.jpg"}, {"url": "https://all.culture.ru/uploads/546b47414d799be18ca6b941e2acd444.jpeg", "title": "_U7A7896.jpg"}, {"url": "https://all.culture.ru/uploads/fbfab75b7b2eee4a1827b96ac081a24f.jpeg", "title": "_U7A7929.jpg"}]', NULL, 'Цирки', 'ГУП «Большой Московский государственный цирк на проспекте Вернадского»', 'Москва', 'Europe/Moscow', 'пр-кт Вернадского,д 7', NULL, 'г Москва,г Москва,пр-кт Вернадского,д 7', NULL, 7736039722, 'othergov', 'Москва', 'Europe/Moscow', '[{"network":"vk","name":"Большой Московский Цирк","networkId":"48016498","updateDate":"2021-03-30T07:22:06Z","createDate":"2021-03-30T07:22:06Z","accountId":35954,"postingGroupId":33135},{"network":"twitter","name":"Цирк на Вернадского","networkId":"3544813755","isPersonal":true,"updateDate":"2021-05-20T09:20:42Z","createDate":"2021-05-20T09:20:42Z","accountId":37902,"postingGroupId":34511}]', 5004, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-48016498&id=456239847&hash=69e4fb1353a07164\" width=\"426\" height=\"240\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', '{"to": "19:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9263, '[{"url":"https://тумба.онлайн/msk/places/63922","serviceName":"Тумба.онлайн"},{"serviceName":"Тумба.онлайн"},{"url":"https://www.culture.ru/institutes/42809/bolshoi-moskovskii-gosudarstvennyi-cirk-na-prospekte-vernadskogo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/moskva/cirki/4807pl","serviceName":"Афиша7"},{"url":"https://opentripmap.com/ru/card/W155217637","serviceName":"OpenTripMap"},{"url":"https://www.2do2go.ru/places/17461/bolshoi-cirk-na-prospekte-vernadskogo","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Bolshoy-Moskovskiy-gosudarstvenniy-cirk-na-prospekte-9c2","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-06-16 12:01:22+03', '2023-01-25 11:58:31+03', 24, '0101000020E61000008C2D043928C5424014B35E0CE5D84B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Государственный цирк Удмуртии', 'Ижевск', 'Europe/Samara', 'ул Красноармейская,д 136', NULL, 'Респ Удмуртская,г Ижевск,ул Красноармейская,д 136', '{"type": "Point", "coordinates": [53.21074309871893, 56.841130133788056]}', '<p>За свою более чем вековую историю Ижевский цирк стал неотъемлемой частью культурной жизни республики, горожан и гостей оружейной столицы России. На ижевском манеже выступали лучшие мастера циркового искусства – Анатолий, Владимир, Юрий и Тереза Дуровы, Николай Гладильщиков, Иван Рубан, Валентин Филатов, Мстислав Запашный, земляк Иван Кудрявцев и многие другие звезды мировой величины. </p><p>Предыдущее здание цирка открылось в конце ноября 1943 года. Поражает мудрость и ответственность государства – самый тяжелый год войны, смерть на фронте, смерть в тылу от недоедания и непосильной работы. До мая 1945 года еще более полутора лет, а государство вводит цирк как символ уверенности в Победе и счастливого будущего детей военного и послевоенного поколений.</p><p> В 1990 году Ижевский цирк не просто закрыли, а прервали связь поколений жителей республики. Восстановить ее было человеческим и гражданским долгом. 1 сентября 2003 года, когда в новый цирк приехали первоклассники со всей Удмуртии, стал одним из самых светлых и добрых в жизни республики в последние годы. </p><p>Сегодняшнее здание Государственного цирка Удмуртии, по мнению специалистов, является одним из лучших в России. Благодаря высокому профессионализму строителей уникальный архитектурный проект реализован в кратчайшие сроки. Цирк оснащен самой современной техникой, высококачественным звуковым и световым оборудованием, что позволяет сделать цирковое представление по-настоящему красочным зрелищем.</p><p> Органично вписалась в цирковой комплекс гостиница «Арена», открытие которой в 2006 году обозначило полное завершение строительства комплекса Государственного цирка Удмуртии. </p><p>С момента открытия арены нового цирка на манеже выступили многие звезды современного мирового циркового искусства. Зрители Удмуртии рукоплескали Татьяне и Александру Филатовым, Николаю Сквирскому, Михаилу Артуру и Карине Багдасаровым, братьям Запашным и многим другим.</p><p> Государственный цирк Удмуртии стал популярным местом отдыха для людей всех возрастов. А добрая традиция открывать каждый цирковой сезон в сентябре представлениями для всех первоклассников республики стала своеобразной визитной карточкой Государственного цирка Удмуртии. Совсем недавно в цирке открылась собственная цирковая детская студия, которая станет трамплином для создания своей труппы.</p><p><span>Новый цирковой комплекс рассчитан на 1 749 мест и оснащен самым современным световым и акустическим оборудованием. </span></p>', 'http://udmcircus.ru', 'udmcircus@udm.ru', '[]', '{"url": "https://all.culture.ru/uploads/4b2cfdf1dee343de98e2c119be850f27.jpg", "title": "92b6aaa4bae499165fe50e6147a57073_w2048_h2048.jpg"}', '[{"url": "https://all.culture.ru/uploads/613a21c56099ef80ca3931a7b133b469.jpeg", "title": "wx1080.jpg"}, {"url": "https://all.culture.ru/uploads/1ca8b7dc69ab6564dcdd9e0c480f4fcc.jpg", "title": "Ижевский цирк-зал-1.jpg"}]', NULL, 'Цирки', 'АУК УР «Государственный цирк Удмуртии»', 'Ижевск', 'Europe/Samara', 'ул Красноармейская,д 136', NULL, 'Респ Удмуртская,г Ижевск,ул Красноармейская,д 136', NULL, 1841011877, 'othergov', 'Удмуртская Республика', 'Europe/Samara', '[{"network":"vk","name":"Государственный Цирк Удмуртии","networkId":"79774283","updateDate":"2023-01-12T09:44:58Z","createDate":"2023-01-12T09:44:58Z","accountId":42708,"postingGroupId":39020},{"network":"twitter","name":"цирк Удмуртии","networkId":"1920198384","isPersonal":true,"updateDate":"2017-06-07T10:32:02Z","createDate":"2017-06-07T10:32:02Z","accountId":15364,"postingGroupId":13265}]', 5905, '[{"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, NULL, NULL, NULL, NULL, '{"to": "15:00:00", "from": "12:00:00"}', '{"to": "15:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10149, '[{"url":"https://www.culture.ru/institutes/42807/gosudarstvennyi-cirk-udmurtii","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/izhevsk/cirki/94129pl","serviceName":"Афиша7"},{"url":"https://visitudmurtia.ru/places/5/gosudarstvennyi-cirk-udmurtii","serviceName":"Visit Udmurtia"},{"serviceName":"Культурный регион"},{"url":"https://www.2do2go.ru/places/40309/izhevskiy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Gosudarstvenniy-cirk-Udmurtii-e0c","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W54951726","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-22 10:58:14+03', '2023-02-28 11:36:23+03', 25, '0101000020E6100000816D3EA1F99A4A406026F826AA6B4C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Севастопольский государственный цирк', 'Севастополь', 'Europe/Moscow', 'ул Пожарова,д 1б', NULL, 'г Севастополь,г Севастополь,ул Пожарова,д 1б', '{"type": "Point", "coordinates": [33.509595, 44.604604]}', '<p>В Севастополе установлен современный цирковой шатер – точно такой же, как стоит в Монте-Карло. Это уникальное сооружение, в котором нет дополнительных опор, конструкций, деталей, которые бы мешали зрительскому восприятию, поэтому гостям одинаково хорошо видно представление и из первого ряда, и из последнего.</p><p>Работа выдающихся мастеров циркового искусства в Севастопольском цирке, который распахнул свои двери в 1986 году, сделала его заслуженно любимым в городе. Сюда вот уже много лет приходят ценители циркового искусства, чтобы увидеть новые программы. На манеже проводились разнообразные мероприятия: конкурсы детских любительских цирковых коллективов, мастер-классы, открытые репетиции и многое другое.</p><p><span>В истории становления Севастопольского цирка немаловажную роль сыграл самый знаменитый клоун России Юрий Никулин, который горячо одобрил инициативу севастопольцев открыть всесезонный стационарный городской цирк. В 1997 году он написал письмо <span>на имя мэра Севастополя </span>и высказал надежду на то, что «Укрцирк» и правительство Украины пойдут городу-герою в этом деле навстречу: выделят законную землю и профинансируют доброе дело. А сам Никулин пообещал для самого первого представления «прислать ряд первосортных номеров Московского цирка…»</span></p> <p><span> Слова великого клоуна, казалось, были услышаны. По инициативе севастопольского предпринимателя Жаркова вначале был разработан шикарный план-макет целого циркового городка, который должен располагаться на улице Парковой. Здесь предусматривалось сооружение красочного шапито, игровых аттракционов, мини-зоопарка, гостиничного комплекса со стоянкой для авто и даже слоновника на восемь африканских «кораблей саванн». </span></p><p><span>К сожалению, этому плану не суждено было исполниться, но цирк шапито в Севастополе на улице Пожарова работает и готов круглогодично принимать цирковые программы и дарить яркие представления и эмоции жителям и гостям города. </span></p>', 'https://www.circus-sevastopol.ru', 'sev@circus.ru', '[{"value": "78692559392", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/a223014c6122f54a2cb566d876e60b36.jpg", "title": "PHOTO-2023-11-02-12-08-10.jpg"}', '[{"url": "https://all.culture.ru/uploads/83e0c3153c943cbef0088a32be735585.jpg", "title": "xi7Dbc6Ug8g.jpg"}, {"url": "https://all.culture.ru/uploads/ee215f995b4b6eb0b89600ed4209670f.jpg", "title": "R5yc8d0Aw-4.jpg"}, {"url": "https://all.culture.ru/uploads/ff226dacb9e5acff20f1ae096963bbdf.jpg", "title": "bvCKvjS4Yk4.jpg"}, {"url": "https://all.culture.ru/uploads/a189949d41d776bc018490930e43dc61.jpg", "title": "P8B5M58UUxo.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 81513, '[{"url":"https://www.culture.ru/institutes/94502/sevastopolskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-10-30 16:42:49+03', '2023-11-09 08:35:53+03', 26, '0101000020E6100000419AB1683AC14040F183F3A9634D4640');
INSERT INTO "Cirki".cirki_clubs VALUES ('Санкт-Петербургский государственный цирк в Автово', 'Санкт-Петербург', 'Europe/Moscow', 'ул Автовская,д 1А', NULL, 'г Санкт-Петербург,г Санкт-Петербург,ул Автовская,д 1А', '{"type": "Point", "coordinates": [30.264835000000005, 59.865149]}', '<p>История цирка в Автово берет начало в 1985 году, когда у парка Победы начали строить Российскую Национальную библиотеку, и для шапито было выбрано место в Кировском районе. На разработку проекта нового цирка и его воплощение ушло 10 лет. От прежней концепции передвижного шатра отказались, поставив цель сделать цирк полустационарным. Это бы позволило проводить представления в любое время года.</p><p> В итоге появилось уникальное здание цирка. Это шапито, но его купол, в отличие от временных шатров, не поддерживается дополнительными опорами, которые бы ухудшили видимость арены для зрителей. Вместимость зрительного зала в несколько раз превышает стандартные для цирков шапито 600–700 и составляет внушительные 1 655 мест.</p><p>На текущий момент слаженная работа служб цирка и широкие технические возможности, представленные конструкцией, позволяют проводить представления мирового уровня практически во всех представленных в цирке жанрах. За все время существование цирка на его манеже выступали выдающиеся артисты: Тамерлан Нугзаров, Людмила Чугунова, Виталий Смолянец, Евгений Майхровский.</p>', 'http://www.circus-avtovo.ru', 'Avtovo@circus.ru', '[{"value": "78127849742", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8ce196772fd60515023802be786ee8a9.jpg", "title": "Y7fbDJl73iE.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 23390, '[{"url":"https://www.culture.ru/institutes/42757/sankt-peterburgskii-gosudarstvennyi-cirk-v-avtovo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sankt-peterbyrg/cirki/12233pl","serviceName":"Афиша7"},{"url":"https://тумба.онлайн/spb/places/61753","serviceName":"Тумба.онлайн"},{"url":"https://opentripmap.com/ru/card/W191472985","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"url":"http://afisha.sputnik.ru/places/Sankt-Peterburgskiy-gosudarstvenniy-cirk-v-Avtovo-f88","serviceName":"sputnik"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2016-09-06 16:16:27+03', '2023-11-01 10:16:15+03', 27, '0101000020E610000010D6FF39CC433E406495D233BDEE4D40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Курский государственный цирк', 'Курск', 'Europe/Moscow', 'ул Александра Невского,зд 4', 'бесплатная парковка перед цирком', 'обл Курская,г Курск,ул Александра Невского,зд 4', '{"type": "Point", "coordinates": [36.18929600000001, 51.725692]}', '<p><span>Жители полюбили это искусство ещё с XIX века, когда на Георгиевской площади стали проводить представления в передвижных цирках Шапито. Георгиевская площадь располагалась в месте, где сейчас находится Пролетарский сквер. Как только приближалась Пасха, на площади появлялись самые разные увеселительные сооружения, балаганы, мини-театры, зверинцы, карусели, открывались небольшие лавки по продаже сладостей и фруктовой воды. Площадь наполнялась народом, а клоуны зазывали на представление в цирк. </span></p><p><span>Цирк посещали первоклассные артисты, а курские газеты всегда писали об этом, делая цирку рекламу. Приезжали знаменитые балаганы Лемана, Робби, обычно выступавшие в Санкт-Петербурге и Москве. </span></p>', 'http://circus-kursk.ru', 'info@circus-kursk.ru', '[{"value": "74712222101", "comment": "касса цирка"}]', '{"url": "https://all.culture.ru/uploads/bbab30101caa17f4260ffc268ec816e3.jpg", "title": "цирк-банкетный зал.jpg"}', '[{"url": "https://all.culture.ru/uploads/8206df49c8ce87d994b025cdb41ad962.jpg", "title": "_DSC5374.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425"