INSERT INTO "Cirki".cirki_clubs VALUES ('Саратовский государственный цирк', 'Саратов', 'Europe/Samara', 'ул им Чапаева В.И.,д 61', 'ост. «Крытый рынок» – авт. № 6, 53, 90, тролл. № 15, микроавт. № 8а, 13, 21, 79, 83', 'обл Саратовская,г Саратов,ул им Чапаева В.И.,д 61', '{"type": "Point", "coordinates": [46.02103299999999, 51.533809]}', '<p><span>Российский цирк начинал свою историю в 1873 году, когда еще молодые, но уже известные в России цирковые артисты – братья Дмитрий, Аким и Петр Никитины, уроженцы и жители Саратовской губернии, – вернулись в родной город после длительного гастрольного турне по Центральной России.</span></p><p>В настоящее время цирк – это стабильно работающее предприятие. За последние 14 лет он неоднократно поощрялся и был награжден штандартом губернатора области, помещался на областную доску почета. За экономические результаты был признан лидером экономического развития, лучшим налогоплательщиком России. Славные традиции, заложенные основателями первого Русского и Саратовского цирка, бережно сохраняются и развиваются.</p>', 'https://www.circus-saratov.ru', 'saratov@circus.ru', '[{"value": "78452990369", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d389a092ff48e5c82ae0801daba46dc2.JPG", "title": "СаратовскийЦирк2023июнь_7.JPG"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"20