, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12054, '[{"url":"https://www.culture.ru/institutes/42778/saratovskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/sar/places/69011","serviceName":"Тумба.онлайн"},{"url":"https://afisha7.ru/saratov/cirki/5747pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/31802/cirk-im-bratev-nikitinykh","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Saratovskiy-gosudarstvenniy-cirk-bf5","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/ORC12054","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-28 17:00:23+03', '2023-10-27 08:55:56+03', 29, '0101000020E610000080919735B1024740BDA772DA53C44940');
INSERT INTO "Cirki".cirki_clubs VALUES ('Новокузнецкий государственный цирк', 'Новокузнецк', 'Asia/Krasnoyarsk', 'ул Кирова,д 70', NULL, 'обл Кемеровская,г Новокузнецк,ул Кирова,д 70', '{"type": "Point", "coordinates": [87.151701, 53.756552]}', '<p>Первый цирк в <span>Новокузнецке</span> появился в 1935 году в виде деревянного <span>шатра</span>, в те времена в цирк приезжали самые знаменитые артисты – клоун <span>Карандаш</span>, династии Дуровых и Филатовых. Со временем здание обветшало, а в <span>1957 году</span> его закрыли.</p><p>В <span>1967 году</span> на <span>улице Кирова</span> забили первую сваю нового здания цирка. <span>30 апреля</span><span> </span><span>1974 года современный цирк </span><span>открыл свои двери для зрителей и дал первое представление. </span>Причем первое представление, как это тогда было принято, здесь устроили для самих строителей. А вскоре в цирке было не протолкнуться из-за толпы счастливых детей, которых мамы и папы привозили не только со всех уголков Новокузнецка, но и из многочисленных городов и поселков юга Кузбасса! Новокузнецкий государственный цирк работал практически всю неделю – и собирал аншлаги! В <a></a>1970-х здесь давали до сотни представлений в месяц. </p><p>Это здание цирка функционирует и по сей день, сегодня оно является еще и главным развлекательным центром Новокузнецка. Жители города преданы своему цирку на протяжении уже многих лет.</p><p> </p><p>Новокузнецкий цирк продолжает жить и радовать публику все новыми программами. За последнее время на манеж выходили артисты программ «Шоу воды, огня и света», «Эпохи», «Цирк зажигает огни». В них участвуют лауреаты множества престижных цирковых фестивалей, артисты Российской государственной цирковой компании и других цирков страны. </p> <p></p><p></p>', 'http://www.circus-novokuznetsk.ru', NULL, '[{"value": "73843579985", "comment": "доп. 3005"}]', '{"url": "https://all.culture.ru/uploads/17a0d13532bebbd6e754bda67107dad8.jpg", "title": "71228044.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12046, '[{"url":"https://www.culture.ru/institutes/42785/novokuzneckii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/novokuzneck/cirki/5740pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/43462/novokuzneckii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Novokuzneckiy-gosudarstvenniy-cirk-565","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/N2001258520","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:55:35+03', '2023-10-26 11:36:50+03', 30, '0101000020E610000050711C78B5C9554098DC28B2D6E04A40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Рязанский государственный цирк', 'Рязань', 'Europe/Moscow', 'ул Лево-Лыбедская,д 34', 'Остановка "Цирк", "Библиотека им. Горького". Автобусы: 1, 7, 11, 13, 17, 18, 21, 23, 48, 57. Троллейбусы: 3,5,6,8,10. Маршрутное такси: 31, 47, 49, 53, 65, 66, 68, 73, 75, 77, 87, 88, 91, 98, 99', 'обл Рязанская,г Рязань,ул Лево-Лыбедская,д 34', '{"type": "Point", "coordinates": [39.74919399999999, 54.631254]}', '<p>Долгие годы жители Рязани довольствовались дававшимися заезжими артистами цирковыми представлениями в сооружениях временного типа. В 1910-е годы в Рязани братья Никитины в летнее время устанавливали временную конструкцию – шапито. В 1914 году в цирке Никитиных состоялось первое цирковое выступление А. Дурова. Дуров развлекал рязанцев скромным номером, в котором были задействованы пять собак. В 1927 году в Рязани усилиями атлета, содержателя чемпионатов французской борьбы Г. Яковлева появился дощатый летний цирк. Различные коллективы арендовали этот цирк в 1929–1931 годах.<br /><br />Открывшийся в 1971 году в самом центре Рязани новый фундаментальный цирк, рассчитанный на 1 700 зрительных мест, стал достопримечательностью города. На арене Рязанского цирка выступали знаменитые цирковые артисты, такие как Юрий Никулин, Маргарита Назарова, братья Запашные, Карандаш, Юрий Куклачев, Ирина Бугримова и другие. Цирк располагает двумя манежами – репетиционным и для выступления. При Рязанском цирке работает цирковая гостиница. Кроме цирковых выступлений, Рязанский цирк принимает известных певцов и артистов. Рязанский государственный цирк принадлежит Росгосцирку.</p>', 'https://www.circus-ryazan.ru', 'ryazan@circus.ru', '[{"value": "74912419110", "comment": "Приемная"}, {"value": "74912419140", "comment": "Колл-центр"}]', '{"url": "https://all.culture.ru/uploads/2c6b06b3cb0628ae62c4d5ebcc07bf54.jpeg", "title": "IMG_2232.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12045, '[{"url":"https://afisha7.ru/ryazan/cirki/54100pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/55697/ryazanskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://opentripmap.com/ru/card/W101850040","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:55:07+03', '2023-10-26 12:52:43+03', 31, '0101000020E6100000002EC896E5DF43400EBC5AEECC504B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Ростовский государственный цирк', 'Ростов-на-Дону', 'Europe/Moscow', 'пр-кт Буденновский,д 45', NULL, 'обл Ростовская,г Ростов-на-Дону,пр-кт Буденновский,д 45', '{"type": "Point", "coordinates": [39.705040999999994, 47.22441]}', '<p>Здание Ростовского цирка необыкновенно, впрочем, глядя на его прямоугольные формы и могучую колоннаду, скорее скажешь, что это театр, но не цирк. И только горельеф, так называемая квадрига на фронтоне да две характерные фигуры по обе стороны от главного входа указывают на его причастность к цирковому искусству.</p><p>Отличается цирк от других и своим внутренним видом. Великолепные фойе, повсюду художественная лепка, позолота, орнаменты, сверкающий хрусталь огромных люстр. Авторы проекта архитекторы Г. Петров и А. Барулин, инженер Н. Щепетов постарались, чтобы кроме удобства зритель получил и эстетическое удовлетворение.</p><p>Но главное отличие цирка – его зрительный зал. При входе в него охватывает ощущение большого масштаба. Вместимость зрительного зала позволяет за одно представление показать шоу почти 1 500 человек.</p><p>В настоящее время Ростовский цирк обладает мощным творческим потенциалом, здесь ищут и готовят молодые артистические кадры, пишут новую музыку, ставят уникальные трюки для воздушных цирковых номеров. А на гастроли приезжают настоящие звезды циркового искусства и именитые коллективы.</p>', 'http://www.circus-rostov.ru', 'rostov@circus.ru', '[{"value": "78632407093", "comment": "Касса"}, {"value": "79913660823", "comment": "Администратор"}]', '{"url": "https://all.culture.ru/uploads/6c6f841ca3a09c465fbb7fc244914df8.JPG", "title": "IMG_9837.JPG"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2