ysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12042, '[{"url":"https://www.culture.ru/institutes/42788/rostovskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/rnd/places/67108","serviceName":"Тумба.онлайн"},{"url":"https://afisha7.ru/rostov-na-donu/cirki/5737pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/33335/rostovskii-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Rostovskiy-gosudarstvenniy-cirk-36c","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/R2900125","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:53:32+03', '2023-10-30 10:43:52+03', 32, '0101000020E610000068AB92C83EDA43409B728577B99C4740');
INSERT INTO "Cirki".cirki_clubs VALUES ('Нижегородский государственный цирк', 'Нижний Новгород', 'Europe/Moscow', 'ул Коммунистическая,д 38', 'В 5 мин. ходьбы от ст. м. «Московская», от Московского ж/д вокзала, от ТЦ «Республика». Можно добраться на метро, на автобусах 2, 5, 17, 22, 34, 37, 47, 48, 95, 138 и пр., на трамваях 1, 4, 6, 7, 21 и пр., на троллейбусах 10, 25 и пр. – все маршруты, идущие до Московского ж/д вокзала.', 'обл Нижегородская,г Нижний Новгород,ул Коммунистическая,д 38', '{"type": "Point", "coordinates": [43.953183, 56.318491]}', '<p><span>Нижегородский цирк – один из старейших в стране (стал третьим после Пензы и Саратова). Его основали известные цирковые продюсеры того времени – братья Никитины. При этом есть несколько аспектов, в которых Нижегородский цирк стал первым: в нижегородском цирке Никитиных впервые зажгли электрический свет, а еще впервые в России на манеже были представления на льду и на воде.</span></p> <p><span>В 2007 году начался новый период в истории Нижегородского цирка. </span><span>1 сентября 2007 года, спустя 23 года реконструкции, Нижний Новгород стал городом, в котором открылся самый крупный цирковой комплекс в Европе. Со своей автономной котельной, огромной конюшней, отдельными помещениями для морских животных, для хищников, для слонов, для собак, для обезьян, с большой современной ветлечебницей. </span><span>В 2021 году цирк принял участие в празднике в честь Дня города «Нижний-800».<span> </span></span></p> <p style="margin-left:0px"><span><span>Сегодня Нижегородский цирк является точкой притяжения горожан и гостей культурного центра региона, привлекая современными цирковыми шоу. </span></span></p><p><span><span>Нижегородский цирк в последнее время стал площадкой для выступления всемирно известных звезд цирка и их программ. В новогодние и рождественские каникулы здесь прошли гастроли Большого Московского цирка и его программы «Страшная сила» с Эдгардом и Аскольдом Запашными в главных ролях. А после начались гастроли ш</span></span><span><span>оу «Пять континентов» Продюсерского центра заслуженного артиста РФ Гии Эрадзе, в котором собраны лучшие номера отечественного цирка.</span></span></p>', 'http://www.circus-nnovgorod.ru', 'nnovgorod@circus.ru', '[{"value": "78312389529", "comment": "Кассы"}]', '{"url": "https://all.culture.ru/uploads/4fef1934c852bd82d045e1e3c87cf9d1.jpeg", "title": "IMG_4966.JPG"}', '[{"url": "https://all.culture.ru/uploads/6e462b5409fa532ba6731e1e83798c0c.jpeg", "title": "2.jpg"}, {"url": "https://all.culture.ru/uploads/df785f7e37aed147c3272bdc1aabaed3.jpeg", "title": "3.jpg"}, {"url": "https://all.culture.ru/uploads/b4ebd3caaea55d35d8376b48a526da9b.jpeg", "title": "1.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12038, '[{"url":"https://www.culture.ru/institutes/42792/nizhegorodskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/nnv/places/74862","serviceName":"Тумба.онлайн"},{"url":"https://afisha7.ru/nizhniy-novgorod/cirki/5733pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/31143/nizhegorodskiy-gosudarstvennyy-cirk","serviceName":"2do2go.ru"},{"url":"https://opentripmap.com/ru/card/R2821198","serviceName":"OpenTripMap"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:52:33+03', '2023-10-27 16:54:56+03', 33, '0101000020E6100000350D8AE601FA454001892650C4284C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Воронежский государственный цирк', 'Воронеж', 'Europe/Moscow', 'ул 20-летия Октября,д 121', NULL, 'обл Воронежская,г Воронеж,ул 20-летия Октября,д 121', '{"type": "Point", "coordinates": [39.18532999999999, 51.655797]}', '<p>Цирк в Воронеже появился еще задолго до того, как было построено первое стационарное здание. Деревянный цирк построен итальянским антрепренером М. Труцци в 1882 году. Цирк Труцци в Воронеже пользовался большим успехом. Он был одним из крупнейших в стране. Выступать в нем было престижно, здесь начинал карьеру известный цирковой артист А. Дуров. Его имя носит Воронежский цирк с 10 ноября 1997 года, а в июле 2008 года в фойе был открыт памятник А. Дурову (автор скульптуры – В. Арсенадзе).<br /></p><p>Воронежский государственный цирк сегодня является филиалом компании «Росгосцирк». Регулярно в город на гастроли приезжают звезды циркового искусства и известные коллективы. Свой творческий путь здесь начинали выдающиеся цирковые артисты И. Золототрубов, Зуев и Тертычный, Л. Шапошников. Более 20 лет цирк возглавлял народный артист России дрессировщик львов Б. Бирюков. <br /></p><p>Воронежский цирк – любимое место досуга зрителей. Помимо проката и показа цирковых представлений здесь проводятся выставки, социально-благотворительные мероприятия, мастер-классы от ведущих, заслуженных артистов циркового искусства, открытые репетиции для всех желающих, которые собирают аншлаги. Цирк активно формирует культурную среду региона.</p>', 'http://www.circus-voronezh.ru', 'voronezh@circus-voronezh.ru', '[{"value": "74732007384", "comment": "Касса"}, {"value": "74732765902", "comment": "Касса"}]', '{"url": "https://all.culture.ru/uploads/543ba6318172cc666a3f748b4afaaeaf.jpg", "title": "tsirk.jpg"}', '[{"url": "https://all.culture.ru/uploads/e438bb7314618b50bacbba67b038e6e0.jpg", "title": "Efxg-vXR8R0.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12036, '[{"url":"https://www.culture.ru/institutes/42794/voronezhskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/vrn/places/64217","serviceName":"Тумба.онлайн"},{"url":"https://afisha7.ru/voronezh/cirki/5731pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/33753/voronezhskiy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Voronezhskiy-gosudarstvenniy-cirk-3bc","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W250926395","serviceName":"OpenTripMap"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:51:25+03', '2023-10-30 16:01:17+03', 34, '0101000020E6100000DC7BB8E4B89743404FE8F527F1D34940');
INSERT INTO "Cirki".cirki_clubs VALUES ('Владивостокский государственный цирк', 'Владивосток', 'Asia/Vladivostok', 'ул Светланская,д 103', NULL, 'край Приморский,г Владивосток,ул Светланская,д 103', '{"type": "Point", "coordinates": [131.906326, 43.116273]}', '<p> Владивостокскому цирку более 100 лет. Впервые жители города увидели цирковое представление в 1885 году в цирке Ламбергера, располагавшемся на Светланской улице в Клубном овраге (сейчас территория Матросского клуба). </p><p>С этого времени во Владивостоке поочередно открывались цирки разной направленности. Их общее число достигает 10. В них выступали как русские, так и иностранные труппы. Об успехах цирка в городе свидетельствует тот факт, что, находясь во Владивостоке в мае 1891 года, цесаревич Николай, наследник царской короны, пожаловал в награду цирку 100 рублей.</p><p>31 декабря 1973 года жители Владивостока и Приморского края получили прекрасный подарок – новое здание цирка на Светланской. В 2017 году он был реконструирован, и здание получило современный облик. Капитальный ремонт проводился в рамках региональной программы «Развитие культуры Приморского края». В ходе работ практически заново залита манежная плита. Строители заменили кровлю и витражи, в цирке появились декоративные элементы из искусственного камня и зеркала, украшенное в морской тематике фойе. </p><p>На сегодняшний день манеж цирка принимает гастролирующие программы практически каждый месяц. Артисты Российской государственной цирковой компании демонстрируют лучшие шоу и невероятные человеческие способности, дарят настоящий праздник поклонникам циркового искусства.</p>', 'https://www.circus-vladivostok.ru', 'vladivostok@circus.ru', '[{"value": "74232228252", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/a894c7841f5f1a75149047105e746cf7.jpg", "title": "2017-10-11.jpg"}', '[{"url": "https://all.culture.ru/uploads/877654c03ee014eea11a08e152ff9716.jpg", "title": "2018-02-24.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12032, '[{"url":"https://www.culture.ru/institutes/71984/vladivostokskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vladivostok/cirki/102400pl","serviceName":"Афиша7"},{"url":"https://opentripmap.com/ru/card/W26686828","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:48:12+03', '2023-10-26 10:29:25+03', 35, '0101000020E61000007730629F007D604033349E08E28E4540');
INSERT INTO "Cirki".cirki_clubs VALUES ('Брянский государственный цирк', 'Брянск', 'Europe/Moscow', 'пр-кт Ленина,д 69', NULL, 'обл Брянская,г Брянск,пр-кт Ленина,д 69', '{"type": "Point", "coordinates": [34.37098900000001, 53.251892]}', '<p>Цирк – одно из самых вместительных зрелищных помещений Брянска. Автор проекта – архитектор Г. В. Наприенко. Здание было введено в эксплуатацию 30 декабря 1974 года. Первое представление состоялось 10 апреля 1975 года. Проект был разработан в 1966 году и подразумевал повторное и многократное применение. </p><p>Брянский цирк принимает в свои гостеприимные объятия все возрастные группы от мала до велика. Профессиональная администрация, улыбчивые контролеры, находчивые униформисты создают непередаваемую атмосферу праздника от фойе до манежа, а на самой арене создают удивительное настроение непревзойденные мастера циркового искусства.</p><p>В разные времена в Брянском цирке выступали такие признанные артисты, как Татьяна Запашная, Тамерлан Нугзаров, Юрий Филатов, Екатерина Венегас, Андрей Дементьев-Корнилов и многие другие.</p><p>В 2022–2023 годах цирк стал гораздо краше и комфортабельнее. Впервые в городе был проведен уникальный художественный фестиваль «Живая стена» на внешней стене конюшни, что само по себе стало достопримечательностью Брянска. Был проведен косметический ремонт закулисной части, гостиницы для артистов и других помещений цирка.</p>', 'http://www.circus-bryansk.ru', 'bryansk@circus.ru', '[{"value": "74832745547", "comment": ""}, {"value": "74832745536", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d42b1e57bfbd0e6f30f1c318327b85f4.jpg", "title": "IMG_20231027_160836.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"