sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12029, '[{"url":"https://afisha7.ru/bryansk/cirki/106691pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/72003/bryanskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://www.2do2go.ru/places/40217/bryanskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Bryanskiy-gosudarstvenniy-cirk-0f3","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W74480929","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:45:25+03', '2023-11-02 16:02:06+03', 36, '0101000020E610000080164B917C2F4140E00F3FFF3DA04A40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Ярославский государственный цирк', 'Ярославль', 'Europe/Moscow', 'ул Свободы,д 69', NULL, 'обл Ярославская,г Ярославль,ул Свободы,д 69', '{"type": "Point", "coordinates": [39.86542700000001, 57.625614]}', '<p>Первый зимний цирк в Ярославле построил Рудольф Гверра в 1850 году. В 1870-е годы К. Вилье давал представления «Гимнастического цирка». В 1913 году ярославец Емельянов построил теплое здание цирка-театра, которое сдавал в аренду, в том числе Э. Труцци, Ц. Арригони, братьям Ефимовым, М. Пемпковскому с его цирком «Фантазия». </p><p>В 1920-х годах заезжие цирковые коллективы выступали в здании, построенном пожарной командой. Первый государственный цирк был возведен в городе в 1937 году. Он был деревянным. Его здание было полностью разрушено во время войны в 1943 году.</p><p>Новый стационарный цирк типового советского проекта построили только в 1963 году. На его арене выступали такие артисты, как Юрий Дуров, Олег Попов, Юрий Никулин, Карандаш, Игорь Кио, Андрей Николаев, Николай Павленко и многие другие. </p><p><span>С апреля 2009 по март 2011 года к 1000-летию Ярославля шла первая за полвека реконструкция давно обветшавшего здания. Открытие отреставрированного цирка состоялось 30 марта 2011 года.</span></p><p><span> В настоящее время Ярославский цирк является не только местом для выступления ведущих цирковых коллективов страны, но и площадкой для реализации социально важных проектов региона.<br /></span></p>', 'http://circus-yaroslavl.ru', 'yaroslavl@circus.ru', '[{"value": "74852608521", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/e19387ebf412a805a3b8bc452608178c.jpeg", "title": "Ярославский цирк.jpeg"}', '[{"url": "https://all.culture.ru/uploads/1d23ef32358b4d90cf12f6f2f6692036.jpeg", "title": "Яр цирк.jpeg"}, {"url": "https://all.culture.ru/uploads/7c50431265cd598ac96fbc58bd4b54a1.jpeg", "title": "Яр цирк1.jpeg"}, {"url": "https://all.culture.ru/uploads/6f29e26d77d18176e72a52e638bdda76.jpeg", "title": "Яр цирк3.jpeg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate"