INSERT INTO "Cirki".cirki_clubs VALUES ('Омский государственный цирк', 'Омск', 'Asia/Omsk', 'пр-кт Карла Маркса,д 43Б', NULL, 'обл Омская,г Омск,пр-кт Карла Маркса,д 43Б', '{"type": "Point", "coordinates": [73.389152, 54.956104]}', '<p>История Омского цирка началась в 1898 году, когда в новом деревянном здании на нынешней улице Партизанской начал давать представления цирк-театр купца Сичкарева. Здесь проходили не только цирковые представления, но и спектакли театральной труппы Долина. В 2016 году Омский цирк вновь открыл свои двери после капитального ремонта.</p><p>Сегодня это одно из самых популярных мест для культурного досуга среди жителей и гостей города. Вместимость зрительного зала – около 1 500 человек. Представления проходят с аншлагами и сопровождаются громкими аплодисментами. На гастроли приезжают титулованные артисты и знаменитые цирковые коллективы, прославленные на весь мир: легендарные шоу Гии Эрадзе, шоу Анатолия Сокола, цирк Филатовых и многие другие.</p>', 'http://www.circus-omsk.ru', 'circusomsk@mail.ru', '[{"value": "73812208197", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/5c73daca0a75aa39954b23d81bcf3742.jpg", "title": "IMG_9832.jpg"}', '[{"url": "https://all.culture.ru/uploads/cfaa1603281de15a5e5d620fa9821772.jpg", "title": "itFiDSaCD7Y.jpg"}, {"url": "https://all.culture.ru/uploads/ad36b658168b16fa47a5485aaabbd391.jpg", "title": "zQTeZ-xWS2M.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","na