 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12022, '[{"url":"https://тумба.онлайн/oms/places/66710","serviceName":"Тумба.онлайн"},{"url":"https://www.culture.ru/institutes/42802/omskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/omsk/cirki/5723pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/32480/omskiy-gosudarstvennyy-cirk","serviceName":"2do2go.ru"},{"url":"https://opentripmap.com/ru/card/W38534010","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:41:39+03', '2023-10-27 17:59:02+03', 38, '0101000020E6100000124BCADDE758524093C9A99D617A4B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Костромской государственный цирк', 'Кострома', 'Europe/Moscow', 'пр-кт Мира,д 26', NULL, 'обл Костромская,г Кострома,пр-кт Мира,д 26', '{"type": "Point", "coordinates": [40.942183, 57.774009]}', '<p style="margin-left:0px"><span>Цирковое искусство как явление появилось в Костроме более 130 лет назад. </span><span>В 1928 году на углу проспекта Текстильщиков и улицы Комсомольской построили деревянное каркасно-засыпное здание стационарного цирка на 1 490 мест. В 1970 году он сгорел. </span><span></span><span>Весной 1984 года, в год 100-летия открытия первого цирка, новое здание на 1 625 мест распахнуло двер для многочисленной публики. <span>Ц<span>ирк</span> <span>носит</span> <span>имя</span> дрессировщицы Эльворти Эльвины Михайловны – заслуженной артистки РСФСР и народной артистки России.</span></span></p> <p style="margin-left:0px"><span>В настоящее время цирк регулярно радует жителей Костромы новыми яркими и зрелищными программами Росгосцирка.<span> На гастроли приезжают титулованные артисты и знаменитые коллективы, прославленные на весь мир: цирк Филатовых, Артур и Карина Багдасаровы, единственный в мире аттракцион «Медведи-канатоходцы» под руководством Александра Иванова, дрессировщица львов в четвертом поколении Ольга Борисова, конно-балетный спектакль Тамерлана Нугзарова и Светланы Авдеевой и многие другие.</span> </span></p>', 'https://sites.google.com/site/kosgoscircus', NULL, '[{"value": "74942558641", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/3b4c1c5b1de7fc2af162cdbbd43a82dd.jpg", "title": "821ee19c73076a9074fe1f4f0b493d5a (1).jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":912