"name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12021, '[{"url":"https://тумба.онлайн/kst/places/65055","serviceName":"Тумба.онлайн"},{"url":"https://www.culture.ru/institutes/42803/kostromskoi-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kostroma/cirki/5722pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/43425/kostromskoi-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Kostromskoy-gosudarstvenniy-cirk-b24","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W176177086","serviceName":"OpenTripMap"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:41:00+03', '2023-10-30 09:45:26+03', 39, '0101000020E610000070ECD97399784440A3E716BA12E34C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Кисловодский государственный цирк', 'Кисловодск', 'Europe/Moscow', 'пр-кт Победы,д 12', 'От станции «Минутка» – маршр. такси № 14, 23, 103ж, 104г до ост. «Музыкальная школа». От ж/д вокзала – маршр. такси № 23, 103ж до ост. «Цирк».', 'край Ставропольский,г Кисловодск,пр-кт Победы,д 12', '{"type": "Point", "coordinates": [42.719716, 43.913954]}', '<p> История цирка в Кисловодске началась еще задолго до даты его официального открытия – 30 июня 1973 года. 2023 год – юбилейный для цирка, ему исполняется 50 лет. Цирк Кисловодска является единственным учреждением такого профиля в районе Кавказских Минеральных Вод. Это уникальное по своей архитектуре сооружение еще и самое большое по вместимости зрителей – одновременно зал может принять 1 483 зрителя. Цирк Кисловодска является визитной карточкой и одной из главных достопримечательностей своего региона. Он воспитал своим чудотворным искусством многие поколения маленьких жителей города и подарил тепло и свет взрослым почитателям циркового искусства. </p>', 'http://circus-kislovodsk.ru', 'kislovodsk@circus.ru', '[{"value": "78793729658", "comment": "Касса"}]', '{"url": "https://all.culture.ru/uploads/a467b18b4f8caa5b3d6458f97e591fef.JPG", "title": "IMG_1352.JPG"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","