umor"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12020, '[{"url":"https://www.culture.ru/institutes/42804/kislovodskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kislovodsk/cirki/5721pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/43464/kislovodskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Kislovodskiy-gosudarstvenniy-cirk-92f","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W314990763","serviceName":"OpenTripMap"},{"serviceName":"Культурная афиша (Одноклассники)"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:39:17+03', '2023-10-26 16:37:52+03', 40, '0101000020E6100000373465A71F5C45403106D671FCF44540');
INSERT INTO "Cirki".cirki_clubs VALUES ('Новосибирский государственный цирк', 'Новосибирск', 'Asia/Krasnoyarsk', 'ул Челюскинцев,д 21', NULL, 'обл Новосибирская,г Новосибирск,ул Челюскинцев,д 21', '{"type": "Point", "coordinates": [82.90967699999999, 55.041756]}', '<p>Впервые отдельные цирковые номера демонстрировались в Новониколаевске (с 1926 года Новосибирск) в начале XX века в балаганах на народных гуляньях. С 1910 года работали антрепризы В. Камухина, А. Коромыслова, Ф. Изако, Э. Стрепетова, В. Янишевского, которые давали представления в деревянных зданиях. Значительное место в программах отводилось состязаниям борцов; выступали ведущие артисты цирка – Сосины, Бим-Бом, А. Дуров, В. Лазаренко. В середине 20-х годов в Новосибирске действовал летний цирк-шапито (директор – Г. Бунин).</p><p>11 февраля 1971 года празднично засияли огни нового цирка. Его строительством начиналась реконструкция старейшего района города Железнодорожного, вдоль улицы Челюскинцев. Сама улица расширялась и благоустраивалась. </p><p> </p><p>Новосибирский государственный цирк сегодня является филиалом компании «Росгосцирк». Регулярно в город на гастроли приезжают звезды циркового искусства и известные коллективы. <br /></p><p>Новосибирский цирк – любимое место досуга зрителей. Помимо проката и показа цирковых представлений здесь проводятся выставки, социально-благотворительные мероприятия, мастер-классы от заслуженных артистов циркового искусства, открытые репетиции для всех желающих, которые собирают аншлаги. Цирк активно формирует культурную среду региона.</p>', 'http://www.circus-novosibirsk.ru', 'circus-sib@mail.ru', '[{"value": "73832359513", "comment": ""}, {"value": "73832044277", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/b3b090c1c2458ba9d6ca89f8db63fae6.jpg", "title": "Новосибирский цирк.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12018, '[{"url":"https://www.culture.ru/institutes/42805/novosibirskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/nsk/places/64834","serviceName":"Тумба.онлайн"},{"url":"https://afisha7.ru/novosibirsk/cirki/5720pl","serviceName":"Афиша7"},{"url":"https://www.2do2go.ru/places/33187/novosibirskii-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Novosibirskiy-gosudarstvenniy-cirk-e01","serviceName":"sputnik"},{"url":"https://opentripmap.com/ru/card/W25643426","serviceName":"OpenTripMap"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:38:24+03', '2023-11-02 17:12:28+03', 41, '0101000020E6100000183BE12538BA5440B534B74258854B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Ивановский государственный цирк', 'Иваново', 'Europe/Moscow', 'пр-кт Ленина,д 42', NULL, 'обл Ивановская,г Иваново,пр-кт Ленина,д 42', '{"type": "Point", "coordinates": [40.974801, 57.003235]}', '<p>Открытие Ивановского государственного цирка состоялось 28 сентября 1933 года. Авторами проекта первого советского государственного цирка были выпускники инженерно-строительного факультета ИВПИ – архитектор С. А. Минофьев и инженер Б. В. Лопатин. </p><p> Весной 1975 года в деревянном цирке прошло последнее представление. Горсовет принял решение о сносе здания. 11 февраля 1983 года состоялось открытие нового здания Ивановского государственного цирка. В 2014 году цирк был закрыт на капитальный ремонт. </p><p> 30 октября 2015 года Ивановский цирк открылся после реконструкции. После переоснащения он стал одним из самых современных цирков в России. Имеет 1 644 места для зрителей. Сейчас Ивановский государственный цирк носит имя династии земляков-канатоходцев Волжанских. Администрация цирка ведет активную социальную политику. Проводятся благотворительные представления, открытые репетиции и мастер-классы.</p><p>За долгие годы работы цирка на его арене выступили многие знаменитые артисты: комики И. С. Радунский и И. О. Вильтазак (дуэт «Бим-Бом»), дрессировщики Дуровы, Б. А. Эдер, Н. П. Гладильщиков, Н. А. Никитин, династия Запашных, известный иллюзионист Э. Кио, династия Филатовых, династия Александровых-Серж, династия Сокол, а также известные на весь мир клоуны О. Попов, Карандаш, В. Лазаренко, А. Юсупов и другие. </p>', 'http://www.circus-ivanovo.ru', 'info@circus-ivanovo.ru', '[{"value": "74932416013", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/ca70fba54d9da20d8081c2a3c157a21f.jpg", "title": "ca649c95c7188042cf8ebaad7417f5b1.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'minc