:"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12044, '[{"url":"https://www.culture.ru/institutes/42786/ivanovskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/ivanovo/cirki/5739pl","serviceName":"Афиша7"},{"url":"https://opentripmap.com/ru/card/R1628769","serviceName":"OpenTripMap"},{"url":"https://www.2do2go.ru/places/43421/ivanovskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Ivanovskiy-gosudarstvenniy-cirk-7cd","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:54:36+03', '2023-11-24 10:56:08+03', 42, '0101000020E6100000D68D7747C67C4440ED9925016A804C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Пермский государственный цирк', 'Пермь', 'Asia/Yekaterinburg', 'ул Уральская,д 112', NULL, 'край Пермский,г Пермь,ул Уральская,д 112', '{"type": "Point", "coordinates": [56.27609789087675, 58.02057235656813]}', '<p>Первое цирковое представление в Перми состоялось в 1884 году. Это был цирк Труцци. В июне 1896 года город посетил Дуров с дрессированными животными. В течение лета 1897 года здесь был цирк Боровского, зверинец Эйгуса, музей восковых фигур Боцва, труппа дагомейцев. Их представления, как и многие другие, проходили в шапито. Позднее было возведено деревянное здание цирка на улице Екатерининской (Большевистской). В начале XX века здание было снесено. Сейчас на этом месте располагается музыкальное училище. В августе 1970 года состоялось открытие нового стационарного цирка.<br /></p><p>Сегодня Пермский цирк – площадка для проведения гастролей больших цирковых программ. Сюда приезжают не только артисты со всей страны, но и зарубежные коллективы, обладатели высших цирковых наград по всему миру, в том числе обладатели «Золотого клоуна» Монте-Карло. В год на арене сменяется порядка 5-6 масштабных цирковых проектов. Пермский цирк собирает под своим куполом жителей и гостей города, вносит разнообразие в досуг граждан и помогает удерживать высокий культурный статус города.</p>', 'http://www.circus-perm.ru', 'perm@circus.ru', '[{"value": "73422738000", "comment": "доб. 3255 (приемная)"}]', '{"url": "https://all.culture.ru/uploads/61b83a00e91eae31b115e69796d26214.jpg", "title": "tempImageFAslg4.jpg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ 