6, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12037, '[{"url":"https://www.culture.ru/institutes/42793/permskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/perm/cirki/5732pl","serviceName":"Афиша7"},{"url":"https://тумба.онлайн/prm/places/67244","serviceName":"Тумба.онлайн"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=e4966cde-49a3-4842-9144-8e7011323b7e&shareType=venue","serviceName":"ФанТам"},{"url":"https://opentripmap.com/ru/card/W24268029","serviceName":"OpenTripMap"},{"url":"https://www.2do2go.ru/places/33571/permskiy-cirk","serviceName":"2do2go.ru"},{"url":"http://afisha.sputnik.ru/places/Permskiy-gosudarstvenniy-cirk-46a","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:52:11+03', '2024-05-13 16:31:36+03', 43, '0101000020E6100000B5E7F92C57234C40B5546F1DA2024D40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Сочинский государственный цирк', 'Сочи', 'Europe/Moscow', 'ул Депутатская,д 8', NULL, 'край Краснодарский,г Сочи,ул Депутатская,д 8', '{"type": "Point", "coordinates": [39.73830547922262, 43.568880834881696]}', '<p>Сочинский цирк находится на пересечении проспектов Пушкина и Курортного, возле прекрасного памятника садово-паркового искусства – дендрария. Удобные обзорные галереи с красочными мозаичными панно, необычные фигуры птиц и животных, искусно выполненных в мраморном полуфойе, – все это подготавливает к восприятию циркового действа, в котором участвуют артисты высочайшего класса. </p><p>Сочи – город с прекрасными цирковыми традициями. Здесь в разное время выступали все звезды русского (в прошлом советского) цирка. Сочинский цирк гостеприимно принимал артистов из Болгарии, Румынии, Польши, Германии, Югославии, Китая и Монголии. Каждый раз, уходя с представления, зрители уносят с собой ощущение праздника, щедро одаривая аплодисментами мужественных, обаятельных людей. </p>', 'http://circus-sochi.ru', 'sochi-circus@mail.ru', '[{"value": "78623000368", "comment": "касса"}]', '{"url": "https://all.culture.ru/uploads/4156eb87ad14b590d312e420b559e962.jpeg", "title": "Фасад 24.jpeg"}', NULL, NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postin