'{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12031, '[{"url":"https://www.culture.ru/institutes/42797/sochinskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sochi/cirki/5728pl","serviceName":"Афиша7"},{"url":"https://тумба.онлайн/sch/places/66278","serviceName":"Тумба.онлайн"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c72efe57-ab91-46c3-85af-c1a244dbf9c8&shareType=venue","serviceName":"ФанТам"},{"url":"https://www.2do2go.ru/places/31426/sochinskii-cirk","serviceName":"2do2go.ru"},{"url":"https://opentripmap.com/ru/card/N736770847","serviceName":"OpenTripMap"},{"url":"http://afisha.sputnik.ru/places/Sochinskiy-gosudarstvenniy-cirk-e33","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:46:58+03', '2024-06-17 10:18:31+03', 44, '0101000020E610000000DC3FCB80DE4340AC915216D1C84540');
INSERT INTO "Cirki".cirki_clubs VALUES ('Тюменский государственный цирк', 'Тюмень', 'Asia/Yekaterinburg', 'ул Первомайская,д 15', NULL, 'обл Тюменская,г Тюмень,ул Первомайская,д 15', '{"type": "Point", "coordinates": [65.534696, 57.152003]}', '<p>История Тюменского цирка началась в XIX в., когда в 1839 г. в городе начали выступать уличные гимнасты. В конце XIX в. выступления проходили в шатрах, а в 1897 г. появилось первое помещение для цирковых выступлений, причем в нем были установлены печи, поэтому представления могли проводиться и зимой. </p><p>Современное здание цирка было открыто в 2004 г. Его зал рассчитан на <span>1 610 мест.</span></p><p>Тюменский цирк с его оригинальной архитектурой является городской достопримечательностью. Ночью цирк украшен иллюминацией. На его крыше установлен металлический шар, который светится ночью. На площадке перед цирком расположены бронзовые статуи знаменитых советских клоунов: Карандаша, Юрия Никулина и Олега Попова. </p>', 'http://www.circus-tyumen.ru', 'tumen@circus.ru', '[{"value": "73452462633", "comment": ""}, {"value": "73452518737"}]', '{"url": "https://all.culture.ru/uploads/fbb20614abbe334a3b2d72f54ecbb394.jpg", "title": "tsirk.jpg"}', '[{"url": "https://all.culture.ru/uploads/493d68b67add858a2e3d1c6717ff3125.jpg", "title": "88476765.jpg"}, {"url": "https://all.culture.ru/uploads/40d2a15483f4caffade95d196915162a.jpg", "title": "Тюменский_цирк-1.jpg"}, {"url": "https://all.culture.ru/uploads/2c3ca934bfd789f9cd98ef43eb793e3b.jpg", "title": "800px-Клоун_Карандаш_у_Тюменского_госцирка.jpg"}, {"url": "https://all.culture.ru/uploads/9edc5788adf210c20c3cf583f0d1feca.jpg", "title": "Статуя_Олега_Попова_у_Тюменского_госцирка.jpg"}, {"url": "https://all.culture.ru/uploads/c58d8248ab3df7f118f7f5e2856d6199.jpg", "title": "Статуя_Юрия_Никулина_у_Тюменского_госцирка.jpg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 80, "name": "Животные", "sysName": "zhivotnye"}, {"id": 156, "name": "Шоу", "sysName": "shou"}, {"id": 268, "name": "Цирковое представление", "sysName": "cirkovoe-predstavlenie"}, {"id": 273, "name": "Отдых и развлечения", "sysName": "otdyh-i-razvlecheniya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 341, "name": "Юмор", "sysName": "yumor"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12053, '[{"url":"https://afisha7.ru/tyumen/cirki/5746pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/42779/tyumenskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://тумба.онлайн/tum/places/83151","serviceName":"Тумба.онлайн"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=ead379e5-bf8c-4201-adde-8446d2a9c62e&shareType=venue","serviceName":"ФанТам"},{"url":"https://www.2do2go.ru/places/43429/tyumenskii-gosudarstvennyi-cirk","serviceName":"2do2go.ru"},{"url":"https://opentripmap.com/ru/card/N412121134","serviceName":"OpenTripMap"},{"url":"http://afisha.sputnik.ru/places/Tyumenskiy-gosudarstvenniy-cirk-6ca","serviceName":"sputnik"},{"serviceName":"Культурная афиша (Одноклассники)"}]', NULL, NULL, NULL, NULL, '2015-07-28 16:59:50+03', '2024-11-14 13:16:13+03', 45, '0101000020E610000054539275386250406BF294D574934C40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Астраханский государственный цирк', 'Астрахань', 'Europe/Samara', 'ул Каховского,д 1А', NULL, 'обл Астраханская,г Астрахань,ул Каховского,д 1А', '{"type": "Point", "coordinates": [48.057649, 46.351713]}', '<p> В XIX веке, когда у народа было мало поводов для развлечений, ярмарка, проходившая каждую неделю, считалась праздником. Именно с этого времени и ведет отсчет цирк в Астрахани. На ярмарках выступали клоуны и акробаты, которые за приемлемую плату смешили народ, демонстрируя свои уникальные навыки. </p><p>Итальянский циркач с предпринимательской жилкой А. Безано заметил любовь народа к такому виду мероприятий и решил организовать постоянный цирк. Местом для тренировок и организации представлений был выбран деревянный дом, который А. Безано соорудил собственноручно. Главными участниками цирка предприимчивого итальянца были его дети и ученики. </p><p>Публика хорошо восприняла новое развлечение, поэтому в 1898 братья Никитины открыли второй цирк. Он тоже был деревянным, но уже имел крышу шатрового типа. В то время в нем ставились театральные миниатюры и показывались представления с клоунами. <br /></p><p>10 апреля 2010 года в торжественной обстановке в Астрахани состоялось открытие обновленного здания цирка. Он вошел в когорту областных видов искусства как социально значимое и любимое астраханцами учреждение культуры. Астраханцы и гости города могут круглый год наслаждаться цирковым искусством. Цирк является украшением площади города, приглашает лучшие цирковые программы, здесь проходят гастроли артистов, с триумфом покоривших многие страны мира.<br /></p>', 'http://www.circus-astrahan.ru', 'info@circus-astrahan.ru', '[{"value": "78512513717", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/09b5cc5b2f254757f085987626d00a9b.jpeg", "title": "WhatsApp Image 2023-10-30 at 15.25.26 (3).jpeg"}', '[{"url": "https://all.culture.ru/uploads/c239e4a884227a7cde87a988931e029a.jpeg", "title": "WhatsApp Image 2023-10-30 at 15.25.26 (4).jpeg"}, {"url": "https://all.culture.ru/uploads/010a14ce90a399fd1fe8648e4b9b3b9d.jpeg", "title": "WhatsApp Image 2023-10-30 at 15.25.26 (2).jpeg"}]', NULL, 'Цирки', 'ФКП «Российская государственная цирковая компания»', 'Москва', 'Europe/Moscow', 'ул Пушечная,д 4/1', NULL, 'г Москва,г Москва,ул Пушечная,д 4/1', NULL, 7702060003, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Брянский  Цирк","networkId":"48760124","updateDate":"2016-09-06T07:45:19Z","createDate":"2016-09-06T07:45:19Z","accountId":9125,"postingGroupId":7875},{"network":"vk","name":"ВОЛГОГРАДСКИЙ ЦИРК","networkId":"12728615","updateDate":"2016-09-26T08:35:10Z","createDate":"2016-09-26T08:35:10Z","accountId":9751,"postingGroupId":8364},{"network":"vk","name":"Кировский цирк [ОФИЦИАЛЬНАЯ ГРУППА]","networkId":"122263425","updateDate":"2016-09-10T11:16:11Z","createDate":"2016-09-10T11:16:11Z","accountId":9409,"postingGroupId":8088},{"network":"vk","name":"Курский государственный цирк","networkId":"130025365","updateDate":"2018-10-19T08:25:55Z","createDate":"2018-10-19T08:25:55Z","accountId":22823,"postingGroupId":20163},{"network":"vk","name":"Ростовский Цирк","networkId":"84001017","updateDate":"2019-08-16T12:16:54Z","createDate":"2019-08-16T12:16:54Z","accountId":22823,"postingGroupId":23597},{"network":"vk","name":"Таганрогский Цирк","networkId":"485750015","isPersonal":true,"updateDate":"2018-05-10T13:24:33Z","createDate":"2018-05-10T13:24:33Z","accountId":21185,"postingGroupId":18782},{"network":"vk","name":"Таганрогский цирк","networkId":"165438687","updateDate":"2018-05-10T13:25:37Z","createDate":"2018-05-10T13:25:37Z","accountId":21185,"postingGroupId":18783},{"network":"vk","name":"Челябинский цирк","networkId":"51313522","updateDate":"2016-10-10T17:11:43Z","createDate":"2016-10-10T17:11:43Z","accountId":10097,"postingGroupId":8635},{"network":"vk","name":"???? НОВОСИБИРСКИЙ ГОСУДАРСТВЕННЫЙ ЦИРК????","networkId":"55664893","updateDate":"2016-09-06T08:43:30Z","createDate":"2016-09-06T08:43:30Z","accountId":9133,"postingGroupId":7880},{"network":"ok","name":"НОВОСИБИРСКИЙ ЦИРК","networkId":"52618356392159","updateDate":"2016-09-06T08:45:11Z","createDate":"2016-09-06T08:45:11Z","accountId":9134,"postingGroupId":7881},{"network":"ok","name":"Цирк Новосибирский","networkId":"569207802079","isPersonal":true,"updateDate":"2016-09-06T08:45:17Z","createDate":"2016-09-06T08:45:17Z","accountId":9134,"postingGroupId":7882}]', 5563, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12023, '[{"url":"https://www.culture.ru/institutes/42801/astrakhanskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/astrahan/cirki/5724pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d2da32cd-f65c-4824-a1ed-a6e3869aa20a&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 12023, NULL, NULL, NULL, '2015-07-28 16:41:53+03', '2024-12-16 15:53:35+03', 46, '0101000020E6100000D4D2DC0A61074840FD497CEE042D4740');
INSERT INTO "Cirki".cirki_clubs VALUES ('Казанский государственный цирк', 'Казань', 'Europe/Moscow', 'пл Тысячелетия,д 2', NULL, 'Респ Татарстан,г Казань,пл Тысячелетия,д 2', '{"type": "Point", "coordinates": [49.100239276885986, 55.79858645990439]}', '<p><span>Казанский государственный цирк – один из старейших в России. Он ведет свою историю с 1890 года, когда братья Никитины построили в центре Казани первое здание стационарного цирка. </span></p><p><span></span><span></span><span>Современному зданию цирка – знаменитой «летающей тарелке» – 57 лет. Это официально признанный памятник архитектуры, шедевр модернизма. Манеж Казанского цирка уникален: он покрыт особенно упругим и крепким каучуком, который разработали по специальному заказу. Такого покрытия нет ни у одного цирка страны. </span><span></span></p> <p><span>В 1969–1989 годах Казанский цирк славился своей национальной труппой – Татарским цирковым коллективом. Имена работавших в нем артистов навсегда вписаны </span><span>в историю российского цирка. </span><span></span><span>Сегодня при цирке работает детская цирковая школа. В ней бесплатно обучаются 150 детей от 6 до 14 лет. </span><span></span></p> <p><span></span><span></span></p>', 'https://kazan-circus.ru', 'mk.circus@tatar.ru', '[{"value": "78432225758", "comment": ""}, {"value": "78432225759", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f037db53bdb1d1b0797d8ef0b3803da7.jpg", "title": "DSCF4179.jpg"}', '[{"url": "https://all.culture.ru/uploads/a2b0830eec5a2452b31f22683939b7c9.jpg", "title": "DSCF4208.jpg"}, {"url": "https://all.culture.ru/uploads/006f4084e543926173e6e18fc58c299c.jpeg", "title": "IMG_0936.jpg"}, {"url": "https://all.culture.ru/uploads/0d74af9abe922965c231c4559549b9db.jpeg", "title": "IMG-20191217-WA0054.jpg"}]', NULL, 'Цирки', 'ГБУК «Казанский государственный цирк»', 'Казань', 'Europe/Moscow', 'пл Тысячелетия,д 2', NULL, 'Респ Татарстан,г Казань,пл Тысячелетия,д 2', NULL, 1654007920, 'mincult', 'Республика Татарстан', 'Europe/Moscow', '[{"network":"vk","name":"Казанский государственный цирк","networkId":"131135893","updateDate":"2019-09-17T12:45:18Z","createDate":"2019-09-17T12:45:18Z","accountId":26807,"postingGroupId":23932}]', 7061, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', '{"to": "18:30:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12228, '[{"url":"https://www.culture.ru/institutes/42776/kazanskii-gosudarstvennyi-cirk","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kazan/cirki/5856pl","serviceName":"Афиша7"},{"url":"https://тумба.онлайн/kzn/places/81746","serviceName":"Тумба.онлайн"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=f77f5f44-4fd7-4436-9d1f-adff52fff9ba&shareType=venue","serviceName":"ФанТам"}]', 12228, NULL, NULL, NULL, '2015-07-30 10:19:00+03', '2025-03-14 15:02:53+03', 47, '0101000020E6100000000000A4D48C4840AD28C41438E64B40');
INSERT INTO "Cirki".cirki_clubs VALUES ('Центр циркового искусства «Цирк Арт-Алле»', 'Саратовская область', 'Europe/Samara', 'пр-кт Ленина,зд 41', NULL, 'обл Саратовская,г Маркс,пр-кт Ленина,зд 41', '{"type": "Point", "coordinates": [46.74362, 51.711921]}', '<p><span>Цирк существует в г. Марксе с 1994 года. Его основали заслуженные работники культуры РФ Сергей и Людмила Соловьевы, их горячо приветствовали зрители и участники коллектива. В 1997 году цирку было присвоено звание «народный».</span></p> <p><span>Новый комплекс «Арт-Алле» в г. Марксе строили 18 лет. Строительство началось в 2004 году, останавливалось из-за отсутствия финансирования и было возобновлено в 2020-м. </span></p> <p><span>Торжественная церемония открытия состоялась 25 декабря 2021 года. Позже был завершен монтаж специализированного оборудования, установлена мебель. Первое представление состоялось 4 марта 2022 года.</span></p> <p><span>В двухэтажном здании, которое спроектировали специально для цирка, есть большой и малый залы, спортзал, зал хореографии и фотозона. Малый зал включает в себя 80 мест, большой – 340 мест.</span></p> <p><span>Сейчас в цирке занимается более 50 артистов. </span></p><p><span></span><span>Воспитанники «Арт-Алле» работают во многих коллективах России и мира – в Большом Московском цирке им. Юрия Никулина на Цветном Бульваре, канадском цирке </span><span>Cirque du Soleil</span> и многих других.</p> <p><span>Цирк представляет Саратовскую область на крупнейших сценических площадках страны. Программа постоянно совершенствуется и дополняется новыми номерами и трюками. Огромное внимание уделяется индивидуально подобранным костюмам, высокопрофессиональному реквизиту и оборудованию. Артисты имеют большой гастрольный опыт за рубежом на популярных концертных площадках и цирковых аренах. </span></p> <p><span>Выпускники отделения циркового искусства филиала Саратовского областного колледжа искусств в г. Марксе выступают и преподают в лучших российских и зарубежных учреждениях.</span></p>', 'http://арт-алле.рф', 'artalle@mail.ru', '[{"value": "78452241025", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/a29ca0df2545ba56647eab47f4ab6362.JPG", "title": "_DSC0152.JPG"}', '[{"url": "https://all.culture.ru/uploads/ccaadbc85424c3d594f13c2d244e020f.jpg", "title": "BNe8x0LU4sc.jpg"}, {"url": "https://all.culture.ru/uploads/241c5e88334c16398e5e8a9503d1f941.jpg", "title": "CXB7AGEzEgA.jpg"}, {"url": "https://all.culture.ru/uploads/5169c3f181b33f9476b323167081ef40.jpg", "title": "jB7YCJe2eSE.jpg"}, {"url": "https://all.culture.ru/uploads/587a9299e480df071cc51b4ef12f217d.jpg", "title": "6urn5IiDLL0.jpg"}, {"url": "https://all.culture.ru/uploads/466689a36906b03da5e53e7b448edb0a.jpg", "title": "6__ZU8bp4Kk.jpg"}, {"url": "https://all.culture.ru/uploads/7d41080ebf307d2413b0130fc8e1a1e2.jpg", "title": "UVA77PCoJeg.jpg"}, {"url": "https://all.culture.ru/uploads/b1e8daa8ff3b9781cbe1a9784ead7900.jpg", "title": "m80CxFYXCyY.jpg"}]', NULL, 'Цирки', 'ГАУК СО «Центр Циркового Искусства «Цирк Арт-Алле»', 'Саратовская область', 'Europe/Samara', 'пр-кт Ленина,зд зд 41', NULL, 'обл Саратовская,г Маркс,пр-кт Ленина,зд зд 41', NULL, 6449101615, 'othergov', 'Саратовская область', 'Europe/Samara', '[{"network":"vk","name":"ГАУКСО Центр циркового искусства \"Цирк Арт-Алле\"","networkId":"210377643","updateDate":"2022-12-13T07:31:47Z","createDate":"2022-12-13T07:31:47Z","accountId":44017,"postingGroupId":38215},{"network":"ok","name":"ГАУК СО Центр циркового искусства \"Цирк Арт-Алле\"","networkId":"58678845898762","updateDate":"2022-12-13T07:32:04Z","createDate":"2022-12-13T07:32:04Z","accountId":44018,"postingGroupId":38216}]', 32931, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73954, '[{"url":"https://www.culture.ru/institutes/86972/centr-cirkovogo-iskusstva-cirk-art-alle","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/marks/cirki/88216pl","serviceName":"Афиша7"},{"url":"https://тумба.онлайн/sar/places/84314","serviceName":"Тумба.онлайн"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=13734a36-4c52-4723-b8a2-347892ee5b3b&shareType=venue","serviceName":"ФанТам"}]', 73954, NULL, NULL, NULL, '2022-12-08 13:13:12+03', '2025-09-04 09:30:15+03', 48, '0101000020E61000006553AEF02E5F4740F52A323A20DB4940');
INSERT INTO "Cirki".cirki_clubs VALUES ('Государственный цирк Республики Саха (Якутия)', 'Якутск', 'Asia/Yakutsk', 'ул Пояркова,д 22', 'автобусы № 16, 17, 18, 19', 'Респ Саха /Якутия/,г Якутск,ул Пояркова,д 22', '{"type": "Point", "coordinates": [129.724129, 62.032449]}', '<p style="">Государственный цирк Якутии имени Марфы и Сергея Расторгуевых был создан по Указу Президента Якутии М. Николаева и по инициативе засл.арт. РФ и РС(Я) Сергея и Марфы Расторгуевых 5 сентября 1994 года. С 2004г. якутский цирк помещается в здании, имеющем форму бриллианта, с залом на 823 мест, поэтому называется «Бриллиантовый цирк». Имеет свою постоянную труппу, собственный оркестр и балет. </p><p style="">В коллективе работают артисты самых различных цирковых жанров – выпускники Московских ГУЦЭИ, ВТМЭИ, Свердловской ЦТМЭИ, Китайского циркового колледжа, Якутского колледжа культуры и искусств. Многие из них являются заслуженными артистами и отличниками культуры Якутии, победителями и призерами международных и всероссийских фестивалей (Монте-Карло, Италия, Испания, Белоруссия, Казахстан, города России др.). Эксклюзивные цирковые спектакли международного уровня – это «Тепло вечной мерзлоты» (2012 г.), этно-шоу «Земля Мамонта» (2023 г.), для которого впервые были изготовлены единственные в мире роботизированные мамонт с мамонтенком. Якутский цирк стал инициатором и организатором республиканского циркового фестиваля (с 1999 г.) и международного циркового фестиваля «МАМОНТенок» и циркового форума (с 2004 г).<span> </span>Уникальная самобытная школа якутского цирка сумела объединить традиции российской (советской) цирковой школы, китайской школы и культурных традиций народов Севера.</p>', 'http://diamond-circus.ru', 'gc@gov14.ru', '[{"value": "74112429002", "comment": "приемная"}, {"value": "79142735537", "comment": "касса"}]', '{"url": "https://all.culture.ru/uploads/3e73d96e1b68f333d3445159f3f28968.jpg", "title": "Цирк.jpg"}', '[{"url": "https://all.culture.ru/uploads/d79f77a7ef8c3ae8b0f29ffb0d438428.jpg", "title": "IMG-20251006-WA0035.jpg"}, {"url": "https://all.culture.ru/uploads/6c314389e2475ac9952cfbce74bb34a4.jpg", "title": "IMG-20251006-WA0037.jpg"}, {"url": "https://all.culture.ru/uploads/1a840800e995cbf2104c3d13ac5d3a15.jpg", "title": "IMG-20251006-WA0041.jpg"}]', NULL, 'Цирки', 'АУ «Государственный цирк РС(Я)»', 'Якутск', 'Asia/Yakutsk', 'ул Пояркова,д 22', NULL, 'Респ Саха /Якутия/,г Якутск,ул Пояркова,д 22', NULL, 1435032377, 'mincult', 'Республика Саха (Якутия)', 'Asia/Yakutsk', NULL, 17843, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 28102, '[{"url":"https://www.culture.ru/institutes/42754/gosudarstvennyi-cirk-respubliki-sakha-yakutiya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/yakutsk/cirki/15007pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=f86890df-85d6-4cbd-a298-e47d46355406&shareType=venue","serviceName":"ФанТам"}]', 28102, NULL, NULL, NULL, '2017-01-18 12:39:45+03', '2025-10-21 12:09:01+03', 49, '0101000020E6100000BAA294102C376040DAE4F04927044F40');
