INSERT INTO muzei.muzei_clubs VALUES ('Вашкинский районный краеведческий музей', 'Вашкинский район', 'Europe/Moscow', 'ул Первомайская,д 20', NULL, 'обл Вологодская,р-н Вашкинский,с Липин Бор,ул Первомайская,д 20', '{"type": "Point"}', '<p>Вашкинский районный краеведческий музей является информационным и культурным центром для всех жителей округа. Предшественником музея был Центр традиционной народной культуры, который был открыт 4 марта 1994 года. В 2006 году центр преобразован в Вашкинский районный краеведческий музей. </p><p> В музее насчитывается более 9 000 экспонатов, которые хранят память и традиции края. Основной фонд музея распределен на коллекции: археология, металл, дерево, керамика, текстиль, нумизматика, письменные памятники, изобразительные источники. В музее представлены постоянно действующие экспозиции «Археология», «Кузнечный промысел», «Берестяной промысел», «Гончарный промысел», «Русская изба», «Спутник женской судьбы», «Народный костюм», «Великая Отечественная война», «Предметы крестьянского быта», «Дом ремесел», «Рыба и рыболовство на Белом озере», а также временные выставки.</p>', NULL, 'lipinbormuseum@rambler.ru', '[{"value": "78175821437", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d09707c87e9db4c479ccca185ef9a1f4.jpg", "title": "Изображение 030.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вашкинский районный краеведческий музей»', 'Вашкинский район', 'Europe/Moscow', 'ул Первомайская,д 20', NULL, 'обл Вологодская,р-н Вашкинский,с Липин Бор,ул Первомайская,д 20', NULL, 3504025916, 'mincult', 'Вашкинский район', 'Europe/Moscow', NULL, 4753, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 15027, '[{"url":"https://afisha7.ru/lipin-bor/muzei-i-galerei/7177pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/20951/vashkinskii-raionnyi-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b9e52cd0-e03c-4abc-9600-7a122fa768f8&shareType=venue","serviceName":"ФанТам"}]', 15027, NULL, 1776, 141904, '2015-09-14 14:18:44+03', '2025-09-17 16:13:05+03', 257, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Сямженский районный краеведческий музей', 'Сямженский район', 'Europe/Moscow', 'ул Советская,д 24', NULL, 'обл Вологодская,р-н Сямженский,с Сямжа,ул Советская,д 24', '{"type": "Point"}', '<p>Сямженский районный краеведческий музей – один из музеев с. Сямжа Сямженского района. Он был создан 4 июня 1991 года. Учредителем является Сямженский муниципальный район. </p><p>В краеведческом музее представлены экспозиции: «Природа», «Солдат и труженик спасли страну», «Археология», «Культура и быт (конец XIX – начало XX в.)». </p><p>Сегодня в собрании музея зарегистрировано более пяти тысяч единиц хранения, есть интересные коллекции прялок, самоваров, берестяных изделий, традиционных народных костюмов и городской одежды конца XIХ века, русской вышивки. Собрано много документов времен Великой Отечественной войны, о событиях становления советской власти в крае, о периоде развития Сямженского района в 70–80 гг. </p><p>Основные направления деятельности музея: научно-исследовательская, научно-фондовая, экспозиционно-выставочная, культурно-просветительская.</p><p>Всегда в продаже сувенирная продукция с символикой района и красивыми местами Сямжи.</p>', 'https://rkm-syamzha.vlg.muzkult.ru', 'museum-skm@mail.ru', '[{"value": "78175221858", "comment": ""}, {"value": "78175221032"}]', '{"url": "https://all.culture.ru/uploads/f162023b422bcd397d7b0c0318cfe0c2.jpeg", "title": "aAJn5Nh_4XE.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК Сямженского МО «Сямженский краеведческий музей»', 'Сямженский район', 'Europe/Moscow', 'ул Советская,д 24', NULL, 'обл Вологодская,р-н Сямженский,с Сямжа,ул Советская,д 24', NULL, 3516003297, 'mincult', 'Сямженский район', 'Europe/Moscow', '[{"network":"ok","name":"Комсомол в моей судьбе! ВЛКСМ - 100 лет!","networkId":"55137242317042","updateDate":"2021-10-12T07:03:25Z","createDate":"2021-10-12T07:03:25Z","accountId":36616,"postingGroupId":35686},{"network":"ok","name":"Музей Краеведческий","networkId":"561119970034","isPersonal":true,"updateDate":"2021-04-08T11:46:09Z","createDate":"2021-04-08T11:46:09Z","accountId":36616,"postingGroupId":33464}]', 4779, '[{"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 15082, '[{"url":"https://afisha7.ru/syamzha/muzei-i-galerei/7207pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/20920/syamzhenskii-raionnyi-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=f3162933-1b7b-4112-8480-5d5d7e65c8bc&shareType=venue","serviceName":"ФанТам"}]', 15082, NULL, 1757, 139016, '2015-09-15 14:41:42+03', '2026-02-18 08:04:06+03', 280, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Чагодощенский музей истории и народной культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Кирова,д 1', NULL, 'обл Вологодская,р-н Чагодощенский,рп Чагода,ул Кирова,д 1', '{"type": "Point"}', '<p><span>Чагодощенский музей – один из самых молодых музеев Вологодской области. Он располагается в центре рабочего поселка Чагода, построенного в 1920–1930-х годах по чертежам известного советского архитектора Н. А. Троцкого. </span></p><p><span>Чагодощенский музей предлагает посетителям 3 постоянных экспозиции, рассказывающие об истории здешних мест: «Древняя и средневековая история края, предметы быта, орудия труда конца XIX – начала XX века», «Природа родного края, промышленность, народное образование и культура времен СССР», «Под стягами отечества». </span></p><p><span>Фонды музея состоят из 13 коллекций. Приоритетными являются «Стекло», «Археология», «Живопись», «Нумизматика», «Документы». С момента образования музея его сотрудники занимаются сбором и изучением изделий из стекла. Ведется научно-исследовательская работа по истории стекольного производства в Чагодощенском крае с XIX века по настоящее время. Ежегодным итогом этой работы становятся выставки стекла, проводимые в рамках празднования Дня стеклоделов.</span></p>', 'http://chagodamuzei.ru/index', 'chagodamuzei@yandex.ru', '[{"value": "78174121658", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/00ac5de529e7c5369d88ef3f8d7a1ad5.jpeg", "title": "dcdd06490ec5681ec3f14a5d35a08213.jpeg"}', NULL, NULL, 'Музеи и галереи', 'Чагодощенский музей истории и народной культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Школьная,д 15', NULL, 'обл Вологодская,р-н Чагодощенский,п Чагода,ул Школьная,д 15', NULL, 3522000583, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 10102, '[{"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 15163, '[{"url":"https://afisha7.ru/chagoda/muzei-i-galerei/7240pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/8276/chagodoshenskii-muzei-istorii-i-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d9eb5f12-dcd2-4b61-a367-7f6fd800c5bb&shareType=venue","serviceName":"ФанТам"}]', 15163, 8276, 1751, 132303, '2015-09-16 16:15:36+03', '2025-12-17 16:56:36+03', 300, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Усть-Кубинский районный краеведческий музей', 'Усть-Кубинский район', 'Europe/Moscow', 'ул Яковлева,д 8', NULL, 'обл Вологодская,р-н Усть-Кубинский,с Устье,ул Яковлева,д 8', '{"type": "Point"}', '<p><span>Муниципальное учреждение культуры "Усть-Кубинский районный краеведческий музей" открыт 8 июля 1995 года. Основную экспозицию составили экспонаты, собранные на территории Усть-Кубинского района в 1986 году экспедицией под руководством А. А. Рыбакова. На 1 января 2025 года м</span><span>узейный фонд составляет более 4 тысяч единиц хранения. </span></p><p><span>Для посетителей открыты один выставочный и два экспозиционных зала. Основная экспозиция музея посвящена истории края, духовно-культурному наследию, развитию ремесел, промыслов и производств. </span></p><p><span>Для посетителей музея проводятся обзорные экскурсии, музейные уроки, лекции, конференции, тематические мероприятия, вечера-встречи, праздники.</span></p>', NULL, 'ustkub.muzey@gmail.com', '[{"value": "78175321659", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/56ed0de6a18d6816eb676b9fc80819fe.jpeg", "title": "91670.660x371.jpg"}', NULL, NULL, 'Музеи и галереи', 'МУК «Усть-Кубинский районный краеведческий музей»', 'Усть-Кубинский район', 'Europe/Moscow', 'ул Яковлева,д 8', NULL, 'обл Вологодская,р-н Усть-Кубинский,с Устье,ул Яковлева,д 8', NULL, 3519003344, 'mincult', 'Усть-Кубинский район', 'Europe/Moscow', NULL, 10105, '[{"name": "Доступная среда"}]', NULL, '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 15165, '[{"url":"https://afisha7.ru/uste/muzei-i-galerei/7241pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/12313/ust-kubinskii-raionnyi-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=a039ccf1-529a-4d74-b095-c5b9b8fe4f9a&shareType=venue","serviceName":"ФанТам"}]', 15165, 12313, 1760, 141923, '2015-09-16 16:19:29+03', '2025-10-31 15:45:22+03', 301, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей-квартира Василия Ивановича Белова', 'Вологда', 'Europe/Moscow', 'ул Октябрьская,д 10', 'подъезд 1, кв. 4', 'обл Вологодская,г Вологда,ул Октябрьская,д 10', '{"type": "Point"}', '<p>Мемориальный музей-квартира Василия Белова – единственный в мире мемориальный музей, посвященный Василию Ивановичу Белову (1932–2012), русскому писателю, одному из крупнейших представителей деревенской прозы.</p><p>Музей предоставляет своим посетителям возможность окунуться в атмосферу второй половины ХХ и начала XXI века, познакомиться с биографией и творчеством русского писателя, чье творчество вошло в сокровищницу современной отечественной литературы. Музей был открыт 21 октября 2015 года в доме, в котором Василий Иванович Белов жил с семьей начиная с 1987 года. Мероприятие состоялось в рамках Года литературы в России и было приурочено ко дню рождения Василия Ивановича Белова. </p><p>В мемориальной квартире посетители увидят подлинные вещи писателя и его семьи. В экспозиции представлено около 1 500 предметов. Обстановка музея, его дух помогают лучше понять и оценить произведения, созданные великим мастером. Неизменной осталась обстановка кабинета Василия Ивановича, его письменный стол, личная библиотека, которая насчитывает более 4 000 томов. Василий Белов очень любил живопись, что отражается в уникальной коллекции изобразительного искусства, включающей и работы самого писателя. Интерес для посетителей представляют комнаты супруги Ольги Сергеевны Беловой и дочери писателя Анны. Многие экспонаты в музее – подарки Василию Белову от многочисленных почитателей его таланта. </p><p>Квартира в годы жизни Василия Ивановича была тем центром, который объединял общественную, культурную, художественную жизнь города: сюда приходили писатели, художники, композиторы, политики, священнослужители; здесь велись многочасовые разговоры о жизни, о литературе, о судьбах страны; здесь бывали Распутин, Крупин, Личутин, Лихоносов, пел романсы Штоколов, выступал Савва Ямщиков и многие другие крупнейшие представители культурной жизни не только Вологодчины, но и всей России. </p><p>У каждого предмета в этой квартире своя история, своя связь с прошлым, с тем временем, когда здесь жил и работал Василий Белов. Здесь им были написаны романы «Год великого перелома», «Час шестый», повести «Бухтины вологодские» и «Повесть об одной деревне», автобиографическая повесть «Невозвратные годы», воспоминания о Василии Шукшине «Тяжесть креста», о Валерии Гаврилине «Голос, рожденный под Вологдой»; многочисленные рассказы, в том числе ставший визитной карточкой писателя «Душа бессмертна»; очерки, публицистические статьи, стихи.</p>', 'https://kirmuseum.org/ru/muzeynie_kompleksi/muzey_kvartira_v_i_belova', 'belovmuseum@yandex.ru', '[{"value": "79211261423", "comment": "директор"}, {"value": "79211420856", "comment": "сотрудники"}]', '{"url": "https://all.culture.ru/uploads/d7bee9d4b59373acec4ded077417a280.jpg", "title": "_DSC4384.jpg"}', '[{"url": "https://all.culture.ru/uploads/8a6be59e9e50cbe7e21809c7796fc799.jpg", "title": "_DSC4367.jpg"}, {"url": "https://all.culture.ru/uploads/39a57f81df7fd4cd04bbbd155e6a7caf.jpg", "title": "_DSC4395.jpg"}, {"url": "https://all.culture.ru/uploads/0016361c9019a7dbeb7ca097d86e068f.jpg", "title": "_DSC4451.jpg"}, {"url": "https://all.culture.ru/uploads/98907f438a4866c7f32decd1280a4bce.jpg", "title": "DSC_1451.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Музей-квартира"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, 'https://kirmuseum.org/belovtour/index.html?scene_name=scene_pano-5139', '["Литературный","Персональный, мемориальный"]', NULL, 15227, '[{"url":"https://www.culture.ru/institutes/20860/muzei-kvartira-vasiliya-ivanovicha-belova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/7289pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=2912cf57-d989-4b7c-b364-83e4ca22b826&shareType=venue","serviceName":"ФанТам"}]', 15227, 20860, NULL, NULL, '2015-09-21 12:20:40+03', '2025-09-02 16:53:41+03', 321, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Народный дом г. Кириллова', 'Кирилловский район', 'Europe/Moscow', 'ул Преображенского,д 3', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Преображенского,д 3', '{"type": "Point"}', '<p>Народный дом – красное двухэтажное здание в центре Кириллова. Его история неразрывно связана с историей города. </p><p><span>Здание было построено в 1916 году на средства купца Петра Симонова. Уроженец Кириллова проживал в Петербурге и скончался в 1910 году. «Желая оставить по себе добрую память на родине», он завещал средства на строительство в городе гостиного двора. При этом Петр Симонов с особой тщательностью указал и назначение, и место, где должно было располагаться здание. Завещание купца выполнили. Но пришла революция, и в жизни гостиного двора начался новый этап. </span></p><p><span>В декабре 1917 года здесь проходил I уездный съезд Советов. А с 1918 года за ним закрепилось название «Народный дом». Впрочем, среди современных жителей Кириллова оно известно также как «Красные ряды». В разное время в здании располагались народный театр, районный Дом культуры, библиотека, магазины. Постепенно оно стало приходить в аварийное состояние, и все учреждения и организации были из него выведены. </span></p><p><span>Несколько лет Народный дом пустовал, но в 2014 году районные власти передали его в безвозмездное пользование Кирилло-Белозерскому музею-заповеднику. </span></p><p><span>С 2015 года в здании проводятся временные выставки. В Народном доме можно познакомиться с художниками современности, увидеть как абстрактное искусство, так и реализм. Именно здесь проходят выставки Виктора и Лидии Казариных, Михаила Копьева, Владислава Сергеева, Михаила Приемышева, Романа Захарова, Людмилы Лупушор, Семена Ганичева, Ольги Карпачевой, Аркадия Полякова, Владимира Кордюкова, Владимира Лупандина, Олега Иванова, Максима Малоземова, Евгения Родионова, Ильи Буслакова и Ильи Оши. </span></p><p><span>Народный дом – площадка для межрегиональных выставок «Редкая иконография», «Иконы Русского Севера», «Прялки Северной Двины», показов мод.</span></p>', 'http://kirmuseum.org', NULL, '[]', '{"url": "https://all.culture.ru/uploads/0721debbd25a59e78357c1e4f6388223.JPG", "title": "Народный дом, 2015.JPG"}', NULL, NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Изобразительного исскуства"]', NULL, 15276, '[{"url":"https://www.culture.ru/institutes/20841/narodnyi-dom-g-kirillova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/7327pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=cfcae899-5340-4e17-a99b-f79a1b06db78&shareType=venue","serviceName":"ФанТам"}]', 15276, NULL, NULL, NULL, '2015-09-23 11:56:05+03', '2025-08-27 16:47:33+03', 328, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Междуреченский музей', 'Междуреченский район', 'Europe/Moscow', 'ул Сухонская Набережная,д 16', NULL, 'обл Вологодская,р-н Междуреченский,с Шуйское,ул Сухонская Набережная,д 16', '{"type": "Point"}', '<p><span> Музей расположен в старинном здании 1840 года постройки, в котором провел детские годы крупный ученый-математик, заведующий кафедрой Санкт-Петербургского университета Александр Николаевич Коркин (1837–1909).</span></p> <p><span> Музей </span><span> </span><span>образован на базе существовавшего ранее районного краеведческого музея, открытого, в свою очередь, на базе Центра традиционной народной культуры. В 1998 году центр был реорганизован в Междуреченский краеведческий музей с созданием сектора краеведения и сектора народного творчества как структурных подразделений.</span></p><p><span>Фонд музея насчитывает более 5 000 единиц. </span> Работают 3 постоянные экспозиции:</p><ol><li> «Крестьянский быт и ремесла Междуречья на рубеже XIX–XX веков». В ее рамках выделена выставка «Как рубашка в поле выросла» (цикл обработки льна), на основе которой разработана интерактивная экскурсия под тем же названием.</li><li> «Храмы Междуречья» – выставка картин самодеятельного художника В. С. Перешивалова.</li><li> «Гостиная конца ХIХ – начала ХХ века». </li><li>Одновременно музей может принять до 40 человек</li></ol><p>Музей – это площадка для творческих людей. Здесь проводятся различные досуговые, традиционные, массовые мероприятия. </p> <p><span><span></span></span></p>', 'http://mezhmuzei.ru', 'mezhmuzei@mail.ru', '[{"value": "78174921073", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/6ceb6386c066643990738166e2c06d73.jpg", "title": "20221202_093812.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Междуреченский районный художественно-краеведческий музей»', 'Междуреченский район', 'Europe/Moscow', 'ул Сухонская Набережная,д 16', NULL, 'обл Вологодская,р-н Междуреченский,с Шуйское,ул Сухонская Набережная,д 16', NULL, 3513002672, 'mincult', 'Междуреченский район', 'Europe/Moscow', NULL, 10670, NULL, NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 16268, '[{"url":"https://www.culture.ru/institutes/20464/mezhdurechenskii-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/shuyskoe/muzei-i-galerei/88600pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d810d59d-92c8-4138-bfaa-abd9959cf4ea&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', 16268, NULL, 1753, 138969, '2015-10-05 14:18:57+03', '2026-04-29 14:50:00+03', 576, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Грязовецкий музей истории и народной культуры', 'Грязовецкий район', 'Europe/Moscow', 'ул Карла Маркса,д 67', NULL, 'обл Вологодская,р-н Грязовецкий,г Грязовец,ул Карла Маркса,д 67', '{"type": "Point"}', '<p>Грязовецкий музей истории и народной культуры располагается в доме купца Разумовского-Машалдина второй половины XIX века. Это здание включено в перечень объектов исторического и культурного наследия федерального значения. В разные годы здесь находились ресторан, мужская гимназия, краеведческий музей, школа для глухонемых детей. В 1978 году краевед Антонина Носкова на общественных началах организовала народный музей, который в 1980 году стал филиалом вологодского музея-заповедника.<br /></p><p>Экспозиции музея посвящены истории Грязовца и Грязовецкого  края с XVIII – начала XIX века до сегодняшнего дня. Музей представлен такими экспозициями, как «Вологодский лен», «Крестьянский дом и все, что в нем», «Грязовец торговый», «Грязовец купеческий», «Дорогами войны» и «Природа родного края». </p>', 'http://gryazovec-muzeum.vgr.muzkult.ru/about', 'muzei.gorod@yandex.ru', '[{"value": "78175521654", "comment": ""}, {"value": "79095940726"}]', '{"url": "https://all.culture.ru/uploads/36c2e39b3090cacb713f2dcc9997f910.jpg", "title": "RM_l07SDmTFvx6gevinelZF8QBjGiDGbAz16SOBUd2N412W25rccGudJ9hnu2DALn2129NTtBRUFN17hjCkUV71J.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Грязовецкий музей истории и народной культуры»', 'Грязовецкий район', 'Europe/Moscow', 'ул Карла Маркса,д 67', NULL, 'обл Вологодская,р-н Грязовецкий,г Грязовец,ул Карла Маркса,д 67', NULL, 3509006554, 'mincult', 'Грязовецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Ассоциация грязовецких художников","networkId":"220960961","updateDate":"2024-12-10T19:04:10Z","createDate":"2024-12-10T19:04:10Z","accountId":52082,"postingGroupId":46805},{"network":"vk","name":"Грязовецкий музей истории и народной культуры","networkId":"40744173","updateDate":"2024-12-10T19:03:26Z","createDate":"2024-12-10T19:03:26Z","accountId":52082,"postingGroupId":46804}]', 10685, '[{"name": "История"}, {"name": "Искусство"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий","Исторический","Этнографический"]', NULL, 16270, '[{"url":"https://afisha7.ru/gryazovec/muzei-i-galerei/64756pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/20462/gryazoveckii-muzei-istorii-i-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=f0798f5f-2a83-458c-8422-1e1f358f5e7e&shareType=venue","serviceName":"ФанТам"}]', 16270, NULL, 1740, 113800, '2015-10-05 14:22:23+03', '2025-11-01 13:26:21+03', 577, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Историко-мемориальный музей А.Я. Яшина', 'Никольский район', 'Europe/Moscow', 'ул Банковская,д 14', NULL, 'обл Вологодская,р-н Никольский,г Никольск,ул Банковская,д 14', '{"type": "Point"}', '<p>В исторической части города Никольска находится двухэтажное здание «Историко-мемориального музея А.Я. Яшина», открытого в 1989 году на базе двух самостоятельных музеев – краеведческого и мемориального.</p><p>В настоящее время музей включает в себя как составляющие: </p><p>1. Здание в городе Никольске, где находятся основные краеведческие и мемориальные экспозиции; </p><p>2. Музей крестьянского быта в д. Блудново; </p><p>3. Историко-мемориальный комплекс писателя А.Я. Яшина на Бобришном Угоре, который является особо охраняемой природной территорией – комплексным (ландшафтным) государственным заказником областного значения. </p>', 'https://xn----itbfgdiahcon1bq9k.xn--p1ai/', 'nikolsk_museum@mail.ru', '[{"value": "78175422252", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/b01ec6eb0ca6e2f1ed10c773c0e6f83b.jpeg", "title": "mus_nik1.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Историко-мемориальный музей А.Я. Яшина Никольского муниципального района»', 'Никольский район', 'Europe/Moscow', 'ул Банковская,д 14', NULL, 'обл Вологодская,р-н Никольский,г Никольск,ул Банковская,д 14', NULL, 3514006510, 'mincult', 'Никольский район', 'Europe/Moscow', NULL, 4831, '[{"name": "История"}, {"name": "Доступная среда"}]', NULL, '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, 'https://xn----itbfgdiahcon1bq9k.xn--p1ai/%d0%b2%d0%b8%d1%80%d1%82%d1%83%d0%b0%d0%bb%d1%8c%d0%bd%d1%8b%d0%b9-%d1%82%d1%83%d1%80/', '["Краеведческий"]', NULL, 18056, '[{"url":"https://www.culture.ru/institutes/7235/istoriko-memorialnyi-muzei-a-ya-yashina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/nikolsk-35/muzei-i-galerei/8955pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c071e6a3-0ba4-47a4-99f8-f7a81ff45fe6&shareType=venue","serviceName":"ФанТам"}]', 18056, 7235, 1738, 113750, '2015-11-30 11:24:35+03', '2025-10-06 10:50:34+03', 742, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Выставочный зал г. Череповца', 'Череповец', 'Europe/Moscow', 'ул Юбилейная,д 36', NULL, 'обл Вологодская,г Череповец,ул Юбилейная,д 36', '{"type": "Point"}', '<p>В выставочном зале, который был открыт в Череповце в 1980 году, собираются и выставляются произведения живописи, графики, скульптуры и декоративно-прикладного искусства. </p><p>Каждый месяц в двух экспозиционных залах представляются новые выставочные проекты, различные по характеру и содержанию, по оформлению и подаче материала, в том числе выставки современного искусства, персональные выставки местных художников, участников МООХ «Солнечный квадрат». Помимо выставок здесь проводятся встречи с художниками, концерты классической музыки и бардовской песни, мастер-классы.</p><p> На базе выставочного зала работает Ресурсный центр творческого развития детей и подростков. Специалисты центра проводят творческие программы, построенные на взаимодействии искусства, науки и образования: «Математика и изобразительное искусство», «От пера до шариковой ручки», цикл занятий «Алхимия искусства» для всех возрастов.</p>', 'http://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493336", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4bb83fc7918377eada714cf6ac4690f5.jpg", "title": "9790e6fd16a1c18d22a7401576c2b467.jpg"}', '[{"url": "https://all.culture.ru/uploads/fab2e6bd36435c88afc16f7c8c2ad53c.JPG", "title": "IMG_8797.JPG"}, {"url": "https://all.culture.ru/uploads/ac45e19a2e93f091e582c2ffd7576811.JPG", "title": "IMG_3045.JPG"}, {"url": "https://all.culture.ru/uploads/375b5c936e08c712a1c9ab6c5d1acfb0.JPG", "title": "IMG_7515.JPG"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "Современное искусство"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Ремесла и художественные промыслы"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Изобразительное искусство"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Изобразительного исскуства"]', NULL, 18122, '[{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/8998pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/12184/vystavochnyi-zal-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1188f277-c1ee-4b4c-8517-bae3e2116340&shareType=venue","serviceName":"ФанТам"}]', 18122, 12184, 4368, NULL, '2015-12-01 09:37:14+03', '2025-09-09 17:37:56+03', 774, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей дипломатического корпуса', 'Вологда', 'Europe/Moscow', 'ул Герцена,д 35', NULL, 'обл Вологодская,г Вологда,ул Герцена,д 35', '{"type": "Point"}', '<p><span>Музей дипломатического корпуса – частный исторический музей в Вологде, расположенный в доме П.Д. Пузан-Пузыревского, в котором в 1918 году размещалось американское посольство. </span><span>Экспозиция знакомит с малоизвестными событиями, происходившими в Вологде с февраля по июль 1918 года и связанными с пребыванием в городе 11 иностранных посольств и миссии.</span></p><p><span>В музее представлены ценные документы, письма, дневники (из архивов России, США, Великобритании, Франции), а также мемориальные вещи участников тех событий, предметы интерьера XX века, воссоздающие атмосферу и быт постреволюционной России.</span><span><br /></span></p>', NULL, NULL, '[{"value": "78817227220", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/6bc0cd279fe2e6f81cc62a0711853b44.jpg", "title": "73478.jpg"}', NULL, NULL, 'Музеи и галереи', 'Музей дипломатического корпуса', 'Вологда', 'Europe/Moscow', 'ул Герцена,д 35', NULL, 'обл Вологодская,г Вологда,ул Герцена,д 35', NULL, NULL, 'commercial', 'Вологда', 'Europe/Moscow', NULL, 12356, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18125, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/9000pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=32c10675-e498-4327-8eac-7ac88f6cd09e&shareType=venue","serviceName":"ФанТам"},{"url":"https://www.culture.ru/institutes/8207/muzei-diplomaticheskogo-korpusa","serviceName":"Культура.рф"}]', 18125, 8207, NULL, NULL, '2015-12-01 10:22:18+03', '2015-12-08 16:19:15+03', 775, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей истории города Кириллова и Кирилловского района', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 103', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 103', '{"type": "Point"}', '<p>В 2010 году в Кирилло-Белозерском музее-заповеднике был создан новый отдел – Музей истории города и района. Здание, где разместилась экспозиция, являлось типичным жилым домом кирилловских горожан конца XIX века. В 1901 году деревянный одноэтажный дом на Большой Набережной (ныне улица Гагарина) принадлежал наследникам крестьянина Алексея Борисовича Кузнецова. В начале ХХ века, по воспоминаниям старожилов, в доме жил врач городской земской больницы Иоаким Яковлевич Нодельман, прослуживший в Кирилловском уездном земстве 35 лет и скончавшийся в 1919 году. </p><p>Затем в разные годы в здании размещались контора леспромхоза, детское отделение районной больницы, детский сад, начальная школа (до 2009 года). В феврале 2010 года по ходатайству Кирилло-Белозерского музея-заповедника администрация Кирилловского района передала пустующее здание в безвозмездное пользование музею. После ремонта в нем разместился отдел музея, изучающий и показывающий историю города Кириллова и Кирилловского района.</p><p>Новый музей не может пока представить историю Кирилловского края во всей ее полноте, но он дает возможность заглянуть в прошлое и увидеть, как жили люди в Кириллове 100 лет тому назад, какие вещи окружали горожан в их повседневной жизни, как преображалась домашняя обстановка в праздничные дни.</p><p>Постоянная экспозиция представляет интерьер жилого городского дома, построенного в конце XIX века. Авторы музейной реконструкции не ставили своей целью показать реально существовавшие интерьеры комнат этого здания, воссоздать их с исторической достоверностью на тот или иной период. Тем не менее воссоздана первоначальная планировка дома, восстановлены растесанные стены с первоначальными дверными проемами, закрыты поздние проемы. Смешение в одном пространстве предметов городского быта разных эпох служит своеобразным напоминанием о нескольких поколениях жителей Кириллова. Обои, характер драпировок на окнах, стилизованные люстры позволяют погрузиться в атмосферу, характерную для конца XIX века – времени строительства дома.</p>', 'http://kirmuseum.org', NULL, '[]', '{"url": "https://all.culture.ru/uploads/5d5380c7129d1f230413ab43e4853ecb.jpg", "title": "IMG_3338 (Custom) (2).jpg"}', '[{"url": "https://all.culture.ru/uploads/25e1797fc49b6914704bd25c919c561b.jpg", "title": "Гостинная.jpg"}, {"url": "https://all.culture.ru/uploads/08c20347909ab848b5b384f7e13d0cc3.jpg", "title": "13_HDR2.jpg"}, {"url": "https://all.culture.ru/uploads/925395a3235fffdca37ebfc47cb22abf.jpg", "title": "1_HDR2.jpg"}, {"url": "https://all.culture.ru/uploads/ce78e3a1208d0615f2692fb35c9f9949.jpg", "title": "3_HDR2.jpg"}, {"url": "https://all.culture.ru/uploads/2d6c6108ed044e528171967998a82cbf.jpg", "title": "4_HDR2.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "История"}, {"name": "Дом-музей"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 19194, '[{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/9712pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/24811/muzei-istorii-goroda-kirillova-i-kirillovskogo-raiona","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=84b1b091-4474-49e3-8a8c-ac8eea2dc9bd&shareType=venue","serviceName":"ФанТам"}]', 19194, 24811, NULL, NULL, '2016-03-02 14:28:22+03', '2025-08-27 16:56:35+03', 914, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музейный комплекс «Цыпино»', 'Кирилловский район', 'Europe/Moscow', NULL, 'автобусное сообщение отсутствует, возможен заказ такси', 'обл Вологодская,р-н Кирилловский,нп Цыпино', '{"type": "Point"}', '<p> В полутора километрах от Ферапонтова монастыря с его знаменитыми росписями Дионисия, которые привлекают множество туристов, расположилось местечко Цыпино, примечательное во многих отношениях.</p><p> Прежде всего, сюда стоит добраться, чтобы полюбоваться старинной деревянной церковью Пророка Илии редкой конструкции, с четырехъярусным шатром и подвесными галереями. Церковь построена в середине XVIII века и стоит на берегу красивейшего и чистейшего Ильинского озера. Расположение этой церкви не случайно: это древний погост, тесно связанный с историей заселения Русского Севера и историей Ферапонтова монастыря. </p><p>Сейчас, кроме деревянной церкви Илии Пророка, мы можем видеть следы кирпичной ограды с остатками ворот и холмом, поросшим травой, под которым скрыт взорванный каменный храм Димитрия Солунского. Сама деревянная Ильинская церковь была спасена от разрушения и отреставрирована в начале 2000-х.</p><p> Если зайти внутрь, можно насладиться абсолютно точно восстановленным интерьером церкви, рассмотреть высокий четырехъярусный иконостас, пройтись по боковым галереям, в которых расположена экспозиция, посвященная деревянному зодчеству Русского Севера и истории самой Ильинской церкви, а также необыкновенным людям, жизнь и деятельность которых была связана с этими местами. <br /></p>', 'https://kirmuseum.org/ru/muzeynie_kompleksi/muzeyniu_kompleks_cypino', 'museum@kirmuseum.org', '[{"value": "78175749261", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/96e551b48a90876a741f3b45faccfa6d.jpg", "title": "724_slide_img1.jpg"}', '[{"url": "https://all.culture.ru/uploads/64277d30e21c8ae23c9113b3a58d48fc.jpg", "title": "723_slide_img2.jpg"}, {"url": "https://all.culture.ru/uploads/a51dc51ec4ad4682587744f3fa88ba48.jpg", "title": "723_slide_img3.jpg"}, {"url": "https://all.culture.ru/uploads/b534c0fd125caa6c3bfbee07245dbf5a.jpg", "title": "66_slide_img2.jpg"}, {"url": "https://all.culture.ru/uploads/4ad30351c568c630d917421e1641e2ff.jpg", "title": "724_slide_img2.jpg"}, {"url": "https://all.culture.ru/uploads/8120c07296d933ba48be9eeb87f6ce72.jpg", "title": "66_slide_img3.jpg"}, {"url": "https://all.culture.ru/uploads/cf1d785eaf2679bc6f3ccc4c33fcb127.jpg", "title": "725_slide_img1.jpg"}, {"url": "https://all.culture.ru/uploads/43c1335e072ca31885031c7e249e1113.jpg", "title": "725_slide_img2.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "История"}, {"name": "Открытые площадки"}, {"name": "Музеи-храмы"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей-храм, монастырь"]', NULL, 23920, '[{"url":"https://www.culture.ru/institutes/66677/muzeinyi-kompleks-cypino","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/88114pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b44994bd-a5ce-4567-a5b9-3feabe807873&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', 23920, NULL, NULL, NULL, '2016-09-09 12:43:38+03', '2025-04-30 09:34:10+03', 1183, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей истории и культуры Великого Устюга', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', '{"type": "Point"}', '<p>Постоянные экспозиции музея посвящены истории и культуре Великого Устюга XII–ХХ веков. </p> <p>Археологические находки, предметы вооружения XII–XVI веков и другие материалы свидетельствуют о раннем периоде в истории города, об участии устюжан в создании единого Русского государства.</p> <p>В залах представлены подлинные предметы из коллекций музея, отражающие вклад устюжан в освоение Сибири и территорий Русской Америки, в развитие торговли со странами Западной Европы и Китаем.</p> <p>Подлинники XVII–XIX веков представляют Великий Устюг как крупный торгово-ремесленный центр. В витринах – превосходные изделия устюжских мастеров. Это иконы, просечные шкатулки, финифть и филигрань. Здесь можно увидеть серебряные изделия с черневой гравюрой, в том числе уникальную трехчастную дарохранительницу (1770). Отдельный зал посвящен самобытному художественному промыслу Великого Устюга – резьбе и росписи по бересте.</p> <p>В музее проводятся мастер-классы и интерактивные занятия для детей.</p>', NULL, NULL, '[{"value": "78173823576", "comment": "служба приёма"}, {"value": "78173823629", "comment": "научные сотрудники"}]', '{"url": "https://all.culture.ru/uploads/6b1e88ea473c176cce301c61a52ce435.jpg", "title": "Дом Усова Музей истории.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "История"}, {"name": "Коллекции"}, {"name": "Ремесла и художественные промыслы"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический","Художественный","Художественных ремесел"]', NULL, 29894, '[{"url":"https://www.culture.ru/institutes/55067/muzei-istorii-i-kultury-velikogo-ustyuga","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/57586pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=85716f76-7e37-4b09-a6b5-d5043222f3dc&shareType=venue","serviceName":"ФанТам"}]', 29894, NULL, NULL, NULL, '2017-04-25 11:49:40+03', '2025-11-01 13:17:08+03', 1424, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей природы г. Великий Устюг', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 65', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 65', '{"type": "Point"}', '<p> Музей природы расположен во флигеле бывшего дома купца Г. В. Усова. </p><p>Светозвуковая экспозиция «Русский Север. Времена года» знакомит с животным и растительным миром края. В панорамной витрине можно увидеть кошку рысь и енотовидную собаку, лесных куликов вальдшнепов и семью медведей, выполненных корифеем отечественной таксидермии Н. К. Назьмовым. </p> <p>Экспозиция «Живое прошлое Земли» посвящена палеонтологическим находкам и открытиям, сделанным в окрестностях Великого Устюга. Здесь представлены зубы, костные щитки, ребра парейазавров, слепки черепов пермских ящеров, впервые найденных на Устюжской земле, а также кости животных ледникового периода. Посетители смогут собрать макет скелета парейазавра. </p> <p>В зале «Хозяин тайги» можно познакомиться с бурым медведем, его внешним видом, отпечатками лап, повадками, побывать в берлоге, «зайти в гости» к трем медведям.</p> <p>О березе и ее значении в жизни природы и человека рассказывает экспозиция «Русская береза».</p><p style="text-align:justify"></p>', 'http://ustyug-museum.ru/mus-priroda', NULL, '[{"value": "78173823576", "comment": "служба приёма"}, {"value": "78173823397", "comment": "музей природы"}]', '{"url": "https://all.culture.ru/uploads/9fe457ccc92051fe89ec0e00c2bde0cc.jpg", "title": "EbYG1DvBDX4.jpg"}', '[{"url": "https://all.culture.ru/uploads/6ad75b07adb307d7e68edb09b9526bf2.jpg", "title": "Диорама 1.jpg"}, {"url": "https://all.culture.ru/uploads/4b646a03208f24bd219ef52e48e17d3e.jpg", "title": "Диорама 2.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Палеонтология"}, {"name": "Коллекции"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Биологический","Палеонтологический"]', NULL, 29895, '[{"url":"https://www.culture.ru/institutes/53317/muzei-prirody-g-velikii-ustyug","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/57587pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=df167ef1-b7c6-4f3c-9ae2-5746885189ca&shareType=venue","serviceName":"ФанТам"}]', 29895, NULL, 4493, NULL, '2017-04-25 11:54:21+03', '2025-11-01 13:12:55+03', 1425, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей древнерусского искусства г. Великого Устюга', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 84', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 84', '{"type": "Point"}', '<p><span> М</span><span>узей расположен в уникальном памятнике архитектуры середины XVII века – церкви Вознесения. </span><span>Это один из самых красивых памятников Русского Севера. В храме сохранились неповторимые иконостасы XVIII века. </span></p><p><span> В музее широко представлены</span><span> </span><span>памятники</span><span> </span><span>устюжской иконописи XV–XVII веков, произведения строгановского лицевого шитья, рукописные и старопечатные книги из библиотек устюжских монастырей и церквей. Доминанты экспозиции – выдающиеся произведения устюжского искусства: чудотворная икона «Богоматерь Одигитрия Смоленская» (около 1558) и резная Сень царских врат (ХVII в.), храмовая икона</span><span> </span><span>Успенского собора</span><span> </span><span>«Успение Богоматери» (1496) и поклонный резной белокаменный крест (1625), вытесанный мастером Мисаилом в память преставления небесного покровителя Устюга святого Прокопия Праведного, плащаница «Положение во гроб» ХV столетия, плащаницы ХVII века – вклады именитых людей Строгановых в устюжские храмы.</span></p><p style="margin-left:0cm;text-align:justify"> </p><p><span>Музей древнерусского искусства дает возможность устюжанам и многочисленным гостям города открыть значение Великого Устюга как крупного культурного центра Русского Севера, прикоснуться к духовно-нравственным истокам русской культуры.</span></p><p><span> Часть пространства музея превратилась в мастерскую иконописца – для детей и взрослых здесь проходят мастер-классы «В иконописной мастерской».</span><span> </span></p>', 'http://ustyug-museum.ru/mus-icons', 'voznesenie1648@yandex.ru', '[{"value": "78173823576", "comment": "Служба приёма"}, {"value": "78173823405", "comment": "Музей древнерусского искусства"}]', '{"url": "https://all.culture.ru/uploads/81342a622bb06f3cdbbff5eefd55437c.jpg", "title": "Церковь Вознесения 4.jpg"}', '[{"url": "https://all.culture.ru/uploads/d4904ad32e1f8134096924e665f48d72.jpg", "title": "В иконописной мастерской 1.jpg"}, {"url": "https://all.culture.ru/uploads/15c7dec627fcd4ce770df27abf380b40.jpg", "title": "В иконописной мастерской С улыбкой.jpg"}, {"url": "https://all.culture.ru/uploads/a608bedb9ac6a0d11adb7345d76e7c9e.jpg", "title": "Икона Одигитрия.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}, {"name": "Изобразительное искусство"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Архитектурный","Художественный","Дек.прикладного и нар. искусства","Исторический","Изобразительного исскуства","Музеи скульптуры"]', NULL, 29896, '[{"url":"https://www.culture.ru/institutes/28974/muzei-drevnerusskogo-iskusstva-g-velikogo-ustyuga","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/16271pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=9ec00a7a-926f-4ff1-ac23-4d5c9d53c5b3&shareType=venue","serviceName":"ФанТам"}]', 29896, NULL, 4496, NULL, '2017-04-25 12:06:27+03', '2025-11-01 13:16:53+03', 1426, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей этнографии г. Великий Устюг', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 66', 'Никольская церковь.', 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 66', '{"type": "Point"}', '<p>В 1986 г. после завершения реставрационных работ в Никольской церкви – памятнике архитектуры ХVII–ХIХ вв. – открыли выставочный зал, посвященный народной культуре и быту, а в 2006 г. в здании были развернуты две тематические экспозиции Музея этнографии.</p> <p>Первая из них представляет народное искусство Устюжского края ХVII – начала ХХ в. во всем его разнообразии – здесь узорное ткачество, вышивка, резьба, роспись по дереву, ковка, просечка и керамика. В музее воссоздан уголок интерьера крестьянской избы. Вход в голбец, двери, опечье, заборки, шкафы-поставцы, люлька, сундуки, праздничные дуги, прялки украшены яркой цветочной кистевой росписью, которая широко бытовала в декоративном убранстве крестьянских изб.</p> <p>На втором этаже размещается экспозиция «Русские праздники», которая раскрывает содержание праздника как важной составной части культуры русского народа. Главная ценность экспозиции – праздничный ряд иконостаса церкви Димитрия Солунского, включающий 30 икон северной школы письма.</p>', 'http://ustyug-museum.ru/mus-ethno', 'muznikola@mail.ru', '[{"value": "78173823576", "comment": "служба приёма"}, {"value": "78173823385", "comment": "Музей этнографии"}]', '{"url": "https://all.culture.ru/uploads/8bd437472d8bbd66bb9a1ce3608baee4.jpg", "title": "Церковь Никольская 1.jpg"}', '[{"url": "https://all.culture.ru/uploads/beb594173250bb2d63afdbc3c09028e8.jpg", "title": "Церковь Никольская 5.jpg"}, {"url": "https://all.culture.ru/uploads/6a48bf47f8b21f761ea8ad094d5d315a.jpeg", "title": "915 В Музее этнографии.JPG"}, {"url": "https://all.culture.ru/uploads/6d144a5951caf39ca14f45945a38e67e.jpeg", "title": "lY0fUoOlm7I.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Народная культура"}, {"name": "Этнография"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Этнографический","Дек.прикладного и нар. искусства","Изобразительного исскуства"]', NULL, 29901, '[{"url":"https://www.culture.ru/institutes/53316/muzei-etnografii-g-velikii-ustyug","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/57588pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=289ad3f9-5b79-42e1-ac53-2fbbc3155030&shareType=venue","serviceName":"ФанТам"}]', 29901, NULL, 4497, NULL, '2017-04-25 13:23:13+03', '2025-11-01 13:08:19+03', 1427, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей новогодней и рождественской игрушки', 'Великоустюгский район', 'Europe/Moscow', 'пл Коммуны,д 7', 'бывший храм Жен-мироносиц', 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пл Коммуны,д 7', '{"type": "Point"}', '<p><span>Музей новогодней и рождественской игрушки работает в Великом Устюге – на родине Деда Мороза – с 1998 года. Музей приглашает в мир доброй сказки. Здесь можно увидеть замечательную коллекцию из более 1,5 тысяч елочных игрушек XX – нач. XXI в., познакомиться с традициями празднования Нового года и Рождества в разных странах.</span></p><p><span>В подклете (на первом этаже) оформлено пространство школы Древней Руси. Здесь проводятся интерактивные занятия «Старорусская школа», можно представить себя учеником такой школы, посидеть на школьной скамье, выполнить задания учителя, получить похвалу или наказание смогут все любознательные и смелые, пришедшие на урок.</span></p><p><span>Здесь же проводятся интерактивные занятия для детей «Короб чудес», посвященные русской народной игрушке. </span></p>', 'http://ustyug-museum.ru/mus-newyeartoys', 'ustyug.museum@mail.ru', '[{"value": "78173823576", "comment": "Служба приема"}, {"value": "78173820722", "comment": "Музей новогодней игрушки"}]', '{"url": "https://all.culture.ru/uploads/e44ab32e775934deb91e4ee53254e0f3.jpg", "title": "3a9e3d9da2c8808494260f05e3b04964.jpg"}', '[{"url": "https://all.culture.ru/uploads/e70d9a9d35956bb38180110e5e76e07e.jpg", "title": "2f40fa270575efcd43901b6f2cf49d49_w2048_h2048.jpg"}, {"url": "https://all.culture.ru/uploads/c857a168e77ab6d4657905f8859832e2.jpg", "title": "32f98dd51f5a5ff1761ef32b30108f0f_w2048_h2048.jpg"}, {"url": "https://all.culture.ru/uploads/702c720dc538b9cc9376dc9bb6c6af7a.jpg", "title": "ad87cf51d0acf436b3f10d213f425eb5_w2048_h2048.jpg"}, {"url": "https://all.culture.ru/uploads/61a1e5e21e43012716cfb1ec7f1c3ce7.jpg", "title": "eac0257d918f63b8fb1be640eb4c2404_w2048_h2048.jpg"}, {"url": "https://all.culture.ru/uploads/07c5e27716abec7564cf4da01a2e8b01.jpg", "title": "ed98a62fc7907b65d946d2c0f8a27787_w2048_h2048.jpg"}, {"url": "https://all.culture.ru/uploads/b74e4c4e5859d3d5d2a63c1713b6c405.jpg", "title": "Стеклянные.jpg"}, {"url": "https://all.culture.ru/uploads/141399dab85ef42972cb9069160fee21.jpg", "title": "f6797362b48d9cd4a58b8b948cd66bb2.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "История"}, {"name": "Игрушки"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический","Дек.прикладного и нар. искусства","Этнографический"]', NULL, 29902, '[{"url":"https://www.culture.ru/institutes/28792/muzei-novogodnei-i-rozhdestvenskoi-igrushki","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/16274pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=41233daf-0af2-434f-a491-47736ef4ade4&shareType=venue","serviceName":"ФанТам"}]', 29902, NULL, 4499, NULL, '2017-04-25 13:50:37+03', '2025-11-01 13:09:21+03', 1428, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Выставочный зал Великоустюгского музея-заповедника', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 55', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 55', '{"type": "Point"}', '<p> Выставочный зал музея располагается в бывшей церкви Власьевской (Богоявленской), построенной в 1687–1689 гг. Она возведена как теплый храм Иоанновского собора. Из всех построек Соборного дворища эта церковь меньше всего претерпела изменений и до наших дней сохранила свой первоначальный облик. Непритязательные архитектурные формы храма свидетельствуют о камерном характере храма, обслуживающего повседневные нужды Соборного дворища. Два окна церкви на южном фасаде украшены крупными наличниками из полихромных устюжских изразцов.</p><p><span></span></p><p> </p><p style="text-align:justify"> </p> <p> Ежегодно в Великоустюгском государственном музее-заповеднике открывается более 10 новых выставок. Значительная их часть проходит в выставочном зале: это выставки из фондов Великоустюгского музея и передвижные из фондов музеев страны, традиционно много выставок работ устюжских и российских художников. В период зимнего туристического сезона в храме Богоявления Господня проводятся рождественские вертепные представления «Звезды рождественской сиянье».</p>', 'http://ustyug-museum.ru/smallhall', NULL, '[{"value": "78173823576", "comment": "служба приёма"}, {"value": "78173824800", "comment": "выставочный зал"}]', '{"url": "https://all.culture.ru/uploads/cd100ed10381826487f3a5b88e128011.jpg", "title": "5614982bcc4ed1af56db6b415e6ce737_w2048_h2048.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 30235, '[{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/60875pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/28972/vystavochnyi-zal-velikoustyugskogo-muzeya-zapovednika","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=7ef6d16d-e6ce-45dd-9613-5c87ab16ff5a&shareType=venue","serviceName":"ФанТам"}]', 30235, NULL, NULL, NULL, '2017-05-15 13:19:09+03', '2026-03-31 16:02:23+03', 1461, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Детский музейный центр г. Великого Устюга', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 60', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 60', '{"type": "Point"}', '<p> При поддержке Министерства культуры РФ, Департамента культуры, туризма и охраны объектов культурного наследия Вологодской области и личном патронате губернатора Вологодской области О. А. Кувшинникова в 2014 г. в Великоустюгском государственном музее-заповеднике открылся многопрофильный детский музейный центр. </p><p>Концепцией музейного центра предусмотрена реализация трех основных направлений работы с детьми: историческое, естественно-научное и художественное. В рамках естественно-научного направления деятельности организована работа планетария. В рамках проекта «Колумбы русские» осуществляется историческое направление работы: создана экспозиция, посвященная устюжским землепроходцам и мореплавателям. </p><p>Здесь проводятся детские художественные выставки и выставки для детей, детские конкурсы, мастер-классы художественных промыслов Русского Севера. Проект «Солнечный лучик» направлен на обеспечение доступа детей-инвалидов к культурным ценностям.</p>', 'http://ustyug-museum.ru/detskii-centr', 'ustyug.museum@mail.ru', '[{"value": "78173823576", "comment": "служба приема музея-заповедника"}, {"value": "78173821615", "comment": "Детский музейный центр"}]', '{"url": "https://all.culture.ru/uploads/4db551622d66ce67669802eb7ec558d0.jpg", "title": "Детский музейный центр .jpg"}', '[{"url": "https://all.culture.ru/uploads/3bd4edbb551f894acf94fa3d9be30653.JPG", "title": "DSC07962.JPG"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Музей-заповедник","Исторический","Художественный"]', NULL, 30666, '[{"url":"https://www.culture.ru/institutes/28973/detskii-muzeinyi-centr-g-velikogo-ustyuga","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/16466pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=4ca7f352-1bf0-4fe1-9bf4-9cbdb7e64206&shareType=venue","serviceName":"ФанТам"}]', 30666, NULL, 4498, NULL, '2017-06-08 16:40:48+03', '2025-11-01 13:17:01+03', 1474, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Кичменгско-Городецкий краеведческий музей', 'Кичменгско-Городецкий район', 'Europe/Moscow', 'ул Спортивная,д 6', NULL, 'обл Вологодская,р-н Кичменгско-Городецкий,с Кичменгский Городок,ул Спортивная,д 6', '{"type": "Point"}', '<p><span>В настоящее время БУК «Краеведческий музей» располагается в двухэтажном кирпичном здании. В 2011 году в музее проведён косметический ремонт. Экспозиционно-выставочная площадь составляет 336,5 кв. м., площадь под хранение фондов – 25,9 кв. м. </span></p> <p><span>В музее представлены следующие постоянные экспозиции: «Древний период. Заселение края», «Православие в районе», «Крестьянско-мещанский быт. Развитие ремёсел», «Зал боевой славы», экспозиция, посвящённая военно-морскому флоту (на основе материалов, предоставленных клубом военных моряков запаса им. К. Ф. Петряшова). Музей является неотъемлемой частью культурной жизни села, бережно хранит и развивает традиции  культуры. Наш район имеет славную историю, которая уходит своими корнями в глубину веков. Во все века на нашей территории проживали трудолюбивые люди, защитники Отечества, патриоты, которые вкладывали все свои силы в развитие и процветание родного края.<em></em>   </span></p> <p><b> </b></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/06966a40281aae42b7de41266e5dfeae.jpg", "title": "DSCF1199.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Кичменгско-Городецкий районный краеведческий музей»', 'Кичменгско-Городецкий район', 'Europe/Moscow', 'ул Спортивная,д 6', NULL, 'обл Вологодская,р-н Кичменгско-Городецкий,с Кичменгский Городок,ул Спортивная,д 6', NULL, 3512005977, 'mincult', 'Кичменгско-Городецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Кичменгско-Городецкий  краеведческий музей","networkId":"206041382","updateDate":"2021-07-29T13:46:21Z","createDate":"2021-07-29T13:46:21Z","accountId":38923,"postingGroupId":35230}]', 13379, '[{"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "17:00:00", "from": "08:30:00"}', '{"to": "17:00:00", "from": "08:30:00"}', '{"to": "17:00:00", "from": "08:30:00"}', '{"to": "17:00:00", "from": "08:30:00"}', '{"to": "17:00:00", "from": "08:30:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 30843, '[{"url":"https://afisha7.ru/kichmengskiy-gorodok/muzei-i-galerei/16603pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/29054/kichmengsko-gorodeckii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c9b99a01-7800-40aa-bc9d-0582ef4a9ae2&shareType=venue","serviceName":"ФанТам"}]', 30843, NULL, 1756, 113957, '2017-06-29 11:30:38+03', '2023-03-28 16:03:12+03', 1477, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Художественный музей г. Череповца', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', '{"type": "Point"}', '<p>Уникальные коллекции Художественного музея г. Череповца никогда не оставляли равнодушными посетителей. Собрание русской живописи конца XVIII – начала XX в. формировалось в 20–30-е гг. прошлого столетия благодаря поступлениям из Государственного музейного фонда и центральных музеев Москвы и Санкт-Петербурга. Гордость музея – памятники православного искусства. </p><p>Сегодня собрание иконописи музея знают далеко за пределами России. В экспозиции «Русское православное искусство XIV– XIX вв.» представлены русские иконы, лицевое шитье, рукописные и старинные книги, литье, эмали. Подлинные работы известных русских художников, мебель, художественный фарфор, стекло, бронза собраны в экспозиции «Русское искусство конца XVIII – начала XX в.». Здесь можно увидеть в том числе и предметы из знаменитой коллекции бронзы С. С. Абамелек-Лазарева.</p>', 'http://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202517525", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8c3da9a472e73514a9d2b236d2263674.jpg", "title": "zPiInl_dnXc.jpg"}', '[{"url": "https://all.culture.ru/uploads/f0b50a0dd1bb51f304d3a2ee75c1876a.jpeg", "title": "i15nSqOd1kA.jpg"}, {"url": "https://all.culture.ru/uploads/0f463939bef64b65bee5aa6e60d3d154.jpeg", "title": "SS9Ku8K4qMg.jpg"}, {"url": "https://all.culture.ru/uploads/1095bdb769f125b9687cc9e0a8eddd5e.jpeg", "title": "46E1v0EbpZg.jpg"}, {"url": "https://all.culture.ru/uploads/6d28161ccb50cb5ffe8dbbc1c882b8f7.jpeg", "title": "iMBzx1Yo2GA.jpg"}, {"url": "https://all.culture.ru/uploads/a2808f6bd4013e140d147795dd711498.jpeg", "title": "u8BqNxcC85s.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "Живопись"}, {"name": "Экскурсии"}, {"name": "Русское искусство"}, {"name": "Коллекции"}, {"name": "Доступная среда"}, {"name": "Изобразительное искусство"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 33169, '[{"url":"https://www.culture.ru/institutes/34713/khudozhestvennyi-muzei-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/17985pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=6bb4913a-4757-48cc-9939-12e240a7d02b&shareType=venue","serviceName":"ФанТам"}]', 33169, NULL, NULL, NULL, '2017-12-14 09:24:35+03', '2025-09-04 14:12:06+03', 1554, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Историко-краеведческий музей г. Череповца', 'Череповец', 'Europe/Moscow', 'пр-кт Луначарского,д 41', NULL, 'обл Вологодская,г Череповец,пр-кт Луначарского,д 41', '{"type": "Point"}', '<p>Музей ведет свою историю с 1896 года, в 1925 году он получил статус краеведческого. </p><p>Экспозиция «Город юный – город древний» рассказывает о прошлом края с древнейших времен до современности. В ней представлено вооружение ордынского воина, офицерские мундиры и оружие XVIII–XX веков, дамские платья и крестьянские сарафаны, зенитная пушка и авиационная бомба времен Великой Отечественной войны, модель первой доменной печи, келья монаха Череповецкого Воскресенского монастыря, интерьеры жилых комнат 1930-х и 1950-х годов. Образно представлен и современный город.</p><p>В 2016 году в музее открылась обновленная экспозиция «Череповецкий край в древности и Средневековье», посвященная очень большому историческому периоду: от VII тысячелетия до н. э., когда на территории современного Череповца появились первые поселенцы, до эпохи Смутного времени в начале XVII <span>века</span><span>.</span></p><p><span>В музее проводятся театрализованные экскурсии, мастер-классы, уроки мужества. </span></p>', 'http://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202553355", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/ecd1f8858d1f6db0fbc674ea6a1a051d.jpeg", "title": "Внешний вид 2.jpg"}', '[{"url": "https://all.culture.ru/uploads/9b8ea471ef059f596564dfeb14b00991.jpeg", "title": "kmuTk1YP0EE.jpg"}, {"url": "https://all.culture.ru/uploads/475fce1a612ab7f266d201c510c5fc7f.jpeg", "title": "ed-5HhrLHOU.jpg"}, {"url": "https://all.culture.ru/uploads/a8b9a531d7c9db9751512100fb05a48b.jpeg", "title": "Ykx7j4ZFWqc.jpg"}, {"url": "https://all.culture.ru/uploads/0994b5f781588c36881e58b912275d01.jpeg", "title": "F6Rpf8k2ZLQ.jpg"}, {"url": "https://all.culture.ru/uploads/3e044499ca62c506741f2b75c03a040c.jpeg", "title": "C4ibrjgpGP8.jpg"}, {"url": "https://all.culture.ru/uploads/6338097bf188460323fe52fa76009c30.jpeg", "title": "8Qv7MruUk5Y.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический","Краеведческий"]', NULL, 33209, '[{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/18012pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/34709/istoriko-kraevedcheskii-muzei-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b1a91160-cb07-467b-a1bc-102c8fe06752&shareType=venue","serviceName":"ФанТам"}]', 33209, NULL, 4371, NULL, '2017-12-18 12:49:08+03', '2025-09-09 17:32:40+03', 1559, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей орхидей', 'Вологда', 'Europe/Moscow', 'пер Ершовский,д 10а', NULL, 'обл Вологодская,г Вологда,пер Ершовский,д 10а', '{"type": "Point"}', '<p>Первый в мире Музей орхидей. В нем представлены орхидеи со всего света.&nbsp;В Музее орхидей ежедневно проводятся экскурсии различной тематики, интересные как взрослым, так и детям. Не упустите возможность познакомиться с разнообразием орхидей со всего света – от жарких тропиков до северных лесов.</p><p>Музей открыт в 2018 году в Ботаническом саду «Ботаника».</p><p>Увлекательные и познавательные мастер-классы для детей и взрослых, интересные квесты, интерактивные курсы предлагает Музей орхидей детям и взрослым.</p><p>Каскад водоемов, вплетенный в горный ландшафт, и тропические орхидеи со всех уголков света станут отличным фоном для красивой и оригинальной фотосессии.</p><p>Орхидеи завоевали такую невероятную популярность у современных цветоводов именно благодаря красоте цветков. Оно и не удивительно, ведь разнообразие их форм и расцветок действительно поражает воображение. Чего только стоят миниатюрные цветочки размером до нескольких миллиметров! Или мощные красочные цветки до 25 см в диаметре! По характеру цветения эти растения и различают между собой. Существуют орхидеи с одиночными цветками (пафиопедилум) и многоцветковые (фаленопсис).</p><span style="font-weight:bold">Экскурсии:</span><p></p><p><span style="font-weight:bold">Путешествие с орхидеями по материкам и странам</span></p><p></p><p></p><p>Во время экскурсии вы узнаете основные места обитания орхидей. Узнаете, какие орхидеи можно встретить в северных широтах России, в тропиках и субтропиках Америки, в горном поясе Азии, в жаркой Африке.</p><p><span style="font-weight:bold">Орхидеи разных климатических групп</span></p><p>Семейство орхидных давно существует на нашей планете. За долгое время эти экзотические растения распространились по всему миру и адаптировались к разным климатическим условиям. Во время экскурсии вы познакомитесь с тропическими растениями, прохладолюбивыми и северными орхидеями, узнаете, почему орхидеи растут на скалах, деревьях и прячутся даже в болотах.</p><p>В стоимость экскурсии входит цена входного билета в Музей орхидей.</p><p>После успешного воплощения в жизнь проекта Ботанический сад в Вологде – Ботаника, создатели тропической оранжереи, задумались о дальнейшем расширении объекта. Несмотря на то, что ботанических садов именно оранжерейного типа во всем мире предостаточно – многообразием коллекцией растений, накопленным опытом и несомненным авторитетом поражают главные ботанические сады страны – это главный ботанический сад РАН им Н. В. Цицина г. Москвы и Ботанический сад МГУ «Аптекарский огород».</p>', 'http://orchids-museum.ru', NULL, '[{"value": "79211296807", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f1fdb2c371c3d3253871cacd66c97e66.JPG", "title": "DSC08266.JPG"}', '[{"url": "https://all.culture.ru/uploads/6397c911c7c07e051fed74a93c7b28da.jpg", "title": "vknNpqQKKok.jpg"}, {"url": "https://all.culture.ru/uploads/3476f82d08e6e4be9f99393f785ff320.JPG", "title": "DSC08242.JPG"}, {"url": "https://all.culture.ru/uploads/6f047e6510997a0fa914d747c7785d7d.JPG", "title": "DSC08272.JPG"}]', NULL, 'Музеи и галереи', 'Ботанический сад Ботаника', 'Вологодский район', 'Europe/Moscow', 'Ершовский переулок,10А', NULL, 'обл Вологодская,р-н Вологодский,Вологда,Ершовский переулок,10А', NULL, 3525103812, 'commercial', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Ботанический Сад ? Вологда","networkId":"122583085","updateDate":"2020-03-02T08:05:41Z","createDate":"2020-03-02T08:05:41Z","accountId":29012,"postingGroupId":26529}]', 20785, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Отраслевые"]', NULL, 35765, '[{"url":"https://www.culture.ru/institutes/36424/muzei-orkhidei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/19545pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b8ca7b93-32d9-4177-9f0c-c32f5481a8b3&shareType=venue","serviceName":"ФанТам"}]', 35765, NULL, NULL, NULL, '2018-08-16 10:03:21+03', '2018-08-17 15:40:50+03', 1691, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Депозитарий г. Великий Устюг', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 58', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 58', '{"type": "Point"}', '<p>Большие площади депозитария отведены под открытое, то есть доступное для посетителей, хранение предметов. Это стало возможным благодаря завершению крупного многолетнего проекта по переоборудованию здания бывшего кинотеатра в специальное музейное хранилище. В 2007 году фонды музея из множества приспособленных помещений были перемещены в здание депозитария. Здесь разместились многочисленные коллекции, среди которых изразцы и мебель, художественная береста, стекло и фарфор, книги и документы. </p><p>В отдельном зале представлена коллекция предметов из металла. В основном это самовары: самовары-чайники, походные самовары. В этом же зале представлены поддужные колокольчики разных размеров, подсвечники, канделябры, замки, ключи большие и маленькие. </p><p>В депозитарии также проводятся мастер-классы и интерактивные занятия для детей. </p>', 'https://ustyug-museum.ru/openfonds', 'ustyug.museum@mail.ru', '[{"value": "78173823576", "comment": "служба приема музея-заповедника"}, {"value": "78173821466", "comment": "депозитарий"}]', '{"url": "https://all.culture.ru/uploads/f5070d5e6a3667657ab2236d3d79c240.jpg", "title": "1vxsilowFdo.jpg"}', '[{"url": "https://all.culture.ru/uploads/d7960df4e70704cb9bd83e880676546b.jpg", "title": "DSC_09281.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "Коллекции"}, {"name": "Доступная среда"}]', NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический","Архитектурный","Художественный"]', NULL, 36523, '[{"url":"https://www.culture.ru/institutes/38363/depozitarii-g-velikii-ustyug","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/19936pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=24e82412-a2c9-4dac-a6ca-73387b3e291a&shareType=venue","serviceName":"ФанТам"}]', 36523, NULL, NULL, NULL, '2018-10-31 11:44:58+03', '2025-11-01 13:15:11+03', 1728, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Мультимедиа-арт-пространство Fabrica', 'Вологда', 'Europe/Moscow', 'ул Благовещенская,д 53', 'третий этаж', 'обл Вологодская,г Вологда,ул Благовещенская,д 53', '{"type": "Point"}', '<p>Fabrica – это открытое творческое мультимедиа-арт-пространство, созданное, чтобы стать концентратором поклонников классического и современного искусства, соединив в себе эти формы при помощи технологичных решений. Расположенное в бывшем здании швейной фабрики, пространство призвано прочными нитями связать опытных и начинающих авторов в единое полотно искусства. </p><p>Универсальное и современное оснащение пространства позволяет проводить множество форматов: </p><ul><li>интерактивные выставки художников;</li><li>презентации и творческие вечера авторов;</li><li>творческий нетворкинг;</li><li>творческую мультимедиа лабораторию;</li><li>музыкальные концерты и квартирники;</li><li>мультижанровые мероприятия.</li></ul><p>Задача пространстваFabrica – стать основой для развития творческого сообщества и дальнейшей коллаборации художников и авторов.</p>', NULL, 'fabrica.artspace@gmail.com', '[{"value": "79815000401", "comment": ""}, {"value": "79211259955", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/6b7eee6daae6de4f1d530b398a2545a2.jpg", "title": "de8ba7a1ace8ea4b42b0651e7f0309d7_w2048_h2048.jpg"}', '[{"url": "https://all.culture.ru/uploads/f81c7aef9ccf98fda450874576fcfaf7.jpg", "title": "i6CALgKW3Ug.jpg"}, {"url": "https://all.culture.ru/uploads/35b640f69110e0bee8f35f424355b793.jpg", "title": "c6ed8912dd01925109d5813cc1a3db1f_w2048_h2048.jpg"}]', NULL, 'Музеи и галереи', 'Мультимедийное арт-пространство FABRICA', 'Вологда', 'Europe/Moscow', 'ул Благовещенская,д 53', NULL, 'обл Вологодская,г Вологда,ул Благовещенская,д 53', NULL, 3525364765, 'commercial', 'Вологда', 'Europe/Moscow', NULL, 21379, '[{"name": "Современное искусство"}, {"name": "Классическое искусство"}]', NULL, NULL, '{"to": "18:00:00", "from": "13:00:00"}', NULL, '{"to": "18:00:00", "from": "13:00:00"}', NULL, NULL, '{"to": "18:00:00", "from": "13:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 36532, '[{"url":"https://www.culture.ru/institutes/38747/multimedia-art-prostranstvo-fabrica","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/19941pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=2c3b5afc-c134-4f05-b39c-f54d1de5db63&shareType=venue","serviceName":"ФанТам"}]', 36532, NULL, NULL, NULL, '2018-10-31 17:15:45+03', '2020-08-10 17:29:15+03', 1729, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Вытегорский краеведческий музей', 'Вытегорский район', 'Europe/Moscow', 'пр-кт Победы,д 4', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,пр-кт Победы,д 4', '{"type": "Point"}', '<p>Музей был основан в 1912 году, основатели музея – Сергеев Георгий Александрович, директор Вытегорского реального училища, и Винницкий Леонард Францевич, инженер водных путей сообщения Мариинской водной системы. </p><p> Изначально это был отдел природы, а сейчас экспозиция музея разделена на 3 отдела: «Природные богатства края», «Древности Вытегории», «История Вытегорского края».</p><p>Собрание фондовых коллекций насчитывает более 77 000 предметов, из них более 42 000 предметов основного фонда. Всего 23 коллекции: драгметаллы, скульптура, живопись, книги, древнерусская живопись, ткани, дерево, медали (знаки, значки), кожа (резина, кость, пластмасса), фаянс (стекло, глина), природа, нумизматика, бумажные деньги, металл, археология, оружие, негативы, фото– и киноматериалы, документы, печатные издания и документы по флоту, вещевой фонд по флоту, изобразительные материалы по флоту. </p><p>Музей предлагает услуги: экскурсионное обслуживание, оформление и открытие выставок, хранение экспонатов, продажа сувенирной продукции, размещение и продвижение рекламы.</p>', 'https://museum-vytegra.vlg.muzkult.ru', 'klyuev.09@mail.ru', '[{"value": "79585851020", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/905866b26f6e4944f40d0ea11a3a92f6.JPG", "title": "IMG_6813.JPG"}', '[{"url": "https://all.culture.ru/uploads/0010f8cbcd8961e895144c5bbf30f21e.JPG", "title": "IMG_6848.JPG"}, {"url": "https://all.culture.ru/uploads/b569aef0c8662fdf4fb540160877eb00.JPG", "title": "IMG_6980.JPG"}, {"url": "https://all.culture.ru/uploads/22a07995e42c7868e33aeeacf8dcd1f4.JPG", "title": "IMG_7016.JPG"}, {"url": "https://all.culture.ru/uploads/9f6a567ef644f4b3e0c9b58c56729f8b.JPG", "title": "DSC00808.JPG"}, {"url": "https://all.culture.ru/uploads/ff0f477f2ad255e9afa9a26a30bb7a8e.JPG", "title": "DSC00835.JPG"}, {"url": "https://all.culture.ru/uploads/7f032e6ee75f8eb6e56520804d94046e.JPG", "title": "DSC00814.JPG"}, {"url": "https://all.culture.ru/uploads/154aedacecee7a4098f65f8dc931a205.JPG", "title": "DSC00830.JPG"}]', NULL, 'Музеи и галереи', 'МБУК «Вытегорский объединенный музей»', 'Вытегорский район', 'Europe/Moscow', 'ул 3 Интернационала,д 2', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,ул 3 Интернационала,д 2', NULL, 3508003511, 'mincult', 'Вытегорский район', 'Europe/Moscow', '[{"network":"vk","name":"Вытегорский объединенный музей","networkId":"64441013","updateDate":"2025-07-15T11:35:30Z","createDate":"2025-07-15T11:35:30Z","accountId":53518,"postingGroupId":48169},{"network":"vk","name":"Елена Шинкарчук","networkId":"121910670","updateDate":"2025-07-15T11:36:33Z","createDate":"2025-07-15T11:36:33Z","accountId":53518,"postingGroupId":48170}]', 10671, '[{"name": "История"}, {"name": "Искусство"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 38060, '[{"url":"https://afisha7.ru/vytegra/muzei-i-galerei/20933pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/40701/vytegorskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=8cd67c95-0574-4280-af70-8ad9c3477980&shareType=venue","serviceName":"ФанТам"}]', 38060, NULL, 1745, 113872, '2019-03-18 14:04:37+03', '2026-03-03 16:51:40+03', 1787, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музейно-выставочный центр Главного управления МЧС России по Вологодской области', 'Вологда', 'Europe/Moscow', 'ул Зосимовская,д 63а', 'проезд маршрутами автобусов № 6,40,19,48,35,27,29,9 до остановки Зосимовская', 'обл Вологодская,г Вологда,ул Зосимовская,д 63а', '{"type": "Point"}', '<p>Пожарно-техническая выставка при Вологодском областном отделе пожарной охраны была создана в 1973 году трудами начальника ОПО А. Н. Котт и его подчиненных. В потоке посетителей были не только жители города Вологды, но и многих районов области, а также других государств – Швеции, Кубы, Финляндии, Америки. В 2017 году была проведена ее реконструкция, в ходе которой полностью заменены материалы в большом и малом зале. В апреле 2019 года открылся новый интерактивный выставочный зал раритетной техники пожарной охраны. </p><p>На выставке регулярно проводятся экскурсии с посетителями, совещания, проходят конференции, учеба личного состава, выставки детского рисунка. За время работы выставки, в настоящее время носящей название Центра противопожарной пропаганды и общественных связей, ее посетили более 250 тысяч человек. Многочисленные благодарственные отзывы его посетителей подтверждают необходимость и важность проводимой работы.</p>', NULL, 'muzei.mchs@mail.ru', '[{"value": "79637309092", "comment": "+7211431082"}]', '{"url": "https://all.culture.ru/uploads/2280bccdd558badacd0251964836db8c.jpeg", "title": "tE0koVs2OR-800x600.jpg"}', '[{"url": "https://all.culture.ru/uploads/5a91839901948fcbc381cbe5bc967351.jpeg", "title": "xCpZa5CdRP-800x600.jpg"}, {"url": "https://all.culture.ru/uploads/e88fa1a256925589c3c908952fde75e6.jpeg", "title": "YiSCPnUKiD-800x600.jpg"}, {"url": "https://all.culture.ru/uploads/aa4593c07bfa8bd9dd82ec23f3d1a44d.jpeg", "title": "Vejp9FsPJS-800x600.jpg"}, {"url": "https://all.culture.ru/uploads/3de44733290e43ab7e930808dca59d5f.jpeg", "title": "ceaaGW6VCnM.jpg"}, {"url": "https://all.culture.ru/uploads/8cf2cdeb94d19bce5858d545478f39e5.jpeg", "title": "IMG_6781-12-02-18-14-33.JPG"}]', NULL, 'Музеи и галереи', 'Музей пожарной охраны Вологодской области', 'Вологда', 'Europe/Moscow', 'ул Зосимовская,д 63а', NULL, 'обл Вологодская,г Вологда,ул Зосимовская,д 63а', NULL, 3525147560, 'othergov', 'Вологда', 'Europe/Moscow', NULL, 22313, '[{"name": "История"}, {"name": "Выставочные залы"}, {"name": "Органы государственного надзора"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический","Истории организаций"]', NULL, 38994, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/21540pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/40053/muzeino-vystavochnyi-centr-glavnogo-upravleniya-mchs-rossii-po-vologodskoi-oblasti","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1fbff774-a677-41eb-9a0d-7007365647a2&shareType=venue","serviceName":"ФанТам"}]', 38994, NULL, NULL, NULL, '2019-05-14 11:01:39+03', '2019-05-27 11:55:43+03', 1825, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Подводная лодка Б-440»', 'Вытегорский район', 'Europe/Moscow', 'ул Комсомольская,д 15А', 'на берегу Вытегорского водохранилища, около речного порта', 'обл Вологодская,р-н Вытегорский,г Вытегра,ул Комсомольская,д 15А', '{"type": "Point"}', '<p> Музей «Подводная лодка Б-440» был основан в 2005 году на базе большой океанской дизель-электрической подводной лодке 641 проекта. В 2012 году музей в качестве отдела вошёл в состав Вытегорского объединённого музея. </p><p> Выставочные залы рассказывают о боевом пути экипажа подлодки, истории развития подводного флота в России, участии субмарин в боевых действиях в годы Великой Отечественной войны. В музее экспонируются выставочные проекты Музея «Победы» в рамках международного проекта «Территория Победы». </p><p>В музее имеется система QR-кодов, с помощью которых можно получить информацию о назначении отсеков, рубок, оборудования, а также аудиогид по основной палубе на русском, английском, французском и немецком языках. </p><p> Для всех категорий граждан проводятся экскурсии, разнообразные квест-игры, тактические командные игры, беседы патриотической направленности для обучающихся образовательных учреждений, мастер-класс по вязанию морских узлов. Организована продажа сувенирной продукции. </p>', 'https://museum-vytegra.vlg.muzkult.ru', 'klyuev.09@mail.ru', '[{"value": "79585851020", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/52578392c0cfec7dabd26f52d5cce037.jpeg", "title": "d61544ecdc57d011aa3c526e7e2c6413.jpeg"}', '[{"url": "https://all.culture.ru/uploads/fe6e0c8767b81d8882f1a6224c2a1395.jpg", "title": "Совещание с туроператорами 034.jpg"}, {"url": "https://all.culture.ru/uploads/a3eb7dabb36f47fcb573862617b38f64.JPG", "title": "IMG_4289.JPG"}, {"url": "https://all.culture.ru/uploads/08473dbbdfdbef75dfa09a0a5a9b0172.JPG", "title": "DSCN4280.JPG"}, {"url": "https://all.culture.ru/uploads/475c3aa8be1f13cfb22a0320c924dc5e.jpg", "title": "моя (1).jpg"}, {"url": "https://all.culture.ru/uploads/deb52993abde0d99769680c0100d2fa5.JPG", "title": "P7294750.JPG"}]', NULL, 'Музеи и галереи', 'МБУК «Вытегорский объединенный музей»', 'Вытегорский район', 'Europe/Moscow', 'ул 3 Интернационала,д 2', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,ул 3 Интернационала,д 2', NULL, 3508003511, 'mincult', 'Вытегорский район', 'Europe/Moscow', '[{"network":"vk","name":"Вытегорский объединенный музей","networkId":"64441013","updateDate":"2025-07-15T11:35:30Z","createDate":"2025-07-15T11:35:30Z","accountId":53518,"postingGroupId":48169},{"network":"vk","name":"Елена Шинкарчук","networkId":"121910670","updateDate":"2025-07-15T11:36:33Z","createDate":"2025-07-15T11:36:33Z","accountId":53518,"postingGroupId":48170}]', 10671, '[{"name": "История"}, {"name": "Открытые площадки"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Военно-Морской"]', NULL, 39982, '[{"url":"https://www.culture.ru/institutes/40762/muzei-podvodnaya-lodka-b-440","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vytegra/muzei-i-galerei/21967pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=2f923ba2-d2fa-4ea6-821c-13ca90aadc06&shareType=venue","serviceName":"ФанТам"}]', 39982, NULL, NULL, NULL, '2019-09-26 09:06:24+03', '2026-03-03 16:45:01+03', 1888, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей археологии г. Череповца', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 19', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 19', '{"type": "Point"}', '<p>Музей археологии существует в Череповце много лет, а коллекция находок, которая в нем хранится и выставляется, – одна из крупнейших на Северо-Западе. </p><p>Фонды музея насчитывают более 100 тысяч единиц хранения, их возраст – от 10 тысяч до 600 лет. Среди них есть уникальные вещи, в том числе: янтарные украшения I тыс. до н. э., шахматная фигурка X века, украшения и предметы культа с изображениями животных и многое другое.</p><p>Такая богатая коллекция сформировалась благодаря многочисленным экспедициям. Музей действует как центр археологического исследования территории Вологодской области. Раскопки ведутся в Шескнинском, Белозерском, Кирилловском и других районах области. </p><p>Экспозиция знакомит с основными археологическими памятниками региона, уникальными экспонатами, которые позволяют заглянуть глубоко в прошлое и узнать, где на территории современного Череповца поселились люди, чем они жили, на кого и как охотились, какими занимались ремеслами.</p>', 'https://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493331", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/9c652766cf3439106429c954489b8ffd.jpeg", "title": "lUesSuzY5xo.jpg"}', '[{"url": "https://all.culture.ru/uploads/8daa6e72c9bbc92545a9a4335be9e79a.jpeg", "title": "archeology.jpg"}, {"url": "https://all.culture.ru/uploads/7654a0cc435fdf59684eb5b7bf9585ca.jpeg", "title": "archeology (3).jpg"}, {"url": "https://all.culture.ru/uploads/367c9e155182f8e65b1eb12afbae28cb.jpeg", "title": "archeology (2)jpg.jpg"}, {"url": "https://all.culture.ru/uploads/55edd67e459c3dafe49d07879e4b371f.jpeg", "title": "archeology (1).jpg"}, {"url": "https://all.culture.ru/uploads/37b911687aeaa24a8971f96a909a63cb.jpeg", "title": "JJswVCQWI0U.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Археология"}, {"name": "Коллекции"}, {"name": "Доступная среда"}, {"name": "Культурное наследие"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Археологический"]', NULL, 40589, '[{"url":"https://www.culture.ru/institutes/41085/muzei-arkheologii-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/60935pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=023df563-cf0b-4581-932b-79a69c14ae0f&shareType=venue","serviceName":"ФанТам"}]', 40589, NULL, 4369, NULL, '2019-11-04 14:31:38+03', '2025-09-04 14:44:42+03', 1920, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Кадниковский краеведческий музей', 'Сокольский район', 'Europe/Moscow', 'ул Розы Люксембург,д 20', NULL, 'обл Вологодская,р-н Сокольский,г Кадников,ул Розы Люксембург,д 20', '{"type": "Point"}', '<p>Музей был открыт 6 февраля 1986 года. Его основателем и первым директором стал А. Н. Мальгинов. Долгое время музей работал на общественных началах. В это время проводилась напряженная работа по сбору экспонатов, которые дали бы наглядное представление о прошлом города. </p><p>1 марта 1993 года на базе музея был открыт Кадниковский районный исторический музей. Благодаря реконструкции залов он получил дополнительные площади. На сегодняшний день это филиал Сокольского районного музея, фонды включают 7 000 экспонатов.</p><p>В музее работают как постоянные экспозиции, так и временные выставки. Посетители смогут познакомиться с историей основания Кадникова и Кадниковского уезда в экспозиции «Крестьянские будни». Кадников всегда славился как купеческий город – представлена экспозиция, которая рассказывает о местном купечестве и его влиянии на экономическое развитие города. </p><p>История становления православной веры иллюстрирована в экспозиции «Монастыри и подвижники Заозерского края». Здесь рассказана история 13 православных монастырей, основанных на территории Кадниковского уезда в XIII–XV веках. Также в музее можно окунуться в культуру повседневности дворян на примере семьи предводителя Кадниковского уездного дворянства Ю. М. Зубова. История города в период Великой Отечественной войны представлена историей военного аэродрома. </p>', 'https://sokolmuzey.ru', 'sokolmuzei@mail.ru', '[{"value": "78173341579", "comment": ""}, {"value": "79215359086", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/74d4e339f7ae8fdeaefa14d8b2ff1adb.jpg", "title": "20240815_130834.jpg"}', '[{"url": "https://all.culture.ru/uploads/e08a1f679355b74655ed6180ef85ce91.jpeg", "title": "oVTYUJVFJDw.jpg"}, {"url": "https://all.culture.ru/uploads/c05427e7ec8be9dcad73f2f99faffc74.jpg", "title": "IMG-20241008-WA0038.jpg"}, {"url": "https://all.culture.ru/uploads/47fe1b3332acd6b68d135fec3a48ac2a.jpg", "title": "df8XT0HUo0A — копия.jpg"}, {"url": "https://all.culture.ru/uploads/d336358a7396868090c1fbff4a8a8919.jpg", "title": "ILMGSVJy1-M.jpg"}, {"url": "https://all.culture.ru/uploads/a334ad8cc25502b83bd8a856cd762405.jpg", "title": "jbccs-1czx0.jpg"}, {"url": "https://all.culture.ru/uploads/3bccf19e96a885d6f473d359f13d692b.jpg", "title": "20240802_115955.jpg"}, {"url": "https://all.culture.ru/uploads/5285292ad1594bfdf0cc55d7686eeb21.jpg", "title": "20240725_124020.jpg"}]', NULL, 'Музеи и галереи', 'БУК СМО «Сокольский Музей»', 'Сокольский район', 'Europe/Moscow', 'ул Набережная Свободы,д 50', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Набережная Свободы,д 50', NULL, 3527011740, 'mincult', 'Сокольский район', 'Europe/Moscow', '[{"network":"vk","name":"Кадниковский краеведческий музей","networkId":"195495184","updateDate":"2023-07-10T12:49:58Z","createDate":"2021-05-05T17:34:23Z","accountId":37643,"postingGroupId":34337},{"network":"vk","name":"Сокольский музей","networkId":"217753345","updateDate":"2022-12-22T11:23:09Z","createDate":"2022-12-22T11:23:09Z","accountId":44385,"postingGroupId":38636},{"network":"vk","name":"Сокольский-Районный Музей","networkId":"364420001","updateDate":"2022-12-22T11:23:29Z","createDate":"2022-12-22T11:23:29Z","accountId":44385,"postingGroupId":38637}]', 2555, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Искусство"}, {"name": "Этнография"}, {"name": "Коллекции"}, {"name": "Ремесла и художественные промыслы"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 53176, '[{"url":"https://afisha7.ru/sokol/muzei-i-galerei/54112pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/55446/kadnikovskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=3b88da92-fab0-4095-b536-e3a8dc5d98e1&shareType=venue","serviceName":"ФанТам"}]', 53176, NULL, NULL, NULL, '2021-05-05 14:30:15+03', '2025-07-22 11:51:15+03', 2230, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Александра Башлачева', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 35А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 35А', '{"type": "Point"}', '<p>В год 60-летия со дня рождения Александра Башлачева в его родном городе открылся музей, посвященный памяти поэта. Появление музея, его необходимость и значимость определили люди, которым близко творчество Башлачева и дорога память о нем. В 2009 году поклонники таланта поэта оформили народную экспозицию, а в 2020 году появилась идея создать новую концепцию. Бесценную поддержку оказала семья Александра. Откликнулись и друзья Башлачева: поделились уникальными материалами, записями, предметами. </p><p>Благодаря выстроенной драматургии музыки, звука, света, видео, визуальных эффектов и предметов небольшое помещение буквально оживает и заполняется историей одной яркой личности, ставшей символом и голосом поколения. Александр был необыкновенным человеком и прекрасным поэтом, новая экспозиция рассказывает о первом воспоминаниями мамы, друзей и голосом самого Башлачева, а о втором можно судить по записям песен и черновикам стихов. </p><p>Авторы проекта придумали оригинальный аудиовизуальный спектакль, в котором хроника жизни и творческого пути поэта звучит голосами родных, друзей, его песнями, мыслями, которыми он делился в интервью. Предметы, бережно сохраненные семьей и переданные в музей, до определенного момента скрыты от глаз посетителей в витринах, меняющих прозрачность и показывающих вещи в задуманном порядке.</p>', 'https://александрбашлачев.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202440545", "comment": "Запись на экскурсии"}, {"value": "78202518511", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2471e90e8bd24ee127a2ce8ac28b28a1.jpeg", "title": "b7b4ab1e06739ca74aa9547194bf9f45.jpeg"}', '[{"url": "https://all.culture.ru/uploads/782a2cc586534e06926f1d6ee2e28a93.jpeg", "title": "1e5862276bc72d5b472c7f27324fcdbd.jpeg"}, {"url": "https://all.culture.ru/uploads/4c90a719c90bcc0f9e6cf3ceb23fa132.jpeg", "title": "IMG_3129.JPG"}, {"url": "https://all.culture.ru/uploads/49000e1661c401ac223cb40ad60a6f1b.jpeg", "title": "IMG_3107.JPG"}, {"url": "https://all.culture.ru/uploads/15a6ada50ac7954c78ac03edde6d3c95.jpeg", "title": "IMG_3085.JPG"}, {"url": "https://all.culture.ru/uploads/3af9e832390034383a58e593f9bb3186.jpeg", "title": "IMG_3082.JPG"}, {"url": "https://all.culture.ru/uploads/7278d7c944be21a5c436193ce67a78a4.jpeg", "title": "IMG_3073.JPG"}, {"url": "https://all.culture.ru/uploads/051749473fbbcb8f866c7784dc63c8a7.jpeg", "title": "IMG_3070.JPG"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "Музыка"}, {"name": "Коллекции"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 53219, '[{"url":"https://www.culture.ru/institutes/50579/muzei-aleksandra-bashlacheva","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/48195pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=6bea0654-1369-4690-9764-079065b45f6b&shareType=venue","serviceName":"ФанТам"}]', 53219, NULL, NULL, NULL, '2021-05-07 12:20:24+03', '2025-09-11 15:33:12+03', 2232, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Экспозиция «Санитарный эшелон»', 'Череповец', 'Europe/Moscow', 'ул Завокзальная', NULL, 'обл Вологодская,г Череповец,ул Завокзальная', '{"type": "Point"}', '<p><span style="font-style:normal;font-weight:400"></span></p><p><span>Экспозиция, открытая к 75-летию Великой Победы, посвящена подвигу военных медиков и железнодорожников, она рассказывает об истории легендарного военно-санитарного поезда № 312, </span>который в первые дни войны (26 июня 1941 года) был сформирован и направлен на фронт с Вологодского паровозовагоноремонтного завода. Такие поезда фактически были госпиталями на колесах: в них бойцов не только везли в тыловые госпитали, но и лечили. </p> <p>Экспозиция представляет собой воссозданный отрезок железнодорожного пути станции Череповец, на котором установлен паровоз ЛВ и два вагона. </p> <p>В таком же вагоне (выпуска 1940 года), которые были в составе постоянных военно-санитарных поездов, оформлена экспозиция «Поезд милосердия» – части интерьера специализированных вагонов: вагона-аптеки, операционного, штабного, хозяйственного и др. Базу экспозиции составили фондовые коллекции Череповецкого музейного объединения. Некоторые предметы передали музею неравнодушные горожане. Часть мебели изготовили по чертежам того времени, некоторые предметы (столы, шкафы из музейных фондов) отреставрировали. Даже занавески вышиты по сохранившимся архивным фотографиям.</p> <p>Во втором вагоне дореволюционной постройки, отреставрированном и предоставленном РЖД безвозмездно, проводятся интерактивные занятия.</p><p>Экспозицию можно посетить по предварительной записи.</p><p><span style="font-style:normal;font-weight:400"></span></p>', 'https://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202553355", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/a48c1e41b03fe3d48b14cedb7c1cee6c.jpeg", "title": "paVdISQ_DxU.jpg"}', '[{"url": "https://all.culture.ru/uploads/ec5e20dc8a9fd6aa1173474a70216d70.jpeg", "title": "_KAQMVxqH4Y.jpg"}, {"url": "https://all.culture.ru/uploads/5dac8ffba752920a43bfb13f7996e6ca.jpeg", "title": "IMG_4833.JPG"}, {"url": "https://all.culture.ru/uploads/64c60042b874d35dc4493c958aff2383.jpeg", "title": "IMG_9799.JPG"}, {"url": "https://all.culture.ru/uploads/d079de4aecde2ae5eb0db21580a89160.jpeg", "title": "IMG_9812.JPG"}, {"url": "https://all.culture.ru/uploads/e13c961220ee314723795b23cd6366be.jpeg", "title": "IMG_2210.JPG"}, {"url": "https://all.culture.ru/uploads/9f7f783240565623f3468001de74132a.jpeg", "title": "vn94K2VoMaA.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Коллекции"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Военно-Исторический"]', NULL, 54920, '[{"url":"https://www.culture.ru/institutes/52105/ekspoziciya-sanitarnyi-eshelon","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/50531pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=72852ac7-ef56-42f1-b8d9-6ef39a237bb7&shareType=venue","serviceName":"ФанТам"}]', 54920, NULL, NULL, NULL, '2021-06-22 14:01:21+03', '2025-09-09 17:38:14+03', 2283, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Демонстрационный зал предприятия «Северная чернь»', 'Великоустюгский район', 'Europe/Moscow', 'ул Анатолия Угловского,д 1', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Анатолия Угловского,д 1', '{"type": "Point"}', '<p> В 2014 году распахнул свои двери Демонстрационный зал ЗАО «Северная чернь», созданный для популяризации народного художественного промысла.</p> <p> У жителей Великого Устюга и гостей города появилась прекрасная возможность познакомиться с историей знаменитого ювелирного промысла, с секретами и особенностями оригинальной технологии чернения по серебру, полюбоваться уникальными ювелирными изделиями.</p> <p>Несомненно, гордостью музейного собрания является комплект столовых приборов работы заслуженного деятеля искусств РСФСР Е. П. Шильниковского, с удивительными по сложности рисунками, выполненными в технике черневой художественной гравюры по мотивам сказок А. С. Пушкина, который в 1937 году на Всемирной выставке в Париже произвел настоящий фурор и был удостоен Большой Золотой медали. Современные авторские работы, представленные в экспозиции, также поражают великолепием, изяществом и тщательной проработкой каждой детали, характерными для изделий с северной чернью.</p>', 'https://sevchern.ru', 'expo@sevchern.ru', '[{"value": "79315087610", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2f3bc230c8fc0a909692a3c9ad03c57c.jpeg", "title": "46214ed73bcff83ec30bba61c17c496b.jpeg"}', '[{"url": "https://all.culture.ru/uploads/9ba5c16a0ee192efe0f00f604ae9a735.jpeg", "title": "2Экспозиция Столовый набор Пушкинская серия.jpg"}, {"url": "https://all.culture.ru/uploads/e81e58cb154ef830e98e0d94371793f5.jpeg", "title": "5Демонстрация изделий Северной черни и Императорского фарфорового завода.jpg"}, {"url": "https://all.culture.ru/uploads/bcc711e4703f3cfb3aafe359babd1fb8.jpeg", "title": "мастерская 2.jpg"}, {"url": "https://all.culture.ru/uploads/67f240122e0401ac9ab3bde169a8081b.jpeg", "title": "5f5cac189b31854ecf97f33e3b3a41e6.jpeg"}]', NULL, 'Музеи и галереи', 'Закрытое акционерное общество «Великоустюгский завод «Северная чернь»', 'Великоустюгский район', 'Europe/Moscow', 'ул Анатолия Угловского,д 1', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Анатолия Угловского,д 1', NULL, 3526011667, 'commercial', 'Великоустюгский район', 'Europe/Moscow', NULL, 28073, '[{"name": "История"}, {"name": "Современное искусство"}, {"name": "Выставочные залы"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 55542, '[{"url":"https://www.culture.ru/institutes/52584/demonstracionnyi-zal-predpriyatiya-severnaya-chern","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/51949pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d674b56c-2226-459e-a70d-5bca0290b8b1&shareType=venue","serviceName":"ФанТам"}]', 55542, NULL, NULL, NULL, '2021-07-09 15:30:41+03', '2021-09-22 12:18:24+03', 2297, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Культурно-выставочный центр «Вологодский музей детства»', 'Вологда', 'Europe/Moscow', 'ул Маяковского,д 1', NULL, 'обл Вологодская,г Вологда,ул Маяковского,д 1', '{"type": "Point"}', '<p>Вологодский музей детства – это не просто музей, а частная коллекция одной семьи. Более 20 лет экспонаты бережно собиралась из разных уголков мира и впоследствии нашли место в экспозициях музея, открытого в декабре 2019 года.</p><p>Сегодня музей готов показать (а сотрудники – рассказать о каждой) 3 000 игрушек советского времени. В витринах живут игрушки, отражающие ту историческую действительность, в которой были созданы. А для того, чтобы музей не только жил, но и приносил пользу, реализуется активная добровольческая деятельность. </p><p>Сотрудники музея сохраняют и изучают историю игрушечного производства на территории Вологодской области, планируя открыть выставку и показать ее всем желающим, сохраняют памятник архитектуры регионального значения – дом купчихи Красненьковой, привлекают детей и родителей к совместному времяпровождению и сотворчеству. Родители учатся играть с детьми, а дети – с родителями.</p><p> </p><p>Музей реализует уникальные программы «Игрушечные выходные» и «Игрушечные каникулы». </p>', 'https://vmuzey.com/event/ekskursiya-istoriya-strany-cherez-istoriyu-igrushki', 'ira-met@yandex.ru', '[{"value": "79115197090", "comment": "Ирина"}, {"value": "79115152479", "comment": "Надежда"}]', '{"url": "https://all.culture.ru/uploads/e5ff768ca258e3cf5ff4b716d23ece8c.jpg", "title": "дом.jpg"}', '[{"url": "https://all.culture.ru/uploads/80c000f26de2204c177772b44c211cd7.jpg", "title": "карлсон.jpg"}, {"url": "https://all.culture.ru/uploads/01feb85e5e7eec235c1b6971c9787d8d.jpg", "title": "космонавт.jpg"}, {"url": "https://all.culture.ru/uploads/07af0375ec1e8869bad0f6db97935017.jpg", "title": "магазин.jpg"}, {"url": "https://all.culture.ru/uploads/e5db049099004b6f063468df7caa1a4a.jpg", "title": "машинки.jpg"}, {"url": "https://all.culture.ru/uploads/584be8d0fe536ade9a4967b795e57a1f.jpg", "title": "новый год.jpg"}, {"url": "https://all.culture.ru/uploads/49f03e6880f7e488154028138048ab52.jpg", "title": "осн 1.jpg"}, {"url": "https://all.culture.ru/uploads/ed8f6b0d4226b09a85b771e2fc612422.jpg", "title": "школьница.jpg"}]', NULL, 'Музеи и галереи', 'АНО КВЦ «Вологодский музей детства»', 'Вологда', 'Europe/Moscow', 'пр-кт Советский', NULL, 'обл Вологодская,г Вологда,пр-кт Советский', NULL, 3525419284, 'noncommercial', 'Вологодская область', 'Europe/Moscow', NULL, 28331, '[{"name": "История"}, {"name": "Искусство"}, {"name": "Игрушки"}, {"name": "Коллекции"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 56569, '[{"url":"https://www.culture.ru/institutes/53384/kulturno-vystavochnyi-centr-vologodskii-muzei-detstva","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/57461pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=837c9bbf-2f93-4dc3-bfd3-7b5105e9c8ba&shareType=venue","serviceName":"ФанТам"}]', 56569, NULL, NULL, NULL, '2021-08-23 16:38:19+03', '2023-11-08 08:27:32+03', 2342, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Интерактивный музей «Галинские паруса»', 'Череповецкий район', 'Europe/Moscow', 'д 16', 'из Череповца: ехать в направлении на г. Кириллов, у дорожного знака «Галинское» – поворот направо, ехать прямо до бело-красного маяка, дом будет справа', 'обл Вологодская,р-н Череповецкий,д Галинское,д 16', '{"type": "Point"}', '<p>Музей был создан 5 мая 2017 года семьей Сергея Токарева – мастера-лодочника. Сергей более 40 лет работает с деревом, создает полноразмерные лодки и корабли, их макеты, а также инсталляции, изображающие животных и героев сказок. </p><p>За долгие годы изучения темы судостроения и работы над созданием моделей у Сергея накопилось дотаточно знаний, возникло желание ими делиться. Так обычный частный участок превратился в территоррию музея. Были построены чайная для приема гостей, судоверфь для строительства лодок и бассейн из сруба и баннера для спуска моделей. Количество экспонатов росло, и постепенно гараж для машины превратился в «Волшебную сарайку», которую так любят маленькие гости. Там разместились небольшие модели кораблей.</p><p>Отличительная черта музея – сотрудники не просто показывают экспонат и рассказывают о нем, а проводят целую интерактивную программу с участием гостей. Здесь и стрельбы из самодельных пушек, и покатушки на деревянном самокате, и встреча гостей с пиратами и Айболитом! На территории музея повсюду расположены веселые инсталляции: котики, рыбки, пингвины, самолет и даже самый большой в Вологодской области макет корабля. </p><p>В настоящее время экспозиция музея насчитывает более 700 экспонатов ручной работы, каждый из которых можно потрогать, подвигать и рассмотреть поближе детально, что очень любят дети. </p><p> </p>', 'http://www.galparus.ru', 'galparus@gmail.com', '[{"value": "79212596587", "comment": ""}, {"value": "79005457264"}]', '{"url": "https://all.culture.ru/uploads/7234af3934c1dcd779e2e74cdfb45f23.jpeg", "title": "IMG_0746.jpeg"}', '[{"url": "https://all.culture.ru/uploads/54c155d5f66097da79a258c5990a3f6e.jpeg", "title": "k1nybtXDx9U.jpg"}, {"url": "https://all.culture.ru/uploads/b537338eae2c812825522c6179f7c5af.jpeg", "title": "KUwpmMiEvc8.jpg"}, {"url": "https://all.culture.ru/uploads/077729a14f82f57f8679205717f52033.jpeg", "title": "kZUZkLHrhlQ.jpg"}, {"url": "https://all.culture.ru/uploads/54591c73506297200367fa86ca854b0c.jpeg", "title": "QUFpQfLEILw.jpg"}, {"url": "https://all.culture.ru/uploads/8b4bde92d54902d5a21894354c79425c.jpeg", "title": "4tCtUgZ7qww.jpg"}, {"url": "https://all.culture.ru/uploads/63b9625d36b706ea750cefe8374dc605.jpeg", "title": "_N-jqCmPGZM.jpg"}, {"url": "https://all.culture.ru/uploads/b3fccbc4eb541a0f30f02b9c3861dcb0.jpeg", "title": "jEr_1of-an4.jpg"}]', NULL, 'Музеи и галереи', 'ИП Токарев Сергей Алексеевич', 'Череповецкий район', 'Europe/Moscow', 'д 16', NULL, 'обл Вологодская,р-н Череповецкий,д Галинское,д 16', NULL, 352809866887, 'commercial', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Интерактивный музей \"Галинские Паруса\"","networkId":"99769731","updateDate":"2018-01-30T20:14:38Z","createDate":"2018-01-30T20:14:38Z","accountId":19468,"postingGroupId":17145}]', 19733, '[{"name": "История"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-99769731&id=456239058&hash=f1636bc4abaf4662&hd=2\" width=\"853\" height=\"480\"></iframe>"}]', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Судостроения","Исторический","Изобразительного исскуства"]', NULL, 57267, '[{"url":"https://www.culture.ru/institutes/56865/interaktivnyi-muzei-galinskie-parusa","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/54964pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d4a88f99-8177-4301-aecc-26e7e4ce2f4e&shareType=venue","serviceName":"ФанТам"}]', 57267, NULL, NULL, NULL, '2021-10-06 12:36:34+03', '2021-12-02 16:34:35+03', 2437, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей аптеки', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 35А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 35А', '{"type": "Point"}', '<p>Экспозиция располагается в помещении, где до недавнего времени работала старейшая аптека Череповца. Предметный ряд позволяет проследить долгий путь аптечного дела – от «зелейных лавок» и государевых аптек, обслуживавших только царское семейство, в фармацевтическое производство, способное обеспечить необходимыми лекарственными препаратами население всей страны.</p><p>В экспозиции собрано все, что связано с профессиями фармацевта и провизора. Вниманию посетителей предложены старинные справочники, профессиональное оборудование, механизмы и аппараты. Здесь можно рассмотреть старинные сигнатуры (ярлыки с копией рецепта), на фотографиях увидеть, как выглядели интерьеры дореволюционных и советских аптек.</p><p>Помимо основной экспозиции, в музейном пространстве воссоздана «зелейная лавка», которая дает представление о средневековом прототипе современных аптек. За занавесом располагаются старинные шкафы с влажными препаратами, чучелами животных, засушенными лекарственными травами. <br /></p><p style="text-align:justify"><span></span></p><p></p>', 'https://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493335", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/0b38930141998f92d4e8e13b95ad8485.jpg", "title": "DSC_0237.jpg"}', '[{"url": "https://all.culture.ru/uploads/84ffbacf0a93bdeeeaa6b79c390c9b87.jpeg", "title": "7q_jfnFe1Uc.jpg"}, {"url": "https://all.culture.ru/uploads/be5c734fa5c39895d091d030c5bda3f8.jpeg", "title": "музей аптеки (5).jpg"}, {"url": "https://all.culture.ru/uploads/83b38a82578e3e7d4b97c47295fc3072.jpeg", "title": "музей аптеки (1).jpg"}, {"url": "https://all.culture.ru/uploads/940501887fb76dc2d7ecb827f2241609.jpeg", "title": "музей аптеки (4).jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Точные науки"}, {"name": "Коллекции"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Естественнонаучный"]', NULL, 57356, '[{"url":"https://www.culture.ru/institutes/54368/muzei-apteki","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/61162pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=bfd154c0-ebb3-43b8-9d9a-87e49234e2f1&shareType=venue","serviceName":"ФанТам"}]', 57356, NULL, NULL, NULL, '2021-10-11 10:18:05+03', '2025-09-09 17:37:31+03', 2444, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей-усадьба Батюшковых и А. И. Куприна', 'Устюженский район', 'Europe/Moscow', 'ул Центральная', NULL, 'обл Вологодская,р-н Устюженский,п Даниловское,ул Центральная', '{"type": "Point"}', '<p>7 сентября 1960 г., к 90-летию со дня рождения А. Куприна, в Даниловском был открыт Народный музей. Экспозиция занимала одну комнату и была посвящена творчеству А. Куприна в период его пребывания в Даниловском и владельцу дома Ф. Батюшкову, другу писателя. </p> <p>В 1962 г., к 175-летию со дня рождения поэта, советом учреждения было подготовлено обращение в Министерство культуры РСФСР и в Вологодский облисполком с призывом о преобразовании музея<span> </span>в государственный. В 1969 г. Народный музей А. И. Куприна и Батюшковых был реорганизован в Дом Батюшковых – Куприна. </p> <p>В 1987 г., к 200-летию со дня рождения поэта, была открыта новая экспозиция, посвященная роду Батюшковых, воссозданы усадебные интерьеры <span>XIX</span> в.: гостиные, столовая, кабинет, где представлены мемориальные вещи, принадлежавшие Ф. Д. Батюшкову. С 1995 г. второй этаж дома заняла постоянно действующая выставка с материалами о жизни и творчестве писателя А. Куприна и его посещениях Устюжны и Даниловского. </p> <p>Ежегодно в мае в усадьбе на межрегиональном конкурсе чтецов «Отеческие пенаты» встречаются любители поэзии. Мероприятие посвящено дню рождения К. Батюшкова. Кроме того, музей приглашает на тематические и интерактивные экскурсии, литературно-исторические квесты, зимой – на новогодние и рождественские елки для детей, традиция проведения которых была заложена А. Куприным. </p> <p>Архивный фонд Музея-усадьбы Батюшковых и А. И. Куприна с документами рода Батюшковых и их окружения <span>XIX </span>– нач. <span>XX</span> в. находится в фондах Устюженского краеведческого музея.</p>', 'http://ukm35.ru', 'ukm35@mail.ru', '[{"value": "79211354344"}]', '{"url": "https://all.culture.ru/uploads/3e0ddd022bf5fffc1a798cbf0482fb31.jpeg", "title": "102.jpeg"}', '[{"url": "https://all.culture.ru/uploads/754c89250c679007df41f48a3bbdba48.jpeg", "title": "101.jpeg"}]', NULL, 'Музеи и галереи', 'МБУК «Устюженский краеведческий музей»', 'Устюженский район', 'Europe/Moscow', 'пл Соборная,д 5', NULL, 'обл Вологодская,р-н Устюженский,г Устюжна,пл Соборная,д 5', NULL, 3520002426, 'mincult', 'Устюженский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК \"Устюженский краеведческий музей\"","networkId":"58033465","updateDate":"2018-04-12T15:53:42Z","createDate":"2018-04-12T15:53:42Z","accountId":20795,"postingGroupId":18421},{"network":"vk","name":"Усадьба Батюшковых и А.И.Куприна в Даниловском","networkId":"133747579","updateDate":"2018-04-12T15:57:56Z","createDate":"2018-04-12T15:57:56Z","accountId":20795,"postingGroupId":18422}]', 4326, '[{"name": "История"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Доступная среда"}, {"name": "Классическое искусство"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей-усадьба"]', NULL, 60272, '[{"url":"https://www.culture.ru/institutes/59905/muzei-usadba-batyushkovykh-i-a-i-kuprina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/ustyuzhna/muzei-i-galerei/61326pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=4695a8c0-17d6-4045-8888-75c8ace1ce53&shareType=venue","serviceName":"ФанТам"}]', 60272, NULL, NULL, NULL, '2022-01-28 15:37:15+03', '2025-09-19 16:23:43+03', 2571, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музейно-творческий центр народного художника России В. Н. Корбакова', 'Вологда', 'Europe/Moscow', 'ул Октябрьская,д 13', NULL, 'обл Вологодская,г Вологда,ул Октябрьская,д 13', '{"type": "Point"}', '<p>Постоянная экспозиция живописных и графических произведений В. Н. Корбакова в Доме Корбакова включает в себя не только произведения из дара художника городу Вологде, но и работы разных лет, находящиеся в фондах Вологодской областной картинной галереи.</p><p> Живописные работы, представленные в выставочных залах центра, отражают самые характерные направления и черты дарования Корбакова. Это пейзажи, портреты, натюрморты, сюжетно-тематические картины. Среди пейзажных работ художника большой раздел занимают живописные и графические произведения, созданные им во время пленэров в старинных русских городах Вологодской области.<br></p><p> </p><p>Наряду с пейзажными работами в экспозиции большое место занимают портреты. Портретные серии Корбакова – это портреты его современников, людей разных возрастов и профессий, но одинаково интересных для художника. В экспозиции представлены портреты ветеранов Великой Отечественной войны, женские портреты, портреты детей и молодежи. Исключительную ценность представляют натурные и историко-документальные портреты вологжан.</p><p>Наряду с живописными и графическими произведениями В. Корбакова хранится и экспонируется уникальная коллекция портретов художника «Меня рисуют друзья», которая создавалась отечественными и зарубежными художниками за последние полвека. Среди авторов работ – признанные классики современного искусства: В. Попков, Т. Салахов, Т. Яблонская, И. Глазунов.</p>', 'http://www.vologda-gallery.ru', 'chief-gallery@mail.ru', '[{"value": "78172725576", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/46634272cef00b429796c531feb9ead6.jpg", "title": "dbf6b28a217bdc423e0736c4da79d4e1.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодская областная картинная галерея»', 'Вологда', 'Europe/Moscow', 'ул Мира,д 34', NULL, 'обл Вологодская,г Вологда,ул Мира,д 34', NULL, 3525022842, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 3132, '[{"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 6233, '[{"url":"https://www.culture.ru/institutes/11799/muzeino-tvorcheskii-centr-narodnogo-khudozhnika-rossii-v-n-korbakova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/2820pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=16b82755-fd51-4ffd-b2b2-903aeb7de1a7&shareType=venue","serviceName":"ФанТам"}]', 6233, 11799, 4345, NULL, '2015-04-27 10:51:28+03', '2025-08-29 16:17:50+03', 2659, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Евгения Преображенского', 'Кирилловский район', 'Europe/Moscow', 'ул Преображенского,д 3', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Преображенского,д 3', '{"type": "Point"}', '<p>Экспозиционный комплекс с полноценным мультимедийным наполнением разместился в семи залах здания бывшего Народного дома. Это совместный проект Кирилло-Белозерского музея-заповедника и Российского военно-исторического общества. Он посвящен советской авиации времен Великой Отечественной войны, рассказывает о летчиках – уроженцах Кирилловского района, участниках войны, конструкторах авиационной техники и авиационного вооружения.</p><p> Основная часть экспозиции посвящена жизни Е. Н. Преображенского – выдающегося летчика, родившегося и выросшего на Кирилловской земле. Также представлены материалы об уроженцах Кирилловского района и Вологодской области, связанных с авиацией. Среди них авиаконструктор С. В. Ильюшин и конструктор авиационного оружия М. Е. Березин, а также известные летчики – Герой Советского Союза В. Н. Калачев, старейшие русские авиаторы, участники Первой мировой, Гражданской и Великой Отечественной войн И. Г. Чучин и С. А. Мельников, генерал-майор авиации А. Ф. Обухов, подполковник авиации Н. З. Павлов, командир авиаэскадрильи майор А. В. Виноградов, генерал-майор авиации В. Ф. Воронов.</p>', 'http://kirmuseum.org', NULL, '[]', '{"url": "https://all.culture.ru/uploads/3feb75ac4c3df68717b79a67cec32530.jfif", "title": "f9e55728911be14e08883346694cfcd0.jfif"}', '[{"url": "https://all.culture.ru/uploads/f7f43f33e37b258d03e5239f4b329130.jpg", "title": "пр1.jpg"}, {"url": "https://all.culture.ru/uploads/0e2d82d9f8c48d6ed0376c89fe6df03e.jpg", "title": "пр2.jpg"}, {"url": "https://all.culture.ru/uploads/156a3a924dd4eb20e520adc306402be1.jpg", "title": "пр3.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "История"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Военно-Исторический"]', NULL, 64688, '[{"url":"https://www.culture.ru/institutes/65653/muzei-evgeniya-preobrazhenskogo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/68943pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1edc3ebb-fdaa-452f-ace0-5f9d70db7b91&shareType=venue","serviceName":"ФанТам"}]', 64688, NULL, NULL, NULL, '2022-03-01 15:25:15+03', '2025-08-27 16:39:42+03', 2836, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей военной техники «Парк Победы»', 'Череповец', 'Europe/Moscow', 'ул Парковая', NULL, 'обл Вологодская,г Череповец,ул Парковая', '{"type": "Point"}', '<p>Музей военной техники «Парк Победы» открылся 9 мая 2015 года в честь 70-летия Победы в Великой Отечественной войне.</p><p>На площадках под открытым небом представлены образцы советского и российского вооружения: бронетанковая и транспортная техника, зенитно-ракетное и артиллерийское вооружение. Коллекция военной техники продолжает пополняться новыми экспонатами.</p><p></p><p>В музее представлено несколько экспозиций: «Пограничный рубеж» – макет участка государственной границы Российской Федерации, «Передний край», где воссоздан участок линии фронта времен Великой Отечественной войны, «Горячая точка», рассказывающая о межрегиональных конфликтах. На территории музея установлены памятник Герою Советского Союза, генералу армии В. Ф. Маргелову и Памятный знак, посвященный подвигу во время Великой Отечественной войны доноров крови города Череповца. Для посетителей работает выставочный зал.</p><p></p><p></p><p>Музей военной техники стал для Череповца символом памяти о героических страницах военной истории страны. Это место, куда приходят горожане, чтобы почувствовать связь с поколением победителей и отдать дань уважения защитникам Отечества.</p>', 'https://www.чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493323"}]', '{"url": "https://all.culture.ru/uploads/2578fdef474f258f255d5d8ff7c24b85.jpg", "title": "DEW31RV-Eas.jpg"}', '[{"url": "https://all.culture.ru/uploads/f2c344cb57385450387c158177aaa324.jpg", "title": "X6ZWarGM9QA.jpg"}, {"url": "https://all.culture.ru/uploads/0e9fb45f6dd3c672cb9fd71a9a4ffdf6.jpg", "title": "sj2pcuRjYu4.jpg"}, {"url": "https://all.culture.ru/uploads/488732d543d0a3bbd0bd57d80e8478fd.jpg", "title": "2-8cCP7ztQ4.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Реконструкция"}, {"name": "Открытые площадки"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Военно-Исторический"]', NULL, 64693, '[{"url":"https://www.culture.ru/institutes/64714/muzei-voennoi-tekhniki-park-pobedy","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/68945pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=6fc69bb7-88d2-4f59-af65-55eb73eec805&shareType=venue","serviceName":"ФанТам"}]', 64693, NULL, NULL, NULL, '2022-03-01 15:54:23+03', '2025-09-04 14:46:09+03', 2838, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Тотемский краеведческий музей', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д 44', '{"type": "Point"}', '<p><span>Тотемский краеведческий музей был основан в 1915 году членами Вологодского научного общества по изучению Северного края. На протяжении уже 100 лет основная экспозиция краеведческого музея размещена в помещениях бывшего духовного училища. Сейчас в главном музейном здании располагаются отделы археологии, истории, искусства и природы. </span></p><p><span>25 залов экспозиции – серьезный повод для того, чтобы уделить этому музею самое пристальное внимание. Богатые археологические коллекции занимают три зала экспозиции. В 2019 году открылся зал палеонтологии «Сухонские ящеры». В исторической экспозиции музея особый интерес вызывает зал, посвященный солеварению в Тотьме. Не оставят ни одного посетителя равнодушными экспозиции, посвященные Петровской ремесленной школе и творчеству художника-земляка Феодосия Михайловича Вахрушова. С миром флоры и фауны региона гостей знакомит обновленный отдел природы.</span></p>', 'http://tourizm-totma.ru/museum', 'totmamuz@mail.ru', '[{"value": "78173922337"}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/93a1344e4ee545f4a41862ebd3dc8409.jpg", "title": "Здание краеведческого музея (2).jpg"}', '[{"url": "https://all.culture.ru/uploads/2a03a34f960494fd5f57285d94668174.jpg", "title": "экспозиция  краеведческого 15.jpg"}, {"url": "https://all.culture.ru/uploads/c8f1510ec486933cd3d969a36a6c3aca.jpg", "title": "экспозиция краеведческого музея 7.jpg"}, {"url": "https://all.culture.ru/uploads/dd306ffa3b566c277d28c3e515ec31bf.jpg", "title": "экспозиция  краеведческого музея 8.jpg"}, {"url": "https://all.culture.ru/uploads/d5b8f8665ba6be0218360aca187d835e.jpg", "title": "экспозиция краеведческого 17.jpg"}, {"url": "https://all.culture.ru/uploads/4dc217b29265617b103f905b988ec607.jpg", "title": "экспозиция краеведческого музея.jpg"}, {"url": "https://all.culture.ru/uploads/990ea66ba5b5435dcd4d8f81a9512931.jpg", "title": "image378.jpg"}, {"url": "https://all.culture.ru/uploads/790cea95a1abc59c92cdb5e89a71060a.jpg", "title": "W1EvvVg2BEk.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "История"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Классическое искусство"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 6485, '[{"url":"https://www.culture.ru/institutes/12082/totemskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/polevskoy/muzei-i-galerei/99405pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=a0ef5d2f-68d1-4a14-9f4c-1825c998b38d&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 6485, 12082, 113853, 1743, '2015-04-28 10:42:09+03', '2025-09-05 10:35:24+03', 2854, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Интерактивный музей бумаги г. Сокол', 'Сокольский район', 'Europe/Moscow', 'пр-кт Советский,д 8', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,пр-кт Советский,д 8', '{"type": "Point"}', '<p>Интерактивный музей бумаги – единственный музей такого типа в Северо-Западном федеральном округе России. Он открылся 19 декабря 2014 года, став ярким образцом государственно-частного партнерства между администрацией Сокольского муниципального района и ПАО «Сокольский целлюлозно-бумажный комбинат». </p><p>Музей располагает пятью выставочными залами. В экспозиции представлены материалы по истории создания бумаги, по развитию предприятий целлюлозно-бумажной промышленности, а также подлинные экспонаты – станки, лабораторное оборудование, изделия из бумаги. Украшением экспозиции музея является макет бумагоделательной машины, выполненный студентами Сокольского ЦБТ в 1970-е гг.</p>', 'https://sokolmuzey.ru', 'sokolmuzei@mail.ru', '[{"value": "78173321059", "comment": ""}, {"value": "79535093213", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/c1b54ac1168d698e4c3b3fbdfd58d856.jpg", "title": "jBJSeOxwMas.jpg"}', '[{"url": "https://all.culture.ru/uploads/db4822f884b59693daffca0dfb1e5fb7.jpg", "title": "oIxNrLTi7AM.jpg"}, {"url": "https://all.culture.ru/uploads/4d5a57ff239f95ff3ed3af6d3b794b31.jpg", "title": "11UZsuZQ214.jpg"}, {"url": "https://all.culture.ru/uploads/490efc2d0bb4e81fce92135462fae2b3.jpg", "title": "9e3lCWyAztY.jpg"}, {"url": "https://all.culture.ru/uploads/607e6c2f58eec9277d8a1755349d399c.jpg", "title": "AtvZ6C5y7Lo.jpg"}]', NULL, 'Музеи и галереи', 'БУК СМО «Сокольский Музей»', 'Сокольский район', 'Europe/Moscow', 'ул Набережная Свободы,д 50', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Набережная Свободы,д 50', NULL, 3527011740, 'mincult', 'Сокольский район', 'Europe/Moscow', '[{"network":"vk","name":"Кадниковский краеведческий музей","networkId":"195495184","updateDate":"2023-07-10T12:49:58Z","createDate":"2021-05-05T17:34:23Z","accountId":37643,"postingGroupId":34337},{"network":"vk","name":"Сокольский музей","networkId":"217753345","updateDate":"2022-12-22T11:23:09Z","createDate":"2022-12-22T11:23:09Z","accountId":44385,"postingGroupId":38636},{"network":"vk","name":"Сокольский-Районный Музей","networkId":"364420001","updateDate":"2022-12-22T11:23:29Z","createDate":"2022-12-22T11:23:29Z","accountId":44385,"postingGroupId":38637}]', 2555, '[{"name": "Наука и техника"}, {"name": "История"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий","Истории организаций"]', NULL, 64943, '[{"url":"https://afisha7.ru/sokol/muzei-i-galerei/69088pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/66045/interaktivnyi-muzei-bumagi-g-sokol","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=af64060f-f525-4bae-ac15-9c8da1734e3e&shareType=venue","serviceName":"ФанТам"}]', 64943, NULL, NULL, NULL, '2022-03-04 16:47:54+03', '2023-03-05 08:27:51+03', 2857, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Николая Клюева', 'Вытегорский район', 'Europe/Moscow', 'пр-кт Советский,д 6а', 'Здание детской библиотеки, 2-й этаж', 'обл Вологодская,р-н Вытегорский,г Вытегра,пр-кт Советский,д 6а', '{"type": "Point"}', '<p>Музей основан в 1991 году, рассказывает о жизненном и творческом пути русского поэта начала XX века Николая Алексеевича Клюева. Музей расположен в здании, в котором поэт в течение 5 лет снимал квартиру.  Основу экспозиции составляют личные вещи поэта, фотографии и документы, переданные старожилами города и наследниками его столичных друзей. Особую роль в формировании фонда музея сыграли С. И. Субботин, Б. Н. Кравченко, Н. Д. Перуанская, М. И. Ручьев, В. С. Шевелева, Н. В. Клычкова, Н. Ю. Грякалова. Музейное пространство организовано в виде деревянной шкатулки-ларца, витрины напоминают старообрядческие складные иконы. </p>', 'https://museum-vytegra.vlg.muzkult.ru', 'klyuev.09@mail.ru', '[{"value": "79585851020", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f0249e4b65a5205d524c00624aeee0f5.JPG", "title": "Музей  Н.Клюева.JPG"}', '[{"url": "https://all.culture.ru/uploads/cb877fbc4815df71ae974d0aedaa7a65.jpg", "title": "vy060000.jpg"}, {"url": "https://all.culture.ru/uploads/ed35bcddd445a602413e25329c30250e.JPG", "title": "DSC06214.JPG"}, {"url": "https://all.culture.ru/uploads/f267e49523c1bab487b65380ccc0bb30.jpg", "title": "DSC01499 1.jpg"}, {"url": "https://all.culture.ru/uploads/c37e4350d2ccd7456160b54e3209ce4f.JPG", "title": "DSC01502.JPG"}, {"url": "https://all.culture.ru/uploads/991907a736ac3d06173e2e15cef7fe82.JPG", "title": "DSC06233.JPG"}, {"url": "https://all.culture.ru/uploads/13f3057d7916241610472572baba1d48.JPG", "title": "DSC06251.JPG"}]', NULL, 'Музеи и галереи', 'МБУК «Вытегорский объединенный музей»', 'Вытегорский район', 'Europe/Moscow', 'ул 3 Интернационала,д 2', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,ул 3 Интернационала,д 2', NULL, 3508003511, 'mincult', 'Вытегорский район', 'Europe/Moscow', '[{"network":"vk","name":"Вытегорский объединенный музей","networkId":"64441013","updateDate":"2025-07-15T11:35:30Z","createDate":"2025-07-15T11:35:30Z","accountId":53518,"postingGroupId":48169},{"network":"vk","name":"Елена Шинкарчук","networkId":"121910670","updateDate":"2025-07-15T11:36:33Z","createDate":"2025-07-15T11:36:33Z","accountId":53518,"postingGroupId":48170}]', 10671, '[{"name": "Дом-музей"}, {"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Литературный","Персональный, мемориальный"]', NULL, 65441, '[{"url":"https://www.culture.ru/institutes/78832/muzei-nikolaya-klyueva","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vytegra/muzei-i-galerei/71034pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=2d0f0e0a-4168-465f-90f3-5c93ed036da8&shareType=venue","serviceName":"ФанТам"}]', 65441, NULL, NULL, NULL, '2022-03-17 09:38:54+03', '2023-03-28 11:30:59+03', 2897, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Литературный музей д. Владимировка', 'Череповецкий район', 'Europe/Moscow', 'ул Северянина,д 1', NULL, 'обл Вологодская,р-н Череповецкий,д Владимировка,ул Северянина,д 1', '{"type": "Point"}', '<p>Литературный музей находится в 40 километрах от Череповца близ деревни Владимировка, на берегах рек Суды и Кемзы, в окружении хвойного леса. Это живописное место в середине XIX века стало поэтической колыбелью будущего поэта Игоря Северянина. Здесь он проводил каникулы во время учебы в Череповецком реальном училище и сюда приезжал уже известным человеком.</p><p><span>Двухэтажный усадебный дом был построен дядей поэта М. П. Лотаревым. Чудесная природа здешних мест оставила неизгладимый след в душе поэта и пробудила в нем, по его собственному признанию, поэтическое вдохновение. У милого сердцу северного уголка он взял себе и поэтическое имя – Северянин. Сегодня в большом усадебном доме размещается экспозиция, рассказывающая об истории усадьбы и ее бывших владельцах, о самом знаменитом представителе семейства Лотаревых – поэте Северянине.</span></p><p><span>В экспозиции представлены архивные фотографии, учебники с отметкой реального училища, в котором обучался Игорь Северянин, подлинное зеркало. Дочь управляющего усадьбой Александра Спиричева рассказывала, как поэт, будучи гимназистом, не раз приезжал во Владимировку к своему дяде Михаилу Лотареву, поскольку был влюблен в его дочь Лизавету. Чтобы понравиться кузине, Северянин подолгу стоял перед зеркалом и тщательно прорисовывал тушью только что пробившиеся усики. Зеркало сохранилось идеально. </span></p><p><span> </span></p><p><span>Посещение и экскурсии – только по предварительной заявке. </span><span><br /></span></p>', 'http://чермо.рф', NULL, '[{"value": "78202517973", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d2ea15c88389d01ac6fa6bfb02c8d563.jpeg", "title": "DSC_0977_kopia.jpg"}', '[{"url": "https://all.culture.ru/uploads/c6139c1d1a4b6e05e468d75f957f6f73.JPG", "title": "IMG_0302.JPG"}, {"url": "https://all.culture.ru/uploads/bd2f19118233b029317fa3ad9ff1ae96.JPG", "title": "IMG_0299.JPG"}, {"url": "https://all.culture.ru/uploads/3a61cb3fd57489092d399a48ed26abdc.JPG", "title": "IMG_0303.JPG"}, {"url": "https://all.culture.ru/uploads/3c95e2d73166861765fa13a7d8e7548d.JPG", "title": "IMG_0362.JPG"}, {"url": "https://all.culture.ru/uploads/3df245b0c4c478409507a3c8b2f745a4.JPG", "title": "IMG_0557.JPG"}, {"url": "https://all.culture.ru/uploads/5cd5d91c9ea4e2a72e7d2486dc6f5256.jpeg", "title": "4MJnQu_MXbk.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Экскурсии"}, {"name": "Усадьба"}, {"name": "Биография"}, {"name": "Литература"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Литературный"]', NULL, 6633, '[{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/3037pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/12145/literaturnyi-muzei-d-vladimirovka","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=415138fd-6a18-42ed-8cae-e929796dc0d5&shareType=venue","serviceName":"ФанТам"}]', 6633, 12145, 4367, NULL, '2015-04-28 12:05:53+03', '2025-09-09 17:31:53+03', 2981, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей вепсской культуры', 'Бабаевский район', 'Europe/Moscow', 'д 4', NULL, 'обл Вологодская,р-н Бабаевский,д Берег,д 4', '{"type": "Point"}', '<p><span>Музей вепсской культуры был открыт 24 июня 2004 года в Куйском сельсовете. До этого была проведена большая собирательская работа. Огромную роль в открытии музея сыграли Н. Г. Зайцева – доктор филологических наук, З. И. Строгальщикова, В. К. Яшов и др. В 2007 году помещение музея было передано библиотеке, и все экспонаты перевезли в деревню Берег. </span></p> <p><span>В настоящее время здесь можно увидеть предметы быта, которыми пользовались вепсы – малочисленный коренной народ. В экспозиции представлена литература на вепсском языке. Музей находится далеко от центра, сегодня это уголок нетронутой природы, где можно услышать вепсскую речь, узнать о культуре вепсского народа. </span></p>', 'http://km-babaevo.vlg.muzkult.ru', 'babaevomuzei@yandex.ru', '[{"value": "78174321531"}, {"value": "78174321531"}]', '{"url": "https://all.culture.ru/uploads/9796e867f5f0feb836a7716e2c11ec4b.jpg", "title": "aZm4l_AJm7A.jpg"}', NULL, NULL, 'Музеи и галереи', 'Бабаевский краеведческий музей им. М.В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'переулок Юных пионеров,2', NULL, 'обл Вологодская,р-н Бабаевский,д Бабаево,переулок Юных пионеров,2', NULL, 3501006658, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Бабаевский краеведческий музей","networkId":"205571511","updateDate":"2023-05-26T07:21:53Z","createDate":"2023-05-26T07:21:53Z","accountId":47783,"postingGroupId":42436}]', 2800, '[{"name": "История"}, {"name": "Этнография"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 66951, '[{"url":"https://www.culture.ru/institutes/81060/muzei-vepsskoi-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/muzei-i-galerei/74237pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d4bf72e0-a9d0-426b-a6f4-0e3b365ee1b8&shareType=venue","serviceName":"ФанТам"}]', 66951, NULL, 10499, NULL, '2022-03-25 08:27:19+03', '2026-02-17 11:56:59+03', 3035, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Борисовский краеведческий музей им. Ю. А. Голубцова', 'Бабаевский район', 'Europe/Moscow', 'ул Быстрова,д 13', NULL, 'обл Вологодская,р-н Бабаевский,с Борисово-Судское,ул Быстрова,д 13', '{"type": "Point"}', '<p><span>Борисовский музей носит имя Юлия Александровича Голубцова – учителя географии, краеведа, неутомимого путешественника, человека с энциклопедическими знаниями. В 1958 году Юлий Александрович создал школьный музей, а затем Борисовский сельский. Открытие музея состоялось в ноябре 1987 года.</span></p> <p><span>Сегодня здесь можно познакомиться с богатейшей историей села, с материалами о дворянских усадьбах Качаловых, Пушторских, Владимирских, Паниных.</span></p> <p><span>В экспозиции представлены предметы деревенского обихода, в том числе старинная посуда, сундуки, льняная одежда, фонари, прялки, зобеньки, предметы кузнечного ремесла и многое другое. Также посетители имеют возможность познакомиться с работами народных умельцев. </span></p>', 'http://km-babaevo.vlg.muzkult.ru', NULL, '[{"value": "78174321531"}, {"value": "78174321531"}]', '{"url": "https://all.culture.ru/uploads/3323e3aff55749d24242ac4cfb12ddd6.jpg", "title": "-jVJ25af8_A.jpg"}', NULL, NULL, 'Музеи и галереи', 'Бабаевский краеведческий музей им. М.В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'переулок Юных пионеров,2', NULL, 'обл Вологодская,р-н Бабаевский,д Бабаево,переулок Юных пионеров,2', NULL, 3501006658, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Бабаевский краеведческий музей","networkId":"205571511","updateDate":"2023-05-26T07:21:53Z","createDate":"2023-05-26T07:21:53Z","accountId":47783,"postingGroupId":42436}]', 2800, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 66952, '[{"url":"https://www.culture.ru/institutes/81059/borisovskii-kraevedcheskii-muzei-im-yu-a-golubcova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/muzei-i-galerei/74238pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=fcc7ee5a-4edf-4f2b-98b3-08663157569a&shareType=venue","serviceName":"ФанТам"}]', 66952, NULL, 10498, NULL, '2022-03-25 08:31:43+03', '2026-01-27 09:56:34+03', 3036, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Пожарский краеведческий музей им. В. С. Басникова', 'Бабаевский район', 'Europe/Moscow', 'ул Центральная,д 4', NULL, 'обл Вологодская,р-н Бабаевский,д Пожара,ул Центральная,д 4', '{"type": "Point"}', '<p><span>В деревне Пожара в здании бывшей колхозной конторы 14 июня 1974 года открылся первый музей. Директором музея был назначен Александр Михайлович Константинов, ветеран педагогического труда, он посвятил музею 17 лет. С помощью народных умельцев и деревенских жителей Александр Михайлович создавал первые экспозиции. </span></p> <p><span>За активную воспитательную работу и развитие музейного дела 18 мая 1984 года Пожарскому музею было присвоено звание «народный». В 1997 году решением администрации Бабаевского района присвоено имя Василия Сергеевича Басникова.</span></p> <p><span>В настоящее время в «Зале боевой славы» можно услышать о подвигах пожарцев, в «Зале трудовой славы» – о трудовых достижениях земляков</span> <span>и деятельности колхоза им. XXI съезда КПСС. В комнате «Предметы старины» можно познакомиться с бытом и жизнью наших предков, в «Русской избе» – узнать об укладе жизни крестьян.</span> </p>', 'http://km-babaevo.vlg.muzkult.ru', NULL, '[{"value": "78174321531"}]', '{"url": "https://all.culture.ru/uploads/d5c2043651c3f606ddb05bdaf28b1604.jpg", "title": "aNa_thXFjCg.jpg"}', NULL, NULL, 'Музеи и галереи', 'Бабаевский краеведческий музей им. М.В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'переулок Юных пионеров,2', NULL, 'обл Вологодская,р-н Бабаевский,д Бабаево,переулок Юных пионеров,2', NULL, 3501006658, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Бабаевский краеведческий музей","networkId":"205571511","updateDate":"2023-05-26T07:21:53Z","createDate":"2023-05-26T07:21:53Z","accountId":47783,"postingGroupId":42436}]', 2800, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 66953, '[{"url":"https://www.culture.ru/institutes/81036/pozharskii-kraevedcheskii-muzei-im-v-s-basnikova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/muzei-i-galerei/74239pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=65b1d50f-f67a-4beb-be73-77cf62c3c2a9&shareType=venue","serviceName":"ФанТам"}]', 66953, NULL, 10545, 147474, '2022-03-25 08:36:31+03', '2026-02-17 10:44:07+03', 3037, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Тимошинский краеведческий музей им. А. В. Ульянова', 'Бабаевский район', 'Europe/Moscow', 'ул Школьная,д 14', NULL, 'обл Вологодская,р-н Бабаевский,д Тимошино,ул Школьная,д 14', '{"type": "Point"}', '<p>Тимошинский краеведческий музей имени Андрея Васильевича Ульянова.</p><p>Впервые идею о создании музея в деревне Тимошино в 1979 г. предложил<span> Андрей Васильевич </span>Ульянов. </p> <p><span>Тимошинский музей истории колхоза «Ленинский путь» открылся 9 мая 1981 г. Эта дата была приурочена к 36-й годовщине Великой Победы. После смерти Андрея Васильевича Ульянова (25 февраля 2002 г.) решением Бабаевского районного собрания представителей № 13 от 26 апреля 2002 г. музею присвоено его имя.</span></p> <p><span>На сегодняшний день здесь представлено более 4 000 экспонатов, которые располагаются в залах музея, отражающих историю, культуру, <span> </span>природу края.</span></p>', 'http://km-babaevo.vlg.muzkult.ru', NULL, '[{"value": "78174321531"}, {"value": "78174321531"}]', '{"url": "https://all.culture.ru/uploads/2e41fcc327b19ff9e9290e13a33ce045.jpg", "title": "0a5bfb91fca896f0-w373-h200.jpg"}', NULL, NULL, 'Музеи и галереи', 'Бабаевский краеведческий музей им. М.В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'переулок Юных пионеров,2', NULL, 'обл Вологодская,р-н Бабаевский,д Бабаево,переулок Юных пионеров,2', NULL, 3501006658, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Бабаевский краеведческий музей","networkId":"205571511","updateDate":"2023-05-26T07:21:53Z","createDate":"2023-05-26T07:21:53Z","accountId":47783,"postingGroupId":42436}]', 2800, '[{"name": "Доступная среда"}]', NULL, NULL, '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 66956, '[{"url":"https://www.culture.ru/institutes/81038/timoshinskii-kraevedcheskii-muzei-im-a-v-ulyanova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/muzei-i-galerei/74240pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=e2a240c3-1779-4bba-9b7f-e22d54112e4f&shareType=venue","serviceName":"ФанТам"}]', 66956, NULL, 10546, 147493, '2022-03-25 08:42:43+03', '2026-01-27 09:54:29+03', 3038, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Вологодская областная картинная галерея', 'Вологда', 'Europe/Moscow', 'ул Мира,д 34', NULL, 'обл Вологодская,г Вологда,ул Мира,д 34', '{"type": "Point"}', '<p>На выставочной площадке сформированы пять экспозиций, в том числе две постоянные (третий, четвертый этажи) и три временные выставки (второй, пятый этажи), что позволяет широко раскрыть богатейшую коллекцию регионального художественного музея и представить творчество выдающихся мастеров изобразительного искусства. С учетом архитектуры и структуры внутренних помещений здания в нем наиболее логичным представляется экспонирование произведений современного искусства, в связи с чем главный акцент будет сделан на творчестве художников XX–XXI веков: от мастеров авангарда до современников.</p> <p>На третьем этаже создана постоянная экспозиция «Искусство XX–XXI веков», в которой представлены произведения живописи, графики, скульптуры ведущих отечественных художников Ильи Машкова, Роберта Фалька, Константина Юона, Петра Кончаловского, Михаила Нестерова, Юрия Кугача, Николая Андронова, Зураба Церетели и многих других из собрания Вологодской областной картинной галереи.</p> <p>В выставочных пространствах четвертого этажа разместилась впервые созданная в Вологде постоянная экспозиция «Вологодские художники XX–XXI веков», которая представляет произведения живописи, графики, скульптуры, декоративно-прикладного искусства ведущих вологодских художников Владимира Корбакова, Джанны Тутунджан, Михаила Ларичева, Николая Баскакова, Олега Бороздина, Александра Пантелеева, Евгения Соколова, Яна Крыжевского, Генриха Асафова, Георгия Калинина, Валерия Страхова, Юрия Воронова, Николая Мишусты и других из собрания Вологодской областной картинной галереи.</p>', 'http://www.vologda-gallery.ru', 'chief-gallery@mail.ru', '[]', '{"url": "https://all.culture.ru/uploads/758244850e30c18f082fe4bb7625c61a.JPG", "title": "DSC_2634.JPG"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодская областная картинная галерея»', 'Вологда', 'Europe/Moscow', 'ул Мира,д 34', NULL, 'обл Вологодская,г Вологда,ул Мира,д 34', NULL, 3525022842, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 3132, '[{"name": "Современное искусство"}, {"name": "Искусство"}, {"name": "Доступная среда"}, {"name": "Изобразительное искусство"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Изобразительного исскуства"]', NULL, 6797, '[{"url":"https://www.culture.ru/institutes/11830/vologodskaya-oblastnaya-kartinnaya-galereya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3158pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=0b591d0d-d884-4d4d-9304-ba25455fcfa4&shareType=venue","serviceName":"ФанТам"}]', 6797, 11830, 1749, 113938, '2015-04-28 14:19:38+03', '2025-08-29 16:19:57+03', 3120, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом-музей А. А. Угрюмова', 'Тарногский район', 'Europe/Moscow', 'ул Советская,д 20', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Советская,д 20', '{"type": "Point"}', '<p>Музей открыл свои двери для посетителей 26 февраля 2002 года. Это деревянный дом, украшенный резными наличниками, построенный в 1929 году. В нем проживали первый врач кокшеньгской земской больницы А.П. Угрюмов (1874-1939) и Почетный гражданин села Тарногский Городок, заслуженный учитель школ РСФСР, краевед Андрей Андреевич Угрюмов (1915-1995) со своей семьей. Изначально, экспонаты были размещены в комнатах по темам: «Родословная семьи Угрюмовых», «Жизнь и деятельность А.А. Угрюмова», «Развитие народного просвещения на Кокшеньге», «Жизнь сельской интеллигенции в конце XIX – н. XX века». В настоящее время постоянная экспозиция историко – мемориального отдела насчитывает 254 музейных предмета и состоит из трех залов.</p> <p>Первый зал «Краеведы и краеведение", в нем рассказывается о краеведах Кокшеньги. Одно из ведущих мест в списке краеведов занимает Величутин Василий Елизарович, энтузиаст-краелюб, основатель и первый директор Тарногского районного музея, автор более 300 публикаций в областных и районных газетах.</p> <p>Второй зал «Быт советского сельского учительства в 70-е годы XX века» . За основу экспозиции взята обстановка жилой комнаты семьи Угрюмовых. В ней представлены мемориальные музейные предметы семьи, которые позволяют окунуться в атмосферу советского прошлого.</p> <p>Третий зал «Кабинет Андрея Андреевича Угрюмова». В нем хранятся подлинные документы, предметы, фотографии, принадлежавшие краеведу и его семье. </p>', 'https://tarnog.vlg.muzkult.ru', 'm21485@yandex.ru', '[{"value": "78174821157", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/68abeeee342942cfb335d9f28d3c2b86.jpg", "title": "ди.jpg"}', '[{"url": "https://all.culture.ru/uploads/4df3389f25576ff8084d0a169860268b.JPG", "title": "13  фрагмент экспозиции А.А.Угрюмова.JPG"}, {"url": "https://all.culture.ru/uploads/9e8c577bdf65eee44d41df9e42b7571d.jpg", "title": "ДУ каб.3.jpg"}, {"url": "https://all.culture.ru/uploads/da1d643e9ce0eb435a8c85bc12e9640e.jpg", "title": "ДУ ЗО.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Тарногский музей традиционной народной культуры»', 'Тарногский район', 'Europe/Moscow', 'ул Советская,д 14', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Советская,д 14', NULL, 3517003540, 'mincult', 'Тарногский район', 'Europe/Moscow', NULL, 3846, '[{"name": "История"}, {"name": "Доступная среда"}]', NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 68048, '[{"url":"https://www.culture.ru/institutes/81452/dom-muzei-a-a-ugryumova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/tarnogskiy-gorodok/muzei-i-galerei/75170pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d1005df3-b2d3-4415-b72a-4683969182e1&shareType=venue","serviceName":"ФанТам"}]', 68048, NULL, 4508, NULL, '2022-04-05 14:02:18+03', '2025-10-07 10:27:55+03', 3128, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Нюксенский краеведческий музей', 'Нюксенский район', 'Europe/Moscow', 'ул Советская,д 5', NULL, 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Советская,д 5', '{"type": "Point"}', '<p>Инициаторами создания музея в селе Нюксенице выступили райком КПСС, отдел культуры, школа, совет ветеранов. 6 ноября 1977 года стал настоящим праздником для жителей села. Этот день стал датой открытия музея в Нюксенском районе. </p><p>В настоящее время музей насчитывает более 9000 предметов хранения. Экспозиции рассказывают и показывают историю Нюксенского края от крестьянских времен до современности. В музее можно познакомится с традиционными промыслами и ремеслами, с предметами, отражающими быт людей советской эпохи, с природой края, ее достопримечательностями.</p><p>Ежегодно в музее оформляются временные выставки, отражающие различные аспекты жизни и деятельности нюксян и историю края. В музее проводятся экскурсии на темы: «От снопа до сарафана», «Ремесла Нюксенского края», «Наше маленькое село и большая война», «Флора и фауна Нюксенского края».</p><p>Краеведческий музей работает со всеми группами населения: школами, детскими садами, школьниками, отпускниками, людьми пожилого возраста. Сегодня музея – это центр патриотического воспитания. </p>', 'http://музей.нюксеница.рф', 'kraewedchesky2010@yandex.ru', '[]', '{"url": "https://all.culture.ru/uploads/df9212528915de8959c42f694f633386.jpeg", "title": "нюксенский районный краеведческий музей.jpg"}', '[{"url": "https://all.culture.ru/uploads/48d5715906cd270dff8f65e38c4b7c2c.JPG", "title": "DSC_0214[1].JPG"}, {"url": "https://all.culture.ru/uploads/f17f22bb51f6b01ae7bc54d34d1dde74.jpg", "title": "2A2oVwe1LfYxi7DVjsEy3j1eyiU8zgvJTGSKL8BPdvvfoVNPeQ7MncrzJnPQ3cJFJLkSXD-cjXDvw622tybfbV8q.jpg"}, {"url": "https://all.culture.ru/uploads/e07cd35e267453caf4dfc920e58fe3e0.jpg", "title": "Lc6zIacLLH33nZcGSj6idRRex6GfqlAf0esROXgG8-pSj-VU1SKFWfkT5c4-11ClfOP_aVLH-4WQbdBtlHbMyjHY.jpg"}, {"url": "https://all.culture.ru/uploads/dab35d4feb250ce4e76bf765b347dbc5.jpg", "title": "ICZQJIBaYwgrGAe4PG8oWjp8AipxVB5ktrkDFHeksegP-mZxWzBRtmpXrtdfl2XVm9-Z-bhD1WOS9ribsM7-jr8m.jpg"}, {"url": "https://all.culture.ru/uploads/a211af8cb6498bfab36481feaf8e26e7.jpg", "title": "X1wON0M0c1znWGTsO-dZ7zs8C4b57YWR8nzQ60r1bW7KJLiDapHRYIK7mV1FuJ6-wANIpZjOPdZ0rvEbmwEgi70i.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «Нюксенский районный краеведческий музей»', 'Нюксенский район', 'Europe/Moscow', 'ул Советская,д 5', NULL, 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Советская,д 5', NULL, 3515003583, 'mincult', 'Нюксенский район', 'Europe/Moscow', NULL, 3960, '[{"name": "История"}, {"name": "Доступная среда"}, {"name": "Культура для школьников"}, {"name": "Для детей"}]', NULL, '{"to": "17:00:00", "from": "08:45:00"}', '{"to": "17:00:00", "from": "08:45:00"}', '{"to": "17:00:00", "from": "08:45:00"}', '{"to": "17:00:00", "from": "08:45:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 6816, '[{"url":"https://www.culture.ru/institutes/7217/nyuksenskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/nyuksenica/muzei-i-galerei/3174pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=7bcd4ccb-4c54-45d7-944b-62255aa00d2e&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 6816, 7217, 1755, 138992, '2015-04-28 14:29:23+03', '2026-03-06 16:29:46+03', 3143, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Историко-этнографический музей «Усадьба Гальских»', 'Череповец', 'Europe/Moscow', 'ул Матуринская,д 28', NULL, 'обл Вологодская,г Череповец,ул Матуринская,д 28', '{"type": "Point"}', '<p> Усадьба Гальских – памятник архитектуры, истории и культуры начала XIX века. Это один из редких примеров сохранения в городской среде не просто помещичьего дома, а всей системы хозяйственных построек (конюшни, людские избы, амбары, маслобойня, круглый сад, шорная мастерская). В усадьбе сохраняется ощущение патриархальной деревенской жизни. Здесь можно посидеть на берегу реки Шексны или в тени старой липы, полюбоваться красотой барского дома, прокатиться на лошади. </p><p>Посетители познакомятся с родословием семей Резановых, Кудрявых, Гальских, Шитовых, увидят подлинные вещи из усадеб Горка и Куркино. Даже обыкновенная домашняя утварь – короба, пестери, сундуки, прялки, дуги – сделаны умело, добротно; в них есть природная эстетика и красота. Бытовые предметы северных мастеров восхищают виртуозностью исполнения, безупречным чувством масштаба, ритма и колорита. В музее проводятся интерактивные экскурсии, занятия по росписи, лепке из глины и изготовлению народной куклы. Работает конно-спортивная секция для детей; для взрослых разработаны абонементы верховой езды. </p>', 'http://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493328", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/05a6bd8687f50ded57c3dda210a8da06.jpeg", "title": "Rq5piM8YzEo.jpg"}', '[{"url": "https://all.culture.ru/uploads/e36520ba41942cef2dae576d5be37d08.jpg", "title": "Усадьба хоровод.jpg"}, {"url": "https://all.culture.ru/uploads/b15441dd0ceeda47dac70b353b499d35.jpg", "title": "чайная.jpg"}, {"url": "https://all.culture.ru/uploads/6dd3251663f29956c7d6f5bcb75d3b92.jpg", "title": "usadba2.jpg"}, {"url": "https://all.culture.ru/uploads/2a882a10c9b54ceb5da8bda90de1d077.jpeg", "title": "l__ama6Hnus.jpg"}, {"url": "https://all.culture.ru/uploads/6a4b7f9eb6a887a0cabda7f3b3bfb976.jpeg", "title": "Q7zQPx-hK1Y.jpg"}, {"url": "https://all.culture.ru/uploads/af90749ba05ad217eb05d7b92cda108d.jpeg", "title": "SZpUbjMMxMs.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Экскурсии"}, {"name": "Усадьба"}, {"name": "Этнография"}, {"name": "Архитектура"}, {"name": "Доступная среда"}, {"name": "Культурное наследие"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, 'http://munas.ru/virtual-tours', '["Исторический","Этнографический"]', NULL, 6822, '[{"url":"https://www.culture.ru/institutes/12172/istoriko-etnograficheskii-muzei-usadba-galskikh","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/3178pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=778ad6ad-a1a6-4c47-9c4c-d2c5bcc40f14&shareType=venue","serviceName":"ФанТам"}]', 6822, 12172, 4366, NULL, '2015-04-28 14:32:21+03', '2025-09-04 12:18:55+03', 3153, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Вологодский историко-архитектурный и художественный музей-заповедник', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', '{"type": "Point"}', '<p><span>Первая попытка создания историко-архитектурного музея относится к 1885 году: именно тогда был открыт открыт для посещений домик Петра I, за которым последовало открытие других культурных учреждений. Музей включает в себя комплекс памятников Вологодского кремля и девять филиалов, среди которых Дом-музей Петра I и Музей кружева. Общая площадь памятников архитектуры, входящих в состав музея, составляет 9 000 кв. м. Ежегодно их посещают около 200 тысяч человек.</span><br></p><p>Фонды музея насчитывают более 400 000 единиц хранения. Ежегодно строится более 40 выставок различной тематики. В состав музея входят восемь подразделений: Архитектурно-этнографический музей Вологодской области, «Вологда на рубеже XIX–XX веков», «Вологодская ссылка», Дом-музей Петра I, Дом-музей А. Ф. Можайского, «Литература. Искусство. Век ХХ», «Мир забытых вещей», Музей кружева.</p>', 'http://www.vologdamuseum.ru', NULL, '[{"value": "78172722511", "comment": "Экскурсионный отдел"}, {"value": "78172728122", "comment": "Пресс-служба"}]', '{"url": "https://all.culture.ru/uploads/3ca8d962793f72119065ca8324ba14ed.jpg", "title": "lKN7cjwWRx4.jpg"}', '[{"url": "https://all.culture.ru/uploads/9661ab99d9ac08bfd7181692192ea5d8.jpg", "title": "1ed242deb7fb92b9ee19edb33a25bebb_w2048_h2048.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Архитектура"}, {"name": "Доступная среда"}, {"name": "Культура для школьников"}, {"name": "Культурное наследие"}]', NULL, NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей-заповедник"]', NULL, 6906, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3248pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/10119/vologodskii-istoriko-arkhitekturnyi-i-khudozhestvennyi-muzei-zapovednik","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=a088c116-3c79-4451-84bf-74ee6603f312&shareType=venue","serviceName":"ФанТам"}]', 6906, 10119, 1739, 113764, '2015-04-28 15:12:45+03', '2025-08-29 14:38:00+03', 3241, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Краеведческий музей Сокольского округа', 'Сокольский район', 'Europe/Moscow', 'ул Набережная Свободы,д 50', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Набережная Свободы,д 50', '{"type": "Point"}', '<p><span>Музей был основан в 1962 году. 23 февраля 1993 года общественный музей был реорганизован в Сокольский городской историко-краеведческий музей, а 1 января 2006 года прошла реорганизация музея в Краеведческий музей Сокольского района с филиалом «Кадниковский краеведческий музей». В связи с муниципальной реформой, с 17 января 2023 года музей переименован Краеведческий музей Сокольского округа. </span></p><p><span>Его основу составляют коллекции предметов материальной культуры: крестьянского быта, одежда, изделия из дерева и металла, коллекция нумизматики и фалеристики. Экспозиция музея начинается с предметов, датированных периодом эпохи мезолита и заканчивается экспонатами относящимися к быту советских людей 1980-х годов. </span></p><p><span>В настоящее время музей является научно-исследовательским и научно-просветительским учреждением, хранилищем памятников материальной и духовной культуры Сокольской земли.</span></p>', 'https://sokolmuzey.ru', 'sokolmuzei@vfil.ru', '[{"value": "78173321059", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/5df2a3cdba909d39a1567e7a994e58d3.jpeg", "title": "810606.jpg"}', '[{"url": "https://all.culture.ru/uploads/74537f0bb14b55e4dadcd439dc53ae31.jpeg", "title": "Фасад Сокольского музея (2).jpg"}, {"url": "https://all.culture.ru/uploads/93834d27fafaeaf56c83ef15c506c238.jpeg", "title": "Зал Коммунальная квартира (2).jpg"}, {"url": "https://all.culture.ru/uploads/23b9374047d7da671124e6d5d3c57ce4.jpeg", "title": "В Зале Воинской Славы.jpg"}, {"url": "https://all.culture.ru/uploads/416bbf505df264fe186306145bda5f42.jpeg", "title": "Зал Воинской Славы.jpg"}]', NULL, 'Музеи и галереи', 'БУК СМО «Сокольский Музей»', 'Сокольский район', 'Europe/Moscow', 'ул Набережная Свободы,д 50', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Набережная Свободы,д 50', NULL, 3527011740, 'mincult', 'Сокольский район', 'Europe/Moscow', '[{"network":"vk","name":"Кадниковский краеведческий музей","networkId":"195495184","updateDate":"2023-07-10T12:49:58Z","createDate":"2021-05-05T17:34:23Z","accountId":37643,"postingGroupId":34337},{"network":"vk","name":"Сокольский музей","networkId":"217753345","updateDate":"2022-12-22T11:23:09Z","createDate":"2022-12-22T11:23:09Z","accountId":44385,"postingGroupId":38636},{"network":"vk","name":"Сокольский-Районный Музей","networkId":"364420001","updateDate":"2022-12-22T11:23:29Z","createDate":"2022-12-22T11:23:29Z","accountId":44385,"postingGroupId":38637}]', 2555, '[{"name": "История"}, {"name": "Археология"}, {"name": "Искусство"}, {"name": "Этнография"}, {"name": "Доступная среда"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 7072, '[{"url":"https://afisha7.ru/sokol/muzei-i-galerei/3381pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/5353/kraevedcheskii-muzei-sokolskogo-okruga","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=aa0ec182-6cd2-4da5-aeb9-c0cc842aee2c&shareType=venue","serviceName":"ФанТам"}]', 7072, 5353, 1752, 132318, '2015-04-28 17:08:29+03', '2024-08-15 18:16:09+03', 3464, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Центр металлургической промышленности', 'Череповец', 'Europe/Moscow', 'ул Мира,д 42', 'трамвай № 4 до ост. «Водородная»; автобусы №№ 6, 8, 12, 25, 27, 37, 38 до ост. «Доменная»', 'обл Вологодская,г Череповец,ул Мира,д 42', '{"type": "Point"}', '<p><span>Центр металлургической промышленности – культурно-образовательный комплекс, посвященный истории и современности металлургической отрасли: от истоков зарождения кустарного железного промысла до создания современных промышленных гигантов, каким является Череповецкий металлургический комбинат. Индустриальная тема представлена с использованием широкого спектра музейных технологий – как традиционных, так и современных. </span></p> <p><span>Залы центра оснащены интерактивными экранами, электронными стендами, аудиовизуальными инсталляциями, которые созданы на основе уникальных фото- и видеоархивов, документов и артефактов. Здесь можно узнать об основных вехах развития металлургии, побывать на Череповецкой ярмарке ХIХ века, примерить доспехи или рабочий костюм, выплавить сталь, оживить макеты основных экологических объектов металлургического комбината.</span></p> <p><span>Экспозиции, погружающие в мир металлургии, дополняют </span><span>зал «Металлоториум» – творческая площадка, оснащенная лабораториями для изучения различных свойств металлов, и </span><span>3D-стереозал, который перенесет посетителей в основные цеха ЧерМК. </span></p> <p><span>На территории музейного комплекса создана экспозиция под открытым небом «Путешествие к стальным истокам» – собрание реальных агрегатов, которые используются как для производства, так и для перевозки металлопродукции. </span></p> <p><span>В комплекс центра входит вагон-музей академика И. П. Бардина, который сыграл важнейшую роль в истории строительства   ЧерМК, ставшего центром металлургии Северо-Западного федерального округа.</span></p>', 'http://museummet.ru', 'museummet@severstal.com', '[{"value": "78202564222"}, {"value": "78202562727"}]', '{"url": "https://all.culture.ru/uploads/9ee675c8d9312689adc62481c706fd17.jpg", "title": "1.jpg"}', '[{"url": "https://all.culture.ru/uploads/4bf1a8f3c6abec01793e052578821548.jpg", "title": "2.jpg"}, {"url": "https://all.culture.ru/uploads/f367e017fe66398479b5262e5a8db9ae.JPG", "title": "5.JPG"}, {"url": "https://all.culture.ru/uploads/9c5aa4ec79d604cbf680e0f85da53c7f.jpg", "title": "8.jpg"}, {"url": "https://all.culture.ru/uploads/ad04c81a2479a0cbc82aa054020ce5f9.JPG", "title": "3.JPG"}, {"url": "https://all.culture.ru/uploads/26056190f476a2edb977d20ff612eff1.JPG", "title": "4.JPG"}, {"url": "https://all.culture.ru/uploads/407c912874c506d1c8d61f951aa49fde.JPG", "title": "9.JPG"}]', NULL, 'Музеи и галереи', 'АНО «Информационный центр металлургической промышленности»', 'Череповец', 'Europe/Moscow', 'ул Мира,д 42', NULL, 'обл Вологодская,г Череповец,ул Мира,д 42', NULL, 3528242660, 'noncommercial', 'Череповец', 'Europe/Moscow', NULL, 30544, '[{"name": "Наука и техника"}, {"name": "История"}, {"name": "Открытые площадки"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Истории организаций","Отраслевые"]', NULL, 70752, '[{"url":"https://www.culture.ru/institutes/83885/centr-metallurgicheskoi-promyshlennosti","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/82458pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c56b3955-2801-45b5-81f3-ef92c90cbfca&shareType=venue","serviceName":"ФанТам"}]', 70752, NULL, NULL, NULL, '2022-09-03 15:55:51+03', '2022-09-05 16:16:45+03', 3466, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Шаламовский дом', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', '{"type": "Point"}', '<p><span>Коллекции русского искусства XVIII – начала ХХ века и западноевропейская живопись и графика XVII–XIX веков Вологодской областной картинной галереи с 1988 года расположена в здании на улице Сергея Орлова, больше известном в городе как Шаламовский дом. Здесь же, на первом этаже, находится мемориальный музей В. Т. Шаламова и проводятся художественные выставки.</span></p><p><span>Двухэтажный особняк, выстроенный в 1844 году, принадлежал изначально Вологодской епархии и был использован как жилое помещение для причта Софийского собора. Здесь родился и до 1924 года жил известный русский писатель Варлам Тихонович Шаламов (1907–1982). Его автобиографическая повесть «Четвертая Вологда» дает исторический и художественный образ этого дома.</span></p>', 'http://www.vologda-gallery.ru/podrazdelenie/shalamovskiy-dom-0', NULL, '[{"value": "78172721256", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/efb4c3dc1a8c0eaef343b2f8752b5074.jpg", "title": "pict3958.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодская областная картинная галерея»', 'Вологда', 'Europe/Moscow', 'ул Мира,д 34', NULL, 'обл Вологодская,г Вологда,ул Мира,д 34', NULL, 3525022842, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 3132, '[{"name": "Скульптура"}, {"name": "Доступная среда"}, {"name": "Классическое искусство"}, {"name": "Изобразительное искусство"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 7173, '[{"url":"https://www.culture.ru/institutes/11848/shalamovskii-dom","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=06b39c5b-c344-4629-b40b-907564960181&shareType=venue","serviceName":"ФанТам"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3456pl","serviceName":"Афиша7"}]', 7173, 11848, 4344, NULL, '2015-04-29 09:33:59+03', '2025-09-10 10:02:08+03', 3565, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Вологодская ссылка»', 'Вологда', 'Europe/Moscow', 'ул М.Ульяновой,д 33', NULL, 'обл Вологодская,г Вологда,ул М.Ульяновой,д 33', '{"type": "Point"}', '<p><span>Экспозиция «Вологодская ссылка» была открыта в 2006 году в д. 33 на улице М. И. Ульяновой. Это здание было выбрано неспроста: именно в этом доме проживал Иосиф Виссарионович Джугашвили (Сталин), пребывая в ссылке. Но эта историческая личность – не единственный герой экспозиции, ведь Вологодский край еще задолго до него воспринимался как «подстоличная Сибирь» и место ссылки высокопоставленных особ. Музей рассказывает о знаменитых ссыльных, их образе жизни и в полной мере раскрывает ссыльную сторону Вологодчины.</span></p><p>Для посетителей проводятся сборные экскурсии на тему «Русские писатели в вологодской ссылке», «И. В. Сталин и В. М. Молотов в вологодской ссылке», «Н. А. Бердяев и «Северные Афины» и другие. С неожиданной стороны раскроет известных политических деятелей новая программа – «Вологодские ссыльные-поэты: Сталин, Савинков, Соколовский». </p>', 'http://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172562107", "comment": "Музей «Вологодская ссылка»"}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/06b0a0bbba45de746e86cceae50d828b.jpg", "title": "8929.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Мемориал"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 7253, '[{"url":"https://www.culture.ru/institutes/11712/muzei-vologodskaya-ssylka","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3526pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=61a2d9dc-38a3-4044-8202-1c9a987f7d1a&shareType=venue","serviceName":"ФанТам"}]', 7253, 11712, 342, 134934, '2015-04-29 10:02:17+03', '2025-08-29 14:53:26+03', 3664, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Вожегодский краеведческий музей', 'Вожегодский район', 'Europe/Moscow', 'ул Садовая,д 8', NULL, 'обл Вологодская,р-н Вожегодский,рп Вожега,ул Садовая,д 8', '{"type": "Point"}', '<p><span>  </span></p><p>Музей находится в одноэтажном деревянном здании. В 1994 году здание начальной школы перевезли из деревни Лощинской Мишутинского поселения Вожегодского района в Вожегу и переоборудовали под краеведческий музей. Торжественное открытие музея состоялось 6 августа 1995 года к 100-летию посёлка Вожега. </p><p>Музей был создан на основе коллекции краеведческой комнаты районной библиотеки, собираемой на протяжении 5-6 лет на территории района. Большую её часть составляли предметы крестьянского быта, орудия труда конца XIX-начала XX веков. Первая коллекция насчитывала чуть более 500 музейных предметов. С открытия музея началось регулярное пополнение музейных фондов за счёт исследовательских экспедиций. В настоящее время фонд музея насчитывает свыше 5 тыс. единиц хранения. В его основе находятся следующие коллекции: дерево, металл, ткани, керамика, стекло, грампластинки, нумизматика, фотографии и документы, изобразительные источники.</p><p>Современная выставочная деятельность музея представлена двумя постоянными экспозициями: «Промыслы и ремесла Вожегодского края» и «Война. Победа. Память», которая состоит из 3 частей: «Железная дорога в истории края», «Славные сыны отечества» и «Время выбрало нас» (СВО). В выставочном зале оформляются тематические выставки, которые меняются раз в месяц.</p>', 'http://вожегодскиймузей.рф', 'muzey.vozhega@yandex.ru', '[{"value": "78174422657", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4da2a1c12d542837071ef15d4a620b2d.jpg", "title": "hgpMhcrr_sI.jpg"}', '[{"url": "https://all.culture.ru/uploads/8189665f4e7adfe7ff2ad90894961c06.jpg", "title": "2.jpg"}, {"url": "https://all.culture.ru/uploads/7cac15c0846a74cfe78dd965359d380f.jpg", "title": "4.jpg"}, {"url": "https://all.culture.ru/uploads/965202a7b7a54fd5f63a1899cd5b1db4.jpg", "title": "CXwwmFfKqxs.jpg"}, {"url": "https://all.culture.ru/uploads/c80037820c6f930b138f2651f5101f1b.jpg", "title": "2jH283WCXuY.jpg"}, {"url": "https://all.culture.ru/uploads/6349eba9e188cc9b6c9bacb1f749e4b3.jpg", "title": "2s0Rb5azI-g.jpg"}, {"url": "https://all.culture.ru/uploads/d4f07a832cf825cdd250122aeb4ac8fb.jpg", "title": "EYmjZwnoBOQ.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «Вожегодский краеведческий музей»', 'Вожегодский район', 'Europe/Moscow', 'ул Садовая,д 8', NULL, 'обл Вологодская,р-н Вожегодский,рп Вожега,ул Садовая,д 8', NULL, 3506003107, 'mincult', 'Вожегодский район', 'Europe/Moscow', '[{"network":"vk","name":"Вожегодский Краеведческий-Музей","networkId":"350865993","updateDate":"2023-01-12T11:14:44Z","createDate":"2023-01-12T11:14:44Z","accountId":44796,"postingGroupId":39026},{"network":"vk","name":"МБУК \"Вожегодский краеведческий музей\"","networkId":"115173391","updateDate":"2023-01-12T11:14:10Z","createDate":"2023-01-12T11:14:10Z","accountId":44796,"postingGroupId":39025}]', 3201, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Доступная среда"}, {"name": "Культура для школьников"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 7391, '[{"url":"https://www.culture.ru/institutes/11956/vozhegodskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vozhega/muzei-i-galerei/60674pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=40649eeb-2420-40f8-9818-9d583823ca56&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 7391, 11956, 1754, 138988, '2015-04-29 11:03:53+03', '2025-10-22 13:52:22+03', 3809, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Николая Рубцова', 'Вологда', 'Europe/Moscow', 'ул Герцена,д 36', NULL, 'обл Вологодская,г Вологда,ул Герцена,д 36', '{"type": "Point"}', '<p>Музей Николая Рубцова – выставка, посвященная жизни и творчеству Н. М. Рубцова. Н. М. Рубцов является одним из самых значительных лирических поэтов ХХ века. Литературная выставка представляет жизненный путь поэта и его творчество. Документальный материал, представленный на выставке, расположен хронологически по девяти разделам, составляющим экспозиционный пояс. </p><p>Поэтические комплексы – стихи Н. Рубцова, сопровождающиеся пейзажными планами Вологодчины, – придают экспозиции лиризм. Кроме постоянной и временной экспозиций и экскурсий, музей организует творческие вечера поэтов и музыкантов, а также поэтические фестивали. В музее также работает киноклуб.</p>', 'http://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172755539", "comment": "заведующий филиалом"}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/34c6ab9427ad8123a4ce0bb4a75c5da1.jpeg", "title": "IMG_4753.jpeg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "Литература"}, {"name": "Музыка"}, {"name": "Доступная среда"}, {"name": "Николай Рубцов"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 7426, '[{"url":"https://www.culture.ru/institutes/11205/muzei-nikolaya-rubcova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/86923pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b4a09bc8-8893-4892-8582-f39a5b865350&shareType=venue","serviceName":"ФанТам"}]', 7426, 11205, 361, 132375, '2015-04-29 11:19:39+03', '2026-04-13 15:44:41+03', 3846, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Верховажский историко-художественный музей', 'Верховажский район', 'Europe/Moscow', 'ул Луначарского,д 20/29', NULL, 'обл Вологодская,р-н Верховажский,с Верховажье,ул Луначарского,д 20/29', '{"type": "Point"}', '<p>Верховажский район расположен на границе с Архангельской областью. Центром района является село Верховажье, удаленное от Вологды на 230 км. Ведущее учреждение села – Музей, который основан в 1988 году силами общественности и неравнодушными учителями. Первыми предметами стали соха, борона, фотография семьи купцов Нератова и Давыдова, самовар с 12 печатями и др. На сегодняшний день фонд музея включает более 10 000 уникальных экспонатов об истории Посада Верховажье и Поважья. Выставка «История Поважья конца XIX начала ХХ веков охватывает темы сельского хозяйства и утвари, внутреннее убранство крестьянского дома, гончарный промысел, берестоплетение, роспись, ткачество. В купеческом зале можно увидеть фотографии Посада Верховажье столетней давности, в торговой лавке –»красный товар«, привозимый купцами из-за границы и столицы (ткань, чай, конфеты и т.п.). Отдельный зал посвящен 1й мировой войне, первым колхозам и Великой Отечественной войне 1941-45 гг.</p><p>Музейный комплекс включает уникальный зал двукратного олимпийского чемпиона А.Н. Алябьева. Биатлон, лыжи, медали, упорство в достижении цели – это и судьба прославленного земляка и тема выставки.</p><p>Музей живет активной яркой жизнью, проводя обзорные экскурсии по селу и району, мастер-классы и выставки декоративно-прикладного творчества и живописи. Ежегодно в музее проходят фестивали»Красная горка«(фольклор и этнография),»История в лицах" (тантемарески и исторические реконструкции), конференции по краеведению, конкурсы и арт-акции.</p>', NULL, 'm786@mail.museum.ru', '[{"value": "78175921977", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f08de18a19967985be5b8183c456c565.jpg", "title": "20210602_074915.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Верховажский районный исторический музей»', 'Верховажский район', 'Europe/Moscow', 'ул Луначарского,д 20/29', NULL, 'обл Вологодская,р-н Верховажский,с Верховажье,ул Луначарского,д 20/29', NULL, 3505003697, 'mincult', 'Верховажский район', 'Europe/Moscow', '[{"network":"vk","name":"Верховажский Музей","networkId":"206040138","updateDate":"2022-11-16T09:54:56Z","createDate":"2022-11-16T09:54:56Z","accountId":42983,"postingGroupId":37165}]', 3841, '[{"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 7436, '[{"url":"https://www.culture.ru/institutes/10587/verkhovazhskii-istoriko-khudozhestvennyi-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/verhovazhe/muzei-i-galerei/41570pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=58496aa1-eb0e-47cf-a9ff-96cab8c3ba22&shareType=venue","serviceName":"ФанТам"}]', 7436, 10587, 2694, 113726, '2015-04-29 11:24:26+03', '2023-03-23 08:32:10+03', 3854, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Кадуйский краеведческий музей им. А. Г. Юкова', 'Кадуйский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Кадуйский,рп Кадуй,ул Советская,д 16', '{"type": "Point"}', '<p>Музей расположен в историческом купеческом здании постройки начала ХХ века (с 1999 года). Здание деревянное, двухэтажное с паровым отоплением. Общая площадь музея – 300, 8 кв. м, экспозиционно-выставочная площадь – 199, 3 кв. м, площадь для хранения фондов – 22, 8 кв. м.</p><p>Дата основания музея – 70-е годы. Тогда это был школьный музей, основателем которого являлся А. Г. Юков. Дата открытия районного краеведческого музея – сентябрь 2000 года.</p><p>Экспозиция строится по тематико-хронологическому принципу, начинается с заселения края человеком и заканчивается ХХ веком. Основные разделы: «Археология», «Православие и общество», «Годы военные», «Кадуй современный», «Круг жизни». Выделены комплексы – «Рождение», «Кут», «Ткачество», «Кузница». Они представлены уникальными экспонатами. Для оформления используется разнообразная цветовая гамма, индивидуальная для каждого комплекса.</p>', 'https://musei-kadui.wixsite.com/yukov', 'musei-kadui@mail.ru', '[{"value": "78174221530", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/cd98604a424714b531258cc8cd02f680.jpg", "title": "4830868e-9421-4348-ac3f-382a5c0a9239.jpg"}', '[{"url": "https://all.culture.ru/uploads/861c6f745b4539c7714636f3579a8c53.JPG", "title": "12 (1).JPG"}, {"url": "https://all.culture.ru/uploads/efb8bb862d0b925099d62b61a2fe34bd.JPG", "title": "9 (1).JPG"}]', NULL, 'Музеи и галереи', 'МБУК «Кадуйский краеведческий музей им. А. Г. Юкова»', 'Кадуйский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Кадуйский,рп Кадуй,ул Советская,д 16', NULL, 3510006020, 'mincult', 'Кадуйский район', 'Europe/Moscow', '[{"network":"vk","name":"Кадуйский  краеведческий музей","networkId":"154957499","updateDate":"2023-03-13T12:23:43Z","createDate":"2023-03-13T12:23:43Z","accountId":37789,"postingGroupId":40903},{"network":"ok","name":"Елена Белькович (Соболева)","networkId":"437912980","isPersonal":true,"updateDate":"2022-04-29T08:58:17Z","createDate":"2022-04-29T08:58:17Z","accountId":41596,"postingGroupId":36736},{"network":"ok","name":"Культура.Кадуй","networkId":"61103236120724","updateDate":"2023-03-13T12:23:30Z","createDate":"2022-04-18T11:57:23Z","accountId":41596,"postingGroupId":36705}]', 2918, '[{"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 7628, '[{"url":"https://www.culture.ru/institutes/11710/kaduiskii-kraevedcheskii-muzei-im-a-g-yukova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/muzei-i-galerei/3716pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=67e39be1-45ec-468e-8866-673a67cd20f8&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 7628, 11710, 1640, 138954, '2015-04-29 13:13:28+03', '2025-11-01 13:08:27+03', 4033, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Бабаевский краеведческий музей им. М. В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'ул Юных Пионеров,д 2', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,ул Юных Пионеров,д 2', '{"type": "Point"}', '<p><span>Музей имеет шесть экспозиционных залов, рассказывающих об истории появления и развития города Бабаева. </span><span>В музее открыты следующие экспозиции:</span></p><ul><li><span>«Сельский быт» – среди наиболее интересных экспонатов можно отметить шкатулки и вазы из корня сосны, наряд вепсской невесты;</span></li><li><span>«Крестьянская изба деревни Бабаево»;</span></li><li><span>«Развитие железнодорожной станции» – наиболее интересны дубовый стол купца Ганьковского, буфет машиниста Бандиновича;</span></li><li><span>«Бабаево в годы войны» – фотоаппарат «Фотокор», немецкая обувь 1944 года выпуска, репродуктор военного времени.</span></li></ul><p><span>В выставочном зале музея проводятся выставки работ местных художников и фотохудожников, предметов этнографического характера, изделий современных мастеров по вышивке и кружевоплетению, продукции, выращенной на приусадебных участках, и изделий из нее.</span></p>', NULL, 'babaevomuzei@yandex.ru', '[]', '{"url": "https://all.culture.ru/uploads/1019fbbb680778309831d49b250edce5.jpeg", "title": "HGmGWy4OKNc - копия.jpg"}', NULL, NULL, 'Музеи и галереи', 'Бабаевский краеведческий музей им. М.В. Горбуновой', 'Бабаевский район', 'Europe/Moscow', 'переулок Юных пионеров,2', NULL, 'обл Вологодская,р-н Бабаевский,д Бабаево,переулок Юных пионеров,2', NULL, 3501006658, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Бабаевский краеведческий музей","networkId":"205571511","updateDate":"2023-05-26T07:21:53Z","createDate":"2023-05-26T07:21:53Z","accountId":47783,"postingGroupId":42436}]', 2800, '[{"name": "История"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 7655, '[{"url":"https://www.culture.ru/institutes/10586/babaevskii-kraevedcheskii-muzei-im-m-v-gorbunovoi","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/muzei-i-galerei/3737pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=25e86993-cabd-4a23-8bd2-320ad3bf7e80&shareType=venue","serviceName":"ФанТам"}]', 7655, 10586, 1750, 113976, '2015-04-29 13:29:48+03', '2026-01-08 14:29:55+03', 4052, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Харовский историко-художественный музей', 'Харовский район', 'Europe/Moscow', 'ул Ленинградская,д 7', NULL, 'обл Вологодская,р-н Харовский,г Харовск,ул Ленинградская,д 7', '{"type": "Point"}', '<p>В 1967 году в Харовске был создан музей, основой для которого послужил дар его основателя – Степана Михайловича Морозова. Переданная личная коллекция состояла из предметов нумизматики, картин, этнографии – в общей сложности около 500 единиц хранения.</p><p>За все время своего существования музей несколько раз менял адрес и в настоящее время располагается в большом здании, где расположились 2 выставочных зала и постоянные экспозиции: «Большая история маленького города», «Археология и природа Харовского района», «Русская изба», «Харовск в годы Великой Отечественной войны», "СВО: верность, мужество и отвага".</p><p>Ежегодно на территории Харовского района музей проводит пленэр российских художников «Ольховая сторона», по итогам которого организует одноименную выставку принятых в дар картин. В течение года для посетителей проводятся различные интерактивные программы и экскурсии, уроки, беседы, музейные праздники, фонды активно пополняются предметами старины. <br /></p>', 'http://museum-kharovsk.vlg.muzkult.ru', 'kharovsk.muzei@yandex.ru', '[{"value": "78173221492", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8597328bc0a97ac3d73d890bddd321bb.jpg", "title": "a9gK4UsiA-4.jpg"}', NULL, NULL, 'Музеи и галереи', 'Харовский историко-художественный музей', 'Харовский район', 'Europe/Moscow', 'ул Ленинградская,д 7', NULL, 'обл Вологодская,р-н Харовский,г Харовск,ул Ленинградская,д 7', NULL, 3521003493, 'mincult', 'Харовский район', 'Europe/Moscow', '[{"network":"vk","name":"Харовский историко-художественный музей","networkId":"108832552","updateDate":"2018-04-03T05:41:21Z","createDate":"2018-04-03T05:41:21Z","accountId":20483,"postingGroupId":18142}]', 3624, '[{"name": "Живопись"}, {"name": "История"}, {"name": "Этнография"}, {"name": "Краеведение"}, {"name": "Графика"}, {"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий","Художественный","Этнографический"]', NULL, 7674, '[{"url":"https://www.culture.ru/institutes/3205/kharovskii-istoriko-khudozhestvennyi-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/harovsk/muzei-i-galerei/3752pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=67757367-c206-4d49-a987-f31ed359aeb9&shareType=venue","serviceName":"ФанТам"}]', 7674, 3205, 1759, 139073, '2015-04-29 13:41:16+03', '2025-08-28 17:30:09+03', 4065, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Выставочный комплекс «Вологда на рубеже XIX–XX веков»', 'Вологда', 'Europe/Moscow', 'пр-кт Советский,д 16', NULL, 'обл Вологодская,г Вологда,пр-кт Советский,д 16', '{"type": "Point"}', '<p><span>Выставочный комплекс «Вологда на рубеже XIX–XX вв.» расположен в купеческой усадьбе, состоящей из трех строений: лавки, купеческого особняка, доходного дома. Все постройки в начале ХХ в. принадлежали купцу второй гильдии, ювелиру и часовых дел мастеру Александру Павловичу Самарину (1862–1934), поэтому филиал музея «Вологда на рубеже XIX–XX вв.» иногда называют просто домом купца Самарина.<span> </span>Архитектура зданий типична для деревянного вологодского домостроения того времени: при строительстве использованы элементы провинциального модерна и классического стиля. </span></p> <p><span>Экспозиции музея демонстрируют стиль жизни вологодских купцов и мещан на рубеже XIX и XX столетий.</span><span> </span><span>С историей </span><span>дома и его хозяев посетителей знакомят экспонаты небольшой выставки «Реликвии дома Самариных». </span><br /></p><p> В доходном доме находится мемориальная квартира, где в 1912–1914 гг. в ссылке жила М. М. Ульянова с матерью. С 1990-х гг. здесь работают такие выставки, как «Вологда на рубеже веков», «Урок в старой школе», «В доме купца Самарина», «Традиции русского застолья».</p>', 'https://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172724311", "comment": ""}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/dc88963beb351dd11a0be1ccc4506666.jpg", "title": "UI66bUP27ds.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 7678, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3755pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11717/vystavochnyi-kompleks-vologda-na-rubezhe-xix-xx-vekov","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=9bb4f8f4-2648-421a-9e15-8febe56cdd5f&shareType=venue","serviceName":"ФанТам"}]', 7678, 11717, NULL, NULL, '2015-04-29 13:44:07+03', '2025-08-29 14:06:24+03', 4068, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Тарногский музей традиционной народной культуры', 'Тарногский район', 'Europe/Moscow', 'ул Советская,д 14', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Советская,д 14', '{"type": "Point"}', '<p> Тарногский музей традиционной народной культуры был открыт 10 октября 1970 года в здании 1927 года постройки. В настоящее время насчитывает более 15 000 музейных предметов. </p><p>В музее функционирует постоянная экспозиция, отражающая жизнь Кокшеньгского края конца XIX – начала XX века и расположенная в 3 залах. </p><p>Первый зал «Круг жизни северного крестьянина» построен по круговому принципу: от экспонатов, связанных с рождением человека, до экспонатов, связанных с обрядами и традициями погребения. Особый колорит создают фотографии начала XX века, которые дают современному посетителю представление о том, как выглядели жители Спасской волости Тотемского уезда в начале XX века. </p><p>Второй зал «Женские традиционные ремесла» представлен уникальной вышивкой Кокшеньгского края, орудиями труда, украшенными резьбой по дереву. Третий зал – «Основные занятия кокшаров» (земледелие, льноводство, ремесла). Четвертый зал – отдел природы (животный и растительный мир Тарногского района, традиционное природопользование). </p><p>Музей предлагает посетителям обзорные и тематические экскурсии, музейные уроки и занятия, творческие мастерские и анимационные программы. </p>', NULL, 'm21485@yandex.ru', '[{"value": "78174821157"}]', '{"url": "https://all.culture.ru/uploads/2392b8e77577e80484f281734789ebc7.jpeg", "title": "P1070194.JPG"}', '[{"url": "https://all.culture.ru/uploads/189a103c7b34e9af42feca0063654abc.jpg", "title": "муз.jpg"}, {"url": "https://all.culture.ru/uploads/edd8a52689d58a9974f396d2dc4473df.jpg", "title": "музе.jpg"}, {"url": "https://all.culture.ru/uploads/497d8ba734a06b06d91f65623e8cc21e.jpg", "title": "му.jpg"}, {"url": "https://all.culture.ru/uploads/c10c28ed51ac9c4a7fffdf34345be115.jpg", "title": "отдел природы1.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Тарногский музей традиционной народной культуры»', 'Тарногский район', 'Europe/Moscow', 'ул Советская,д 14', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Советская,д 14', NULL, 3517003540, 'mincult', 'Тарногский район', 'Europe/Moscow', NULL, 3846, '[{"name": "Доступная среда"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 7719, '[{"url":"https://afisha7.ru/tarnogskiy-gorodok/muzei-i-galerei/3773pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/2607/tarnogskii-muzei-tradicionnoi-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=fd5d36f4-4cc7-4db8-8083-cf7eb9e136da&shareType=venue","serviceName":"ФанТам"}]', 7719, 2607, 1737, 113745, '2015-04-29 13:59:53+03', '2025-11-06 17:42:12+03', 4089, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом-музей Петра I г. Вологды', 'Вологда', 'Europe/Moscow', 'пр-кт Советский,д 47', NULL, 'обл Вологодская,г Вологда,пр-кт Советский,д 47', '{"type": "Point"}', '<p> Экспозиция музея размещается в одноэтажном здании – памятнике архитектуры XVII века, который связан с пребыванием Петра I на Вологодчине. </p><p>Об этой части истории края рассказывают более 100 экспонатов. Самые старинные из них – стулья с изображением на спинке двух резных рельефных львов, поддерживающих сердце и корону, с гравировкой «А. Г.» – «Адольф Гутман» – и датой «1704». В витрине можно увидеть било с петровским вензелем и датой «1706». </p><p>Среди картин есть портрет Петра, подаренный императором архиепископу Вологодскому – духовнику императора. К числу уникальных выставочных предметов относятся личные вещи Петра I. Часть экспозиции посвящена истории русского оружия и содержит в себе старинные стволы пушек, мушкет и ружье с ударно-кремневым замком.</p>', 'http://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172752759", "comment": "Дом-музей Петра I"}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/52213659bf832ecd3de86a48d88fbe91.JPG", "title": "IMG_2735.JPG"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Дом-музей"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический","Персональный, мемориальный"]', NULL, 7781, '[{"url":"https://www.culture.ru/institutes/11452/dom-muzei-petra-i-g-vologdy","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3814pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=5783ae87-270a-4697-adc0-6c7626fa531b&shareType=venue","serviceName":"ФанТам"}]', 7781, 11452, 343, 113783, '2015-04-29 14:33:04+03', '2025-08-29 14:41:41+03', 4131, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Открытое хранение фондов»', 'Тотьма', 'Europe/Moscow', 'ул Лесотехникум', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Лесотехникум', '{"type": "Point"}', '<p>«Открытое хранение фондов» называют самым удивительным и интересным музеем Тотьмы. Хотя это скорее депозитарий или хранилище, где представлены коллекции музея во всем их многообразии. В большинстве музеев подобные хранилища для посетителей недоступны, в Тотьме же в ту часть, где содержатся коллекции дерева, стекла, керамики, может попасть любой желающий.</p><p>Богатейшие коллекции трепал, изделий из бересты и глины, изразцов, посуды, мебели позволяют окунуться в старину и ближе узнать удивительный мир русской северной провинции столетней давности. Настоящей визитной карточкой «Открытого хранения» и одним из наиболее сильных впечатлений для туриста является «Комната прялок», которых на ограниченной площади представлено более 600.</p><p>«Открытое хранение фондов» находится на окраине города, на территории Спасо-Суморина монастыря, основанного в 1554 году монахом вологодского Спасо-Прилуцкого монастыря Феодосием Сумориным.</p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173922337", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/26e103c974a85751118071dab7c76390.jpg", "title": "h-33970.jpg"}', '[{"url": "https://all.culture.ru/uploads/ea1eb58e9da2e5a265ee73dd66dd88b4.jpg", "title": "PGXIXbZpwn0.jpg"}, {"url": "https://all.culture.ru/uploads/ad5ed3109b8a348f7e34a74926c35765.jpg", "title": "a44ff53b-1694-4915-a9c9-ef72b15db09b.jpg"}, {"url": "https://all.culture.ru/uploads/d37a3285a1312a4e472f6eadb91967d3.jpg", "title": "q-BnEX_GPAg.jpg"}, {"url": "https://all.culture.ru/uploads/a13b6c7fba8aa448e7eb0b908ade6a2a.jpg", "title": "ef419afc-0b3c-4c63-bb55-6fa190423970.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "Декоративно-прикладное искусство"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Дек.прикладного и нар. искусства"]', NULL, 7841, '[{"url":"https://www.culture.ru/institutes/12087/muzei-otkrytoe-khranenie-fondov","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/muzei-i-galerei/3853pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=a2404c77-a0f3-4c07-a3f5-ad5e724a96cc&shareType=venue","serviceName":"ФанТам"}]', 7841, 12087, 4139, NULL, '2015-04-29 15:11:03+03', '2026-02-05 15:54:17+03', 4185, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей одного стихотворения «Русский огонек»', 'Тотемский район', 'Europe/Moscow', 'д 3', NULL, 'обл Вологодская,р-н Тотемский,д Аникин Починок,д 3', '{"type": "Point"}', '<p>Музей одного стихотворения «Русский огонек» был открыт 5 января 2022 года. Он находится в бывшем доме телятницы колхоза «Никольский» Марии Богдановой, обогревшей и приютившей поэта Николая Рубцова ранним ноябрьским утром 1963 года. </p><p>Студент литинститута Рубцов ехал из столицы в родное село Никольское «на перекладных» и был вынужден завершающую часть пути проделать пешком. Дом Марии Богдановой стал для поэта спасительным, поскольку он шел ночью добрый десяток километров, очень устал и замерз. Благодаря этому случаю родилось стихотворение «Русский огонек», ставшее одним из несомненных шедевров русской лирики ХХ столетия и одной из вершин творчества Николая Рубцова. </p><p>В настоящее время в доме воссоздана обстановка избы по состоянию на 1963 год. В пространстве «Мост» планируются к работе временные выставки – в 2023 году это выставка печных дверец «Огонь в печи не спит...» из личной коллекции Леонида Вересова.</p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173922337"}, {"value": "78173961505"}]', '{"url": "https://all.culture.ru/uploads/649cbed7f616273d5821b375bdc4a467.jpg", "title": "UwM7r3btoug.jpg"}', '[{"url": "https://all.culture.ru/uploads/1e15367fadb74796c06d80bad754baa9.jpg", "title": "_xd1Ba5MxhY.jpg"}, {"url": "https://all.culture.ru/uploads/626d0fe32bdce5f9cbc448e64936d8be.jpg", "title": "dY6hzPaIdz0.jpg"}, {"url": "https://all.culture.ru/uploads/eb9f709624f8beab28265e57b86b260e.jpg", "title": "Hou-2R-Hz6Y.jpg"}, {"url": "https://all.culture.ru/uploads/1f0541c01fd5ee4443afd550ebad1128.jpg", "title": "cb1f7113-e69c-4ac1-9e99-aaee8fe4a360.jpg"}, {"url": "https://all.culture.ru/uploads/35485399dfd6d100e78fab22cf7d7c84.jpg", "title": "24abec2e-cae1-4d80-a1e6-f3562b1d1933.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "Памятные места"}, {"name": "Литература"}]', NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Литературный"]', NULL, 78964, '[{"url":"https://www.culture.ru/institutes/91816/muzei-odnogo-stikhotvoreniya-russkii-ogonek","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/muzei-i-galerei/99441pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=28e17dfe-89f2-4665-bc5a-0e1658810bb3&shareType=venue","serviceName":"ФанТам"}]', 78964, NULL, NULL, NULL, '2023-04-12 14:37:34+03', '2025-09-11 16:20:42+03', 4233, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Архитектурно-этнографический музей Вологодской области', 'Вологодский район', 'Europe/Moscow', NULL, 'Музей "Семенково", 12-й км автодороги «Вологда – Кириллов – Медвежьегорск»', 'обл Вологодская,р-н Вологодский,с/п Семенковское', '{"type": "Point"}', '<p>Решением Вологодского областного совета народных депутатов «О создании музея деревянного зодчества Вологодской области» 14 декабря 1979 года был основан музей.</p><p> </p><p>Архитектурно-этнографический музей Вологодской области «Семенково» сегодня позволяет посетителям окунуться в мир русской деревни конца XIX – начала ХХ в. Здесь можно прикоснуться к традициям жизни предков, к истокам культуры и менталитета русского народа.</p> <p></p><p><span>Музей – памятник федерального (общероссийского) значения, занимает площадь в 12,7 га. На музейной территории располагаются памятники деревянного зодчества середины XIX – начала XX века, перевезенные из Среднесухонского сектора Вологодской области, который включает в себя Нюксенский, Тарногский, Тотемский районы. </span></p><p><span>Архитектурно-этнографический музей ведет активную исследовательскую, реставрационную, экспозиционную, просветительскую работу, ищет новые формы работы с молодежью, привлекает к сотрудничеству образовательные учреждения, способствует сохранению и трансляции традиционной народной культуры.</span></p>', 'http://semenkovo.ru', 'admin@semenkovo.ru', '[{"value": "78172210190", "comment": "Архитектурно-этнографический музей Вологодской области"}]', '{"url": "https://all.culture.ru/uploads/71f273ef2ff8c34124f1a40abfeb2546.jpg", "title": "1.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Народное творчество"}, {"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, 'https://vtour.semenkovo.ru', '["Этнографический","Архитектурный"]', NULL, 7923, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/3911pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11201/arkhitekturno-etnograficheskii-muzei-vologodskoi-oblasti","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=09650284-b5ec-41ae-b4de-ed47da095b5b&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 7923, 11201, 362, 113730, '2015-04-29 15:51:31+03', '2025-08-29 14:12:20+03', 4262, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Комплекс Спасо-Суморина монастыря', 'Тотемский район', 'Europe/Moscow', 'ул Лесотехникум', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Лесотехникум', '{"type": "Point"}', '<p><span>В Комплексе Спасо-Суморина монастыря (открытом хранении фондов) представлены коллекции прялок, трепал, швеек, изделий из бересты, гончарных изделий, изразцов, посуды, мебели. Всего – более 3 000 единиц. </span></p><p><span>Здесь воочию можно увидеть то, что во многих музеях запрятано в запасниках. Здесь можно поработать с этим прекрасным материалом. Эту возможность используют преподаватели и ученики художественных школ, художники.</span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/c022c46917c5132ff8563905879e6c7a.jpg", "title": "71286.660x371.jpg"}', NULL, NULL, 'Музеи и галереи', 'Комплекс Спасо-Суморина монастыря', 'Тотемский район', 'Europe/Moscow', 'ул Лесотехникум', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Лесотехникум', NULL, NULL, 'mincult', 'Тотемский район', 'Europe/Moscow', NULL, 4154, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7941, '[{"url":"https://afisha7.ru/totma/muzei-i-galerei/3922pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/6377/kompleks-spaso-sumorina-monastyrya","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=fd8bc4e9-e77a-4986-8b2b-5138002ba8d2&shareType=venue","serviceName":"ФанТам"}]', 7941, 6377, NULL, NULL, '2015-04-29 16:01:20+03', '2015-12-08 16:12:59+03', 4291, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Водные пути Севера»', 'Вытегорский район', 'Europe/Moscow', 'ул Садовая,зд 1', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,ул Садовая,зд 1', '{"type": "Point"}', '<p>Музей расположен в здании машинного зала первой в Вытегре гидроэлектростанции. Экспозиция открыта в 1981 году, полностью модернизирована в 2022 году. </p><p>На примере карт, схем, подлинных документов музей рассказывает об истории пути, связывающего Балтийский и Каспийский регионы. Посетители могут познакомиться с разными этапами использования пути начиная с X–XI веков: водно-волоковой путь, строительство искусственной Мариинской водной системы, ее реконструкция, значение пути во время Великой Отечественной войны, строительство Волго-Балтийского канала. Гостей заинтересуют диорамы, макеты судов, подлинные предметы, связанные с историей водного пути.</p>', 'https://museum-vytegra.vlg.muzkult.ru', 'klyuev.09@mail.ru', '[{"value": "79585851020", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/d89183186a186ca1352c33235ac0b2fa.jpg", "title": "2tRAM8zIcZM.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Вытегорский объединенный музей»', 'Вытегорский район', 'Europe/Moscow', 'ул 3 Интернационала,д 2', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,ул 3 Интернационала,д 2', NULL, 3508003511, 'mincult', 'Вытегорский район', 'Europe/Moscow', '[{"network":"vk","name":"Вытегорский объединенный музей","networkId":"64441013","updateDate":"2025-07-15T11:35:30Z","createDate":"2025-07-15T11:35:30Z","accountId":53518,"postingGroupId":48169},{"network":"vk","name":"Елена Шинкарчук","networkId":"121910670","updateDate":"2025-07-15T11:36:33Z","createDate":"2025-07-15T11:36:33Z","accountId":53518,"postingGroupId":48170}]', 10671, '[{"name": "История"}, {"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 79737, '[{"url":"https://afisha7.ru/vytegra/muzei-i-galerei/101437pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/92729/muzei-vodnye-puti-severa","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=df78ad4b-1fee-493c-b1a7-c71f96886a2a&shareType=venue","serviceName":"ФанТам"}]', 79737, NULL, NULL, NULL, '2023-05-30 08:49:17+03', '2026-03-03 16:47:26+03', 4330, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом-музей Н. М. Рубцова', 'Тотемский район', 'Europe/Moscow', 'ул Н.Рубцова,д 18', NULL, 'обл Вологодская,р-н Тотемский,с Никольское,ул Н.Рубцова,д 18', '{"type": "Point"}', '<p><span>Музей работает на духовной родине Николая Михайловича Рубцова, в селе Никольском, с которым так или иначе была связана недолгая жизнь поэта. В Никольском он воспитывался в детском доме, закончил семилетку, позже неоднократно возвращался и подолгу проживал здесь. </span></p><p><span>Музей был создан в здании бывшего административного корпуса Никольского детского дома и в настоящее время включает в себя несколько тематических блоков: «Село Никольское и его история», «Детдомовское детство Николая Рубцова», «Жизненный путь Николая Рубцова», «Мемориальная комната поэта», «История музея Николая Рубцова». В коллекциях находится значительное количество подлинных предметов, связанных с именем поэта. </span></p><p><span>Музей Николая Рубцова – духовный и культурный центр всей территории долины реки Толшмы, который постоянно привлекает любителей творчества Николая Михайловича. В конце июля – начале августа самодеятельные поэты со всех уголков страны съезжаются на ежегодный праздник «Рубцовский костер».</span><span></span></p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173961505", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/5e86a9911123db1dee4645c1bf55c648.JPG", "title": "800x600_58253_muzei_rubtsova.JPG"}', '[{"url": "https://all.culture.ru/uploads/d57e1f545df43ea9ca0517b81e33f6c8.jpg", "title": "Музей Рубцова 2.jpg"}, {"url": "https://all.culture.ru/uploads/9c6cbb81542a066ec70132c0124b60c0.jpg", "title": "Музей Рубцова 3.jpg"}, {"url": "https://all.culture.ru/uploads/e95a29e325520ad70fbb1d3f82edcf59.jpg", "title": "Музей Рубцова 8.jpg"}, {"url": "https://all.culture.ru/uploads/43b3e0c49a48796dc0e40f62d0a4a073.jpg", "title": "Музей Рубцова 7.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "Памятные места"}, {"name": "Литература"}, {"name": "Для детей"}]', NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Литературный"]', NULL, 8019, '[{"url":"https://afisha7.ru/totma/muzei-i-galerei/3988pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11136/dom-muzei-n-m-rubcova","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=4e93cba6-97a1-4c27-8b07-fc098bbab5ad&shareType=venue","serviceName":"ФанТам"}]', 8019, 11136, 4140, NULL, '2015-04-29 16:57:35+03', '2025-09-05 10:28:35+03', 4370, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом природы г. Череповца', 'Череповец', 'Europe/Moscow', 'ул Коммунистов,д 42', NULL, 'обл Вологодская,г Череповец,ул Коммунистов,д 42', '{"type": "Point"}', '<p>Музей природы в<span>едет свою историю с 1920-х годов. За более чем 90-летнюю историю неоднократно менялись его название и статус. Неизменной оставалась миссия – собирать, изучать, популяризировать природоведческие знания по истории флоры и фауны. </span></p><p>Сегодня музей обладает замечательными коллекциями: энтомологической, палеонтологической, геологической, минералов, горных пород, гербариями, представляющими большую научную ценность. В настоящее время благодаря экспедициям, которые проводят научные сотрудники музея, его фонды пополняются ценными научными материалами. </p><p>В 2024 году музей пополнился уникальной экспозицией с аквариумами, в которых живут рыбы местных пород: щуки, язи, окуни, форель, стерлядь и др.</p>', 'http://чермо.рф', 'cherepovets_museum@metacom.ru', '[{"value": "78202493341", "comment": ""}, {"value": "78202493342"}]', '{"url": "https://all.culture.ru/uploads/1c7e199c15f7406aa1add3dc0f93efe7.jpg", "title": "llzNAwChjDA.jpg"}', '[{"url": "https://all.culture.ru/uploads/a1762cdb120002c22966fdfcc0de75dc.jpg", "title": "QIm_iMTfLxQ.jpg"}, {"url": "https://all.culture.ru/uploads/d45eaf68468382f0701654ef698eed9c.jpg", "title": "91JncJbUZWw.jpg"}, {"url": "https://all.culture.ru/uploads/2e5ccdd8fdbf0f6046a0f028fb3c2bf2.jpg", "title": "rnPIAj-yoyY.jpg"}, {"url": "https://all.culture.ru/uploads/f1f14f49b8f32ad50f0cf9f7d10ab44c.jpg", "title": "hdCz8DPWBJE.jpg"}, {"url": "https://all.culture.ru/uploads/759c0e79ec180c5816410526b4a62350.jpg", "title": "IMG_4809.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "Животные"}, {"name": "Естественные науки"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Естественнонаучный"]', NULL, 8044, '[{"url":"https://www.culture.ru/institutes/3084/dom-prirody-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/4004pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=3c597f55-0a73-42d2-aa4b-ed476a7ba206&shareType=venue","serviceName":"ФанТам"}]', 8044, 3084, 4370, NULL, '2015-04-29 17:29:26+03', '2025-09-04 14:45:50+03', 4391, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Мемориальная мастерская заслуженного художника РСФСР А. В. Пантелеева', 'Вологда', 'Europe/Moscow', 'ул Козленская,д 4', NULL, 'обл Вологодская,г Вологда,ул Козленская,д 4', '{"type": "Point"}', '<p><span>Александр Васильевич Пантелеев (1932–1990) – выдающийся русский художник второй половины ХХ века, живописец, график, монументалист, сценограф, педагог и оратор, литератор и общественный деятель. </span>Мемориальная мастерская А. В. Пантелеева – мемориальный музей заслуженного художника РСФСР Александра Васильевича Пантелеева, филиал Вологодской областной картинной галереи.</p><p>Мастерская расположена в одноэтажном кирпичном особняке постройки конца XIX века, в котором А. В. Пантелеев работал с 1981 года. До этого здание принадлежало Вологодской типографии и использовалось как цех цинкографии.</p><p>Мастерская занимает две небольшие комнаты, обставленные антикварной мебелью. Кроме творческого наследия А. В. Пантелеева здесь хранятся его книги, коллекция пластинок, предметы прикладного искусства, подарки художнику. Особый интерес представляет живописный инструментарий Александра Васильевича.</p>', 'http://www.vologda-gallery.ru', 'chief-gallery@mail.ru', '[{"value": "78172211639", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/0ac1c840647221ebbd08b3eff827dd8c.jpg", "title": "qQP6F6A0s3I.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодская областная картинная галерея»', 'Вологда', 'Europe/Moscow', 'ул Мира,д 34', NULL, 'обл Вологодская,г Вологда,ул Мира,д 34', NULL, 3525022842, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 3132, '[{"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 8150, '[{"url":"https://www.culture.ru/institutes/11820/memorialnaya-masterskaya-zasluzhennogo-khudozhnika-rsfsr-a-v-panteleeva","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/4072pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=841f3a5e-f54e-410a-bfc4-1a2bdeac5309&shareType=venue","serviceName":"ФанТам"}]', 8150, 11820, 4346, NULL, '2015-04-30 11:08:15+03', '2025-09-04 14:46:53+03', 4489, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Литературная резиденция «Дом дяди Гиляя»', 'Вологда', 'Europe/Moscow', 'ул Чернышевского,д 15', NULL, 'обл Вологодская,г Вологда,ул Чернышевского,д 15', '{"type": "Point"}', '<p>Литературная резиденция «Дом дяди Гиляя» появилась на культурной карте Вологды в апреле 2015 года.</p><p>Особнячок в стиле модерн 1913 года постройки был передан в аренду Вологодскому отделению Союза российских писателей. Эксперимент оказался удачным: писатели и многочисленные волонтеры превратили этот старый домик в свободное творческое пространство, где нашлось место для презентаций книг, выставок молодых художников, музыкальных и театральных вечеров, детских утренников и мастер-классов.</p><p> Литрезиденция названа в честь писателя-земляка Владимира Алексеевича Гиляровского, дом которого располагался неподалеку, но, к сожалению, не сохранился до наших дней. В доме размещена постоянно действующая выставка, посвященная писателю.</p><p> «Дом дяди Гиляя» известен далеко за пределами области. В год его посещает до 3 000 человек, которым интересна литература, история города и судьба выдающегося «короля репортеров», автора настольной книги всех экскурсоводов России «Москва и москвичи» Владимира Гиляровского.</p><p> Проект, родившийся как творческая инициатива общественной организации, вырос до уровня городского культурного учреждения. 1 января 2024 года литературная резиденция стала структурным подразделением Центра культурного развития Вологды и продолжает свою творческую, экскурсионную и просветительскую деятельность.</p>', 'https://rechnik.vlg.muzkult.ru/domgilyaya', 'rechnik83@mail.ru', '[{"value": "79211275812", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/55ba2f4787a9e609f67748cb3622e482.jpg", "title": "дом.jpg"}', NULL, NULL, 'Музеи и галереи', 'МАУК «Центр культурного развития г. Вологды»', 'Вологда', 'Europe/Moscow', 'ул Машиностроительная,д 26', NULL, 'обл Вологодская,г Вологда,ул Машиностроительная,д 26', NULL, 3525230144, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Анна Речникова","networkId":"433487639","updateDate":"2023-11-17T09:15:55Z","createDate":"2023-11-17T09:15:55Z","accountId":21233,"postingGroupId":43960},{"network":"vk","name":"Ансамбль народной песни \"Медуница\" (г. Вологда)","networkId":"200469053","updateDate":"2023-11-17T09:21:46Z","createDate":"2023-11-17T09:21:46Z","accountId":21233,"postingGroupId":43968},{"network":"vk","name":"Волонтёрский отряд ЦКР г. Вологды","networkId":"165529039","updateDate":"2023-11-17T09:21:10Z","createDate":"2023-11-17T09:21:10Z","accountId":21233,"postingGroupId":43961},{"network":"vk","name":"Декоративно - прикладное творчество","networkId":"203337157","updateDate":"2023-11-17T09:21:20Z","createDate":"2023-11-17T09:21:20Z","accountId":21233,"postingGroupId":43963},{"network":"vk","name":"МАУК «ЦКР г. Вологды» (ДК «Речник»)","networkId":"44217358","updateDate":"2023-08-01T12:17:26Z","createDate":"2023-08-01T12:17:26Z","accountId":21233,"postingGroupId":42874},{"network":"vk","name":"НСК Танцевальная студия «Серпантин»","networkId":"210705154","updateDate":"2023-11-17T09:21:26Z","createDate":"2023-11-17T09:21:26Z","accountId":21233,"postingGroupId":43964},{"network":"vk","name":"НСК Хор русской песни \"Реченька\"","networkId":"196555290","updateDate":"2023-11-17T09:21:35Z","createDate":"2023-11-17T09:21:35Z","accountId":21233,"postingGroupId":43966},{"network":"vk","name":"Студия вокала «МЕЧТА»|Вологда","networkId":"206242585","updateDate":"2023-11-17T09:21:31Z","createDate":"2023-11-17T09:21:31Z","accountId":21233,"postingGroupId":43965},{"network":"vk","name":"Студия игры на гитаре?Вологда","networkId":"206858928","updateDate":"2023-11-17T09:21:15Z","createDate":"2023-11-17T09:21:15Z","accountId":21233,"postingGroupId":43962},{"network":"vk","name":"Студия изобразительного искусства?Вологда","networkId":"206859132","updateDate":"2023-11-17T09:21:41Z","createDate":"2023-11-17T09:21:41Z","accountId":21233,"postingGroupId":43967}]', 20392, '[{"name": "История"}, {"name": "Литература"}, {"name": "Дом-музей"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Культура для школьников"}, {"name": "Для детей"}, {"name": "Изобразительное искусство"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Литературный","Историко-бытовой","Изобразительного исскуства","Музыкальный","Фотографии","Художественный"]', NULL, 83126, '[{"url":"https://www.culture.ru/institutes/96077/literaturnaya-rezidenciya-dom-dyadi-gilyaya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/110425pl","serviceName":"Афиша7"}]', 83126, NULL, NULL, NULL, '2024-02-13 12:54:50+03', '2026-03-31 16:32:41+03', 4662, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Галерея современного искусства «Красный мост»', 'Вологда', 'Europe/Moscow', 'наб 6 Армии,д 143', NULL, 'обл Вологодская,г Вологда,наб 6 Армии,д 143', '{"type": "Point"}', '<p>Галерея современного искусства «Красный мост» основана в 2003 году. Экспозиция охватывает работы художников нескольких поколений и стилевых течений. В залах можно познакомиться с творчеством реалистов и символистов, представителей советского андеграунда, а также современных авторов, порой выбирающих весьма оригинальные способы самовыражения в искусстве. </p><p>Общая площадь галерейных залов «Красного моста» – 800 кв. м. Постоянная и временные выставки размещаются на первом, втором этажах и в мансарде. Фонды художественного музея охватывают свыше 1 000 единиц хранения: это не только живопись, но и фотографии, объемные арт-объекты. </p><p>В рамках временных выставок демонстрируются работы живописцев и фотохудожников Вологодский области и других регионов России. Периодически участниками становятся зарубежные авторы. Проводятся выставки современного искусства, мастер-классы, творческие встречи с деятелями искусства, арт-медиации, квесты, поэтические вечера. <br></p>', NULL, 'gl_redmost@mail.ru', '[{"value": "78172239920", "comment": "Администрация"}]', '{"url": "https://all.culture.ru/uploads/0e19b09e4fe759a329ccb95ebefffaec.jpg", "title": "галерея красный мост.jpg"}', NULL, NULL, 'Музеи и галереи', 'МБУК «Галерея современного искусства «Красный Мост»', 'Вологда', 'Europe/Moscow', 'наб 6 Армии,д 143', NULL, 'обл Вологодская,г Вологда,наб 6 Армии,д 143', NULL, 3500000237, 'othergov', 'Вологда', 'Europe/Moscow', NULL, 36363, '[{"name": "Современное искусство"}, {"name": "Выставочные залы"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Изобразительного исскуства"]', NULL, 83222, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/110588pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/96172/galereya-sovremennogo-iskusstva-krasnyi-most","serviceName":"Культура.рф"}]', 83222, NULL, 11362, 173500, '2024-02-17 10:42:06+03', '2025-09-15 15:13:26+03', 4675, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Вологодский краеведческий музей им. В. А. Гаврилина', 'Вологодский район', 'Europe/Moscow', 'ул Свободы,д 22г', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Свободы,д 22г', '{"type": "Point"}', '<p><span>Создание Вологодского краеведческого музея имени В. А. Гаврилина </span><span> стало возможным благодаря реализации регионального социокультурного проекта «Творческое наследие В. А. Гаврилина». 28 января 2004 года состоялось официальное открытие музея. В</span> октябре 2019 года ему присвоено имя композитора. </p> <p><span>Экспозиция, посвященная В. А. Гаврилину и ставшая центральной, отображает жизненный и творческий путь композитора. </span><span>На данный момент музей состоит еще из четырех экспозиционных залов различной тематики: о боевом пути героев Советского Союза – уроженцев Вологодского района, народных промыслах Кубеноозерья, истории древнего торгового села Кубенского. Также есть выставочный зал.</span></p> <p><span>Музей организует проведение экскурсий по территории Вологодского района, культурно-образовательных и массовых мероприятий, мастер-классов, познавательных и развлекательных программ для обучающихся.</span></p> <p><span> </span></p>', NULL, 'VRKM35@yandex.ru', '[{"value": "78172772393", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/0ab5aa104ffcab76df8e962363e55e91.JPG", "title": "DSCN9637.JPG"}', NULL, NULL, 'Музеи и галереи', 'МБУК ВМО «Вологодский краеведческий музей им. В.А. Гаврилина»', 'Вологодский район', 'Europe/Moscow', 'ул Свободы,д 20', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Свободы,д 20', NULL, 3507012305, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 2928, '[{"name": "Краеведение"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 8339, '[{"url":"https://www.culture.ru/institutes/11566/vologodskii-kraevedcheskii-muzei-imeni-v-a-gavrilina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/4218pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=a3fbdaf1-1a28-4f6b-a979-92812795bf8c&shareType=venue","serviceName":"ФанТам"}]', 8339, 11566, 1758, 139035, '2015-04-30 15:12:46+03', '2023-07-07 16:14:02+03', 4699, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей церковной старины', 'Тотьма', 'Europe/Moscow', 'наб Кускова,д 7', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,наб Кускова,д 7', '{"type": "Point"}', '<p><span>На левом берегу реки Сухоны расположен Успенский храм с высокой величавой колокольней. В нем находится Музей церковной старины, открытый в 1995 году. В его экспозиции представлены памятники северорусской иконописи, мелкая пластика из меди и дерева, а также предметы церковной утвари. Большой интерес посетителей вызывает деревянная храмовая скульптура – явление, в целом нехарактерное для православия, но распространенное на Русском Севере. </span></p><p><span>При Музее церковной старины работает колокольня, на смотровую площадку которой можно подняться, чтобы полюбоваться с высоты на реку Сухону и город. Звонница из 6 колоколов восстановлена в 2016 году на средства В. А. Глазачева, потомка тотемской купеческой династии Арсаковых. По пути на колокольню в залах второго и третьего этажей можно ознакомиться с разного рода выставками.</span><span></span></p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173923003", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/08ddf871878d0a6782a48d8bb24279b2.jpg", "title": "Ijxp67hfH44.jpg"}', '[{"url": "https://all.culture.ru/uploads/f86ca848b4725a14d2ab98602dd764e4.JPG", "title": "Музей церковной старины- 5.JPG"}, {"url": "https://all.culture.ru/uploads/9b642fd10851dcc851955f01aeb17f2f.JPG", "title": "Музей церковной старины -7.JPG"}, {"url": "https://all.culture.ru/uploads/d11ac17c46bced148e87cf16fcfe4143.JPG", "title": "Музей церковной старины - 6.JPG"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "Скульптура"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей-храм, монастырь"]', NULL, 8347, '[{"url":"https://afisha7.ru/totma/muzei-i-galerei/4225pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11097/muzei-cerkovnoi-stariny","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=be6c86be-af9a-4f0d-85eb-dd69f6755663&shareType=venue","serviceName":"ФанТам"}]', 8347, 11097, 4138, NULL, '2015-04-30 15:15:41+03', '2025-09-05 10:34:37+03', 4705, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Детский музей г. Череповца', 'Череповец', 'Europe/Moscow', 'пр-кт Луначарского,д 39', NULL, 'обл Вологодская,г Череповец,пр-кт Луначарского,д 39', '{"type": "Point"}', '<p>Знакомство с этим необычным музеем будет интересно не только детям, но и взрослым: здесь можно совершить путешествие в детство разных поколений – с древности и до конца XX века. Любопытны старинные глиняные, деревянные, лоскутные игрушки, куклы, книги и елочные украшения. С особым теплом посетители вспоминают вещи советской эпохи, многие из которых раньше были в каждом доме.</p><p>Музей располагает коллекцией рисунков известной художницы Елизаветы Бём. В детские годы она подолгу гостила в усадьбе Братково неподалеку от Череповца. В бельэтаже музея создана экспозиция «Всего понемножку, или Загадки музейного бельэтажа», тематически связанная с ее творчеством. Здесь нашли отражение любимые сюжеты художницы – детский мир, деревенская жизнь, «близкие и симпатичные» ей самой.</p><p>Детский музей – один из самых посещаемых в Череповце. Ежедневно сюда приходит несколько десятков маленьких посетителей на занятия в рамках программы «Музей – детям». Музейные уроки отличаются от обычной экскурсии, они обязательно носят информационно-практический характер. Дети становятся активными участниками образовательного процесса: отгадывают загадки, читают стихи, лепят из глины и соленого теста, осваивают роспись, смотрят кукольные спектакли.</p><p>В музее более 15 лет работают и с детьми с ограниченными возможностями здоровья. Здесь знают, как сделать визит в музей комфортным и интересным для посетителей с нарушениями слуха, зрения, ментальными нарушениями. </p>', 'http://чермо.рф', 'cherepovets_museum@metacom.ru', '[{"value": "78202493321", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/dfc50ce1a6a5c6a9c3fe859f1d78f692.jpg", "title": "Череповец_Детский_музей.jpg"}', '[{"url": "https://all.culture.ru/uploads/44ea37f809dc818257d7df67a43a359f.jpg", "title": "JOE-oReBOxk.jpg"}, {"url": "https://all.culture.ru/uploads/699888192f149881044884b7d0725286.jpg", "title": "rPMGxMjk9z0.jpg"}, {"url": "https://all.culture.ru/uploads/93b9cc4ee5fccb2c561be71f75adc872.JPG", "title": "IMG_7973.JPG"}, {"url": "https://all.culture.ru/uploads/c8407a303333bb6c659a15324a836ca1.JPG", "title": "IMG_7974.JPG"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 8353, '[{"url":"https://www.culture.ru/institutes/6982/detskii-muzei-g-cherepovca","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/4230pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=4be8288e-c4c0-4165-b700-1d6fc6875269&shareType=venue","serviceName":"ФанТам"}]', 8353, 6982, 4365, NULL, '2015-04-30 15:19:10+03', '2025-09-15 15:58:34+03', 4710, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом-музей А. Ф. Можайского', 'Вологодский район', 'Europe/Moscow', NULL, '12 км', 'обл Вологодская,р-н Вологодский,п Можайское', '{"type": "Point"}', '<p><span> Экспозиция музея посвящена вологодскому периоду жизни и деятельности известного русского изобретателя в области воздухоплавания А. Ф. Можайского (1825–1890). Музей размещается в усадьбе, принадлежавшей супруге изобретателя Л. Д. Кузьминой (имение Котельниково). Экспозиция размещена в деревянном особняке середины XIX века. Именно там были произведены расчеты и опыты, ставшие первым шагом к созданию моноплана – летательного аппарата тяжелее воздуха.</span></p><p><span>В доме-музее располагается также выставка «Вклад вологжан в развитие авиации и космонавтики», рассказывающая об уроженцах Вологодской земли, которые посвятили свою жизнь воздухоплаванию. Среди них выдающийся советский авиаконструктор С. В. Ильюшин, летчики Гражданской и Великой Отечественной войны. Прослежен путь от первого российского самолета до старта космической ракеты «Восход-2» с вологжанином на борту – командиром корабля космонавтом П. И. Беляевым.</span></p><p><span>Филиал открыт 4 ноября 1986 года. К музею примыкает парк, основанный в 1861 году на площади 3 га с прудами, липовыми и дубовыми аллеями.</span></p>', 'https://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172555380", "comment": "Дом-музей А. Ф. Можайского"}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/ae62229167dbf938e61cf2c3fe4c2c22.jpg", "title": "imgB (3).jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "Космонавтика"}, {"name": "Авиация"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 8378, '[{"url":"https://afisha7.ru/vologda/muzei-i-galerei/4248pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11977/dom-muzei-a-f-mozhaiskogo","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=8e9489c1-06ac-4826-971f-e1013908426f&shareType=venue","serviceName":"ФанТам"}]', 8378, 11977, 653, 113711, '2015-04-30 15:33:22+03', '2025-08-29 15:29:39+03', 4736, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Устюженский краеведческий музей', 'Устюженский район', 'Europe/Moscow', 'пл Соборная,д 5', NULL, 'обл Вологодская,р-н Устюженский,г Устюжна,пл Соборная,д 5', '{"type": "Point"}', '<p>Краеведческий музей в Устюжне был открыт в 1921 году. С 1936 года он располагается в соборе Рождества Богородицы (XVII в.).</p><p>В современную экспозицию входят отдел истории, художественный отдел и выставочный зал. Отдел истории знакомит посетителей с историей края XI в. – начала ХХ в. В художественный отдел музея входят зал древнерусской живописи, масляной живописи XIX в. – начала XX в. и выставка коллекции фарфора. </p><p>Зал древнерусской живописи включает в себя сохранившийся четверик собора с мемориальным иконостасом XVII века работы мастеров Московской оружейной палаты. Масляная живопись отдела представлена полотнами И. К. Айвазовского, Б. М. Кустодиева, К. Я. Крыжицкого, Ю. Ю. Клевера и др.</p><p>В одном из залов музея постоянно действует выставка «Птицы и звери». В выставочном зале оформляются экспозиции различной тематики.</p>', 'https://ukm35.ru', 'ukm35@mail.ru', '[{"value": "78173722554", "comment": ""}, {"value": "79211354344"}]', '{"url": "https://all.culture.ru/uploads/6efaa3e0600bde8a2fd526c33e0485da.jpg", "title": "605430990140811-2_ustyuzhna_kraevedchesky_muzey.jpg"}', '[{"url": "https://all.culture.ru/uploads/523cdf05203c129c54e5e8ee4ff6019d.jpg", "title": "VOWph-xlCG0.jpg"}, {"url": "https://all.culture.ru/uploads/f319310b774b74f43e19d08d59532ca0.jpg", "title": "Zc6TjdDXGWE.jpg"}, {"url": "https://all.culture.ru/uploads/bf10d4d9c3c85eda738204c1eded409d.jpg", "title": "5RasZP7Sm-w.jpg"}, {"url": "https://all.culture.ru/uploads/2aa71b0d534959bd4fb93673d0918698.jpg", "title": "RVpSVfKOFq0.jpg"}, {"url": "https://all.culture.ru/uploads/a9234b25488fdbb6d464187f6c0f3638.jpg", "title": "xfalmoJzfPU.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «Устюженский краеведческий музей»', 'Устюженский район', 'Europe/Moscow', 'пл Соборная,д 5', NULL, 'обл Вологодская,р-н Устюженский,г Устюжна,пл Соборная,д 5', NULL, 3520002426, 'mincult', 'Устюженский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК \"Устюженский краеведческий музей\"","networkId":"58033465","updateDate":"2018-04-12T15:53:42Z","createDate":"2018-04-12T15:53:42Z","accountId":20795,"postingGroupId":18421},{"network":"vk","name":"Усадьба Батюшковых и А.И.Куприна в Даниловском","networkId":"133747579","updateDate":"2018-04-12T15:57:56Z","createDate":"2018-04-12T15:57:56Z","accountId":20795,"postingGroupId":18422}]', 4326, '[{"name": "Краеведение"}, {"name": "Русское искусство"}, {"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Краеведческий"]', NULL, 8400, '[{"url":"https://afisha7.ru/ustyuzhna/muzei-i-galerei/4264pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/10978/ustyuzhenskii-kraevedcheskii-muzei","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=be46beff-1ade-448c-a351-35f397bcf958&shareType=venue","serviceName":"ФанТам"}]', 8400, 10978, 1746, 113887, '2015-04-30 15:45:15+03', '2025-08-29 15:30:19+03', 4754, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей мореходов', 'Тотьма', 'Europe/Moscow', 'пер Чкаловский,д 10', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,пер Чкаловский,д 10', '{"type": "Point"}', '<p><span>Дом-музей был открыт в 1990 году в доме, где провел последние дни своей жизни по возвращении на родину Иван Александрович Кусков – тотемский мещанин, основатель самого южного русского поселения на американском континенте – крепости Росс. Завершивший славную плеяду тотемских мореходов, Иван Кусков был выдающимся деятелем своей эпохи, незаурядным дипломатом, благодаря усилиям которого активно развивалась деятельность Российско-американской компании. </span></p><p><span>Экспозиция музея, ставшего первым музеем «Русской Америки», содержит документы, письма, портреты, предметы той эпохи. Перед домом-музеем установлен бюст мореплавателя работы Н. Н. Мухатаевой (1990), а также представлены творения, созданные мастерами в рамках фестивалей деревянной скульптуры «Оживающая история».</span></p><p><span>С января 2025 года дом-музей Ивана Кускова преобразован в музей мореходов, проведена реэкспозиция. </span></p><p><span></span><span></span></p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173921150", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/be23f67adf1534e5f94cc68c46cb95e0.jpg", "title": "Музей Кускова.jpg"}', '[{"url": "https://all.culture.ru/uploads/4fd26a70f7a0dd83d7d8493788c94b30.JPG", "title": "IMG_0652.JPG"}, {"url": "https://all.culture.ru/uploads/6245d1996eaa05507aadb79ca3948323.JPG", "title": "IMG_0681.JPG"}, {"url": "https://all.culture.ru/uploads/27cdea6081b4672e508aee21d80a7c18.jpg", "title": "07ZesqVrRfp2FwLhv8VJ4WHHwej4bsTJlB6xCBwZdAqtXVrXQfw0Ae_GZeTz-rNwmmQUM6flQ4s6f-xdvbqfD9L7.jpg"}, {"url": "https://all.culture.ru/uploads/30ef858054b7d4695543498ce55ee9d8.jpg", "title": "Eum1jqBqmG3cHPUXp6_dMUiONOWMLf2X1YmwSTEb396J4dBQGhK6T_MCYqWkh-Hy2d35Qkfez0EvhLTLaKvLfTn6.jpg"}, {"url": "https://all.culture.ru/uploads/f1c68f5c8206ee871e8a898c357f2118.jpg", "title": "fQ9mvdpU6g5BYV_qoU6pLJa-jUZTOSmBVDRVCPfIpXOpGnBLi-gBG0l4jCatvJRAs5q7crLWSa4IkbGOVe-SQR4f.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "История"}, {"name": "Памятные места"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 8405, '[{"url":"https://www.culture.ru/institutes/11170/muzei-morekhodov","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/muzei-i-galerei/4269pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=3ce1c7e3-4c5c-4af3-9f71-0143d7e3d390&shareType=venue","serviceName":"ФанТам"}]', 8405, 11170, 4137, NULL, '2015-04-30 15:47:22+03', '2026-02-13 11:14:13+03', 4761, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей кружева г. Вологды', 'Вологда', 'Europe/Moscow', 'пл Кремлевская,д 12', NULL, 'обл Вологодская,г Вологда,пл Кремлевская,д 12', '{"type": "Point"}', '<p>Основная экспозиция расположена на площади в 1 500 кв. м и посвящена развитию традиционного художественного промысла Вологодчины и мировым тенденциям развития кружевоплетения с конца XIX по начало XXI века.</p><p>Экспозиция построена в хронологическом порядке. Первый зал посвящен европейским кружевным центрам – Германии, Франции, Польше, Словакии, Испании, а также эпохе зарождения искусства кружевоплетения (XVII–XVIII века), когда плели из золотых и серебряных нитей. В главной галерее представлены экспонаты, раскрывающие следующие кружевные темы: «Кружево в крестьянском костюме и этнографическом текстиле», «Кружевные изделия 1920–1940 годов», авторские произведения художников объединения «Снежинка». На первом этаже музея находятся выставочные залы, салон-магазин, учебный класс; на втором этаже – экспозиционные залы и главная галерея.</p>', 'https://vologdamuseum.ru', NULL, '[{"value": "78172721656", "comment": "Экскурсионный отдел Музей кружева"}, {"value": "78172722511", "comment": "Экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/4b59111ef4573db2456393168b25a47f.jpg", "title": "zdanie-kruz.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "Традиционное искусство"}, {"name": "Ремесла и художественные промыслы"}, {"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Дек.прикладного и нар. искусства"]', NULL, 8430, '[{"url":"https://www.culture.ru/institutes/11721/muzei-kruzheva-g-vologdy","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/4287pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1240c9ee-5c6d-4e9a-b175-5db7fddb3861&shareType=venue","serviceName":"ФанТам"}]', 8430, 11721, 1102, 140304, '2015-04-30 15:59:42+03', '2025-08-29 14:13:50+03', 4789, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Дом с добром', 'Вологда', 'Europe/Moscow', 'пл Кремлевская,д 4', NULL, 'обл Вологодская,г Вологда,пл Кремлевская,д 4', '{"type": "Point"}', '<p><span>«Дом с добром» – это </span><span> интерьеры разных эпох, выставки, антикварные предметы, экскурсии и чаепития, творческие занятия, кино о старом русском городе, авторская кофейня. А также – вологодские тепло, уют и гостеприимство. </span></p><p> </p><p> </p> <p>Культурно-выставочное пространство «Дом с добром» располагается в деревянном доме конца XIX века в историческом центре Вологды. Дом купца Коковашина имеет свою богатую историю, свои тайны и секреты, которые непременно станут известны и его гостям. Выставочные пространства расскажут и покажут жизнь в избе, в купеческом доме, в стильных апартаментах модерна и советских коммуналках. </p><p> Так жили вологжане.</p><p style="text-align:center"><span></span></p><p> </p>', NULL, 'Domsdobrom4@yandex.ru', '[{"value": "79517426782"}, {"value": "79210637312"}]', '{"url": "https://all.culture.ru/uploads/0f257b721839ba1a51d956523bae3f7e.JPG", "title": "1.JPG"}', NULL, NULL, 'Музеи и галереи', 'ООО «Площадь»', 'Вологда', 'Europe/Moscow', 'ул Октябрьская,д 8', NULL, 'обл Вологодская,г Вологда,ул Октябрьская,д 8', NULL, 3525485671, 'commercial', 'Вологодская область', 'Europe/Moscow', NULL, 37030, '[{"name": "Народное творчество"}, {"name": "Дом-музей"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой","Дворцово-парковый ансамбль","Исторический","Литературный","Музей-усадьба","Общеисторический","Художественный","Художественных ремесел"]', NULL, 84711, '[{"url":"https://www.culture.ru/institutes/97645/dom-s-dobrom","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/113384pl","serviceName":"Афиша7"}]', 84711, NULL, NULL, NULL, '2024-05-29 16:13:14+03', '2024-06-05 09:18:06+03', 4844, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Дом И. А. Милютина»', 'Череповец', 'Europe/Moscow', 'пл Революции,д 1', NULL, 'обл Вологодская,г Череповец,пл Революции,д 1', '{"type": "Point"}', '<p>Музей бережно хранит память о незаурядном общественном деятеле, промышленнике, просветителе Иване Андреевиче Милютине. </p><p>За время его почти полувековой деятельности на посту городского головы в Череповце было открыто семь учебных заведений, общественная библиотека, музей, книжный магазин, аптека, типография, богадельня при соборе, дом призрения во имя св. Филиппа и Марии; создана гавань; устроено освещение улиц, проведена телефонная связь. Благодаря усилиям Милютина Северная железная дорога прошла именно через вверенный ему город. </p><p>Выстроенный на высоком холме возле главного городского собора и возвышающийся над рекой Шексной, дом расположен таким образом, чтобы у южной его части открывалась широкая панорама речного простора. Композиция усадьбы гармонично вписывается в единство природного ландшафта и архитектуры.</p>', 'http://чермо.рф', 'cherepovets-museum@yandex.ru', '[{"value": "78202493318", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8b0de840806689c346777b2d0dbbb3f2.jpg", "title": "гид_культура_-30.jpg"}', '[{"url": "https://all.culture.ru/uploads/a0778abf4426d397755d7d6805fef536.JPG", "title": "IMG_4716.JPG"}, {"url": "https://all.culture.ru/uploads/63749b53f3efc3a5f630e7b1ea0b1522.jpeg", "title": "PziwGSoqR78.jpg"}, {"url": "https://all.culture.ru/uploads/917510c9146dff6e49e6b5ec339fc917.jpeg", "title": "PiTG4M7F4bQ.jpg"}, {"url": "https://all.culture.ru/uploads/1746591cc4422a672b08b7cc7787cbc5.jpeg", "title": "wvox7NtTKVc.jpg"}, {"url": "https://all.culture.ru/uploads/be00387be2dc1e4b03b9c4bef6e025de.jpeg", "title": "P2jHh4YNR-Q.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Дом-музей"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный","Краеведческий"]', NULL, 8473, '[{"url":"https://www.culture.ru/institutes/11443/muzei-dom-i-a-milyutina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/4321pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1647fb04-0146-45cc-962d-3d82a415b533&shareType=venue","serviceName":"ФанТам"}]', 8473, 11443, 4364, NULL, '2015-04-30 16:29:02+03', '2025-09-04 14:11:42+03', 4847, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Выставочный зал с. Ферапонтово', 'Кирилловский район', 'Europe/Moscow', 'ул Слободская,д 2', NULL, 'обл Вологодская,р-н Кирилловский,с Ферапонтово,ул Слободская,д 2', '{"type": "Point"}', '<p> Выставочный зал Кирилло-Белозерского музея-заповедник находится в центре села Ферапонтово. Он был открыт в 2023 году как выставочный центр современного искусства. Ранее в здании располагался сельский Дом культуры, в котором проходили творческие вечера, концерты, культурные программы. </p><p>После реставрационных работ силами музейщиков площадку переоборудовали в экспозиционные залы. В настоящее время в этом пространстве демонстрируются работы современных художников. </p><p>Первым, кто экспонировался в выставочном зале Кирилло-Белозерского музея-заповедника в Ферапонтове, стал московский художник с мировым именем Виктор Казарин. Две выставки Виктора Семеновича – «Виктор Казарин. Живопись. Графика» и «Преодоление» – были приняты с успехом на Вологодской земле. </p><p>Ферапонтово постоянно привлекало к себе одаренных и творческих людей. Здесь творил не только Виктор Казарин, но и супруги Андроновы – Николай Иванович и Наталия Алексеевна, Сергей Андрияка, художники Бурмагины… Здесь работал весь цвет русской культуры, русской художественной школы XX века. Работы современных авторов, творивших на Ферапонтовской земле, также станут экспонатами выставочного центра.<br /></p>', 'http://kirmuseum.org', 'pr@kirmuseum.org', '[{"value": "78175732806"}]', '{"url": "https://all.culture.ru/uploads/8eefd00ab3040e06bf376bb626b7406c.jpg", "title": "C3Fr62ORo_4.jpg"}', '[{"url": "https://all.culture.ru/uploads/fed75b4e2858885d052943a846f2c550.jpg", "title": "1Kdo5_x31Qs.jpg"}, {"url": "https://all.culture.ru/uploads/7ad04d369ab9a0d92481578d00bab444.jpg", "title": "0FN4JTC7Hlg.jpg"}, {"url": "https://all.culture.ru/uploads/9b53f08b61b17100ea806084ad59c77a.jpg", "title": "KunQ453n9J8.jpg"}, {"url": "https://all.culture.ru/uploads/29586c6957a19f96ad0603d3078ba41b.jpg", "title": "3Yu1_770W94.jpg"}, {"url": "https://all.culture.ru/uploads/2a6326727309eff321f0b3683d962009.jpg", "title": "m78a9PBJrlg.jpg"}, {"url": "https://all.culture.ru/uploads/d36eb4fba0adbf461f81e97acd024fb6.jpg", "title": "I6LY37k0vbk.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Современное искусство"}, {"name": "Выставочные залы"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Изобразительного исскуства","Музей современного искусства","Художественный"]', NULL, 84867, '[{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/113585pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/97783/vystavochnyi-zal-s-ferapontovo","serviceName":"Культура.рф"}]', 84867, NULL, NULL, NULL, '2024-06-19 12:19:44+03', '2024-06-21 09:10:30+03', 4867, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей «Мир забытых вещей»', 'Вологда', 'Europe/Moscow', 'ул Ленинградская,д 6', NULL, 'обл Вологодская,г Вологда,ул Ленинградская,д 6', '{"type": "Point"}', '<p><span>Музей открыт в мае 1991 года и занимает деревянный особняк середины ХIХ века. Экспозиция содержит два раздела.</span></p><p><span>На первом этаже – «Мир забытых вещей», открывающий посетителям культуру и быт горожан в дореволюционную эпоху. </span>Здесь воссозданы типологические интерьеры XIX – начала XX века: гостиной, столовой, детской и кабинета.</p><p>На втором этаже размещена выставка «История Вологодского портрета XVIII–XIX веков» из дворянских усадеб Вологодской губернии. </p><p>В музее проводятся литературно-музыкальные вечера, детские праздники. Частые гости – потомки вологодских дворян, бережно хранящие семейные традиции. В зале третьего этажа устраиваются выставки реликвий из семейных коллекций и архивов.</p>', 'http://vologdamuseum.ru', 'admin_museum@vologdamuseum.ru', '[{"value": "78172211417", "comment": "Музей «Мир забытых вещей»"}, {"value": "78172722511", "comment": "экскурсионный отдел"}]', '{"url": "https://all.culture.ru/uploads/dee5acaea59b88c19b93d618e624aa59.jpg", "title": "1.jpg"}', NULL, NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Архитектура"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Культура для школьников"}]', NULL, NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 8503, '[{"url":"https://www.culture.ru/institutes/11496/muzei-mir-zabytykh-veshei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/4347pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c51cbe3a-c1b3-40c4-86a5-4c83e0505c6f&shareType=venue","serviceName":"ФанТам"}]', 8503, 11496, 643, 141938, '2015-04-30 17:01:43+03', '2026-01-13 17:58:14+03', 4888, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музейно-выставочный центр «На Большой Садовой»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д 2', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д 2', '{"type": "Point"}', '<p><span>Музейно-выставочный центр «На Большой Садовой» – один из самых молодых музеев Тотьмы. Он открылся в мае 2014 года в помещениях бывшего храма Воскресения. </span></p><p><span>Это интерактивная площадка Тотемского музейного объединения. В выставочных залах первого этажа проходят временные выставки, приоритет при организации которых отдается тотемским художникам, мастерам, умельцам, людям с необычными хобби и увлечениями. Здесь может быть представлено все: от удивительных фотоколлажей до театральных масок, вышивки, инсталляций и даже велосипедов. </span><span>На втором этаже музея – творческое пространство «АнтреСОЛЬ», посвященное теме соли и солеварения в Тотьме. Это не совсем музейная экспозиция, это место интересных встреч, любопытных презентаций, обучающих семинаров, интерактивных игр и других творческих активностей. </span></p><p><span>Вокруг здания учреждения создан «Культурный квартал», насыщенный разнообразными информационными стендами и арт-объектами.</span><span></span></p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173922426", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/de62774c200961f88c4045219853d36a.jpg", "title": "ASBxvPFWmIQ.jpg"}', '[{"url": "https://all.culture.ru/uploads/c995094d9d3faf741bc7ced70a1d3bd0.jpg", "title": "2ikfMhPRDzY.jpg"}, {"url": "https://all.culture.ru/uploads/8b04a21bcbdb7ac72a552d23fa93c010.jpg", "title": "8af201fa0b88e66f5e19d0b0a1782031.jpg"}, {"url": "https://all.culture.ru/uploads/44883742ab8842f0ea2a8285f57008f1.jpg", "title": "2EOMqjXugg8.jpg"}, {"url": "https://all.culture.ru/uploads/8e714a5b7f9dba7ae385b8476065c1b5.jpg", "title": "hNcG03Cqov4.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "Современное искусство"}, {"name": "Культурные центры"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей современного искусства"]', NULL, 8508, '[{"url":"https://www.culture.ru/institutes/11255/muzeino-vystavochnyi-centr-na-bolshoi-sadovoi","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/muzei-i-galerei/4351pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=5d8503dc-00a1-44b2-ad89-2c379d52f34d&shareType=venue","serviceName":"ФанТам"}]', 8508, 11255, 4135, NULL, '2015-04-30 17:06:18+03', '2025-09-05 10:37:09+03', 4892, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей мореходов', 'Тотьма', 'Europe/Moscow', 'ул Кирова,д 15', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Кирова,д 15', '{"type": "Point"}', '<p><span>Музей мореходов был открыт к 300-летию русского флота, располагается на первом этаже Входоиерусалимского храма, построенного на средства тотемских купцов-компанейщиков, мореходов Григория и Петра Пановых. Входоиерусалимский храм-корабль с колокольней-мачтой считается одной из вершин северного барокко. </span></p><p><span>Музей полностью посвящен удивительным страницам истории города, благодаря которым можно говорить о славе Тотьмы как «города русских Колумбов». Музей мореходов содержит 3 тематических комплекса. Первый из них посвящен истории российского флота с момента его зарождения. Во втором зале подробно рассказывается об истории тотемского мореходства, его влиянии на жизнь города, о храмах, возведенных на средства тотемских купцов-компанейщиков. Третий зал посвящен ХХ веку и судьбам тотьмичей, которые служили на флоте, а также новому проекту, продолжающему традиции тотемского мореходства – «Школе путешественников Федора Конюхова». На колокольню, где воссоздана действующая звонница, в часы работы музея можно подняться: считается, что это лучшая высотная точка для обзора города.</span><span></span></p>', 'http://totmamuz.ru', 'totmamuz@mail.ru', '[{"value": "78173922490", "comment": ""}, {"value": "78173924551"}]', '{"url": "https://all.culture.ru/uploads/7f8c6964d0c835ab951124770b7c8e7c.jpg", "title": "Музей мореходов 00.jpg"}', '[{"url": "https://all.culture.ru/uploads/c057118bd74fa0acdb4ef4d503a38551.jpg", "title": "IMG_1899.jpg"}, {"url": "https://all.culture.ru/uploads/681244b33b3a624cec6ea9e42a28a630.jpg", "title": "IMG_1903.jpg"}, {"url": "https://all.culture.ru/uploads/1af002335608aaac4993c3b858fda0de.jpg", "title": "IMG_1907.jpg"}, {"url": "https://all.culture.ru/uploads/acd808bbd2c080a739118026dab198bc.jpg", "title": "IMG_1910.jpg"}, {"url": "https://all.culture.ru/uploads/3fde2f6e66d4916cc0b98cecd1064fad.jpg", "title": "IMG_1894.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «ТМО»', 'Тотьма', 'Europe/Moscow', 'ул Ворошилова,д д 44', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Ворошилова,д д 44', NULL, 3518000904, 'mincult', 'Тотьма', 'Europe/Moscow', NULL, 34781, '[{"name": "История"}, {"name": "Для детей"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Морской","Музей-храм, монастырь"]', NULL, 8529, '[{"url":"https://afisha7.ru/totma/muzei-i-galerei/4367pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/11270/muzei-morekhodov","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=acda369f-4ebf-4712-a8af-76c5a1e52609&shareType=venue","serviceName":"ФанТам"}]', 8529, 11270, 4136, NULL, '2015-04-30 17:28:25+03', '2025-09-05 10:56:16+03', 4917, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Мемориальный дом-музей Верещагиных', 'Череповец', 'Europe/Moscow', 'ул Социалистическая,д 22', NULL, 'обл Вологодская,г Череповец,ул Социалистическая,д 22', '{"type": "Point"}', '<p>Единственный в мире мемориальный дом-музей семьи Верещагиных. В этом доме в XIX веке в семье предводителя уездного дворянства родились Николай Верещагин, основатель молочной промышленности в стране, и Василий Верещагин, знаменитый русский художник.</p><p>Дом, некогда принадлежавший семье Верещагиных, пережил немало испытаний. В 1850-е годы он был продан местному купцу, который сдавал часть помещений второго этажа постояльцам. В 50–60-е годы XX века здесь находились коммунальные квартиры, и лишь в 1984 году здание было передано музею.</p><p>Обстановка мемориального дома бережно воссоздана по воспоминаниям Василия Верещагина. На территории музея сохранились аптекарский огород и каретный сарай.</p>', 'http://чермо.рф', 'batalistver@mail.ru', '[{"value": "78202493316", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f847284da90c004205bc256a48ff3af8.jpg", "title": "гид_культура_-28.jpg"}', '[{"url": "https://all.culture.ru/uploads/f9b8e79550dc289db5a18ed5fe8d59ec.JPG", "title": "фрагмент экспозиции доиа-музея Верещагиных.JPG"}, {"url": "https://all.culture.ru/uploads/500bfb5d4e9a37d782abee109b729f64.jpeg", "title": "7rQkpLefxZw.jpg"}, {"url": "https://all.culture.ru/uploads/51c13bb4e6735b1c27a7eb58524d194e.jpeg", "title": "moTq1Y2eh5g.jpg"}, {"url": "https://all.culture.ru/uploads/dc3004d0c53efc94ef160a957cb44355.jpeg", "title": "SwIHK7Kd3Gs.jpg"}]', NULL, 'Музеи и галереи', 'МАУК «Череповецкое музейное объединение»', 'Череповец', 'Europe/Moscow', 'пр-кт Советский,д 30А', NULL, 'обл Вологодская,г Череповец,пр-кт Советский,д 30А', NULL, 3528012634, 'mincult', 'Череповец', 'Europe/Moscow', '[{"network":"vk","name":"Череповецкое музейное объединение","networkId":"64210614","updateDate":"2019-04-02T10:14:10Z","createDate":"2019-04-02T10:14:10Z","accountId":25132,"postingGroupId":22215}]', 3676, '[{"name": "История"}, {"name": "Биография"}, {"name": "Доступная среда"}, {"name": "Культурное наследие"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Персональный, мемориальный"]', NULL, 8544, '[{"url":"https://www.culture.ru/institutes/11549/memorialnyi-dom-muzei-vereshaginykh","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/muzei-i-galerei/4378pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=ea2a077e-c487-4c07-8fd3-93429238dc5e&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 8544, 11549, 656, 113827, '2015-04-30 17:53:45+03', '2025-09-22 14:41:09+03', 4933, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей фресок Дионисия', 'Кирилловский район', 'Europe/Moscow', 'ул Каргопольская,д 8', NULL, 'обл Вологодская,р-н Кирилловский,с/п Ферапонтовское,с Ферапонтово,ул Каргопольская,д 8', '{"type": "Point"}', '<p>Музей фресок Дионисия размещен в Ферапонтовом монастыре, основанном в 1398 году. Монастырь стоит на высоком холме между двух озер и являет собой редкий пример сохранности и стилевого единства северного монастырского ансамбля XV–XVII веков.</p><p>Собор Рождества Богородицы 1490 года – самый ранний каменный храм на Русском Севере. В соборе в полном композиционном составе сохранились фрески 1502 года, исполненные артелью древнерусского художника Дионисия. Это единственный дошедший до нашего времени монументальный проект великого мастера. </p><p>Здесь экспонируются древнейшие иконы, в том числе Дионисия и его мастерской, предметы, связанные с историей монастыря и окружающих его земель. Музейные фонды включают в себя коллекции живописи, графики, книг, металла, керамики, ткани и дерева. </p><p> Современный Музей фресок Дионисия, объект ЮНЕСКО, – это туристический, научно-просветительский центр, распространяющий знания об уникальных памятниках ансамбля Ферапонтова монастыря через разнообразные формы музейной работы.</p>', 'http://www.dionisy.com', 'ferapont-museum@mail.ru', '[{"value": "78175749261", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/3aa41e5f755b16930e8eef9f9dbe8a32.JPG", "title": "IMG_002.JPG"}', NULL, NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Доступная среда"}]', NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный","Исторический","Архитектурный"]', NULL, 8622, '[{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/4439pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/2100/muzei-fresok-dionisiya","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=e91ffb3f-1186-4ddd-b397-db3c699c74f6&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', 8622, 2100, 1135, 113919, '2015-05-06 16:10:11+03', '2025-08-27 17:05:59+03', 5013, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Кирилло-Белозерский музей-заповедник', 'Кирилловский район', 'Europe/Moscow', NULL, NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов', '{"type": "Point"}', '<p>Кирилло-Белозерский музей-заповедник – визитная карточка Вологодской области. С 1997 года включен в Государственный свод особо ценных объектов культурного наследия народов Российской Федерации. Являясь одним из самых крупных российских музеев, в настоящее время он обладает прекрасными коллекциями древнерусской живописи, лицевого и орнаментального шитья, рукописных и старопечатных книг, археологии, декоративно-прикладного и народного искусства.</p><p>Наряду с архитектурным ансамблем Кирилло-Белозерского монастыря в состав музея входит не менее известный ансамбль бывшего Ферапонтова монастыря (1398) и деревянная церковь Ильи Пророка (1775). С 2000 года Ферапонтов монастырь находится под охраной ЮНЕСКО. Поводом для включения в список Всемирного наследия стали прекрасно сохранившиеся уникальные фрески московского живописца Дионисия, в начале XVI века расписавшего собор Рождества Богородицы. </p>', 'http://www.kirmuseum.org', 'info@kirmuseum.org', '[{"value": "78175731735", "comment": "Дирекция"}, {"value": "78175731479", "comment": "Заказ экскурсий"}]', '{"url": "https://all.culture.ru/uploads/0c94b4f4df13932e54270c96fb4b0cc1.JPG", "title": "IMG_003.JPG"}', NULL, NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Доступная среда"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, 'http://kirmuseum.org/vtour', '["Музей-заповедник"]', NULL, 8623, '[{"url":"https://www.culture.ru/institutes/11007/kirillo-belozerskii-muzei-zapovednik","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/4440pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=bf1be371-0ae6-42f3-934d-93a572b9f0d0&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 8623, 11007, 1747, 113904, '2015-05-06 16:15:20+03', '2025-08-27 16:08:32+03', 5014, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Мемориальная мастерская Татьяны Чистяковой', 'Вологда', 'Europe/Moscow', 'ул Козленская,д 4', NULL, 'обл Вологодская,г Вологда,ул Козленская,д 4', '{"type": "Point"}', '<p> В центре Вологды Кирилло-Белозерский музей-заповедник открыл мемориальную мастерскую известнейшего художника-керамиста России Татьяны Чистяковой. Более полувека Татьяна Александровна была одним из самых востребованных художников Вологодчины. Ее персональные выставки проходили в России, Финляндии, Чехии, Венгрии, Германии. </p><p>Экспозиция, посвященная жизни и творчеству Чистяковой, разместилась в 2 выставочных залах и помещении мастерской, расположенных в доме, построенном в 1915 году на средства вологодского мещанина Василия Михайлова. В советское время дом использовался под жилье. С 1970 года в здании были расположены творческие мастерские членов Союза художников России, проводились выставки работ вологодских художников. </p><p>В мастерской музейные сотрудники сохранили весь антураж и атмосферу. Кроме аутентичного интерьера мастерской, в которой установлены 2 больших муфельных печи, посетители экспозиции увидят более 200 эксклюзивных произведений автора, созданных из глины, шамота и фаянса. </p>', 'https://kirmuseum.org/ru/news', 'belovmuseum@yandex.ru', '[{"value": "79211261423", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4a3710d8729a369974691d942916a4fb.jpg", "title": "71hztpLapnE.jpg"}', '[{"url": "https://all.culture.ru/uploads/f24360671354318bb70ccdec72c4275c.jpg", "title": "-9KIodI7Ll0.jpg"}, {"url": "https://all.culture.ru/uploads/d8a2754353d42f552f54f5909dd3355a.jpg", "title": "ZRIsXzUAV-Y.jpg"}, {"url": "https://all.culture.ru/uploads/f87df9f9fbadc261bb534497fcba716f.jpg", "title": "kpo5uAN7NxQ.jpg"}, {"url": "https://all.culture.ru/uploads/fd568db564f9c57e2af6c7ca473408b8.jpg", "title": "WSL6zsrUDlQ.jpg"}, {"url": "https://all.culture.ru/uploads/bf18555be45c7107e8ab2c6c10ce541d.jpg", "title": "fccWEcv0_dM.jpg"}, {"url": "https://all.culture.ru/uploads/f821da3b1eaddd9a705cf71ff10ea705.jpg", "title": "w3MXjQQpD1Q.jpg"}, {"url": "https://all.culture.ru/uploads/8d2362d547681678f56b30075783b91a.jpg", "title": "2qV9HUR3v30.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Мемориал"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Коллекции"}, {"name": "Выставочные залы"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный","Персональный, мемориальный"]', NULL, 86827, '[{"url":"https://www.culture.ru/institutes/99801/memorialnaya-masterskaya-tatyany-chistyakovoi","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/128471pl","serviceName":"Афиша7"}]', 86827, NULL, NULL, NULL, '2025-01-09 11:14:52+03', '2025-09-02 16:56:46+03', 5093, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Мемориальный дом-музей С. С. Орлова', 'Белозерский район', 'Europe/Moscow', 'ул Дзержинского,д 12', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Дзержинского,д 12', '{"type": "Point"}', '<p>После ремонта 2021–2023 годов экспозиция музея преобразилась, практически полностью поменялась художественная концепция. Она построена на принципе инсталляции: каждому залу задается своя композиционная и ритмическая структура, свой художественный образ. </p><p> </p><p>Во входной зоне посетителей встречает с фотографии сам поэт Сергей Орлов в сопровождении одного из самых значимых для жителей Белозерска стихотворения «Белое озеро». Здесь же расположен экспозиционный модуль «Писатели Белозерского края» и бронзовый бюст поэта.</p><p> </p><p>Очень интересным, особенно для несовершеннолетних, является зал «Детство Сергея Орлова», с которого начинается экспозиция и история жизни Сергея Сергеевича. Здесь посетитель сможет увидеть воды Белого озера, под которыми находится деревня Мегра, модуль «Как растут стихи?».</p> <p>Второй зал «Мир и война» строится на контрасте мирной жизни и войны. В основе комплекса «Боевой путь поэта-танкиста» – карта с обозначением боевого пути Сергея Орлова, подаренная музею полковником в отставке Геннадием Андреевичем Кочуровым. Экспозиционный модуль «Письма с фронта» позволяет проследить связь Сергея Сергеевича со своей семьей: с мамой Екатериной Яковлевной и братом Дмитрием, их обмен фотографиями. </p> <p>Третий зал «Война глазами танкиста» дает образ войны «изнутри», глазами проживающего войну солдата. Об этом, по сути, все военные стихи Орлова, в них рассыпаны реалии. Сам Орлов горел в танке дважды. </p> <p>Четвертый зал экспозиции посвящен памяти о Великой Отечественной войне. Здесь посетитель сможет узнать о фронтовом поколении Сергея Орлова (И. П. Малоземов, И. И. Бузин, С. В. Викулов, Б. М. Пидемский). Доминанта зала – инсталляция, архитектурно организованная кругом, символически обозначающим планету Земля, и двумя вогнутыми плоскостями («млечные пути»).</p> <p>Последний зал экспозиции «Жизнь после войны» посвящен послевоенной жизни поэта Сергея Орлова. Центром является инсталляция «Рабочий стол поэта». В ее основе мемориальные вещи Орлова: рабочий письменный стол, пишущая машинка. На стене за столом – карта звездного неба. Она указывает на увлечение астрономией, внеземными цивилизациями, прошедшее через всю жизнь поэта.</p> <p></p><p> Память о Сергее Орлове – это прежде всего поэтическое наследие. В экспозиции представлены издания большинства сборников Сергея Орлова, на которые можно не просто посмотреть – их можно взять в руки и найти для себя свое орловское стихотворение.</p>', 'http://belozermus.ru', 'orlov@belozermus.ru', '[{"value": "78175622450", "comment": ""}, {"value": "78175623795", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2c3e8d16ad4e4b8f5cfecbe8a725511d.JPG", "title": "IMG_4189.JPG"}', '[{"url": "https://all.culture.ru/uploads/4606b8c13adb1b2c6f9922c8cc8f6cc3.JPG", "title": "IMG_5122.JPG"}, {"url": "https://all.culture.ru/uploads/665ebe2bc7ef6a144f2453af39dffda0.JPG", "title": "IMG_5105.JPG"}, {"url": "https://all.culture.ru/uploads/9368648dc39528afa3bb07cea0c63785.JPG", "title": "IMG_5084.JPG"}, {"url": "https://all.culture.ru/uploads/c687886c2fa63f567679eb235b7b3ab0.JPG", "title": "IMG_5080.JPG"}, {"url": "https://all.culture.ru/uploads/2cc2a2b67f4f5778d52d23b720b69fd3.JPG", "title": "IMG_5045.JPG"}, {"url": "https://all.culture.ru/uploads/57de314197e9d76c903a1d2e5f75eb89.JPG", "title": "IMG_5052.JPG"}, {"url": "https://all.culture.ru/uploads/4b47ae52a5e7c2d028e9eaa9ff0e4a39.JPG", "title": "IMG_5143.JPG"}]', NULL, 'Музеи и галереи', 'БУК ВО «Белозерский областной краеведческий музей»', 'Белозерский район', 'Europe/Moscow', 'ул Фрунзе д 28 / ул Викулова д 1', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Фрунзе д 28 / ул Викулова д 1', NULL, 3503002465, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Белозерский областной краеведческий музей","networkId":"51738627","updateDate":"2018-01-15T11:33:01Z","createDate":"2018-01-15T11:33:01Z","accountId":19101,"postingGroupId":16814}]', 4601, '[{"name": "Литература"}, {"name": "Дом-музей"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, 'http://belozersk.org', '["Литературный"]', NULL, 8751, '[{"url":"https://www.culture.ru/institutes/22253/memorialnyi-dom-muzei-s-s-orlova","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/belozersk/muzei-i-galerei/4545pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b8661825-2e29-47c0-80db-10b211a11f65&shareType=venue","serviceName":"ФанТам"}]', 8751, 22253, NULL, NULL, '2015-05-12 15:09:40+03', '2026-09-14 09:39:59+03', 5164, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Экспозиция «Белозерск исторический»', 'Белозерский район', 'Europe/Moscow', 'ул Фрунзе,д 28', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Фрунзе,д 28', '{"type": "Point"}', '<p>В экспозиции «Белозерск исторический» представлена история Белозерья, начиная с каменного века. В залах размещены материалы археологических исследований, макеты Белозерского кремля (крепость второй половины XV в.), 17 храмов (XVI–XIX вв.). В залах экспозиции размещены мебель, предметы интерьера (XIX – нач. XX в.), денежные знаки (XVIII – нач. XX в.), личные вещи купцов и мещан города, раскрыта история создания и функционирования Мариинской водной системы и Волго-Балтийского водного пути, развитие рыбного промысла. Здесь можно узнать о революционных событиях ХХ в., о коллективизации и индустриализации, развитии сельского хозяйства и промышленных предприятий и других эпизодах истории района.</p> <p>Зал воинской славы расскажет посетителям об участии белозерцев в Куликовской битве и войне 1812 года, о Первой мировой и Великой Отечественной, об Афганистане и Чечне. <span>Экспозиция оборудована интерактивными комплексами: устройство для добывания огня, археологический раскоп, капитанская рубка, завязывание морских узлов, средневековые доспехи и оружие. В экскурсиях используются аниматоры (археолог, дружинник, сестра милосердия), свето- и аудиоэффекты.</span><span></span></p><p><span>Сотрудники музея проводят обзорные экскурсии по городу, экспозиции, а также квест-игру «Сокровищница московской казны».<br /></span></p>', 'http://belozermus.ru', 'history@belozermus.ru', '[{"value": "78175622210", "comment": ""}, {"value": "78175622897", "comment": "факс"}]', '{"url": "https://all.culture.ru/uploads/b91a3016a16b8136bb4230a17d4e816a.jpeg", "title": "IMG_1767.JPG"}', '[{"url": "https://all.culture.ru/uploads/63fed1558f1d71c220c82b181fa6246f.JPG", "title": "1 зал.JPG"}, {"url": "https://all.culture.ru/uploads/7cbf8378a215462aaaaf6ac110748ea2.jpeg", "title": "Зал воинской славы в экспозиции Белозерск исторический (1).JPG"}, {"url": "https://all.culture.ru/uploads/ea9fc6175aa3f5c41d5f136c8761e8ff.jpeg", "title": "Интерактивная экскурсия в Музее Белозерск исторический (1).JPG"}, {"url": "https://all.culture.ru/uploads/1f7e1d33bab844067706f10f3e8c82bb.jpeg", "title": "Обзорная экскурсия в музее Белозерск исторический Ардальонов Д.А (2).JPG"}, {"url": "https://all.culture.ru/uploads/d897d3f07a48e94f717f95f3642622a9.jpeg", "title": "Белозерск исторический (20).jpg"}, {"url": "https://all.culture.ru/uploads/21896414ae8a979df93acb8e3abbb463.jpeg", "title": "Белозерск исторический (6).jpg"}, {"url": "https://all.culture.ru/uploads/e2be973ca776010b6fac27f55483a98c.jpeg", "title": "Белозерск исторический (15).jpg"}]', NULL, 'Музеи и галереи', 'БУК ВО «Белозерский областной краеведческий музей»', 'Белозерский район', 'Europe/Moscow', 'ул Фрунзе д 28 / ул Викулова д 1', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Фрунзе д 28 / ул Викулова д 1', NULL, 3503002465, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Белозерский областной краеведческий музей","networkId":"51738627","updateDate":"2018-01-15T11:33:01Z","createDate":"2018-01-15T11:33:01Z","accountId":19101,"postingGroupId":16814}]', 4601, '[{"name": "История"}, {"name": "Краеведение"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, 'http://belozersk.org', '["Исторический","Художественный","Краеведческий"]', NULL, 8761, '[{"url":"https://www.culture.ru/institutes/22244/ekspoziciya-belozersk-istoricheskii","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/belozersk/muzei-i-galerei/4554pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=518a9ad8-bf73-4cb4-a607-063306956401&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"},{"serviceName":"Культурная афиша (Одноклассники)"}]', 8761, NULL, NULL, NULL, '2015-05-12 23:49:05+03', '2026-09-14 09:40:35+03', 5175, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей этнографии г. Белозерска', 'Белозерский район', 'Europe/Moscow', 'ул Советский вал,д 1', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Советский вал,д 1', '{"type": "Point"}', '<p>В Белозерске после капитального ремонта открыт для посещения Музей этнографии. Для посетителей работают временные экспозиции «Быт крестьянской семьи конца XIX – начала XX века» и «Девичья горница». </p> <p>При посещении музея можно погрузиться в прошлое с головой: надеть на себя народный костюм, занять почетное место в красном углу, увидеть подлинную русскую печь, в которой, к слову, готовят блюда только по традиционным белозерским рецептам. В «Девичьей горнице» расскажут, как девушку воспитывали и выдавали замуж, как проходили посиделки и свадьбы в Белозерске. Все экспонаты здесь подлинные, можно не только посмотреть на них, но и взять их в руки. <br /></p> <p>На базе музея проходят занятия по программе «Музей и дети». В рамках абонементов «В гостях у сказки», «Добрых рук мастерство», «Крестьянские хоромы» организуется комплекс занятий, включающих элементы театрализации. Каждое занятие предполагает знакомство с музейными предметами в экспозиции, традиционные народные песни и хороводы, дидактические игры с этнографическими предметами, короткие фольклорные выступления.</p> <p>В Музее этнографии проводятся тематические экскурсии, лекции, занятия, народные и календарные праздники. С успехом проходят этнографические интерактивные программы для любой категории посетителей «В Белоозере широком щука дивная жила», «Девишник», «Проводы в рекруты» и другие. </p>', 'http://belozermus.ru', 'etno@belozermus.ru', '[{"value": "78175621426", "comment": "сотрудники отдела этнографии"}, {"value": "79914745808", "comment": "заказ экскурсий"}]', '{"url": "https://all.culture.ru/uploads/1cea3e218d6e725df0be2379ef316007.jpg", "title": "Музей этнографии октябрь 2022 (1).jpg"}', '[{"url": "https://all.culture.ru/uploads/34e10dc34920b1962722ea0525366345.JPG", "title": "IMG_2405.JPG"}, {"url": "https://all.culture.ru/uploads/06ced8be9e414f5c26dee8b0f7daff37.JPG", "title": "IMG_2422.JPG"}, {"url": "https://all.culture.ru/uploads/53dce45a589d36e65e51f9f10fde4116.JPG", "title": "IMG_2411.JPG"}, {"url": "https://all.culture.ru/uploads/4947d1e461fadc114fdd4129f7e20612.JPG", "title": "IMG_2410.JPG"}, {"url": "https://all.culture.ru/uploads/a7f43f6e241b7558b2167e3beb674312.JPG", "title": "IMG_2420.JPG"}, {"url": "https://all.culture.ru/uploads/dc9540f69a57983fcbc8b46fb26034bc.JPG", "title": "Музей этнографии октябрь 2022 (9).JPG"}, {"url": "https://all.culture.ru/uploads/081995d012de1d29b0f568ee46926d13.JPG", "title": "1.JPG"}]', NULL, 'Музеи и галереи', 'БУК ВО «Белозерский областной краеведческий музей»', 'Белозерский район', 'Europe/Moscow', 'ул Фрунзе д 28 / ул Викулова д 1', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Фрунзе д 28 / ул Викулова д 1', NULL, 3503002465, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Белозерский областной краеведческий музей","networkId":"51738627","updateDate":"2018-01-15T11:33:01Z","createDate":"2018-01-15T11:33:01Z","accountId":19101,"postingGroupId":16814}]', 4601, '[{"name": "История"}, {"name": "Народная культура"}, {"name": "Этнография"}, {"name": "Доступная среда"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-51738627&id=456239368&hash=80f2493f5128e5f6&hd=2\" width=\"853\" height=\"480\"></iframe>"},{"hosting":"ok","id":"4445105883654"}]', NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Этнографический"]', NULL, 8762, '[{"url":"https://www.culture.ru/institutes/22243/muzei-etnografii-g-belozerska","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/belozersk/muzei-i-galerei/4555pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=29b3f78b-d034-4151-9a07-c0d9b60de1c7&shareType=venue","serviceName":"ФанТам"}]', 8762, NULL, NULL, NULL, '2015-05-12 23:59:12+03', '2026-09-14 09:38:14+03', 5176, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Белого озера', 'Белозерский район', 'Europe/Moscow', 'ул Сергея Викулова,д 5', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Сергея Викулова,д 5', '{"type": "Point"}', '<p>Лимнологический музей, посвященный Белому озеру. </p><p>Первый зал музея «Физико-географическая характеристика Белозерского района» состоит из разделов «Из глубины веков», «Животный мир Вологодской области», «Миграции птиц», «Времена года», «Минералы и горные породы Вологодской области», «Ландшафты Белозерья», «Особо охраняемые природные территории». Здесь представлен большой объем картографического материала. Новое музейное оборудование с интерактивными элементами позволяет более полно представить Белозерье как историческую и природную территорию. Представить звуки древнего моря, проследить смены температур и ландшафта в разные времена года, покопаться в палеонтологическом раскопе и многое другое предлагает экспозиция посетителям. </p> <p>Раздел «Лес и его обитатели» знакомит с хищными животными семейства куньих, собачьих, кошачьих, медвежьих, с хищными птицами из отрядов совообразных и соколообразных и с представителем отряда парнокопытных – кабаном. Раздел «Белое озеро» рассказывает об особенностях гидрорежима озера, его фауне и климате.</p> <p>В 2018 г. в музее открылась уникальная экспозиция «Государев рыбный двор». Посетители имеют возможность разыграть лов рыбы на лодках-двойках, учатся плести рыбацкие сети. Экспозиция рассказывает о путях доставки белозерской рыбы в Москву и Санкт-Петербург, знакомит с редкими рыбными рецептами национальной русской кухни. В экспозиции использованы уникальные архивные документы, материалы местных краеведов.</p> <p>Раздел «Минералы и горные породы мира» представляет около 200 образцов, среди которых руды, поделочные и полудрагоценные камни. Проводятся мастер-классы по плетению рыболовецких сетей, сбору макета динозавра и др. Музей Белого озера демонстрирует всю красоту и разнообразие животного и растительного мира, традиционные формы природопользования, актуальные экологические проблемы этого водоема.</p> <p>Сотрудники музея проводят интерактивные программы, посвященные рыбному промыслу на Белозерье, в том числе гастрономической направленности: квест-игра «Мал сребреник, да дорог», интерактивная экскурсия по экспозиции «Путешествие во владениях Черендака – хозяина Белого озера».</p>', 'http://belozermus.ru', 'ozero@belozermus.ru', '[{"value": "78175621345", "comment": ""}, {"value": "79914745808", "comment": "заказ экскурсий"}]', '{"url": "https://all.culture.ru/uploads/069e08813101e8cce462af7057f68768.JPG", "title": "Музей Белого озера фасад Фото Давыдова С.Л..JPG"}', '[{"url": "https://all.culture.ru/uploads/acf68b1fd48981c1d4e129933be8a9d5.jpeg", "title": "интерьер Музей Белого озера (4).JPG"}, {"url": "https://all.culture.ru/uploads/49668379b548d14604c9284d657b3076.jpeg", "title": "интерьер Музей Белого озера (5).JPG"}, {"url": "https://all.culture.ru/uploads/c210d758364bc29a0fbd702d6c515c1e.jpeg", "title": "Экспозиция Государев рыбный двор в музее Белого озера (2).JPG"}, {"url": "https://all.culture.ru/uploads/198e1b4fe88aec020c7c2a0677cb6725.jpeg", "title": "интерьер Музей Белого озера (2).JPG"}, {"url": "https://all.culture.ru/uploads/6c74b4bd240a7fd3c16a18f671083da4.jpeg", "title": "Музей Белого озера, интерактивная программа.jpg"}, {"url": "https://all.culture.ru/uploads/314e0d215dd3e37d842a39ae68b9ac78.jpeg", "title": "Экспозиция Государев рыбный двор в музее Белого озера (5).JPG"}]', NULL, 'Музеи и галереи', 'БУК ВО «Белозерский областной краеведческий музей»', 'Белозерский район', 'Europe/Moscow', 'ул Фрунзе д 28 / ул Викулова д 1', NULL, 'обл Вологодская,р-н Белозерский,г Белозерск,ул Фрунзе д 28 / ул Викулова д 1', NULL, 3503002465, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Белозерский областной краеведческий музей","networkId":"51738627","updateDate":"2018-01-15T11:33:01Z","createDate":"2018-01-15T11:33:01Z","accountId":19101,"postingGroupId":16814}]', 4601, '[{"name": "Выставочные залы"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Биология"}, {"name": "Для детей"}]', NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, '["Биологический"]', NULL, 8764, '[{"url":"https://www.culture.ru/institutes/22242/muzei-belogo-ozera","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/belozersk/muzei-i-galerei/4557pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=6f7f78cd-74bb-40fb-bffe-c8bce3565a0a&shareType=venue","serviceName":"ФанТам"}]', 8764, NULL, NULL, NULL, '2015-05-13 00:05:52+03', '2026-09-14 09:39:05+03', 5177, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Музей Виктора Казарина', 'Кирилловский район', 'Europe/Moscow', 'ул Слободская,д 6', NULL, 'обл Вологодская,р-н Кирилловский,с Ферапонтово,ул Слободская,д 6', '{"type": "Point"}', '<p>Музей известного русского художника Виктора Семеновича Казарина, которого в искусствоведческой среде окрестили «отцом русского неоэкспрессионизма», находится под эгидой Кирилло-Белозерского музея-заповедника. Он расположен в селе Вологодской области – Ферапонтове.</p><p>В выставочных залах находится живопись и графика автора, а также реконструирована мастерская Виктора Казарина, в которой он работал сутками.</p><p> Узнаваемые черты авторского стиля Казарина – это крупноформатные холсты с пастозными размашистыми мазками и элементами дриппинга, балансирование на грани между фигуративностью и абстракцией, звучные цветовые сочетания и энергия стихийных ритмов. Напористые и взрывные композиции Казарина рождались через длительную аккумуляцию эмоционального и физического напряжения с последующим выбросом энергии на холст. Художник добивался определенного состояния сознания, которое сравнимо с «разматыванием нервов» Николая Некрасова, несколько суток проводившего за карточной игрой перед предстоящим поэтическим трудом. Казарин же изнурял себя непрерывной, по 12–14 часов работой в мастерской. Доводя себя до крайней степени эмоциональной взвинченности, он выходил за пределы рационального, позволяя внутреннему хаосу преобразоваться в наслоение цветовых пятен и линий.</p><p>Художник работал в стесненных условиях малогабаритной комнаты, перемещаясь прямо по холсту большого формата, который располагался на полу. Сокращение дистанции между произведением и автором, пребывающим в состоянии экстатического самозабытья, превращало художественный процесс в телесную, почти шаманскую практику.</p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/2effecc06a84ec176091705ed6b9c815.jpg", "title": "LAK-JA-b0BW7lRZgQg_0uKUabd8U_jXr1-c78nC3LoA9TYKpp-z7jcQHkTmDVfPpd_5LRen-WqQKAseVjCz5kFTy.jpg"}', '[{"url": "https://all.culture.ru/uploads/680a8c495e2c02726fbfb7b152ff714c.jpg", "title": "7u8R7BoDHy9rJwruWtOCdZaBmJhNZx2OYQvf4CqKTXupGj2kfToD00Nu0uR5XOQfWldmcC-U22xbzzYWQAe4tovV.jpg"}, {"url": "https://all.culture.ru/uploads/8f91dddda3fae0f829d5719630f20e37.jpg", "title": "eitSAGGVzBTrfIt7ztwAgD2E3vsXnjKasNgLcc7FK0VqaX8AK2cPgY5WhiU14nRBiLKjVWHCRm-jKM4RUsTtcQMu.jpg"}, {"url": "https://all.culture.ru/uploads/8140a475461702cf177496bd0326cc40.jpg", "title": "vfvIZm35Hd7thIdc69JZL4rauZhSncJ-rTf5nqUNOEZF2_Jv2gVKQU43umkscf8GhJj8zx-C--1v4Q8xcKtC5PBc.jpg"}]', NULL, 'Музеи и галереи', 'ФГБУК «Кирилло-Белозерский историко-архитектурный и художественный музей-заповедник»', 'Кирилловский район', 'Europe/Moscow', 'Заповедная зона, Соборная пл., 1  ', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,Заповедная зона, Соборная пл., 1  ', NULL, 3511001352, 'mincult', 'РФ', 'Europe/Moscow', '[{"network":"vk","name":"Кирилло-Белозерский музей-заповедник","networkId":"2200394","updateDate":"2015-05-22T11:30:08Z","createDate":"2015-05-22T11:30:08Z","accountId":1010,"postingGroupId":1397},{"network":"twitter","name":"Kirillov''s museum","networkId":"231729577","isPersonal":true,"updateDate":"2015-05-22T11:30:25Z","createDate":"2015-05-22T11:30:25Z","accountId":1271,"postingGroupId":1398},{"network":"ok","name":"Кирилло-Белозерский музей-заповедник","networkId":"52208700358722","updateDate":"2015-05-22T11:30:35Z","createDate":"2015-05-22T11:30:35Z","accountId":1272,"postingGroupId":1399}]', 613, '[{"name": "Современное искусство"}, {"name": "Выставочные залы"}, {"name": "Доступная среда"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Художественный"]', NULL, 90013, '[{"url":"https://www.culture.ru/institutes/103045/muzei-viktora-kazarina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/muzei-i-galerei/137494pl","serviceName":"Афиша7"}]', 90013, NULL, NULL, NULL, '2025-09-05 10:21:26+03', '2025-09-16 10:17:10+03', 5394, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Бабушкинский исторический музей', 'Бабушкинский район', 'Europe/Moscow', 'ул Бабушкина,д 46', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул Бабушкина,д 46', '{"type": "Point"}', '<p>Музей с 1975 года является хранителем многовековой истории. Представлено пять экспозиций. В каждой из них множество интересных, неповторимых и ценных экспонатов: предметы крестьянского быта, тканые половики и полотенца, традиционные костюмы, живописные полотна самодеятельных художников, изделия прикладного искусства современных мастеров, фотографии, документы. </p><p><span>Разработан интерактивный туристический маршрут </span><span>«</span><span>Развитие солеварения в Леденгском крае</span><span>»</span><span>. Г</span>остям предоставляется интереснейшая возможность познакомиться с достопримечательностями села, с многовековой историей леденгского солеварения, с жизнью прославленных земляков, таких как Иван Васильевич Бабушкин <span>– </span><span>герой, революционер – и Павел Иванович Беляев </span><span>–</span><span> единственный космонавт Вологодчины.</span></p>', 'https://mbukbrim.ru', 'lena_sysoeva@mail.ru', '[{"value": "78174521506", "comment": "Сысоева Елена Сергеевна"}, {"value": "79215324223", "comment": "Сысоева Елена Сергеевна"}]', '{"url": "https://all.culture.ru/uploads/9728993b156891c43e687ef30c87e00e.jpg", "title": "1.jpg"}', '[{"url": "https://all.culture.ru/uploads/c96213d7a5ba7d2b6bf5d90aa3b43260.jpeg", "title": "DSC_0170.JPG"}, {"url": "https://all.culture.ru/uploads/af97e468d2a043abd2d1adcd6497ba33.jpeg", "title": "IMG_20211004_140120.jpg"}, {"url": "https://all.culture.ru/uploads/eec5c175ad8826b4b87149a62c35c0d1.jpeg", "title": "IMG_20211004_140101.jpg"}, {"url": "https://all.culture.ru/uploads/f89b4fd3130c25c974745ee328fa85ff.jpeg", "title": "IMG_0705.jpg"}, {"url": "https://all.culture.ru/uploads/279145e8c8c0c960e7aab375968a9e67.jpg", "title": "сердце.jpg"}, {"url": "https://all.culture.ru/uploads/b444f91a7802e71661b7554904e29aa5.jpg", "title": "арка.jpg"}, {"url": "https://all.culture.ru/uploads/60fbe57c9e8d3ab30c3c565983ae65ed.jpg", "title": "музей 3.jpg"}]', NULL, 'Музеи и галереи', 'МБУК «Бабушкинский исторический музей»', 'Бабушкинский район', 'Europe/Moscow', 'ул Бабушкина,д 46', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул Бабушкина,д 46', NULL, 3502004999, 'mincult', 'Бабушкинский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК \"Бабушкинский исторический музей\"","networkId":"67932093","updateDate":"2023-12-18T06:40:09Z","createDate":"2023-12-18T06:40:09Z","accountId":38493,"postingGroupId":44239}]', 4799, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Современное искусство"}, {"name": "Этнография"}, {"name": "Декоративно-прикладное искусство"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}, {"name": "Для детей"}]', NULL, '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Исторический"]', NULL, 9087, '[{"url":"https://www.culture.ru/institutes/22088/babushkinskii-istoricheskii-muzei","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/muzei-i-galerei/4718pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=bef7af0d-451a-4186-8fc5-994e5a10c9df&shareType=venue","serviceName":"ФанТам"}]', 9087, NULL, 1744, 113868, '2015-05-19 11:34:13+03', '2023-12-19 08:13:18+03', 5488, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Центр изучения истории и этнографии Русского Севера', 'Вологда', 'Europe/Moscow', 'пр-кт Советский,д 20', NULL, 'обл Вологодская,г Вологда,пр-кт Советский,д 20', '{"type": "Point"}', '<p> Центр изучения истории и этнографии Русского Севера – обособленное подразделение Вологодского государственного историко-архитектурного и художественного музея-заповедника. Он создан в 2024 году для организации научно-исследовательской, просветительской, образовательной, издательской и экспедиционной работы. Центр располагается в Доме купца Соковикова – памятнике деревянного зодчества середины XIX века.</p><p>В выставочном зале экспонируются предметы из зоологической коллекции музея, этнографические предметы из коллекции керамики, тканей, дерева, и другие памятники материальной и духовной культуры, а также природы из фондов Вологодского государственного музея-заповедника и других учреждений. На площадке выставок проводятся экскурсии, мастер-классы, творческие встречи и лекции. </p>', 'https://vologdamuseum.ru', 'vologdamuseum@mail.ru', '[{"value": "78172729982", "comment": ""}, {"value": "78172722511", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2d97ea154a8f3766610e6d081ebb6818.jpeg", "title": "IMG_9500.jpeg"}', '[{"url": "https://all.culture.ru/uploads/cd413950cc3f6ed5dee1325a403a2322.JPG", "title": "IMG_3399.JPG"}, {"url": "https://all.culture.ru/uploads/f113e35ab9c617e1fda83c452d90c4a0.JPG", "title": "IMG_0020.JPG"}, {"url": "https://all.culture.ru/uploads/58dbfee66e1df9945537f80618eb483e.JPG", "title": "IMG_9948.JPG"}]', NULL, 'Музеи и галереи', 'БУК «Вологодский государственный историко-архитектурный и художественный музей-заповедник»', 'Вологда', 'Europe/Moscow', 'ул Сергея Орлова,д 15', NULL, 'обл Вологодская,г Вологда,ул Сергея Орлова,д 15', NULL, 3525032150, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"vk","name":"Вологодский государственный музей-заповедник","networkId":"50587797","updateDate":"2016-01-15T12:06:28Z","createDate":"2016-01-15T12:06:28Z","accountId":4420,"postingGroupId":4259},{"network":"vk","name":"Музей \"Семёнково\"","networkId":"7323557","updateDate":"2016-06-22T15:30:40Z","createDate":"2016-06-22T15:30:40Z","accountId":7648,"postingGroupId":6649},{"network":"vk","name":"Юлия Черноусова (Лопотова)","networkId":"58438208","isPersonal":true,"updateDate":"2018-10-12T09:43:15Z","createDate":"2018-10-12T09:43:15Z","accountId":22716,"postingGroupId":20081},{"network":"twitter","name":"vologdamuseum","networkId":"4216071347","isPersonal":true,"updateDate":"2016-01-15T12:09:27Z","createDate":"2016-01-15T12:09:27Z","accountId":4771,"postingGroupId":4262}]', 4650, '[{"name": "История"}, {"name": "Этнография"}, {"name": "Культура для школьников"}]', NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Историко-бытовой"]', NULL, 91275, '[{"url":"https://www.culture.ru/institutes/104272/centr-izucheniya-istorii-i-etnografii-russkogo-severa","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/muzei-i-galerei/142579pl","serviceName":"Афиша7"}]', 91275, NULL, NULL, NULL, '2025-12-12 17:44:16+03', '2026-01-08 08:58:36+03', 5524, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Собор Архангела Михаила Михайло-Архангельского монастыря', 'Великоустюгский район', 'Europe/Moscow', 'ул Павла Покровского,д 13', 'Михайло-Архангельский собор расположен в центре города. Если вы уже находитесь в Великом Устюге, до собора можно добраться: Пешком. Если вы остановились в центре города, собор находится в пешей доступности. На такси. В Великом Устюге доступны услуги такси. На личном транспорте. Используйте карты или навигационные сервисы, чтобы построить маршрут.', 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Павла Покровского,д 13', '{"type": "Point"}', '<p>Древнейший из монастырей Великого Устюга – Михайло-Архангельский. По сведениям летописца, он был основан монахом Киприаном в 1212 году «при езерах за острожною осыпью».</p><p>Это наиболее полно сохранившийся монастырский комплекс. Его основные каменные сооружения относятся к середине ХVII века. <br></p><p>Композиционный центр архитектурного ансамбля – монументальный пятиглавый Михайло-Архангельский собор с высокой шатровой колокольней. Справа от него – церковь Введения с трапезной палатой, соединенная с храмом переходами. Перед главным входом в собор находится живописная Владимирская надвратная церковь, построенная в 1682 году. Рядом с ней – миниатюрный храм-«памятник» Церковь Преполовения Пятидесятницы, возведенный в 1710 году над местом погребения основателя обители преподобного Киприана. К северу от собора расположены двухэтажные здания настоятельских (1734–1735), к востоку – братских (1736–1737) келий. Территория монастыря окружена невысокими каменными стенами со Святыми вратами, к которым примыкают часовни Прокопия и Иоанна Устюжских.</p>', 'https://ustyug-museum.ru/', 'ustyug.museum@mail.ru', '[{"value": "78173823576", "comment": "справочная"}, {"value": "78173823447", "comment": "директор"}]', '{"url": "https://all.culture.ru/uploads/0827f3a044857d4a4409ed118ae6ced1.jpg", "title": "Фото Кляповская Е.Г..jpg"}', '[{"url": "https://all.culture.ru/uploads/fa8d550eea757e19f683567e7ccf74a4.jpg", "title": "Фото Кляповская Е.Г. Мих.-Арх..jpg"}, {"url": "https://all.culture.ru/uploads/e5e38e8ae280d38de4264cc0416eb146.jpg", "title": "19fp89bpk2ad92j5p8lfr59uro8v7q6i.jpg"}, {"url": "https://all.culture.ru/uploads/8b20890afb164cf40c92ac55577b31fa.jpg", "title": "ltq3pxnvd6mcmmcfdxpoqn6hwbufknc1.jpg"}, {"url": "https://all.culture.ru/uploads/948babdd63058906f55195846d62da8e.jpg", "title": "26if48bjgmn31cg6xlh0fz6enjvcirq7.jpg"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "История"}, {"name": "Памятные места"}, {"name": "Архитектура"}, {"name": "Доступная среда"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Архитектурно-ансамблевый","Исторический","Музей-храм, монастырь"]', NULL, 93009, '[{"url":"https://www.culture.ru/institutes/106294/sobor-arkhangela-mikhaila-mikhailo-arkhangelskogo-monastyrya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/202621pl","serviceName":"Афиша7"}]', 93009, NULL, NULL, NULL, '2026-04-29 12:47:33+03', '2026-04-30 11:31:58+03', 5615, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Троицкий собор Троице-Гледенского монастыря', 'Великоустюгский район', 'Europe/Moscow', 'ул Центральная,д 122', NULL, 'обл Вологодская,р-н Великоустюгский,д Морозовица,ул Центральная,д 122', '{"type": "Point"}', '<p>Троице?Гледенский монастырь основан в последней четверти XII века одновременно с городом Гледен, заложенным князем Всеволодом Большое Гнездо. Архитектурный ансамбль сложился в конце XVII – первой половине XVIII века на средства устюжских купцов. </p> <p>Главная достопримечательность монастыря – великолепный резной золоченый иконостас Троицкого собора. Его возведение продолжалось 8 лет (с 1776 по 1784 год) на пожертвования устюжан.</p> <p>Для выполнения резных работ были приглашены тотемские мастера братья Николай и Тимофей Богдановы. Используя традиционные для ХVIII века мотивы (гирлянды, волюты, рокайли, завитки и т. п.), они украсили иконостас резьбой, поражающей богатством и редкостным разнообразием форм.</p> <p>Иконы, отличающиеся изяществом, точностью рисунка, богатой цветовой палитрой, написаны устюжскими иконописцами купцами А. В. Колмогоровым, Е. А. Шергиным и протоиереем устюжского Успенского собора В. А. Аленевым. Композиции икон отходят от традиционных канонов, поскольку писаны с печатных листов (западноевропейских гравюр)&nbsp;и напоминают больше светскую живопись.</p> <p>Общее впечатление богатства иконостаса усиливается позолотой, выполненной артелью П. А. Лабзина в сложной технике двойника со сплошными цировками (фигурными оттисками по сырому левкасу).</p> <p>Уникальность иконостаса подчеркивает большое количество деревянной скульптуры. На царских вратах расположены фигуры четырех евангелистов, над ними парит в облаках Саваоф. Скульптуры предстоящих у распятия&nbsp;ангелов, головок херувимов, органично сочетаясь с резьбой и иконописью, составляют с ними единое целое. К сожалению, имена резчиков фигур остались неизвестными, но это, без сомнения, были необыкновенно талантливые люди, обладавшие незаурядным мастерством и тонким вкусом.</p> <p>С начала 1980-х годов архитектурный комплекс Троице-Гледенского монастыря является объектом музея-заповедника. Ансамбль монастыря доступен для внешнего осмотра круглый год, Троицкий собор открыт для посетителей только в летний период.</p> ', 'https://ustyug-museum.ru/museums/ansambl-troitse-gledenskogo-monastyrya', 'ustyug.museum@mail.ru', '[{"value": "78173823447", "comment": "директор"}, {"value": "78173823576"}]', '{"url": "https://all.culture.ru/uploads/228818b8c017e4cea821a4cb77e9d7ba.JPG", "title": "13 Ансамбль Троице-Гледенского монастыря, XVII-XVIII вв. Кляповская Е.Г..JPG"}', '[{"url": "https://all.culture.ru/uploads/ae7fb14e605011101d030b5e2223fedf.jpg", "title": "Троице-Гледенский-монастырь-2.jpg"}, {"url": "https://all.culture.ru/uploads/16719375d728b45a64607d540c4db3c1.JPG", "title": "DSC_0040.JPG"}]', NULL, 'Музеи и галереи', 'БУК «Великоустюгский государственный историко-архитектурный и художественный музей-заповедник»', 'Великоустюгский район', 'Europe/Moscow', 'ул Набережная,д 64', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,ул Набережная,д 64', NULL, 3526008449, 'mincult', 'Вологодская область', 'Europe/Moscow', NULL, 4305, '[{"name": "История"}, {"name": "Ансамбли"}, {"name": "Архитектура"}, {"name": "Музеи-храмы"}, {"name": "Доступная среда"}, {"name": "Для молодежи"}]', NULL, NULL, NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "17:30:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, '["Музей-заповедник"]', NULL, 93038, '[{"url":"https://www.culture.ru/institutes/106319/troickii-sobor-troice-gledenskogo-monastyrya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/206788pl","serviceName":"Афиша7"}]', 93038, NULL, NULL, NULL, '2026-05-04 13:29:46+03', '2026-05-04 17:37:28+03', 5617, NULL);
INSERT INTO muzei.muzei_clubs VALUES ('Культурно-просветительский центр «Дом Деда Мороза»', 'Великоустюгский район', 'Europe/Moscow', 'территория Вотчины Деда Мороза,д 1', NULL, 'обл Вологодская,р-н Великоустюгский,Марденгское с/п,территория Вотчины Деда Мороза,д 1', '{"type": "Point"}', '<p>Государственное учреждение культуры «Дом Деда Мороза» было создано в 2003 году для осуществления основных целей проекта «Великий Устюг – родина Деда Мороза». Перед учреждением стоят задачи по формированию обновленного образа Деда Мороза как мудрого друга и советчика; возрождению народных традиций и культуры встречи Нового года как семейного праздника.</p><p>«Дом Деда Мороза» осуществляет активную работу с общественными организациями, благотворительными фондами, учреждениями культуры, образования, спорта, не замыкаясь в своей деятельности на проведении развлекательных и коммерческих мероприятий. Также основными видами деятельности учреждения являются:</p><ul><li>продвижение бренда «Великий Устюг – родина Деда Мороза» на российском и международном уровнях;</li><li>участие в организации и проведении культурно-массовых и творческих мероприятий, направленных на популяризацию образа российского Деда Мороза;</li><li>участие в организации и проведении межрегиональных, общероссийских культурно-массовых мероприятий по различным жанрам любительского искусства и народного творчества;</li><li>организация деятельности творческих коллективов, объединений, ассоциаций, студий, кружков.</li></ul><p><span>Культурно-просветительский центр «Дом Деда Мороза» </span><span>находится в 10 км от города Великий Устюг, в Марденгском сельском поселении на территории Вотчины Деда Мороза.</span></p>', 'http://www.dom-dm.ru', NULL, '[{"value": "78173852132", "comment": "администратор Дома Деда Мороза"}]', '{"url": "https://all.culture.ru/uploads/f2ec06b4fcc771e4fe8ee93928b1b378.jpg", "title": "12.jpg"}', NULL, NULL, 'Музеи и галереи', 'АО «Дед Мороз»', 'Великоустюгский район', 'Europe/Moscow', 'пер Революционный,д 8', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пер Революционный,д 8', NULL, 3526013449, 'othergov', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"Российский Дед Мороз. Дом Деда Мороза","networkId":"20839260","updateDate":"2016-04-14T08:15:14Z","createDate":"2016-04-14T08:15:14Z","accountId":6062,"postingGroupId":5411}]', 5123, '[{"name": "Культурные центры"}, {"name": "Для детей"}]', '[{"hosting":"vk","id":"<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/yBHM8vT9UlE\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, 'http://www.dom-dm.ru/vtour', '["Отраслевые"]', NULL, 9370, '[{"url":"https://www.culture.ru/institutes/38608/kulturno-prosvetitelskii-centr-dom-deda-moroza","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/muzei-i-galerei/4834pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b3b8b394-40ae-414f-b516-3d113206fcc7&shareType=venue","serviceName":"ФанТам"},{"serviceName":"Культурная афиша (ВКонтакте)"}]', 9370, NULL, NULL, NULL, '2015-06-22 04:29:51+03', '2019-02-15 11:00:23+03', 5653, NULL);
